// Rückgängig getippt wird. Das Laborblatt und das Kultur-Fenster teilen sich das.
function kulturenLoeschen(weg, zurueck) {
  const ids = new Set(weg.map((c) => c.id));
  cultures = cultures.filter((c) => !ids.has(c.id));
  const neu = () => {
    renderLabLog();
    renderLabStock();
    renderCultures();
    if (_lbSheet) lbSheetRender();
  };
  neu();
  const timer = setTimeout(async () => {
    for (const c of weg) {
      const r = await apiDelete('/api/cultures/' + encodeURIComponent(c.id));
      if (r && r.error) {
        cultures.push(c);
        toast(t('lb.deleteFailed', { id: c.id, msg: r.error }), 'err');
        renderCultures();
      }
    }
    loadLabStock();
  }, LB_WEG_MS);
  showUndoBar(t('lb.deleted', { n: weg.length }), () => {
    clearTimeout(timer);
    cultures.push(...weg);
    if (zurueck) zurueck();
    neu();
  });
}
// Unten ein Knopf: "N ansetzen" mit dem, was eingetippt ist; ist nichts
