// ─── CAMERA TAB (admin-only WIP) ─────────────────────────────
// Surfaces what an external camera module writes into camera_* tables
// and lets admins edit calibration values + manage the cameras list. The
// detection/measurement loop is external; this dashboard does not run it.
const _cam = {
  calibration: null,
  cameras: [],
  editingId: null,
  pxDistance: null
};

const CAM_CALIB_FIELDS = [
  ['pxPerMm', 'cam.pxPerMm', 'real'],
  ['incubationBagRadiusPx', 'cam.incubationBagRadiusPx', 'int'],
  ['qrAssignRadiusPx', 'cam.qrAssignRadiusPx', 'int'],
  ['yoloConfThreshold', 'cam.yoloConfThreshold', 'real'],
  ['pinMaxAreaRatio', 'cam.pinMaxAreaRatio', 'real'],
  ['harvestGrowthThresholdPct', 'cam.harvestGrowthThresholdPct', 'real'],
  ['harvestStallReadings', 'cam.harvestStallReadings', 'int'],
  ['colonisationScoreThreshold', 'cam.colonisationScoreThreshold', 'real'],
  ['colonisationMinFraction', 'cam.colonisationMinFraction', 'real'],
  ['unseenBagAlertHours', 'cam.unseenBagAlertHours', 'int'],
  ['contamConfThreshold', 'cam.contamConfThreshold', 'real']
];

function showCameraTab() {
  showAdminSubTab('camera');
}

async function loadCameraTab() {
  if (!currentUser || currentUser.role !== 'admin') return;
  let data;
  try {
    const r = await authFetch('/api/camera/dashboard');
    data = await r.json();
  } catch (e) {
    document.getElementById('cam-stats').textContent = t('common.error') + ': ' + (e.message || '');
    return;
  }
  _cam.calibration = data.calibration;
  _cam.cameras = data.cameras || [];
  renderCameraStats(data.stats);
  renderCameraList(_cam.cameras);
  renderCameraCalibForm(_cam.calibration);
  renderCameraFlags(data.flags);
  renderCameraRecent(data.recentMeasurements || []);
}

function renderCameraStats(s) {
  const el = document.getElementById('cam-stats');
  if (!el) return;
  if (!s) {
    el.textContent = t('common.error');
    return;
  }
  const cell = (label, value) =>
    `<div class="card" style="padding:10px;margin:0">
      <div class="fs-xs" style="color:var(--c-text-muted)">${esc(label)}</div>
      <div class="fs-floor" style="--fs-own:1.125rem;font-weight:600;color:var(--c-text)">${esc(String(value))}</div>
    </div>`;
  el.innerHTML =
    cell(t('cam.statCameras'), s.enabledCameras + ' / ' + s.cameras) +
    cell(t('cam.statMeasurements7d'), s.measurementsLast7) +
    cell(t('cam.statSnapshots7d'), s.snapshotsLast7) +
    cell(t('cam.statOpenHarvest'), s.openHarvestFlags) +
    cell(t('cam.statOpenFruiting'), s.openFruitingFlags) +
    cell(t('cam.statLabelled'), s.labelledSamples);
}

function renderCameraList(list) {
  const el = document.getElementById('cam-list');
  if (!el) return;
  if (!list.length) {
    el.innerHTML =
      '<div class="fs-sm" style="color:var(--c-text-muted);padding:8px 0">' + esc(t('cam.noCameras')) + '</div>';
    return;
  }
  const rows = list
    .map((c) => {
      const zone = c.zoneId ? esc(zoneDisplayName(c.zoneId)) : '<span style="color:var(--c-text-muted)">—</span>';
      const masked = maskRtspUrl(c.rtspUrl);
      const stateBadge = c.enabled
        ? `<span class="badge" style="background:#dcfce7;color:#166534">${esc(t('cam.enabled'))}</span>`
        : `<span class="badge" style="background:#fef3c7;color:#92400e">${esc(t('cam.disabled'))}</span>`;
      return `<div class="card" style="padding:10px;margin-bottom:8px;display:flex;gap:10px;align-items:center;flex-wrap:wrap">
          <div style="flex:1;min-width:200px">
            <div style="font-weight:600">${esc(c.name)} ${stateBadge}</div>
            <div class="fs-xs" style="color:var(--c-text-muted);font-family:monospace;word-break:break-all">${esc(masked)}</div>
            <div class="fs-xs" style="color:var(--c-text-muted)">${esc(t('cam.fieldZone'))}: ${zone}</div>
          </div>
          <div style="display:flex;gap:6px">
            <button class="btn btn-sm" data-cam-edit="${c.id}" data-i18n="cam.edit">Edit</button>
            <button class="btn btn-sm btn-r" data-cam-delete="${c.id}" data-i18n="cam.delete">Delete</button>
          </div>
        </div>`;
    })
    .join('');
  el.innerHTML = rows;
  el.querySelectorAll('[data-cam-edit]').forEach((b) =>
    b.addEventListener('click', () => openCameraEdit(parseInt(b.dataset.camEdit, 10)))
  );
  el.querySelectorAll('[data-cam-delete]').forEach((b) =>
    b.addEventListener('click', () => deleteCamera(parseInt(b.dataset.camDelete, 10)))
  );
}

function maskRtspUrl(url) {
  // Hide credentials (rtsp://user:pass@host -> rtsp://***@host) so admins
  // sharing screenshots don't leak passwords.
  if (!url) return '';
  return url.replace(/^(rtsp?:\/\/)([^:]+):([^@]+)@/i, '$1***:***@');
}

function renderCameraCalibForm(c) {
  const wrap = document.getElementById('cam-calib-form');
  if (!wrap) return;
  if (!c) {
    wrap.textContent = t('common.error');
    return;
  }
  wrap.innerHTML = CAM_CALIB_FIELDS.map(([key, label, kind]) => {
    const step = kind === 'int' ? '1' : '0.01';
    const val = c[key] != null ? c[key] : '';
    return `<div>
        <label class="fs-meta" style="font-weight:600;display:block" data-i18n="${label}">${esc(key)}</label>
        <input type="number" step="${step}" min="0" data-cam-calib="${key}" value="${esc(String(val))}" style="width:100%" />
      </div>`;
  }).join('');
  translatePage();
  const ts = c.updatedAt ? new Date(c.updatedAt).toLocaleString(loc()) : '—';
  document.getElementById('cam-calib-status').textContent = t('cam.lastUpdated') + ': ' + ts;
}

async function saveCameraCalibration() {
  const inputs = document.querySelectorAll('[data-cam-calib]');
  const patch = {};
  for (const el of inputs) {
    const v = el.value.trim();
    if (v === '') continue;
    const num = Number(v);
    if (!Number.isFinite(num) || num < 0) {
      document.getElementById('cam-calib-status').textContent = t('cam.invalidValue') + ': ' + el.dataset.camCalib;
      return;
    }
    patch[el.dataset.camCalib] = num;
  }
  try {
    const r = await authFetch('/api/camera/calibration', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(patch)
    });
    if (!r.ok) {
      const err = await r.json().catch(() => ({}));
      document.getElementById('cam-calib-status').textContent = t('common.error') + ': ' + (err.error || r.status);
      return;
    }
    const updated = await r.json();
    _cam.calibration = updated;
    renderCameraCalibForm(updated);
    document.getElementById('cam-calib-status').textContent = t('cam.saved');
  } catch (e) {
    document.getElementById('cam-calib-status').textContent = t('common.error') + ': ' + (e.message || '');
  }
}

function renderCameraFlags(flags) {
  const el = document.getElementById('cam-flags');
  if (!el) return;
  if (!flags || ((!flags.harvest || !flags.harvest.length) && (!flags.fruiting || !flags.fruiting.length))) {
    el.innerHTML = '<div class="fs-sm" style="color:var(--c-text-muted)">' + esc(t('cam.noOpenFlags')) + '</div>';
    return;
  }
  const row = (kind, f) => {
    const ago = f.flaggedAt ? new Date(f.flaggedAt).toLocaleString(loc()) : '—';
    const extra =
      kind === 'harvest'
        ? f.predictedHarvestAt
          ? esc(t('cam.predicted')) + ': ' + new Date(f.predictedHarvestAt).toLocaleString(loc())
          : ''
        : f.peakScore != null
          ? esc(t('cam.peakScore')) + ': ' + Number(f.peakScore).toFixed(2)
          : '';
    return `<div style="display:flex;gap:8px;align-items:center;padding:6px 0;border-bottom:1px solid var(--c-border)">
        <div style="flex:1;min-width:180px">
          <div><b>${esc(f.bagId)}</b> <span style="color:var(--c-text-muted)">${esc(f.batchId || '')}</span></div>
          <div class="fs-xs" style="color:var(--c-text-muted)">${esc(ago)}${extra ? ' · ' + extra : ''}</div>
        </div>
        <button class="btn btn-sm" data-cam-resolve="${kind}:${f.id}" data-i18n="cam.resolve">Resolve</button>
      </div>`;
  };
  let html = '';
  if (flags.harvest && flags.harvest.length) {
    html +=
      '<div style="font-weight:600;margin-bottom:4px">' +
      esc(t('cam.harvestFlags')) +
      '</div>' +
      flags.harvest.map((f) => row('harvest', f)).join('');
  }
  if (flags.fruiting && flags.fruiting.length) {
    html +=
      '<div style="font-weight:600;margin:10px 0 4px">' +
      esc(t('cam.fruitingFlags')) +
      '</div>' +
      flags.fruiting.map((f) => row('fruiting', f)).join('');
  }
  el.innerHTML = html;
  translatePage();
  el.querySelectorAll('[data-cam-resolve]').forEach((b) =>
    b.addEventListener('click', async () => {
      const [kind, id] = b.dataset.camResolve.split(':');
      try {
        const r = await authFetch('/api/camera/flags/' + kind + '/' + id + '/resolve', { method: 'POST' });
        if (!r.ok) throw new Error((await r.json().catch(() => ({}))).error || r.status);
        loadCameraTab();
      } catch (e) {
        toast(t('common.error') + ': ' + (e.message || ''), 'err');
      }
    })
  );
}

function renderCameraRecent(rows) {
  const el = document.getElementById('cam-recent');
  if (!el) return;
  if (!rows.length) {
    el.innerHTML = '<div style="color:var(--c-text-muted)">' + esc(t('cam.noRecent')) + '</div>';
    return;
  }
  const head = `<thead><tr>
      <th>${esc(t('cam.colTime'))}</th>
      <th>${esc(t('cam.colBag'))}</th>
      <th>${esc(t('cam.colDiameter'))}</th>
      <th>${esc(t('cam.colCount'))}</th>
      <th>${esc(t('cam.colConf'))}</th>
    </tr></thead>`;
  const body = rows
    .map((m) => {
      const dt = m.capturedAt ? new Date(m.capturedAt).toLocaleString(loc()) : '—';
      const dia = m.capDiameterMm != null ? Number(m.capDiameterMm).toFixed(1) + ' mm' : '—';
      const conf = m.detectionConf != null ? (Number(m.detectionConf) * 100).toFixed(0) + '%' : '—';
      return `<tr>
          <td>${esc(dt)}</td>
          <td>${esc(m.bagId)}</td>
          <td>${esc(dia)}</td>
          <td>${esc(String(m.mushroomCount || 0))}</td>
          <td>${esc(conf)}</td>
        </tr>`;
    })
    .join('');
  el.innerHTML = '<div style="overflow-x:auto"><table>' + head + '<tbody>' + body + '</tbody></table></div>';
}

function openCameraEdit(id) {
  _cam.editingId = id || null;
  const cam = id ? _cam.cameras.find((c) => c.id === id) : null;
  document.getElementById('cam-edit-title').textContent = id ? t('cam.editCamera') : t('cam.addCamera');
  document.getElementById('cam-edit-name').value = cam ? cam.name : '';
  document.getElementById('cam-edit-rtsp').value = cam ? cam.rtspUrl : '';
  document.getElementById('cam-edit-enabled').checked = cam ? !!cam.enabled : true;
  document.getElementById('cam-edit-status').textContent = '';
  // Populate zone dropdown from existing zones
  const sel = document.getElementById('cam-edit-zone');
  sel.innerHTML =
    `<option value="">${esc(t('cam.zoneNone'))}</option>` +
    zones.map((z) => `<option value="${esc(z.id)}">${esc(z.name || z.id)}</option>`).join('');
  sel.value = cam && cam.zoneId ? cam.zoneId : '';
  document.getElementById('m-cam-edit').classList.add('open');
  setTimeout(() => document.getElementById('cam-edit-name').focus(), 0);
}

function closeCameraEdit() {
  document.getElementById('m-cam-edit').classList.remove('open');
  _cam.editingId = null;
}

async function saveCameraEdit() {
  const payload = {
    name: document.getElementById('cam-edit-name').value.trim(),
    rtspUrl: document.getElementById('cam-edit-rtsp').value.trim(),
    zoneId: document.getElementById('cam-edit-zone').value || null,
    enabled: document.getElementById('cam-edit-enabled').checked
  };
  if (!payload.name) {
    document.getElementById('cam-edit-status').textContent = t('cam.fieldName') + ': ' + t('common.required');
    return;
  }
  if (!payload.rtspUrl) {
    document.getElementById('cam-edit-status').textContent = t('cam.fieldRtsp') + ': ' + t('common.required');
    return;
  }
  try {
    const url = _cam.editingId ? '/api/camera/cameras/' + _cam.editingId : '/api/camera/cameras';
    const method = _cam.editingId ? 'PUT' : 'POST';
    const r = await authFetch(url, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    if (!r.ok) {
      const err = await r.json().catch(() => ({}));
      document.getElementById('cam-edit-status').textContent = err.error || 'HTTP ' + r.status;
      return;
    }
    closeCameraEdit();
    loadCameraTab();
  } catch (e) {
    document.getElementById('cam-edit-status').textContent = e.message || t('common.error');
  }
}

async function deleteCamera(id) {
  const cam = _cam.cameras.find((c) => c.id === id);
  if (!cam) return;
  if (!(await askConfirm(t('cam.delete'), t('cam.confirmDelete', { name: cam.name }), t('cam.delete')))) return;
  try {
    const r = await authFetch('/api/camera/cameras/' + id, { method: 'DELETE' });
    if (!r.ok) throw new Error((await r.json().catch(() => ({}))).error || r.status);
    loadCameraTab();
  } catch (e) {
    toast(t('common.error') + ': ' + (e.message || ''), 'err');
  }
}

// Pixel calibration helper: load image into canvas, click two endpoints,
// compute pixel distance, divide by user-entered mm to get px/mm.
function initCameraPxCalib() {
  const fileInput = document.getElementById('cam-calib-image');
  const canvas = document.getElementById('cam-calib-canvas');
  const pxLabel = document.getElementById('cam-calib-px');
  const mmInput = document.getElementById('cam-calib-mm');
  const applyBtn = document.getElementById('cam-calib-apply');
  if (!fileInput || !canvas || !pxLabel || !mmInput || !applyBtn) return;
  const ctx = canvas.getContext('2d');
  let img = null;
  let p1 = null;
  let p2 = null;

  function redraw() {
    if (!img) return;
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    function dot(p, color) {
      ctx.beginPath();
      ctx.arc(p.x, p.y, 6, 0, 2 * Math.PI);
      ctx.fillStyle = color;
      ctx.fill();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 2;
      ctx.stroke();
    }
    if (p1) dot(p1, '#ea580c');
    if (p2) dot(p2, '#0284c7');
    if (p1 && p2) {
      ctx.strokeStyle = '#ea580c';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(p1.x, p1.y);
      ctx.lineTo(p2.x, p2.y);
      ctx.stroke();
    }
  }

  function updatePx() {
    if (p1 && p2) {
      const dx = p2.x - p1.x;
      const dy = p2.y - p1.y;
      const px = Math.sqrt(dx * dx + dy * dy);
      _cam.pxDistance = px;
      pxLabel.style.display = '';
      pxLabel.textContent = t('cam.pxMeasured', { px: px.toFixed(1) });
      applyBtn.disabled = false;
    } else {
      _cam.pxDistance = null;
      pxLabel.style.display = 'none';
      applyBtn.disabled = true;
    }
  }

  fileInput.addEventListener('change', () => {
    const f = fileInput.files && fileInput.files[0];
    if (!f) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const im = new Image();
      im.onload = () => {
        // Cap canvas at 800px wide so it fits on small screens
        const maxW = 800;
        const scale = im.width > maxW ? maxW / im.width : 1;
        canvas.width = Math.round(im.width * scale);
        canvas.height = Math.round(im.height * scale);
        canvas.style.display = '';
        img = im;
        p1 = null;
        p2 = null;
        updatePx();
        redraw();
      };
      im.src = e.target.result;
    };
    reader.readAsDataURL(f);
  });

  canvas.addEventListener('click', (e) => {
    if (!img) return;
    const rect = canvas.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * canvas.width;
    const y = ((e.clientY - rect.top) / rect.height) * canvas.height;
    if (!p1 || (p1 && p2)) {
      p1 = { x, y };
      p2 = null;
    } else {
      p2 = { x, y };
    }
    updatePx();
    redraw();
  });

  applyBtn.addEventListener('click', () => {
    if (!_cam.pxDistance) return;
    const mm = parseDecimal(mmInput.value);
    if (!Number.isFinite(mm) || mm <= 0) {
      toast(t('cam.invalidMm'), 'err');
      return;
    }
    const ratio = _cam.pxDistance / mm;
    const inp = document.querySelector('[data-cam-calib="pxPerMm"]');
    if (inp) {
      inp.value = ratio.toFixed(3);
      inp.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      document.getElementById('cam-calib-status').textContent = t('cam.calibratedFromImage', {
        ratio: ratio.toFixed(3)
      });
    }
  });
}

// ─── SERVER TAB ─────────────────────────────────────────────
function showServerTab() {
  showAdminSubTab('server');
}
async function loadServerTab() {
  const el = document.getElementById('server-info');
  if (!el) return;
  if (!currentUser || currentUser.role !== 'admin') {
    el.textContent = t('server.adminRequired');
    return;
  }
  try {
    const r = await authFetch('/api/health');
    const h = await r.json();
    const uptimeH = Math.floor(h.uptime / 3600);
    const uptimeM = Math.floor((h.uptime % 3600) / 60);
    const platLabel = h.platform === 'win32' ? 'Windows' : h.platform === 'darwin' ? 'macOS' : 'Linux';
    el.innerHTML =
      '<div><b>' +
      t('server.statusLabel') +
      ':</b> ' +
      esc(h.status) +
      '</div>' +
      '<div><b>' +
      t('server.versionLabel') +
      ':</b> ' +
      esc(h.version) +
      '</div>' +
      // The commit tells whether an update arrived; the version above never
      // changes. Missing without git on the server.
      '<div><b>' +
      t('server.codeLabel') +
      ':</b> ' +
      (h.code ? esc(h.code.commit) + (h.code.date ? ' · ' + esc(fmtDtTime(h.code.date)) : '') : '–') +
      '</div>' +
      (h.labChain ? serverKette(h.labChain) : '') +
      '<div><b>' +
      t('server.platformLabel') +
      ':</b> ' +
      platLabel +
      '</div>' +
      '<div><b>' +
      t('server.nodeLabel') +
      ':</b> ' +
      esc(h.nodeVersion || '–') +
      '</div>' +
      '<div><b>' +
      t('server.uptimeLabel') +
      ':</b> ' +
      uptimeH +
      'h ' +
      uptimeM +
      'm</div>' +
      '<div><b>' +
      t('server.sseLabel') +
      ':</b> ' +
      h.sseClients +
      '</div>' +
      (h.memory ? '<div><b>' + t('server.ramLabel') + ':</b> ' + h.memory.rss + ' MB</div>' : '');
    const stempeln = document.getElementById('btn-lab-stamp');
    if (stempeln) stempeln.addEventListener('click', labStempeln);
  } catch (e) {
    el.textContent = t('server.loadError');
  }
}
// Die Pruefkette des Laborbuchs in einer Zeile: ob der Verlauf noch so ist, wie
// er geschrieben wurde, der juengste Zeitstempel, ob die Signaturen der Stelle
// halten, und ob der letzte Versuch, einen zu holen, scheiterte. Darunter der
// Knopf, der gleich einen holt.
function serverKette(k) {
  const teile = [
    k.ok
      ? t('server.chainOk', { n: k.entries })
      : t('server.chainBroken', { id: k.broken && k.broken[0] ? k.broken[0].id : '?' })
  ];
  // Nachgetragene Eintraege sind kein Bruch, aber sie bleiben genannt.
  for (const a of k.adopted || []) {
    teile.push(t('server.chainAdopted', { n: a.count ?? '?', d: fmtDtTime(a.at), from: a.from ?? '?', to: a.to ?? '?' }));
  }
  const s = k.lastStamp;
  teile.push(s ? t('server.chainStamp', { d: fmtDtTime(s.genTime), id: s.historyId }) : t('server.chainNoStamp'));
  // Die Signaturen fuer sich, ueber alle Stempel: welche nicht halten, welche
  // sich nicht pruefen lassen, und sonst, dass alle geprueft sind. Ein Server
  // von vor der Pruefung schickt sie nicht mit.
  const sig = k.signatures;
  if (sig && k.stamps) {
    if (sig.bad) {
      // firstBad auch dann, wenn vor ihm zehn stehen, die sich nur nicht
      // pruefen lassen.
      const erster = sig.firstBad || (sig.problems || []).find((p) => p.signature === 'bad');
      teile.push(t('server.chainSigBad', { n: sig.bad, total: k.stamps, id: erster ? erster.historyId : '?' }));
    }
    if (sig.unchecked) teile.push(t('server.chainSigUnchecked', { n: sig.unchecked, total: k.stamps }));
    if (!sig.bad && !sig.unchecked) teile.push(t('server.chainSigOk'));
  }
  const an = !!(k.stamping && k.stamping.tsa);
  if (!an) teile.push(t('server.chainStampOff'));
  else if (k.stamping.lastError) {
    teile.push(
      t('server.chainStampErr', { d: fmtDtTime(k.stamping.lastError.at), err: k.stamping.lastError.message })
    );
  }
  // Die juengste zurueckgespielte Sicherung in einer Zeile: wann, wie viel sie
  // verworfen hat, und wo der Stand davor liegt. Alle stehen im Laborbuch.
  const zurueck = k.restores || [];
  const r = zurueck[zurueck.length - 1];
  const sicherung = r
    ? [
        t('server.restoreWhen', { d: fmtDtTime(r.at), user: r.user || '—', n: r.discarded ?? '?' }),
        r.kept ? t('server.restoreKept', { file: r.kept }) : '',
        zurueck.length > 1 ? t('server.restoreEarlier', { n: zurueck.length - 1 }) : ''
      ].filter(Boolean)
    : null;
  return (
    '<div><b>' +
    esc(t('server.chainLabel')) +
    ':</b> ' +
    esc(teile.join(' · ')) +
    '</div>' +
    (an
      ? '<div><button type="button" class="btn btn-sm fs-xs" id="btn-lab-stamp">' +
        esc(t('server.chainStampBtn')) +
        '</button> <span id="lab-stamp-status" class="fs-xs"></span></div>'
      : '') +
    (sicherung ? '<div><b>' + esc(t('server.restoreLabel')) + ':</b> ' + esc(sicherung.join(' · ')) + '</div>' : '')
  );
}
// Was die Antwort auf "Zeitstempel jetzt holen" heisst.
function labStempelText(r) {
  if (!r || r.error) return t('server.chainStampErr', { d: fmtDtTime(new Date().toISOString()), err: (r && r.error) || '' });
  if (r.status === 'stamped') return t('server.chainStampDone', { d: fmtDtTime(r.stamp.genTime) });
  if (r.status === 'current') return t('server.chainStampCurrent');
  if (r.status === 'empty') return t('server.chainStampEmpty');
  if (r.status === 'off') return t('server.chainStampOff');
  return t('server.chainStampWait');
}
async function labStempeln() {
  const btn = document.getElementById('btn-lab-stamp');
  const status = document.getElementById('lab-stamp-status');
  if (btn) btn.disabled = true;
  const r = await apiPost('/api/lab-history/timestamp', {});
  if (status) status.textContent = labStempelText(r);
  if (btn) btn.disabled = false;
  // Ein neuer Stempel steht dann auch in der Zeile darueber.
  if (r && r.status === 'stamped') setTimeout(loadServerTab, 1500);
}
function restartServer() {
  confirm2(t('server.restartTitle'), t('server.restartMsg'), t('server.restartConfirm'), async () => {
    const btn = document.getElementById('btn-server-restart');
    const status = document.getElementById('server-restart-status');
    btn.disabled = true;
    btn.textContent = t('server.restarting');
    status.style.display = 'block';
    status.style.color = 'var(--c-text-muted)';
    status.textContent = t('server.updateStatus');
    try {
      await authFetch('/api/server/restart', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: '{}'
      });
      status.textContent = t('server.waitReconnect');
      let attempts = 0;
      const poll = setInterval(async () => {
        attempts++;
        try {
          const r = await fetch('/api/health');
          if (r.ok) {
            clearInterval(poll);
            window.location.reload();
          }
        } catch (e) {
          /* still down */
        }
        if (attempts > 60) {
          clearInterval(poll);
          status.textContent = t('server.noResponse');
          status.style.color = 'var(--c-red-dark)';
          btn.disabled = false;
          btn.textContent = t('server.updateBtn');
        }
      }, 3000);
    } catch (e) {
      status.textContent = t('common.error') + ': ' + e.message;
      status.style.color = 'var(--c-red-dark)';
      btn.disabled = false;
      btn.textContent = t('server.updateBtn');
    }
  });
}

// ─── MCP SETTINGS ───────────────────────────────────────────
let _mcpToken = '';
async function loadMcpSettings() {
  try {
    const r = await authFetch('/api/mcp/config');
    if (!r.ok) return;
    const cfg = await r.json();
    document.getElementById('mcp-enabled').checked = cfg.enabled;
    document.getElementById('mcp-url').value = cfg.connectorUrl || '';
    toggleMcpSections(cfg.enabled);
    const banner = document.getElementById('mcp-status-banner');
    if (cfg.enabled) {
      banner.style.display = 'block';
      banner.style.background = 'var(--c-primary-light)';
      banner.style.border = '1px solid var(--c-green-border)';
      banner.style.color = 'var(--c-green-dark)';
      banner.textContent = t('mcp.active');
    } else {
      banner.style.display = 'none';
    }
    const statusR = await authFetch('/api/mcp/status');
    if (statusR.ok) {
      const st = await statusR.json();
      if (st.activeSessions > 0) {
        banner.style.display = 'block';
        banner.style.background = 'var(--c-primary-light)';
        banner.style.border = '1px solid var(--c-green-border)';
        banner.style.color = 'var(--c-green-dark)';
        banner.textContent = t('mcp.sessions').replace('{n}', st.activeSessions);
      }
    }
    if (cfg.enabled) loadOAuthClients();
  } catch (e) {
    /* non-admin */
  }
}
function toggleMcpSections(enabled) {
  document.getElementById('mcp-url-section').style.display = enabled ? 'block' : 'none';
  document.getElementById('mcp-token-section').style.display = enabled ? 'block' : 'none';
  document.getElementById('mcp-guide-card').style.display = enabled ? 'block' : 'none';
  document.getElementById('mcp-diag-card').style.display = enabled ? 'block' : 'none';
  document.getElementById('mcp-oauth-card').style.display = enabled ? 'block' : 'none';
}
function showMcpStatus(msg, color) {
  const el = document.getElementById('mcp-status');
  el.style.display = 'block';
  el.style.color = color || '#888';
  el.textContent = msg;
  setTimeout(() => {
    el.style.display = 'none';
  }, 8000);
}
async function saveMcpSettings() {
  try {
    const r = await apiPost('/api/mcp/config', { enabled: document.getElementById('mcp-enabled').checked });
    if (r.error) {
      showMcpStatus(t('mcp.error').replace('{msg}', r.error), 'var(--c-red-dark)');
    } else {
      showMcpStatus(t('mcp.saved'), 'var(--c-green-dark)');
      loadMcpSettings();
    }
  } catch (e) {
    showMcpStatus(t('mcp.error').replace('{msg}', e.message), 'var(--c-red-dark)');
  }
}
async function generateMcpToken() {
  try {
    const r = await authFetch('/api/mcp/generate-token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: '{}'
    });
    const data = await r.json();
    if (data.error) {
      showMcpStatus(t('mcp.error').replace('{msg}', data.error), 'var(--c-red-dark)');
      return;
    }
    _mcpToken = data.token;
    document.getElementById('mcp-token-display').textContent = data.token;
    document.getElementById('mcp-token-display').style.display = 'block';
    document.getElementById('mcp-copy-token-btn').style.display = 'inline-flex';
    showMcpStatus(t('mcp.keyGenerated'), 'var(--c-green-dark)');
  } catch (e) {
    showMcpStatus(t('mcp.error').replace('{msg}', e.message), 'var(--c-red-dark)');
  }
}
async function revokeMcpToken() {
  if (!(await askConfirm(t('mcp.revokeKey'), t('mcp.revokeKeyConfirm'), t('mcp.revokeKey')))) return;
  try {
    const r = await authFetch('/api/mcp/token', { method: 'DELETE' });
    const data = await r.json();
    if (data.error) {
      showMcpStatus(t('mcp.error').replace('{msg}', data.error), 'var(--c-red-dark)');
      return;
    }
    _mcpToken = null;
    document.getElementById('mcp-token-display').textContent = '';
    document.getElementById('mcp-token-display').style.display = 'none';
    document.getElementById('mcp-copy-token-btn').style.display = 'none';
    showMcpStatus(t('mcp.keyRevoked'), 'var(--c-green-dark)');
  } catch (e) {
    showMcpStatus(t('mcp.error').replace('{msg}', e.message), 'var(--c-red-dark)');
  }
}

async function runMcpDiagnostics() {
  const el = document.getElementById('mcp-diag-result');
  el.innerHTML = '<p style="color:var(--c-text-muted)">' + t('mcp.diagRunning') + '</p>';
  try {
    const r = await authFetch('/api/mcp/diagnostics');
    if (!r.ok) {
      el.innerHTML = '<p style="color:var(--c-red-dark)">' + t('mcp.diagFailed') + '</p>';
      return;
    }
    const d = await r.json();
    let html = '<table class="fs-meta" style="width:100%;border-collapse:collapse">';
    const row = (label, val, color) =>
      '<tr><td style="padding:4px 8px;font-weight:600;white-space:nowrap;vertical-align:top">' +
      label +
      '</td><td style="padding:4px 8px;color:' +
      (color || '#333') +
      '">' +
      val +
      '</td></tr>';
    const checks = d.checks || {};
    for (const [k, v] of Object.entries(checks)) {
      const pass = v.startsWith('PASS');
      html += row(k, esc(v), pass ? 'var(--c-green-dark)' : 'var(--c-red-dark)');
    }
    html += row('Protocol', esc(d.protocol));
    html += row(
      'Base URL',
      '<code class="fs-xs" style="background:#f1f5f9;padding:1px 4px;border-radius:3px">' +
        esc(d.connectorUrl) +
        '</code>'
    );
    html += row(t('mcp.diagAutoClients'), String(d.oauthClients?.auto || 0));
    html += row(t('mcp.diagManualClients'), String(d.oauthClients?.manual || 0));
    html += row(t('mcp.diagSessions'), String(d.activeSessions || 0));
    html += '</table>';
    if (d.hint)
      html +=
        '<div class="fs-xs" style="margin-top:8px;padding:8px 10px;border-radius:6px;background:var(--c-primary-light);border:1px solid var(--c-green-border);color:var(--c-green-dark)">' +
        esc(d.hint) +
        '</div>';
    el.innerHTML = html;
  } catch (e) {
    el.innerHTML = '<p style="color:var(--c-red-dark)">Error: ' + esc(e.message) + '</p>';
  }
}

// ─── OAUTH CLIENT MANAGEMENT ────────────────────────────────
function showOAuthStatus(msg, color) {
  const el = document.getElementById('oauth-client-status');
  el.style.display = 'block';
  el.style.color = color || '#888';
  el.textContent = msg;
  setTimeout(() => {
    el.style.display = 'none';
  }, 8000);
}
async function loadOAuthClients() {
  try {
    const r = await authFetch('/api/mcp/oauth-clients');
    if (!r.ok) return;
    const data = await r.json();
    const list = document.getElementById('oauth-client-list');
    if (!list) return;
    if (!data.clients || data.clients.length === 0) {
      list.innerHTML = '<p class="fs-meta" style="color:var(--c-text-muted)">' + t('mcp.noClients') + '</p>';
      return;
    }
    list.innerHTML =
      '<table class="fs-meta" style="width:100%;border-collapse:collapse"><thead><tr>' +
      '<th style="text-align:left;padding:6px;border-bottom:1px solid var(--c-border)">' +
      t('mcp.clientName') +
      '</th>' +
      '<th style="text-align:left;padding:6px;border-bottom:1px solid var(--c-border)">Client ID</th>' +
      '<th style="text-align:left;padding:6px;border-bottom:1px solid var(--c-border)">' +
      t('mcp.created') +
      '</th>' +
      '<th style="text-align:left;padding:6px;border-bottom:1px solid var(--c-border)">' +
      t('mcp.activeSessions') +
      '</th>' +
      '<th style="padding:6px;border-bottom:1px solid var(--c-border)"></th></tr></thead><tbody>' +
      data.clients
        .map((c) => {
          const name = c.clientName || t('mcp.unnamed');
          return (
            '<tr>' +
            '<td style="padding:6px">' +
            esc(name) +
            '</td>' +
            '<td style="padding:6px;font-family:monospace">' +
            esc(c.clientId.slice(0, 8)) +
            '…</td>' +
            '<td style="padding:6px">' +
            esc(c.created ? c.created.slice(0, 10) : '') +
            '</td>' +
            '<td style="padding:6px;text-align:center">' +
            c.activeSessions +
            '</td>' +
            '<td style="padding:6px"><button class="btn btn-sm fs-xs" style="padding:2px 8px;color:var(--c-red-dark)" data-oauth-action="delete" data-client-id="' +
            esc(c.clientId) +
            '" data-auto="' +
            (c.autoRegistered ? 1 : 0) +
            '">' +
            t('mcp.deleteClient') +
            '</button></td></tr>'
          );
        })
        .join('') +
      '</tbody></table>';
    list.onclick = function (e) {
      const btn = e.target.closest('[data-oauth-action="delete"]');
      if (!btn) return;
      deleteOAuthClient(btn.dataset.clientId, btn.dataset.auto === '1');
    };
  } catch (e) {
    console.error('loadOAuthClients:', e);
  }
}
async function deleteOAuthClient(clientId, isAuto) {
  const frage = isAuto ? t('mcp.confirmDeleteAuto') : t('mcp.confirmDelete');
  if (!(await askConfirm(t('mcp.deleteClient'), frage, t('mcp.deleteClient')))) return;
  try {
    const r = await authFetch('/api/mcp/oauth-clients/' + encodeURIComponent(clientId), { method: 'DELETE' });
    const data = await r.json();
    if (data.error) {
      showOAuthStatus(t('mcp.error').replace('{msg}', data.error), 'var(--c-red-dark)');
      return;
    }
    showOAuthStatus(t('mcp.clientDeleted'), 'var(--c-green-dark)');
    loadOAuthClients();
  } catch (e) {
    showOAuthStatus(t('mcp.error').replace('{msg}', e.message), 'var(--c-red-dark)');
  }
}

// ─── SCAN LOG ────────────────────────────────────────────────
let logSortCol = 'time',
  logSortDir = 'desc',
  logDisplayLimit = 200;
function toggleLogSort(col) {
  if (logSortCol === col) logSortDir = logSortDir === 'desc' ? 'asc' : 'desc';
  else {
    logSortCol = col;
    logSortDir = 'desc';
  }
  renderLog();
}
function renderLog() {
  const q = (document.getElementById('log-q').value || '').toLowerCase();
  const actionF = document.getElementById('log-action-filter').value;
  const dateFrom = document.getElementById('log-date-from').value;
  const dateTo = document.getElementById('log-date-to').value;
  const body = document.getElementById('log-body');
  // The ✕ used to be an inline onclick with the row's values pasted into it.
  // esc() is right for markup but not for that: inside an attribute the parser
  // turns &#39; back into ' before the JavaScript is compiled, so a value that
  // merely *looked* escaped ran as code. Reading the values back out of
  // data-* attributes keeps them data — a string the browser hands over, never
  // something it compiles. Wired once, because renderLog() replaces the rows
  // but not the container they sit in.
  if (body && !body._lgDelWired) {
    body._lgDelWired = true;
    body.addEventListener('click', (ev) => {
      const btn = ev.target.closest && ev.target.closest('.lg-del');
      if (!btn || !body.contains(btn)) return;
      deleteLogEntry(btn, btn.dataset.time, btn.dataset.batch, btn.dataset.action, btn.dataset.bag);
    });
  }
  let items = [...scanLog];
  // Filters
  if (q) items = items.filter((e) => JSON.stringify(e).toLowerCase().includes(q));
  if (actionF) items = items.filter((e) => e.action === actionF);
  if (dateFrom) items = items.filter((e) => e.time >= dateFrom);
  if (dateTo) items = items.filter((e) => e.time < dateTo + 'T23:59:59');
  // Sort
  const dir = logSortDir === 'desc' ? -1 : 1;
  items.sort((a, b) => {
    const av = a[logSortCol] || '',
      bv = b[logSortCol] || '';
    return av < bv ? -dir : av > bv ? dir : 0;
  });
  // Sort indicators
  document.querySelectorAll('[id^="log-sort-"]').forEach((el) => (el.textContent = ''));
  const si = document.getElementById('log-sort-' + logSortCol);
  if (si) si.textContent = logSortDir === 'desc' ? '▼' : '▲';
  // Count display
  const total = scanLog.length,
    filtered = items.length;
  const countEl = document.getElementById('log-count');
  if (countEl)
    countEl.textContent =
      filtered === total ? t('log.entries', { n: total }) : t('log.entriesFiltered', { n: filtered, total: total });
  // Paginate
  const hasMore = items.length > logDisplayLimit;
  items = items.slice(0, logDisplayLimit);
  const now = Date.now(),
    h24 = 24 * 60 * 60 * 1000;
  body.innerHTML = items.length
    ? items
        .map((e) => {
          const isRecent = now - new Date(e.time).getTime() < h24;
          return `<tr><td data-mlabel="${esc(t('settings.time'))}" class="lg-time fs-micro" style="color:var(--c-text-muted)">${fmtDtTime(e.time)}</td><td class="fs-xs" data-mlabel="${esc(t('settings.user'))}">${esc(e.user) || '\u2014'}</td><td data-mlabel="${esc(t('settings.action'))}"><span class="badge ${e.action === 'ADD' ? 'b-add' : e.action === 'REMOVE' ? 'b-remove' : e.action === 'HARVEST' ? 'b-harvest' : 'b-move'}">${esc(e.action)}</span></td><td class="fs-micro" data-mlabel="${esc(t('batch.batchId'))}" style="font-family:monospace">${esc(e.batch) || '\u2014'}</td><td class="fs-micro" data-mlabel="${esc(t('settings.bag'))}" style="font-family:monospace">${esc(e.bag) || '\u2014'}</td><td data-mlabel="${esc(t('settings.from'))}">${esc(e.from) || '\u2014'}</td><td data-mlabel="${esc(t('settings.to'))}">${esc(e.to) || '\u2014'}</td><td data-mlabel="${esc(t('batch.species'))}">${e.species ? spDot(e.species) + esc(e.species) : '\u2014'}</td><td class="lg-actions">${isRecent ? '<button class="btn-xs lg-del fs-micro" style="padding:2px 6px" data-time="' + esc(e.time) + '" data-batch="' + esc(e.batch || '') + '" data-action="' + esc(e.action) + '" data-bag="' + esc(e.bag || '') + '" title="' + esc(t('common.delete')) + '">✕</button>' : ''}</td></tr>`;
        })
        .join('')
    : '<tr><td colspan="9" class="empty">' + t('settings.noScans') + '</td></tr>';
  const loadMore = document.getElementById('log-load-more');
  if (loadMore) loadMore.style.display = hasMore ? 'block' : 'none';
}
function deleteLogEntry(btn, time, batch, action, bag) {
  confirm2(
    t('log.deleteEntry'),
    t('log.deleteEntryMsg', { action: action, batch: batch, time: fmtDtTime(time) }),
    t('common.delete'),
    () => {
      // Match on bag too: a bulk ADD/MOVE writes the same time+batch+action to
      // every bag, so without the bag the ✕ on one row deleted the first
      // matching row (and its server id) instead of the clicked one.
      const match = (e) => e.time === time && e.batch === batch && e.action === action && (e.bag || '') === bag;
      const idx = scanLog.findIndex(match);
      if (idx === -1) return;
      const entry = scanLog[idx];
      scanLog.splice(idx, 1);
      const mi = movements.findIndex(match);
      if (mi !== -1) movements.splice(mi, 1);
      const serverId = entry._serverId || entry.id;
      if (serverId) apiDelete('/api/scan-log/' + serverId);
      renderLog();
      renderStatus();
    }
  );
}
function clearLog() {
  confirm2(
    t('settings.clearLog'),
    t('settings.clearLogMsg', { n: scanLog.length }),
    t('settings.clearLogBtn'),
    async () => {
      await apiDelete('/api/scan-log');
      scanLog = [];
      renderLog();
    }
  );
}

// ─── INVENTORY ───────────────────────────────────────────────
const MAT_LABELS = { hardwood: 'Hardwood pellets', wheatbran: 'Wheat bran', gypsum: 'Gypsum', grain: 'Grain', corn: 'Corn meal' };
const MAT_COLORS = { hardwood: '#92400e', wheatbran: '#166534', gypsum: '#1e40af', grain: '#6b21a8', corn: '#a16207' };
const MAT_BG = { hardwood: '#fff7ed', wheatbran: '#f0fdf4', gypsum: '#eff6ff', grain: '#faf5ff', corn: '#fefce8' };
const MAT_BORDER = { hardwood: '#fed7aa', wheatbran: '#bbf7d0', gypsum: '#bfdbfe', grain: '#e9d5ff', corn: '#fef08a' };

// Wie weit zurück gezählt wird, um zu gewichten. Kurz genug, dass eine
// Umstellung im Sortiment durchschlägt, lang genug, dass eine ruhige Woche
// den Durchschnitt nicht kippt.
const AVG_FENSTER_TAGE = 90;

// Beutel je Sorte im Fenster — das Gewicht, mit dem ihr Rezept zählt.
function _avgGewichte() {
  const grenze = Date.now() - AVG_FENSTER_TAGE * 86400000;
  const w = {};
  for (const b of batches) {
    if (!b.strainId) continue;
    const t = Date.parse(b.created);
    if (!Number.isFinite(t) || t < grenze) continue;
    w[b.strainId] = (w[b.strainId] || 0) + (Number(b.qty) || 0);
  }
  return w;
}

// Gewichtetes Mittel eines Rezeptfeldes. Null, wenn keine Sorte einen
// brauchbaren Wert beisteuert — dann greift die nächste Stufe.
function _avgMittel(sorten, feld, gewicht) {
  let summe = 0;
  let gesamt = 0;
  for (const s of sorten) {
    const v = Number(s[feld]);
    if (!Number.isFinite(v) || v <= 0) continue;
    const g = gewicht(s);
    if (!(g > 0)) continue;
    summe += v * g;
    gesamt += g;
  }
  return gesamt > 0 ? summe / gesamt : null;
}

// Der Durchschnitt für die Lagerschätzung — gerechnet, nicht getippt.
//
// Vier Stufen, absteigend: nach der Produktion der letzten 90 Tage gewichtet;
// sonst jedes Rezept gleich; sonst der zuletzt gespeicherte Wert; sonst die
// eingebaute Vorgabe. `quelle` sagt der Oberfläche, welche Stufe gegriffen hat,
// damit dort nicht einfach eine Zahl ohne Herkunft steht.
function getAvgComp() {
  const gespeichert = inventory.avgComposition || {};
  const gew = _avgGewichte();
  const nachProduktion = Object.keys(gew).length > 0;
  const g = (s) => (nachProduktion ? gew[s.id] || 0 : 1);
  const alle = (mushroomStrains || []).filter((s) => s.recBatchType);
  // Holz und Kleie nur aus Block-Rezepten: eine CVG-Sorte hat ihre Masse im
  // Kokos und würde den Schnitt nach unten ziehen, obwohl sie kein Holz nimmt.
  const bloecke = alle.filter((s) => s.recBatchType !== 'grain' && (s.recSubstrate || 'holzkleie') !== 'cvg');
  let quelle = nachProduktion ? 'produktion' : 'rezepte';
  const stufe = (sorten, feld) => {
    const w = _avgMittel(sorten, feld, g);
    if (w != null) return w;
    const m = _avgMittel(sorten, feld, () => 1);
    if (m != null && quelle === 'produktion') quelle = 'rezepte';
    return m;
  };
  const _gyp = _avgMittel(bloecke, 'recGypsumPct', g) ?? _avgMittel(bloecke, 'recGypsumPct', () => 1);
  const nimm = (wert, schluessel, vorgabe) => {
    if (wert != null) return Math.round(wert * 10) / 10;
    quelle = 'gespeichert';
    return gespeichert[schluessel] ?? vorgabe;
  };
  return {
    hwPct: nimm(stufe(bloecke, 'recHardwoodPct'), 'hwPct', 75),
    wbPct: nimm(stufe(bloecke, 'recWheatbranPct'), 'wbPct', 25),
    rhPct: nimm(stufe(bloecke, 'recRhPct'), 'rhPct', 63),
    bagKg: nimm(stufe(bloecke, 'recBagKg'), 'bagKg', NB_BAG_KG_DEFAULT),
    // Kein Rezeptfeld trägt die Größe einer Körnerbrut-Tüte. Die bleibt als
    // Einstellung stehen, und nur die.
    grainBagKg: gespeichert.grainBagKg ?? 1,
    // Gips stand als einziger Anteil dieser Schätzung fest eingebaut auf 1 %,
    // obwohl rec_gypsum_pct daneben liegt und der Mischlauf ihn längst liest.
    // Gemittelt wird wie oben, aber an `quelle` vorbei: die meisten Rezepte
    // führen Gips als Flag ohne Zahl, und ein fehlender Gipsanteil sagt nichts
    // darüber, woher Holz, Kleie und Blockgewicht kommen. Trägt kein Rezept
    // einen Anteil, bleibt es bei 1 % — dann rechnet die Schätzung wie bisher.
    gypPct: _gyp != null ? Math.round(_gyp * 10) / 10 : (gespeichert.gypPct ?? 1),
    grainRhPct: nimm(stufe(alle, 'recGrainRhPct'), 'grainRhPct', 52),
    quelle,
    rezepte: bloecke.length,
    beutel: Object.values(gew).reduce((s, n) => s + n, 0)
  };
}

function estBagsFromMat(mat, stockKg) {
  // Estimate how many fruiting blocks (or grain bags) can be made from this material
  // For HW/WB: dry matter per bag = bagKg × (1 − rh/100), split by avg %
  // For grain: dry grain per bag = grainBagKg × (1 − grainRhPct/100); stock is dry.
  // Gypsum rides on the same dry matter, at the share the recipes carry.
  const c = getAvgComp();
  if (mat === 'grain') {
    const dryPerGrainBag = c.grainBagKg * (c.grainRhPct > 0 ? 1 - c.grainRhPct / 100 : 1);
    return {
      bags: dryPerGrainBag > 0 ? Math.floor(stockKg / dryPerGrainBag) : 0,
      bagKg: c.grainBagKg,
      isGrain: true
    };
  }
  const dryPerBag = mtDryKg(c.bagKg, c.rhPct); // dry matter per bag
  let matPerBag = 0;
  if (mat === 'hardwood') matPerBag = dryPerBag * (c.hwPct / 100);
  if (mat === 'wheatbran') matPerBag = dryPerBag * (c.wbPct / 100);
  if (mat === 'gypsum') matPerBag = dryPerBag * (c.gypPct / 100);
  const bags = matPerBag > 0 ? Math.floor(stockKg / matPerBag) : 0;
  return { bags, matPerBag, bagKg: c.bagKg, isGrain: false };
}

function renderInvStock() {
  if (!inventory.stock) inventory.stock = { hardwood: 0, wheatbran: 0, gypsum: 0, grain: 0 };
  if (!inventory.thresholds)
    inventory.thresholds = {
      hardwood: { minKg: 50 },
      wheatbran: { minKg: 20 },
      gypsum: { minKg: 5 },
      grain: { minKg: 10 }
    };
  if (!inventory.avgComposition)
    inventory.avgComposition = { hwPct: 75, wbPct: 25, rhPct: 63, bagKg: 3, grainBagKg: 1, grainRhPct: 52 };

  const cards = document.getElementById('inv-cards');
  cards.innerHTML = Object.keys(MAT_LABELS)
    .map((mat) => {
      const stock = inventory.stock[mat] || 0;
      const thresh = inventory.thresholds[mat] || { minKg: 0 };
      const low = thresh.minKg > 0 && stock < thresh.minKg;
      const { bags, bagKg, matPerBag, isGrain } = estBagsFromMat(mat, stock);
      const pct =
        thresh.minKg > 0
          ? Math.min(100, Math.round((stock / Math.max(stock, thresh.minKg * 3)) * 100))
          : Math.min(100, Math.round((stock / Math.max(stock, 100)) * 100));
      const estNote = isGrain
        ? t('inv.grainBagsEst', { n: bags, kg: bagKg })
        : t('inv.blocksEst', { n: '<strong>' + bags + '</strong>', kg: bagKg }) +
          ' <span class="fs-micro" style="color:var(--c-text-muted)">' +
          t('inv.avgEstimate') +
          '</span>';
      return `<div style="background:${MAT_BG[mat]};border:1px solid ${low ? 'var(--c-red)' : MAT_BORDER[mat]};border-radius:10px;padding:14px 16px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
        <div class="fs-meta" style="font-weight:600;color:${MAT_COLORS[mat]}">${MAT_LABELS[mat]}</div>
        ${low ? `<span class="fs-micro" style="background:var(--c-red-light);color:var(--c-red-dark);padding:2px 7px;border-radius:99px;font-weight:600">${t('inv.lowStock')}</span>` : ''}
      </div>
      <div class="fs-floor" style="--fs-own:1.625rem;font-weight:700;color:var(--c-text);margin-bottom:2px">${stock.toFixed(1)} <span class="fs-floor" style="--fs-own:0.875rem;font-weight:400;color:var(--c-text-muted)">kg</span></div>
      <div style="height:5px;border-radius:3px;background:rgba(0,0,0,.08);overflow:hidden;margin-bottom:8px">
        <div style="height:100%;border-radius:3px;background:${low ? 'var(--c-red)' : MAT_COLORS[mat]};width:${pct}%;transition:width .3s"></div>
      </div>
      <div class="fs-meta" style="color:var(--c-text-sec);line-height:1.6">${estNote}</div>
      ${thresh.minKg > 0 ? `<div class="fs-xs" style="color:${low ? 'var(--c-red-dark)' : 'var(--c-text-muted)'};margin-top:2px">${t('inv.alertBelow', { n: thresh.minKg })}</div>` : ''}
      <button class="btn btn-sm fs-xs" onclick="openStab('inv','delivery')" style="margin-top:8px">${t('inv.logDelivery')}</button>
      ${(() => {
        const sups = getSuppliersForMat(mat);
        if (!sups.length) return '';
        return `<div class="fs-xs" style="margin-top:8px;padding-top:6px;border-top:1px solid rgba(0,0,0,.06);color:var(--c-text-sec)">
          <span style="font-weight:600;color:${low ? 'var(--c-red-dark)' : 'var(--c-text-muted)'}">${low ? t('inv.reorderFrom') : t('inv.suppliers')}:</span>
          ${sups.map((s) => (safeHref(s.url) ? `<a href="${safeHref(s.url)}" target="_blank" rel="noopener" style="color:var(--c-blue);margin-left:4px">${esc(s.name)}</a>` : `<span style="margin-left:4px">${esc(s.name)}</span>`)).join(',')}
        </div>`;
      })()}
    </div>`;
    })
    .join('');
  renderThresholds();
}

function renderThresholds() {
  const el = document.getElementById('inv-thresholds');
  if (!el) return;
  const c = getAvgComp();

  // Per-material alert thresholds
  const threshHtml = `<div style="overflow-x:auto;margin-bottom:16px"><table>
    <thead><tr><th>${t('inv.thMaterial')}</th><th>${t('inv.thInStock')}</th><th>${t('inv.thAlertBelow')}</th><th>${t('inv.thEstBags')}</th></tr></thead>
    <tbody>
    ${Object.keys(MAT_LABELS)
      .map((mat) => {
        const stock = inventory.stock[mat] || 0;
        const t = inventory.thresholds[mat] || { minKg: 0 };
        const { bags } = estBagsFromMat(mat, stock);
        return `<tr>
        <td style="font-weight:500;color:${MAT_COLORS[mat]}">${MAT_LABELS[mat]}</td>
        <td style="font-weight:600">${stock.toFixed(2)} kg</td>
        <td><input class="fs-meta" type="text" inputmode="decimal" value="${esc(t.minKg)}" style="width:80px;padding:3px 6px" onchange="updateThreshold('${mat}','minKg',this.value)" /></td>
        <td class="fs-meta" style="color:var(--c-text-sec)">~${bags} bags <span class="fs-micro" style="color:var(--c-text-muted)">(avg)</span></td>
      </tr>`;
      })
      .join('')}
    </tbody>
  </table></div>`;

  // Average composition settings
  const compHtml = `<div style="background:var(--c-bg);border-radius:8px;padding:12px">
    <div class="fs-xs" style="font-weight:600;color:var(--c-text-muted);text-transform:uppercase;letter-spacing:.07em;margin-bottom:10px">
      ${t('inv.avgCompTitle')}
    </div>
    <p class="fs-meta" style="color:var(--c-text-muted);margin-bottom:10px;line-height:1.6">
      ${t('inv.avgCompDesc')}
    </p>
    <div class="g6" style="gap:8px">
      ${[
        ['inv.hwPct', c.hwPct, '%'],
        ['inv.wbPct', c.wbPct, '%'],
        ['inv.gypsumPct', c.gypPct, '%'],
        ['inv.waterPct', c.rhPct, '%'],
        ['inv.blockWeight', c.bagKg, 'kg'],
        ['inv.grainWaterPct', c.grainRhPct, '%']
      ]
        .map(
          ([k, v, e]) =>
            `<div><label class="fs-xs">${t(k)}</label>
               <div class="avg-wert">${esc(String(v))}<span class="avg-einheit">${e}</span></div></div>`
        )
        .join('')}
      <div><label class="fs-xs">${t('inv.grainBagWeight')}</label>
        <input type="text" inputmode="decimal" value="${esc(c.grainBagKg)}" class="fs-sm" style="padding:5px 8px" onchange="updateAvgComp('grainBagKg',this.value)" /></div>
    </div>
    <div class="fs-xs" style="margin-top:8px;color:var(--c-text-muted);line-height:1.7">
      <div>${esc(
        c.quelle === 'produktion'
          ? t('inv.avgFromProduction', { n: c.rezepte, bags: c.beutel, days: AVG_FENSTER_TAGE })
          : c.quelle === 'rezepte'
            ? t('inv.avgFromRecipes', { n: c.rezepte })
            : t('inv.avgFromStored')
      )}</div>
      <div>${esc(
        t('inv.avgCompNote', {
          bag: c.bagKg,
          hw: (mtDryKg(c.bagKg, c.rhPct) * (c.hwPct / 100)).toFixed(3),
          wb: (mtDryKg(c.bagKg, c.rhPct) * (c.wbPct / 100)).toFixed(3),
          rh: c.rhPct,
          gbag: c.grainBagKg,
          grain: mtDryKg(c.grainBagKg, c.grainRhPct).toFixed(3),
          grh: c.grainRhPct
        })
      )}</div>
    </div>
  </div>`;
  el.innerHTML = threshHtml + compHtml;
}

// Nur noch die Körnerbrut-Tüte: alles andere kommt aus den Rezepten und ließe
// sich hier nur scheinbar ändern.
function updateAvgComp(key, val) {
  if (key !== 'grainBagKg') return;
  if (!inventory.avgComposition) inventory.avgComposition = {};
  inventory.avgComposition[key] = parseDecimal(val) || 0;
  saveInvConfig();
  renderInvStock();
}

function updateThreshold(mat, key, val) {
  if (!inventory.thresholds) inventory.thresholds = {};
  if (!inventory.thresholds[mat]) inventory.thresholds[mat] = { minKg: 0 };
  inventory.thresholds[mat][key] = parseDecimal(val) || 0;
  saveInvConfig();
  renderInvStock();
}

function delMatChange() {
  const mat = document.getElementById('del-mat').value;
  const stock = inventory.stock?.[mat] || 0;
  document.getElementById('del-current').textContent = t('inv.currentStock', { n: stock.toFixed(2) });
  document.getElementById('del-kg').value = '';
  document.getElementById('del-preview').style.display = 'none';
}
function delPreview() {
  const mat = document.getElementById('del-mat').value;
  const kg = parseDecimal(document.getElementById('del-kg').value) || 0;
  const el = document.getElementById('del-preview');
  if (!kg) {
    el.style.display = 'none';
    return;
  }
  const cur = inventory.stock?.[mat] || 0;
  el.innerHTML =
    t('inv.afterDeliveryLabel') +
    '<strong>' +
    (cur + kg).toFixed(2) +
    ' kg</strong> (' +
    cur.toFixed(2) +
    ' + ' +
    kg +
    ' kg)';
  el.style.display = 'block';
}
function adjMatChange() {
  const mat = document.getElementById('adj-mat').value;
  const stock = inventory.stock?.[mat] || 0;
  document.getElementById('adj-current').textContent = t('inv.currentStock', { n: stock.toFixed(2) });
  document.getElementById('adj-absolute').value = '';
  document.getElementById('adj-delta').value = '';
  document.getElementById('adj-preview').style.display = 'none';
}
function adjPreview(mode) {
  const mat = document.getElementById('adj-mat').value;
  const cur = inventory.stock?.[mat] || 0;
  const el = document.getElementById('adj-preview');
  let newVal, diff;
  if (mode === 'absolute') {
    const abs = parseDecimal(document.getElementById('adj-absolute').value);
    if (isNaN(abs)) {
      el.style.display = 'none';
      return;
    }
    document.getElementById('adj-delta').value = '';
    newVal = Math.max(0, abs);
    diff = newVal - cur;
    el.innerHTML =
      t('inv.setToLabel') +
      '<strong>' +
      newVal.toFixed(2) +
      ' kg</strong> ' +
      (diff >= 0 ? '+' : '') +
      diff.toFixed(2) +
      t('inv.kgFromCurrent');
  } else {
    const delta = parseDecimal(document.getElementById('adj-delta').value);
    if (isNaN(delta)) {
      el.style.display = 'none';
      return;
    }
    document.getElementById('adj-absolute').value = '';
    newVal = Math.max(0, cur + delta);
    diff = delta;
    el.innerHTML =
      t('inv.newTotalLabel') +
      '<strong>' +
      newVal.toFixed(2) +
      ' kg</strong> (' +
      (diff >= 0 ? '+' : '') +
      diff.toFixed(2) +
      ' kg)';
  }
  el.style.display = 'block';
}
function logDelivery() {
  const mat = document.getElementById('del-mat').value;
  const kg = parseDecimal(document.getElementById('del-kg').value) || 0;
  const note = document.getElementById('del-note').value.trim();
  if (kg <= 0) {
    fieldError('del-kg', t('inv.enterQty'));
    return;
  }
  if (!inventory.stock) inventory.stock = { hardwood: 0, wheatbran: 0, gypsum: 0, grain: 0 };
  const prev = inventory.stock[mat] || 0;
  inventory.stock[mat] = prev + kg;
  document.getElementById('del-kg').value = '';
  document.getElementById('del-note').value = '';
  document.getElementById('del-preview').style.display = 'none';
  openStab('inv', 'stock');
  renderInvStock();
  // Confirm only once the server has it. /api/inventory/delta is NOT in the
  // service worker's offline queue (that covers scan-log and contamination
  // reports only), so an offline booking is simply lost — and the optimistic
  // local number is overwritten by the next poll. Reporting success for a
  // delivery that never landed is how stock silently drifts from the floor.
  invDelta(mat, kg, 'delivery', note || 'delivery').then((r) => {
    if (r && r.error) {
      inventory.stock[mat] = prev;
      renderInvStock();
      setFb('err', t('inv.deliveryFailed', { err: r.error }));
      return;
    }
    setFb(
      'ok',
      'Delivery logged: +' + kg + 'kg ' + MAT_LABELS[mat] + ' now ' + inventory.stock[mat].toFixed(2) + 'kg total'
    );
  });
}
function logAdjustment() {
  const mat = document.getElementById('adj-mat').value;
  const absVal = document.getElementById('adj-absolute').value;
  const deltaVal = document.getElementById('adj-delta').value;
  const reason = document.getElementById('adj-reason').value.trim() || 'Manual adjustment';
  if (!inventory.stock) inventory.stock = { hardwood: 0, wheatbran: 0, gypsum: 0, grain: 0 };
  const cur = inventory.stock[mat] || 0;
  let newStock, delta;
  if (absVal !== '') {
    newStock = Math.max(0, parseDecimal(absVal) || 0);
    delta = newStock - cur;
  } else if (deltaVal !== '') {
    delta = parseDecimal(deltaVal) || 0;
    newStock = Math.max(0, cur + delta);
  } else {
    // Neither box filled in, so point at the absolute one — it is the first of
    // the pair and the one that needs no arithmetic to use.
    fieldError('adj-absolute', t('inv.enterAmount'));
    return;
  }
  const prevStock = inventory.stock[mat] || 0;
  inventory.stock[mat] = newStock;
  document.getElementById('adj-absolute').value = '';
  document.getElementById('adj-delta').value = '';
  document.getElementById('adj-reason').value = '';
  document.getElementById('adj-preview').style.display = 'none';
  openStab('inv', 'stock');
  renderInvStock();
  // Same as logDelivery: /api/inventory/set has no offline queue, so confirm
  // only after the server accepts it. A stocktake correction reported as saved
  // and then silently reverted by the next poll is worse than an error.
  invSetAbsolute(mat, newStock, 'adjustment', reason).then((r) => {
    if (r && r.error) {
      inventory.stock[mat] = prevStock;
      renderInvStock();
      setFb('err', t('inv.adjustFailed', { err: r.error }));
      return;
    }
    setFb(
      'ok',
      'Adjusted ' +
        MAT_LABELS[mat] +
        ': ' +
        (delta >= 0 ? '+' : '') +
        delta.toFixed(2) +
        'kg now ' +
        newStock.toFixed(2) +
        'kg'
    );
  });
}

function renderInvLog() {
  const filter = document.getElementById('inv-log-filter').value;
  const body = document.getElementById('inv-log-body');
  if (!inventory.log || !inventory.log.length) {
    body.innerHTML = '<tr><td colspan="6" class="empty">' + t('inv.noUsageHistory') + '</td></tr>';
    return;
  }
  const rows = [...inventory.log]
    .reverse()
    .filter((e) => filter === 'all' || e.mat === filter)
    .slice(0, 200);
  // Build running totals per material going forwards for display
  body.innerHTML = rows
    .map(
      (e) => `<tr>
    <td class="fs-micro" style="color:var(--c-text-muted)">${fmtDtTime(e.time)}</td>
    <td style="color:${MAT_COLORS[e.mat]};font-weight:500">${MAT_LABELS[e.mat]}</td>
    <td style="font-weight:600;color:${e.deltaKg < 0 ? 'var(--c-red-dark)' : 'var(--c-green-dark)'}">${e.deltaKg > 0 ? '+' : ''}${e.deltaKg.toFixed(2)} kg</td>
    <td class="fs-xs">${(e.running || 0).toFixed(1)} kg</td>
    <td><span class="badge ${e.type === 'delivery' ? 'b-add' : e.type === 'adjustment' ? 'b-move' : 'b-harvest'}">${esc(e.type)}</span></td>
    <td class="fs-xs" style="color:var(--c-text-sec)">${esc(e.ref) || '—'}</td>
  </tr>`
    )
    .join('');
}

// Show low-stock alerts in dashboard
function getInvAlerts() {
  if (!inventory.stock || !inventory.thresholds) return [];
  return Object.keys(MAT_LABELS)
    .filter((mat) => {
      const stock = inventory.stock[mat] || 0;
      const thresh = (inventory.thresholds[mat] || {}).minKg || 0;
      return thresh > 0 && stock < thresh;
    })
    .map((mat) => {
      const stock = inventory.stock[mat] || 0;
      const thresh = inventory.thresholds[mat].minKg;
      const { bags } = estBagsFromMat(mat, stock);
      const sups = getSuppliersForMat(mat);
      const supNote = sups.length ? ` — ${t('inv.reorderFrom')}: ${sups.map((s) => s.name).join(', ')}` : '';
      return {
        text: `Low stock: ${MAT_LABELS[mat]}`,
        detail: `${stock.toFixed(1)} kg remaining (≈${bags} bags) — below ${thresh}kg threshold${supNote}`,
        urgent: stock < thresh * 0.5,
        warn: true,
        species: null
      };
    });
}

// Show low lab stock alerts in dashboard
function getLabAlerts() {
  if (!inventory.labThresholds) return [];
  const counts = getLabStockCounts();
  const breakdown = getLabStrainBreakdown();
  const alerts = [];
  // Two floors, and they measure different things. labThresholds is about the
  // shelf as a whole, so it is compared against the total — for every type, as
  // it always was. The per-Sorte minimums v79 added are about one mushroom, and
  // were not read here at all: a Sorte sitting at zero slants with min_mc = 5
  // turned its tile red, raised a task, and still said nothing on the dashboard.
  // Applying the farm-wide number per Sorte instead would be the other error —
  // ten slants in total is not ten slants each.
  LAB_TYPES.forEach((type) => {
    const farmMin = inventory.labThresholds[type] || 0;
    const count = counts[type] || 0;
    if (farmMin > 0 && count < farmMin) {
      alerts.push({
        text: t('lab.lowLabAlert', { type: getLabLabel(type) }),
        detail: t('lab.belowMin', { n: count, min: farmMin }),
        urgent: count === 0,
        warn: true
      });
    }
    // Die Untergrenzen je Sorte liest buildLabMinTasks(), und nur die. Hier
    // standen sie ein zweites Mal: dieselbe Aufschlüsselung, dieselbe
    // Bedingung, und beide Ergebnisse landeten in derselben Tagesliste — eine
    // gerissene Untergrenze als zwei Zeilen. Schlimmer noch, diese Kopie
    // überging die Programm-Kennzeichnung, die die andere achtet, also blieb
    // eine geparkte Sorte hier stehen und rief jeden Tag weiter. Genau die
    // Dauerwarnung, gegen die v78 geschrieben wurde.
  });
  return alerts;
}

// ─── SUPPLIERS ───────────────────────────────────────────────
function renderSuppliers() {
  const el = document.getElementById('suppliers-list');
  if (!el) return;
  if (!suppliers.length) {
    el.innerHTML = `<p class="fs-sm" style="color:var(--c-text-muted)">${t('inv.noSuppliers')}</p>`;
    return;
  }
  const grouped = {};
  Object.keys(MAT_LABELS).forEach((m) => (grouped[m] = []));
  suppliers.forEach((s) => {
    if (grouped[s.mat]) grouped[s.mat].push(s);
  });
  el.innerHTML = Object.keys(MAT_LABELS)
    .map((mat) => {
      const list = grouped[mat];
      if (!list.length) return '';
      return `<div style="margin-bottom:16px">
      <div class="fs-meta" style="font-weight:600;color:${MAT_COLORS[mat]};margin-bottom:6px">${MAT_LABELS[mat]}</div>
      <div style="overflow-x:auto"><table>
        <thead><tr><th>${t('inv.supplierName')}</th><th>${t('inv.supplierUrl')}</th><th>${t('inv.supplierPhone')}</th><th>${t('inv.supplierNotes')}</th><th></th></tr></thead>
        <tbody>${list
          .map(
            (s) => `<tr>
          <td style="font-weight:500">${esc(s.name)}</td>
          <td>${safeHref(s.url) ? `<a class="fs-meta" href="${safeHref(s.url)}" target="_blank" rel="noopener" style="color:var(--c-blue)">${esc(s.url)}</a>` : esc(s.url) || '-'}</td>
          <td class="fs-meta">${s.phone ? esc(s.phone) : '-'}</td>
          <td class="fs-meta" style="color:var(--c-text-sec)">${s.notes ? esc(s.notes) : '-'}</td>
          <td style="white-space:nowrap">
            <button class="btn btn-sm fs-xs" onclick="editSupplier(${s.id})">${t('inv.editSupplier')}</button>
            <button class="btn btn-sm fs-xs" onclick="removeSupplier(${s.id})" style="color:var(--c-red-dark)">${t('inv.deleteSupplier')}</button>
          </td>
        </tr>`
          )
          .join('')}</tbody>
      </table></div>
    </div>`;
    })
    .join('');
}

function editSupplier(id) {
  const existing = id ? suppliers.find((s) => s.id === id) : null;
  const matOpts = Object.keys(MAT_LABELS)
    .map((m) => `<option value="${m}"${existing && existing.mat === m ? ' selected' : ''}>${MAT_LABELS[m]}</option>`)
    .join('');
  const html = `<div style="display:flex;flex-direction:column;gap:10px">
    <div><label>${t('inv.material')}</label><select id="sup-mat">${matOpts}</select></div>
    <div><label>${t('inv.supplierName')}</label><input type="text" id="sup-name" value="${existing ? esc(existing.name) : ''}" placeholder="e.g. Beispiel Pellets GmbH" /></div>
    <div><label>${t('inv.supplierUrl')}</label><input type="text" id="sup-url" value="${existing && existing.url ? esc(existing.url) : ''}" placeholder="https://..." /></div>
    <div><label>${t('inv.supplierPhone')}</label><input type="text" id="sup-phone" value="${existing && existing.phone ? esc(existing.phone) : ''}" placeholder="+49..." /></div>
    <div><label>${t('inv.supplierNotes')}</label><input type="text" id="sup-notes" value="${existing && existing.notes ? esc(existing.notes) : ''}" placeholder="e.g. order number, contact person" /></div>
  </div>`;
  document.getElementById('m-title').textContent = existing ? t('inv.editSupplier') : t('inv.addSupplier');
  document.getElementById('m-body').innerHTML = html;
  document.getElementById('m-ok').textContent = existing ? t('inv.editSupplier') : t('inv.addSupplier');
  confirmCb = async () => {
    const s = {
      mat: document.getElementById('sup-mat').value,
      name: document.getElementById('sup-name').value.trim(),
      url: document.getElementById('sup-url').value.trim(),
      phone: document.getElementById('sup-phone').value.trim(),
      notes: document.getElementById('sup-notes').value.trim()
    };
    if (!s.name) {
      fieldError('sup-name', t('zones.nameRequired'));
      return;
    }
    if (existing) s.id = existing.id;
    const r = await apiPost('/api/suppliers', s);
    if (r && r.id && !existing) {
      s.id = r.id;
      suppliers.push(s);
    } else if (existing) {
      Object.assign(existing, s);
    }
    renderSuppliers();
    renderInvStock();
    setFb('ok', t('inv.supplierSaved'));
  };
  document.getElementById('m-confirm').classList.add('open');
}

// ── Pickup locations ────────────────────────────────────────
// Retired ones stay in the table, greyed out. A calendar event may still point
// at one, and a list that hides it turns "the market we stopped doing" into a
// blank field nobody can explain.
//
// The buttons are wired by delegation rather than the `onclick="fn(id)"` this
// file otherwise uses. Not a style preference: a handler only ever named inside
// an HTML string is invisible to ESLint, so each one costs a permanent
// "defined but never used" warning, and the lint budget is a deliberate ratchet
// (see eslint.config.js — 14 of the existing warnings are exactly this).
function renderPickupLocations() {
  const el = document.getElementById('pickuploc-list');
  if (!el) return;
  if (!el.dataset.wired) {
    el.dataset.wired = '1';
    el.addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-act]');
      if (!btn) return;
      const id = Number(btn.dataset.id);
      if (btn.dataset.act === 'edit') editPickupLocation(id);
      else if (btn.dataset.act === 'retire') retirePickupLocation(id);
      else if (btn.dataset.act === 'reactivate') setPickupLocationActive(id, true);
    });
  }
  if (!pickupLocations.length) {
    el.innerHTML = `<p class="fs-sm" style="color:var(--c-text-muted)">${t('pickupLoc.none')}</p>`;
    return;
  }
  el.innerHTML = `<div style="overflow-x:auto"><table>
    <thead><tr><th>${t('pickupLoc.name')}</th><th>${t('pickupLoc.address')}</th><th>${t('pickupLoc.order')}</th><th></th></tr></thead>
    <tbody>${pickupLocations
      .map(
        (l) => `<tr${l.active ? '' : ' style="opacity:.55"'}>
      <td style="font-weight:500">${esc(l.name)}${l.active ? '' : ` <span class="fs-xs" style="font-weight:400;color:var(--c-text-muted)">(${t('pickupLoc.retired')})</span>`}</td>
      <td class="fs-meta" style="color:var(--c-text-sec)">${l.address ? esc(l.address) : '-'}</td>
      <td class="fs-meta">${l.sortOrder}</td>
      <td style="white-space:nowrap">
        <button class="btn btn-sm fs-xs" data-act="edit" data-id="${l.id}">${t('pickupLoc.edit')}</button>
        ${
          l.active
            ? `<button class="btn btn-sm fs-xs" data-act="retire" data-id="${l.id}" style="color:var(--c-red-dark)">${t('pickupLoc.retire')}</button>`
            : `<button class="btn btn-sm fs-xs" data-act="reactivate" data-id="${l.id}">${t('pickupLoc.reactivate')}</button>`
        }
      </td>
    </tr>`
      )
      .join('')}</tbody>
  </table></div>`;
}

// Every field says what it does, under itself. One paragraph at the foot used
// to cover the name and the address, and it sat directly beneath Reihenfolge —
// the field it did not mention — so the sentence read as an explanation of the
// number above it and left the number unexplained. Three fields, three hints,
// each where the hand already is.
function editPickupLocation(id) {
  const existing = id ? pickupLocations.find((l) => l.id === id) : null;
  const hint = (key) =>
    `<div class="fs-xs" style="color:var(--c-text-muted);margin-top:2px;line-height:1.5">${esc(t(key))}</div>`;
  const html = `<div style="display:flex;flex-direction:column;gap:10px">
    <div><label>${t('pickupLoc.name')}</label><input type="text" id="ploc-name" maxlength="120" value="${existing ? esc(existing.name) : ''}" placeholder="${esc(t('pickupLoc.namePh'))}" />${hint('pickupLoc.nameHint')}</div>
    <div><label>${t('pickupLoc.address')}</label><input type="text" id="ploc-address" maxlength="200" value="${existing && existing.address ? esc(existing.address) : ''}" placeholder="${esc(t('pickupLoc.addressPh'))}" />${hint('pickupLoc.addressHint')}</div>
    <div><label>${t('pickupLoc.order')}</label><input type="number" id="ploc-sort" step="1" value="${existing ? Number(existing.sortOrder) || 0 : 0}" />${hint('pickupLoc.orderHint')}</div>
  </div>`;
  document.getElementById('m-title').textContent = existing ? t('pickupLoc.edit') : t('pickupLoc.add');
  document.getElementById('m-body').innerHTML = html;
  document.getElementById('m-ok').textContent = t('common.save');
  confirmCb = async () => {
    const l = {
      name: document.getElementById('ploc-name').value.trim(),
      address: document.getElementById('ploc-address').value.trim(),
      sortOrder: parseInt(document.getElementById('ploc-sort').value, 10) || 0,
      active: existing ? existing.active !== false : true
    };
    if (!l.name) {
      toast(t('zones.nameRequired'), 'err');
      return;
    }
    if (existing) l.id = existing.id;
    const r = await apiPost('/api/pickup-locations', l);
    if (!r) return;
    if (existing) Object.assign(existing, l);
    else pickupLocations.push({ ...l, id: r.id });
    pickupLocations.sort((a, b) => a.sortOrder - b.sortOrder || a.name.localeCompare(b.name));
    renderPickupLocations();
    setFb('ok', t('pickupLoc.saved'));
  };
  document.getElementById('m-confirm').classList.add('open');
}

async function retirePickupLocation(id) {
  const l = pickupLocations.find((x) => x.id === id);
  if (!l) return;
  if (!(await askConfirm(t('pickupLoc.retire'), t('pickupLoc.confirmRetire', { name: l.name }), t('pickupLoc.retire'))))
    return;
  const r = await apiDelete('/api/pickup-locations/' + id);
  if (!r) return;
  l.active = false;
  renderPickupLocations();
  setFb('ok', t('pickupLoc.saved'));
}

async function setPickupLocationActive(id, active) {
  const l = pickupLocations.find((x) => x.id === id);
  if (!l) return;
  const r = await apiPost('/api/pickup-locations', { ...l, active });
  if (!r) return;
  l.active = active;
  renderPickupLocations();
  setFb('ok', t('pickupLoc.saved'));
}

async function removeSupplier(id) {
  const s = suppliers.find((x) => x.id === id);
  if (!s) return;
  confirm2(
    t('inv.deleteSupplier'),
    'Remove ' + s.name + ' (' + MAT_LABELS[s.mat] + ')?',
    t('inv.deleteSupplier'),
    async () => {
      const r = await apiDelete('/api/suppliers/' + id);
      if (r && r.error) {
        setFb('err', t('common.error') + ': ' + r.error);
        return;
      }
      suppliers = suppliers.filter((x) => x.id !== id);
      renderSuppliers();
      renderInvStock();
      setFb('ok', t('inv.supplierDeleted'));
    }
  );
}

function getSuppliersForMat(mat) {
  return suppliers.filter((s) => s.mat === mat);
}

// ─── USB STICK BACKUP ────────────────────────────────────────
// The start screen reminds admins once a day; Settings → Backup sets sticks up
// and shows what happened. The server notices a plugged-in stick on its own
// (scripts/usb-backup.js) and announces every change as the SSE event
// "usb-backup", so this side asks when told — plus once a minute, which is how
// "done for today" turns into "due" after midnight, and every two seconds
// while a backup runs, in case the event stream is down.
let _usb = null;
let _usbDrives = null;
let _usbKey = null;
let _usbSetupOpen = false;
let _usbTimer = null;

function _usbAdmin() {
  return !!(currentUser && currentUser.role === 'admin');
}

async function loadUsbBackup() {
  clearTimeout(_usbTimer);
  if (!_usbAdmin()) {
    _usb = null;
    renderUsbReminder();
    return;
  }
  try {
    _usb = await apiGet('/api/usb-backup');
  } catch (e) {
    // The last answer stays on screen; the next event or tick asks again.
  }
  renderUsbReminder();
  renderUsbCard();
  const running = !!(_usb && _usb.run && _usb.run.state === 'running');
  _usbTimer = setTimeout(loadUsbBackup, running ? 2000 : 60000);
}

function _usbPct(run) {
  if (!run || !run.bytesTotal) return 0;
  return Math.min(100, Math.floor((run.bytesDone / run.bytesTotal) * 100));
}

// "today 09:12", "yesterday 17:40", or the date: when the last backup was
// is what the reminder is about, and a timestamp makes the reader do the sum.
function _usbWhen(iso) {
  const d = new Date(iso);
  const hm = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  const today = new Date();
  const yesterday = new Date(today.getFullYear(), today.getMonth(), today.getDate() - 1);
  if (localDateStr(d) === localDateStr(today)) return t('usb.today', { time: hm });
  if (localDateStr(d) === localDateStr(yesterday)) return t('usb.yesterday', { time: hm });
  return fmtDtTime(d);
}

function _usbSize(n) {
  if (n === null || n === undefined) return '–';
  if (n >= 1e9) return (n / 1e9).toLocaleString(loc(), { maximumFractionDigits: 1 }) + ' GB';
  return Math.max(1, Math.round(n / 1e6)).toLocaleString(loc()) + ' MB';
}

// The server answers with a code; every code has a sentence in each language.
const USB_ERR_CODES = [
  'NOT_A_DRIVE',
  'SAME_DISK',
  'NEEDS_KEY',
  'HAS_KEY',
  'EXISTS',
  'WRONG_KEY',
  'BAD_KEY',
  'FORMAT',
  'NO_STICK',
  'NOT_PRESENT',
  'BUSY',
  'FULL',
  'READ_ONLY',
  'GONE',
  'NOT_EMPTY',
  'SHRUNK',
  'HELD',
  'DAMAGED',
  'STATE',
  'FAILED'
];
function _usbErrText(code) {
  return t('usb.err.' + (USB_ERR_CODES.includes(code) ? code : 'FAILED'));
}

function _usbReminderText(s) {
  if (s.reminder === 'running') return t('usb.remRunning', { pct: _usbPct(s.run) });
  if (s.reminder === 'state') return '⚠ ' + t('usb.err.STATE');
  if (s.reminder === 'setup') return t('usb.remSetup');
  if (s.reminder === 'first') return t('usb.remFirst');
  if (s.reminder === 'error') return '⚠ ' + t('usb.remError', { why: _usbErrText(s.run && s.run.error && s.run.error.code) });
  if (s.reminder === 'gaps') return '⚠ ' + t('usb.remGaps');
  if (s.reminder === 'remove') return '✓ ' + t('usb.remRemove');
  return s.lastSuccess ? t('usb.remDue', { when: _usbWhen(s.lastSuccess.time) }) : t('usb.remDueNever');
}

function _usbBindReminder(el) {
  if (el.dataset.bound) return;
  el.dataset.bound = '1';
  el.addEventListener('click', () => {
    go('settings', 'n-settings');
    const tab = document.getElementById('st-settings-backup');
    if (tab) tab.click();
  });
}

// Two lines: the backup (due, running, done, failed), and beside it, never
// instead of it, a recovery key nobody has confirmed as put away yet.
function renderUsbReminder() {
  const el = document.getElementById('wk-usb');
  const keyEl = document.getElementById('wk-usb-key');
  if (keyEl) {
    _usbBindReminder(keyEl);
    keyEl.hidden = !(_usb && _usb.enabled !== false && _usb.configured && !_usb.keyConfirmed);
    keyEl.textContent = '⚠ ' + t('usb.remKey');
  }
  if (!el) return;
  _usbBindReminder(el);
  const r = _usb && _usb.reminder;
  el.hidden = !r;
  if (!r) return;
  el.className = 'wk-usb wk-usb-' + r;
  el.textContent = _usbReminderText(_usb);
}

// The key field for the stick in `root`: an id per drive.
function _usbConnectId(root) {
  return 'usb-connect-key-' + encodeURIComponent(root).replace(/[^A-Za-z0-9]/g, '_');
}

// A plugged-in stick a backup may be written to (as the server decides it).
function _usbUsable(p) {
  return !!(p && p.registered && !p.otherKey && p.supported && !p.sameDisk);
}

function _usbStatusLine(s) {
  if (!s.configured) return t('usb.notSetUp');
  if (!s.lastSuccess) return t('usb.noBackupYet');
  return (
    t('usb.lastBackup', { when: _usbWhen(s.lastSuccess.time), label: s.lastSuccess.label }) +
    ' · ' +
    tp('usb.newPhotos', s.lastSuccess.photosNew)
  );
}

function _usbProgressHtml(run) {
  const text =
    run.phase === 'photos' && run.total
      ? t('usb.progressPhotos', { label: run.label, done: run.done, total: run.total })
      : t('usb.progressDb', { label: run.label });
  return (
    '<div class="usb-progress"><progress class="usb-bar" max="100" value="' +
    _usbPct(run) +
    '"></progress><div class="fs-meta">' +
    esc(text) +
    '</div></div>'
  );
}

function renderUsbCard() {
  const body = document.getElementById('usb-body');
  if (!body) return;
  // Someone typing a recovery key into the card: the card is drawn on every
  // data change of anyone, every usb-backup event and once a minute, and
  // each redraw took the field away under their fingers (on a phone, the
  // keyboard with it). It waits until they have left the field.
  const fokus = document.activeElement;
  if (fokus && body.contains && body.contains(fokus) && /^usb-connect-key-/.test(fokus.id || '')) return;
  const s = _usb;
  if (!s) {
    body.innerHTML = '<div class="fs-meta">' + esc(t('usb.loading')) + '</div>';
    return;
  }
  const running = !!(s.run && s.run.state === 'running');
  // Switched off on this server: nothing to set up or plug in here.
  if (s.enabled === false) {
    body.innerHTML = '<div class="usb-msg">' + esc(t('usb.disabled')) + '</div>';
    return;
  }
  let h = '<div class="usb-status">' + esc(_usbStatusLine(s)) + '</div>';
  if (s.stateError) h += '<div class="usb-msg usb-msg-err">⚠ ' + esc(t('usb.err.STATE')) + '</div>';
  // Until somebody confirms the key is put away, the card says so first.
  if (s.configured && !s.keyConfirmed) h += '<div class="usb-msg usb-msg-err">⚠ ' + esc(t('usb.keyUnconfirmed')) + '</div>';
  if (running) h += _usbProgressHtml(s.run);
  else if (s.firstRunPending) h += '<div class="usb-msg usb-msg-err">' + esc(t('usb.firstPending')) + '</div>';
  else if (s.reminder === 'error') {
    const code = s.run && s.run.error && s.run.error.code;
    h += '<div class="usb-msg usb-msg-err">⚠ ' + esc(_usbErrText(code)) + '</div>';
    // Far less than last time is either a mistake or meant; only a person
    // can tell which, so the backup waits for one.
    // For the stick that stopped, by its id: with a second stick plugged in,
    // the server would otherwise take the first it finds.
    const failedStick = s.run && s.run.stickId;
    if (code === 'SHRUNK' && s.present.some((p) => p.id === failedStick && _usbUsable(p))) {
      h +=
        '<div class="usb-row"><button type="button" class="btn btn-r" data-usb="run-force" data-id="' +
        esc(failedStick) +
        '">' +
        esc(t('usb.forceGo')) +
        '</button></div>';
    }
  } else if (s.reminder === 'remove') h += '<div class="usb-msg usb-msg-ok">✓ ' + esc(t('usb.remRemove')) + '</div>';
  // What the last backup could not read on the PC is not on the stick.
  const ls = s.lastSuccess;
  if (!running && ls && (ls.skipped || ls.unreadable)) {
    const parts = [];
    if (ls.skipped) parts.push(tp('usb.gapsFiles', ls.skipped));
    if (ls.unreadable) parts.push(tp('usb.gapsFolders', ls.unreadable));
    h +=
      '<div class="usb-msg usb-msg-err">⚠ ' +
      esc(parts.join(' ')) +
      (ls.missing && ls.missing.length
        ? '<div class="fs-meta">' + esc(t('usb.gapsExamples', { list: ls.missing.join(', ') })) + '</div>'
        : '') +
      '</div>';
  }

  // The sticks a backup can go to right now. With more than one plugged in,
  // each gets its own button, so the backup goes where it was asked for.
  const usable = running ? [] : s.present.filter(_usbUsable);
  if (s.sticks.length) {
    h += '<ul class="usb-sticks">';
    for (const k of s.sticks) {
      const last = k.lastSuccess ? t('usb.stickLast', { when: _usbWhen(k.lastSuccess.time) }) : t('usb.stickNever');
      h +=
        '<li class="usb-stick"><div class="usb-stick-main"><span class="usb-stick-name">' +
        esc(k.label) +
        '</span>' +
        (k.present ? ' <span class="usb-badge">' + esc(t('usb.present')) + '</span>' : '') +
        '<div class="fs-meta">' +
        esc(last) +
        (k.lastError ? ' · ⚠ ' + esc(_usbErrText(k.lastError.code)) : '') +
        '</div></div>' +
        (usable.length > 1 && usable.some((p) => p.id === k.id)
          ? '<button type="button" class="btn btn-sm btn-p" data-usb="run" data-id="' +
            esc(k.id) +
            '">' +
            esc(t('usb.runNow')) +
            '</button>'
          : '') +
        '<button type="button" class="btn btn-sm" data-usb="forget" data-id="' +
        esc(k.id) +
        '" data-label="' +
        esc(k.label) +
        '"' +
        (running ? ' disabled' : '') +
        '>' +
        esc(t('usb.forget')) +
        '</button></li>';
    }
    h += '</ul>';
  }

  // A stick folder of ours on the app's own disk: a copy, never written to.
  for (const p of s.present.filter((x) => x.registered && x.sameDisk)) {
    h += '<div class="usb-msg">' + esc(t('usb.copyOnPc', { name: p.root })) + '</div>';
  }
  // A stick that is plugged in but not one of ours.
  for (const p of s.present.filter((x) => !x.registered)) {
    const name = p.label ? p.root + ' (' + p.label + ')' : p.root;
    if (!p.supported) h += '<div class="usb-msg">' + esc(t('usb.foreignNewer', { name })) + '</div>';
    else if (!s.configured) {
      // One field per stick, each with its own id: with one id for all of
      // them, Connect read the first field whichever row it was in. A key
      // being typed survives the redraw, in its own field.
      const fieldId = _usbConnectId(p.root);
      const typed = document.getElementById(fieldId);
      h +=
        '<div class="usb-connect"><div class="usb-msg">' +
        esc(t('usb.foreignConnect', { name })) +
        '</div><div class="usb-row"><input type="text" id="' +
        esc(fieldId) +
        '" autocomplete="off" spellcheck="false" placeholder="' +
        esc(t('usb.keyPh')) +
        '" value="' +
        esc(typed ? typed.value : '') +
        '"><button type="button" class="btn btn-p" data-usb="connect" data-root="' +
        esc(p.root) +
        '" data-input="' +
        esc(fieldId) +
        '">' +
        esc(t('usb.connect')) +
        '</button></div></div>';
    } else if (p.otherKey) h += '<div class="usb-msg">' + esc(t('usb.foreignOtherKey', { name })) + '</div>';
    else h += '<div class="usb-msg">' + esc(t('usb.foreignForgotten', { name })) + '</div>';
  }

  h += '<div class="usb-row">';
  if (usable.length === 1) {
    h +=
      '<button type="button" class="btn btn-p" data-usb="run" data-id="' +
      esc(usable[0].id) +
      '">' +
      esc(t('usb.runNow')) +
      '</button>';
  }
  if (!running) {
    h +=
      '<button type="button" class="btn" data-usb="setup-open">' +
      esc(t(s.configured ? 'usb.setupAnother' : 'usb.setupFirst')) +
      '</button>';
  }
  if (s.configured) h += '<button type="button" class="btn" data-usb="key">' + esc(t('usb.keyShow')) + '</button>';
  h += '</div>';
  body.innerHTML = h;
}

function renderUsbSetup() {
  const box = document.getElementById('usb-setup');
  if (!box) return;
  box.hidden = !_usbSetupOpen;
  if (!_usbSetupOpen) {
    box.innerHTML = '';
    return;
  }
  const configured = !!(_usb && _usb.configured);
  let h = '<div class="usb-sub">' + esc(t('usb.setupTitle')) + '</div>';
  h += '<p class="fs-meta">' + esc(t('usb.setupHint')) + '</p>';
  if (!_usbDrives) h += '<div class="fs-meta">' + esc(t('usb.searching')) + '</div>';
  else if (!_usbDrives.length) h += '<div class="fs-meta">' + esc(t('usb.noDrives')) + '</div>';
  else {
    h += '<div class="usb-drives">';
    for (const d of _usbDrives) {
      let why = '';
      let off = false;
      if (d.sameDisk) {
        why = t('usb.driveSameDisk');
        off = true;
      } else if (d.stick && !d.stick.supported) {
        why = t('usb.driveNewer');
        off = true;
      } else if (d.stick && d.stick.registered) {
        why = t('usb.driveRegistered');
        off = true;
      } else if (d.stick && !configured) {
        why = t('usb.driveNeedsKey');
        off = true;
      } else if (d.stick && d.stick.otherKey) {
        why = t('usb.driveOtherKey');
        off = true;
      } else if (d.stick) why = t('usb.driveKnown');
      const size = d.total ? t('usb.driveSize', { free: _usbSize(d.free), total: _usbSize(d.total) }) : '';
      h +=
        '<label class="usb-drive' +
        (off ? ' is-off' : '') +
        '"><input type="radio" name="usb-drive" value="' +
        esc(d.root) +
        '"' +
        (off ? ' disabled' : '') +
        '><span class="usb-drive-root">' +
        esc(d.root) +
        '</span><span class="fs-meta">' +
        esc([size, why].filter(Boolean).join(' · ')) +
        '</span></label>';
    }
    h += '</div>';
  }
  h +=
    '<div class="usb-row"><input type="text" id="usb-label" maxlength="40" autocomplete="off" placeholder="' +
    esc(t('usb.labelPh')) +
    '"></div><div class="usb-row"><button type="button" class="btn btn-p" data-usb="setup-go"' +
    (_usbDrives && _usbDrives.length ? '' : ' disabled') +
    '>' +
    esc(t('usb.setupGo')) +
    '</button><button type="button" class="btn" data-usb="setup-rescan">' +
    esc(t('usb.rescan')) +
    '</button><button type="button" class="btn" data-usb="setup-close">' +
    esc(t('common.cancel')) +
    '</button></div>';
  box.innerHTML = h;
}

// The recovery key, right after the first stick was set up or when an admin
// asked for it. The first time, "Done" waits for the box saying it has been
// put away: without the key, a stick is unreadable once this PC is gone.
function renderUsbKey() {
  const box = document.getElementById('usb-key');
  if (!box) return;
  box.hidden = !_usbKey;
  if (!_usbKey) {
    box.innerHTML = '';
    return;
  }
  box.innerHTML =
    '<div class="usb-key"><div class="usb-sub">' +
    esc(t('usb.keyTitle')) +
    '</div><p class="fs-meta">' +
    esc(t('usb.keyWhy')) +
    '</p><code class="usb-key-code">' +
    esc(_usbKey.key) +
    '</code><div class="usb-row"><button type="button" class="btn btn-sm" data-usb="key-copy">' +
    esc(t('usb.keyCopy')) +
    '</button></div>' +
    (_usbKey.fresh
      ? '<label class="usb-key-saved"><input type="checkbox" id="usb-key-saved"><span>' +
        esc(t('usb.keySaved')) +
        '</span></label>'
      : '') +
    '<div class="usb-row"><button type="button" class="btn btn-p" id="usb-key-done" data-usb="key-done"' +
    (_usbKey.fresh ? ' disabled' : '') +
    '>' +
    esc(t('usb.keyDone')) +
    '</button></div></div>';
}

async function _usbLoadDrives() {
  try {
    _usbDrives = (await apiGet('/api/usb-backup/drives')).drives || [];
  } catch (e) {
    _usbDrives = [];
    toast(t('common.error') + ': ' + (e.message || ''), 'err');
  }
  renderUsbSetup();
}

async function _usbSetupGo(btn) {
  const picked = document.querySelector('input[name="usb-drive"]:checked');
  if (!picked) {
    toast(t('usb.pickDrive'), 'err');
    return;
  }
  const labelEl = document.getElementById('usb-label');
  btn.disabled = true;
  const r = await apiPost('/api/usb-backup/setup', { root: picked.value, label: labelEl ? labelEl.value.trim() : '' });
  btn.disabled = false;
  if (!r || r.error) {
    toast(_usbErrText(r && r.code), 'err');
    return;
  }
  _usbSetupOpen = false;
  renderUsbSetup();
  // The key comes back with every setup until it is confirmed as put away.
  if (r.recoveryKey) {
    _usbKey = { key: r.recoveryKey, fresh: true };
    renderUsbKey();
  }
  toast(t('usb.setupDone', { label: (r.stick && r.stick.label) || '' }), 'ok');
  loadUsbBackup();
}

async function _usbConnect(btn) {
  const input = document.getElementById(btn.dataset.input);
  const key = input ? input.value.trim() : '';
  if (!key) {
    toast(t('usb.err.BAD_KEY'), 'err');
    return;
  }
  btn.disabled = true;
  const r = await apiPost('/api/usb-backup/connect', { root: btn.dataset.root, recoveryKey: key });
  btn.disabled = false;
  if (!r || r.error) {
    toast(_usbErrText(r && r.code), 'err');
    return;
  }
  if (input) input.value = '';
  toast(t('usb.connected'), 'ok');
  loadUsbBackup();
}

async function _usbShowKey() {
  if (!(await askConfirm(t('usb.keyShowTitle'), t('usb.keyShowBody'), t('usb.keyShow')))) return;
  const r = await apiPost('/api/usb-backup/key', {});
  if (!r || r.error || !r.recoveryKey) {
    toast(t('common.error'), 'err');
    return;
  }
  // Shown on request before it was ever confirmed, it asks for the
  // confirmation just as the first time does.
  _usbKey = { key: r.recoveryKey, fresh: !(_usb && _usb.keyConfirmed) };
  renderUsbKey();
}

async function _usbKeyDone() {
  if (_usbKey && _usbKey.fresh) {
    const r = await apiPost('/api/usb-backup/key/confirm', {});
    if (!r || r.error) {
      toast(t('common.error'), 'err');
      return;
    }
  }
  _usbKey = null;
  renderUsbKey();
  loadUsbBackup();
}

async function _usbCopyKey() {
  if (!_usbKey) return;
  try {
    await navigator.clipboard.writeText(_usbKey.key);
    toast(t('usb.keyCopied'), 'ok');
  } catch (e) {
    // No clipboard (an old browser, a page not served over HTTPS): select the
    // key so it can be copied by hand.
    const code = document.querySelector('#usb-key .usb-key-code');
    if (code) window.getSelection().selectAllChildren(code);
  }
}

async function _usbForget(id, label) {
  if (!(await askConfirm(t('usb.forgetTitle'), t('usb.forgetBody', { label }), t('usb.forget')))) return;
  const r = await apiDelete('/api/usb-backup/sticks/' + encodeURIComponent(id));
  if (!r || r.error) {
    toast(_usbErrText(r && r.code), 'err');
    return;
  }
  loadUsbBackup();
}

async function _usbRunNow(btn, force) {
  if (force && !(await askConfirm(t('usb.forceTitle'), t('usb.forceBody'), t('usb.forceGo')))) return;
  btn.disabled = true;
  const body = {};
  if (btn.dataset.id) body.id = btn.dataset.id;
  if (force) body.force = true;
  const r = await apiPost('/api/usb-backup/run', body);
  if (!r || r.error) {
    btn.disabled = false;
    toast(_usbErrText(r && r.code), 'err');
    return;
  }
  loadUsbBackup();
}

function initUsbCard() {
  const card = document.getElementById('usb-card');
  if (!card) return;
  card.addEventListener('click', (e) => {
    const b = e.target.closest('[data-usb]');
    if (!b || b.disabled) return;
    const a = b.dataset.usb;
    if (a === 'setup-open') {
      _usbSetupOpen = true;
      _usbDrives = null;
      renderUsbSetup();
      _usbLoadDrives();
    } else if (a === 'setup-close') {
      _usbSetupOpen = false;
      renderUsbSetup();
    } else if (a === 'setup-rescan') {
      _usbDrives = null;
      renderUsbSetup();
      _usbLoadDrives();
    } else if (a === 'setup-go') _usbSetupGo(b);
    else if (a === 'run') _usbRunNow(b, false);
    else if (a === 'run-force') _usbRunNow(b, true);
    else if (a === 'key') _usbShowKey();
    else if (a === 'key-copy') _usbCopyKey();
    else if (a === 'key-done') _usbKeyDone();
    else if (a === 'forget') _usbForget(b.dataset.id, b.dataset.label);
    else if (a === 'connect') _usbConnect(b);
  });
  card.addEventListener('change', (e) => {
    if (e.target.id !== 'usb-key-saved') return;
    const done = document.getElementById('usb-key-done');
    if (done) done.disabled = !e.target.checked;
  });
}

// ─── BACKUP ──────────────────────────────────────────────────
function setStatus(el, msg, ok) {
  el.style.color = ok ? 'var(--c-green-dark)' : 'var(--c-red-dark)';
  el.textContent = msg;
}
async function downloadBackup() {
  const pw = document.getElementById('backup-dl-pw').value;
  const st = document.getElementById('backup-dl-status');
  if (!pw || pw.length < 8) {
    setStatus(st, t('users.minPw'), false);
    return;
  }
  setStatus(st, 'Preparing backup…', true);
  try {
    const r = await authFetch('/api/backup/download', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ password: pw })
    });
    if (!r.ok) {
      const e = await r.json().catch(() => ({}));
      setStatus(st, e.error || 'Download failed', false);
      return;
    }
    const blob = await r.blob();
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    const cd = r.headers.get('content-disposition') || '';
    const m = cd.match(/filename="(.+?)"/);
    a.download = m ? m[1] : 'meistertracker_backup.enc';
    a.click();
    URL.revokeObjectURL(a.href);
    setStatus(st, 'Backup downloaded.', true);
    document.getElementById('backup-dl-pw').value = '';
  } catch (err) {
    setStatus(st, 'Download failed', false);
  }
}
// Clean-slate reset. Deliberately awkward to fire: you pick the categories, type
// the confirmation phrase, and still get a summary dialog naming what goes. The
// server writes a verified backup before deleting anything.
const RESET_CONFIRM_PHRASE = 'ALLES LOESCHEN';
async function runCleanReset() {
  const st = document.getElementById('reset-status');
  const scopes = {
    growing: document.getElementById('reset-growing').checked,
    orders: document.getElementById('reset-orders').checked,
    planning: document.getElementById('reset-planning').checked,
    stock: document.getElementById('reset-stock').checked
  };
  if (!scopes.growing && !scopes.orders && !scopes.planning && !scopes.stock) {
    setStatus(st, t('reset.errNoScope'), false);
    return;
  }
  const typed = (document.getElementById('reset-confirm').value || '').trim().toUpperCase();
  if (typed !== RESET_CONFIRM_PHRASE) {
    setStatus(st, t('reset.errPhrase', { phrase: RESET_CONFIRM_PHRASE }), false);
    return;
  }
  const parts = [];
  if (scopes.growing) parts.push(t('reset.scopeGrowing'));
  if (scopes.orders) parts.push(t('reset.scopeOrders'));
  if (scopes.planning) parts.push(t('reset.scopePlanning'));
  if (scopes.stock) parts.push(t('reset.scopeStock'));
  confirm2(t('reset.confirmTitle'), t('reset.confirmMsg', { what: parts.join(' · ') }), t('reset.btn'), async () => {
    setStatus(st, t('reset.running'), true);
    const r = await apiPost('/api/admin/reset', { ...scopes, confirm: RESET_CONFIRM_PHRASE });
    if (!r || r.error) {
      setStatus(st, t('reset.failed', { err: (r && r.error) || '?' }), false);
      return;
    }
    const rows = Object.values(r.counts || {}).reduce((s, n) => s + n, 0);
    setStatus(st, t('reset.done', { rows: rows, backup: r.backup }), true);
    document.getElementById('reset-confirm').value = '';
    await loadData(); // re-renders via refresh()
  });
}
function restoreBackup() {
  const file = document.getElementById('restore-file').files[0];
  const pw = document.getElementById('backup-restore-pw').value;
  const st = document.getElementById('backup-restore-status');
  if (!file) {
    setStatus(st, 'Select a .enc backup file.', false);
    return;
  }
  if (!pw) {
    setStatus(st, 'Enter the decryption password.', false);
    return;
  }
  confirm2(
    t('settings.restoreBackup') || 'Restore this backup?',
    t('settings.restoreMsg') || 'Replaces ALL data on the server for all users. Cannot be undone.',
    t('settings.restoreConfirm') || 'Yes, restore',
    async () => {
      setStatus(st, 'Restoring…', true);
      try {
        const buf = await file.arrayBuffer();
        const r = await authFetch('/api/backup/restore', {
          method: 'POST',
          headers: { 'Content-Type': 'application/octet-stream', 'x-backup-password': pw },
          body: buf
        });
        if (!r.ok) {
          const e = await r.json().catch(() => ({}));
          setStatus(st, e.error || 'Restore failed', false);
          return;
        }
        setStatus(st, 'Restored successfully. Reloading…', true);
        document.getElementById('backup-restore-pw').value = '';
        setTimeout(() => window.location.reload(), 1500);
      } catch (err) {
        setStatus(st, 'Restore failed', false);
      }
    }
  );
}

// ─── ZONES (Location Management) ────────────────────────────
const ROLE_LABELS = {
  spawn: 'zones.roleSpawn',
  incubation: 'zones.roleIncubation',
  fruiting: 'zones.roleFruiting',
  contaminated: 'zones.roleContaminated'
};
const ROLE_ORDER = ['spawn', 'incubation', 'fruiting', 'contaminated'];
function renderZones() {
  const el = document.getElementById('zones-list');
  if (!el) return;
  if (!zones.length) {
    // Vor der ersten Antwort von /api/data ist zones die leere Vorbelegung.
    // "Noch keine Zonen angelegt" wäre dann eine Behauptung über die Daten,
    // die niemand geprüft hat — und schickt jemanden Zonen anlegen, die es
    // längst gibt. Ob der Abgleich hängt, sagt der Punkt in der Kopfzeile.
    el.innerHTML = '<div class="empty">' + esc(t(datenGeladen ? 'zones.empty' : 'common.loading')) + '</div>';
    return;
  }
  // Group zones by role in canonical order; unknown roles go last.
  const groups = {};
  ROLE_ORDER.forEach((r) => {
    groups[r] = [];
  });
  const extraRoles = [];
  zones.forEach((z) => {
    if (groups[z.role]) groups[z.role].push(z);
    else {
      if (!groups[z.role]) {
        groups[z.role] = [];
        extraRoles.push(z.role);
      }
      groups[z.role].push(z);
    }
  });
  // Within each group: sort by sortOrder (fallback to name for stability).
  Object.keys(groups).forEach((role) => {
    groups[role].sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0) || a.name.localeCompare(b.name));
  });
  const renderZone = (z) => {
    const zoneBags = getZoneBags(z.id);
    const bagCount = Object.keys(zoneBags).length;
    const rackIds = new Set(z.racks.map((r) => r.id));
    const directCount = Object.values(zoneBags).filter((b) => !rackIds.has(b.loc)).length;
    const rackHtml = z.racks.length
      ? z.racks
          .map((r) => {
            const rBags = Object.keys(getRackBags(r.id)).length;
            return `<span class="zone-rack-chip">${esc(r.id)} <span style="color:var(--c-text-muted)">(${rBags})</span>${rBags === 0 ? `<button class="btn btn-sm btn-r zone-rack-del" data-action="del-rack" data-rack="${esc(r.id)}" title="${esc(t('zones.delete'))}">&times;</button>` : ''}</span>`;
          })
          .join('')
      : '<span class="fs-xs" style="color:var(--c-text-muted)">' + t('zones.noRacks') + '</span>';
    return `<div class="zone-row" data-find="zone:${esc(z.id)}" data-zone-id="${esc(z.id)}" data-zone-role="${esc(z.role)}" style="border-left:4px solid ${safeColor(z.color)}">
      <div class="zone-row-header">
        <span class="zone-drag-handle" draggable="true" title="${esc(t('zones.dragToReorder'))}" aria-label="${esc(t('zones.dragToReorder'))}">\u22ee\u22ee</span>
        <span class="zone-row-name">${esc(z.name)}</span>
        <span class="badge">${esc(t(ROLE_LABELS[z.role]) || z.role)}</span>
        <span class="fs-xs" style="color:var(--c-text-muted)">${z.maxCapacity ? bagCount + ' / ' + z.maxCapacity + ' Bags' : tp('dash.bags', bagCount)}</span>
        ${directCount > 0 ? `<span class="badge zone-direct-badge" title="${esc(t('zones.directBagsHint'))}">\u26a0 ${esc(t('zones.directBags', { count: directCount }))}</span>` : ''}
        ${directCount > 0 && z.racks.length ? `<button class="btn btn-sm fs-micro" data-action="bulk-move" data-zone="${esc(z.id)}" style="color:var(--c-red-dark);font-weight:600">${esc(t('zones.moveToRack'))}</button>` : ''}
        <span style="flex:1"></span>
        <button class="btn btn-sm fs-xs" data-action="rename-zone" data-zone="${esc(z.id)}">${esc(t('batch.zones.rename'))}</button>
        <button class="btn btn-sm fs-xs" data-action="zone-capacity" data-zone="${esc(z.id)}" title="${esc(z.maxCapacity ? z.name + ': ' + bagCount + ' / ' + z.maxCapacity : t('zones.capacityNone'))}">${esc(t('zones.capacity'))}</button>
        <button class="btn btn-sm fs-xs" data-action="add-rack" data-zone="${esc(z.id)}">${esc(t('zones.addRack'))}</button>
        <button class="btn btn-sm fs-xs" data-action="toggle-qr" data-zone="${esc(z.id)}">${esc(t('zones.showQr'))}</button>
        <button class="btn btn-sm fs-xs" data-action="print-zone-qr" data-zone="${esc(z.id)}">${esc(t('zones.printQr'))}</button>
        ${
          bagCount === 0
            ? `<button class="btn btn-sm btn-r fs-xs" data-action="del-zone" data-zone="${esc(z.id)}">${t('zones.delete')}</button>`
            : `<button class="btn btn-sm btn-r fs-xs" disabled title="${esc(t('zones.hasBags', { count: bagCount }))}" style="opacity:.45;cursor:not-allowed">${t('zones.delete')}</button>`
        }
      </div>
      <div class="zone-row-racks">${rackHtml}</div>
      <div class="zone-qr-panel" id="zone-qr-${esc(z.id)}" style="display:none"></div>
    </div>`;
  };
  const orderedRoles = [...ROLE_ORDER, ...extraRoles];
  el.innerHTML = orderedRoles
    .map((role) => {
      const zs = groups[role];
      if (!zs || !zs.length) return '';
      const label = esc(t(ROLE_LABELS[role]) || role);
      const header = `<div class="zone-group-header">${label}</div>`;
      return header + zs.map(renderZone).join('');
    })
    .join('');
}
// Drag-and-drop state for zone reordering.
let draggedZoneId = null;
let draggedZoneRole = null;
function clearZoneDropHints() {
  document.querySelectorAll('.zone-row.zone-drop-before,.zone-row.zone-drop-after').forEach((r) => {
    r.classList.remove('zone-drop-before', 'zone-drop-after');
  });
}
function onZoneDragStart(e) {
  const handle = e.target.closest('.zone-drag-handle');
  if (!handle) {
    return;
  }
  const row = handle.closest('.zone-row');
  if (!row) {
    return;
  }
  draggedZoneId = row.dataset.zoneId;
  draggedZoneRole = row.dataset.zoneRole;
  if (e.dataTransfer) {
    e.dataTransfer.effectAllowed = 'move';
    try {
      e.dataTransfer.setData('text/plain', draggedZoneId);
    } catch (_) {}
    try {
      const rect = row.getBoundingClientRect();
      e.dataTransfer.setDragImage(row, e.clientX - rect.left, e.clientY - rect.top);
    } catch (_) {}
  }
  // Delay the dragging class so the browser snapshots the row before we dim it.
  setTimeout(() => {
    row.classList.add('zone-dragging');
  }, 0);
}
function onZoneDragOver(e) {
  if (!draggedZoneId) return;
  const row = e.target.closest('.zone-row');
  if (!row || row.dataset.zoneRole !== draggedZoneRole || row.dataset.zoneId === draggedZoneId) {
    clearZoneDropHints();
    return;
  }
  e.preventDefault();
  if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
  const rect = row.getBoundingClientRect();
  const before = e.clientY - rect.top < rect.height / 2;
  clearZoneDropHints();
  row.classList.add(before ? 'zone-drop-before' : 'zone-drop-after');
}
function onZoneDrop(e) {
  if (!draggedZoneId) return;
  const row = e.target.closest('.zone-row');
  if (!row || row.dataset.zoneRole !== draggedZoneRole || row.dataset.zoneId === draggedZoneId) {
    clearZoneDropHints();
    return;
  }
  e.preventDefault();
  const rect = row.getBoundingClientRect();
  const before = e.clientY - rect.top < rect.height / 2;
  const targetId = row.dataset.zoneId;
  const sourceId = draggedZoneId;
  const role = draggedZoneRole;
  clearZoneDropHints();
  reorderZoneWithinRole(sourceId, targetId, before, role);
}
function onZoneDragEnd() {
  document.querySelectorAll('.zone-row.zone-dragging').forEach((r) => r.classList.remove('zone-dragging'));
  clearZoneDropHints();
  draggedZoneId = null;
  draggedZoneRole = null;
}
async function reorderZoneWithinRole(sourceId, targetId, before, role) {
  const sameRole = zones
    .filter((x) => x.role === role)
    .sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0) || a.name.localeCompare(b.name));
  const srcIdx = sameRole.findIndex((x) => x.id === sourceId);
  if (srcIdx < 0) return;
  const [src] = sameRole.splice(srcIdx, 1);
  const tgtIdx = sameRole.findIndex((x) => x.id === targetId);
  if (tgtIdx < 0) sameRole.push(src);
  else sameRole.splice(before ? tgtIdx : tgtIdx + 1, 0, src);
  // Build full order: roles in canonical order + any extras, each group in its new local order.
  const groups = {};
  ROLE_ORDER.forEach((r) => {
    groups[r] = [];
  });
  const extra = [];
  zones.forEach((x) => {
    if (x.role === role) return;
    if (!groups[x.role]) {
      groups[x.role] = [];
      extra.push(x.role);
    }
    groups[x.role].push(x);
  });
  groups[role] = sameRole;
  Object.keys(groups).forEach((r) => {
    if (r !== role) groups[r].sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0) || a.name.localeCompare(b.name));
  });
  const fullOrder = [...ROLE_ORDER, ...extra].flatMap((r) => groups[r] || []).map((x) => x.id);
  // Optimistic local update so the UI moves immediately.
  fullOrder.forEach((id, idx) => {
    const zz = zones.find((x) => x.id === id);
    if (zz) zz.sortOrder = idx + 1;
  });
  renderZones();
  try {
    const res = await apiPost('/api/zones/reorder', { order: fullOrder });
    if (res && res.error) {
      toast(res.error, 'err');
      await loadData();
    }
  } catch (err) {
    console.error('reorder zones error:', err);
    toast(t('zones.errorReorder', { err: err.message || 'unknown error' }), 'err');
    await loadData();
  }
}
async function addZone() {
  const nameRaw = document.getElementById('zone-name').value.trim();
  // ID is derived from uppercase version for stability; display name keeps user casing
  const id = nameRaw
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '_')
    .replace(/^_+|_+$/g, '');
  if (!id || id.length < 2) {
    fieldError('zone-name', t('zones.errShort'));
    return;
  }
  if (nameRaw.length > 50) {
    toast(t('zones.errLong'), 'err');
    return;
  }
  if (!/^[A-Z]/.test(id)) {
    toast(t('zones.errIdStart'), 'err');
    return;
  }
  const dup = zones.find((z) => z.id === id);
  if (dup) {
    toast(t('zones.errExists') + ' (' + dup.name + ')', 'err');
    return;
  }
  const role = document.getElementById('zone-role').value;
  const color = document.getElementById('zone-color').value;
  const racksRaw = document.getElementById('zone-racks').value.trim();
  const racks = racksRaw
    ? [
        ...new Set(
          racksRaw
            .split(',')
            .map(
              (r) =>
                id +
                '_' +
                r
                  .trim()
                  .toUpperCase()
                  .replace(/[^A-Z0-9]/g, '')
            )
            .filter((r) => r !== id + '_')
        )
      ]
    : [];
  if (racks.some((r) => r === id + '_' || r.length <= id.length + 1)) {
    toast(t('zones.errRackEmpty'), 'err');
    return;
  }
  if (racks.length > 50) {
    toast(t('zones.errTooManyRacks'), 'err');
    return;
  }
  const capVal = document.getElementById('zone-capacity').value.trim();
  const maxCapacity = capVal ? parseInt(capVal, 10) : null;
  if (maxCapacity !== null && (!Number.isFinite(maxCapacity) || maxCapacity < 1)) {
    fieldError('zone-capacity', t('zones.errCapacity'));
    return;
  }
  try {
    const now = new Date().toISOString();
    const res = await apiPost('/api/zones', {
      id,
      name: nameRaw,
      role,
      color,
      sortOrder: zones.length + 1,
      racks,
      maxCapacity,
      created: now
    });
    if (res.error) {
      toast(res.error, 'err');
      return;
    }
    zones.push({
      id,
      name: nameRaw,
      role,
      color,
      sortOrder: zones.length + 1,
      maxCapacity,
      racks: racks.map((r, i) => ({ id: r, sortOrder: i + 1 }))
    });
    rebuildZoneConstants();
    renderZones();
    renderStatus();
    document.getElementById('zone-name').value = '';
    document.getElementById('zone-racks').value = '';
    document.getElementById('zone-color').value = ZONE_ROLE_COLOR.fruiting;
    document.getElementById('zone-role').value = 'fruiting';
    document.getElementById('zone-capacity').value = '';
  } catch (e) {
    console.error('addZone error:', e);
    toast(t('zones.errorCreate', { err: e.message || 'unknown error' }), 'err');
  }
}
function renameZone(id) {
  const z = zones.find((x) => x.id === id);
  if (!z) return;
  prompt2(t('batch.zones.renamePrompt', { old: z.name }), z.name, function (newName) {
    if (!newName || !newName.trim()) return;
    newName = newName.trim();
    if (newName === z.name) return;
    apiPatch('/api/zones/' + encodeURIComponent(id) + '/name', { name: newName }).then((res) => {
      if (res && res.error) {
        toast(res.error, 'err');
        return;
      }
      z.name = newName;
      renderZones();
      renderStatus();
      renderBatches();
    });
  });
}
// Capacity could be set when a zone was created and never again, so a tent whose
// real limit only became clear in use was stuck at whatever was guessed on day
// one — or at nothing. Empty clears the limit rather than meaning zero.
function editZoneCapacity(id) {
  const z = zones.find((x) => x.id === id);
  if (!z) return;
  prompt2(t('zones.capacityPrompt', { zone: z.name }), z.maxCapacity ? String(z.maxCapacity) : '', function (raw) {
    if (raw === null || raw === undefined) return;
    const s = String(raw).trim();
    // '' clears; anything else must be a whole, non-negative number. Number('')
    // is 0, so the empty case is taken first and never reads as a limit of zero.
    let cap;
    if (s === '') cap = null;
    else {
      const n = Number(s);
      if (!Number.isInteger(n) || n < 0) {
        setFb('err', t('zones.capacityBad'));
        return;
      }
      cap = n === 0 ? null : n;
    }
    if ((z.maxCapacity || null) === cap) return;
    apiPatch('/api/zones/' + encodeURIComponent(id) + '/capacity', { maxCapacity: cap }).then((res) => {
      if (res && res.error) {
        toast(res.error, 'err');
        return;
      }
      z.maxCapacity = cap;
      setFb('ok', t('zones.capacitySaved'));
      renderZones();
      renderStatus();
      renderDashBatchTasks();
    });
  });
}
function removeZone(id) {
  const z = zones.find((x) => x.id === id);
  if (!z) return;
  confirm2(t('zones.deleteTitle'), t('zones.deleteMsg', { name: z.name }), t('zones.delete'), async () => {
    const res = await apiDelete('/api/zones/' + encodeURIComponent(id));
    if (res.error) {
      toast(res.error, 'err');
      return;
    }
    zones = zones.filter((x) => x.id !== id);
    rebuildZoneConstants();
    renderZones();
    renderStatus();
  });
}
function addRackToZone(zoneId) {
  prompt2(t('zones.rackPrompt'), 'R3', function (name) {
    if (!name) return;
    const rackId =
      zoneId +
      '_' +
      name
        .trim()
        .toUpperCase()
        .replace(/[^A-Z0-9]/g, '');
    if (ALL_RACKS.includes(rackId)) {
      toast(t('zones.errRackExists'), 'err');
      return;
    }
    apiPost('/api/zones/' + encodeURIComponent(zoneId) + '/racks', { id: rackId }).then((res) => {
      if (res.error) {
        toast(res.error, 'err');
        return;
      }
      const zone = zones.find((z) => z.id === zoneId);
      if (zone) zone.racks.push({ id: rackId, sortOrder: zone.racks.length + 1 });
      rebuildZoneConstants();
      renderZones();
      renderStatus();
    });
  });
}
function removeRack(rackId) {
  confirm2(t('zones.rackDeleteTitle'), t('zones.rackDeleteMsg', { name: rackId }), t('zones.delete'), () => {
    apiDelete('/api/racks/' + encodeURIComponent(rackId)).then((res) => {
      if (res.error) {
        toast(res.error, 'err');
        return;
      }
      zones.forEach((z) => {
        z.racks = z.racks.filter((r) => r.id !== rackId);
      });
      rebuildZoneConstants();
      renderZones();
      renderStatus();
    });
  });
}
function bulkMoveToRack(zoneId) {
  const z = zones.find((x) => x.id === zoneId);
  if (!z || !z.racks.length) return;
  const zoneBags = getZoneBags(zoneId);
  const rackIds = new Set(z.racks.map((r) => r.id));
  const directBags = Object.entries(zoneBags).filter(([, b]) => !rackIds.has(b.loc));
  if (!directBags.length) return;
  const m = document.getElementById('m-locmove');
  document.getElementById('lm-title').textContent = t('zones.moveToRackTitle', { count: directBags.length });
  document.getElementById('lm-info').textContent = zoneDisplayName(zoneId);
  document.getElementById('lm-confirm').style.display = 'none';
  const grid = document.getElementById('lm-grid');
  grid.style.display = 'flex';
  grid.innerHTML = z.racks
    .map((r) => {
      const rBags = Object.keys(getRackBags(r.id)).length;
      return `<button class="btn btn-sm fs-meta" data-action="bulk-rack-target" data-zone="${esc(zoneId)}" data-rack="${esc(r.id)}" style="padding:8px 12px">${esc(r.id)} (${rBags})</button>`;
    })
    .join('');
  m.classList.add('open');
}
async function executeBulkMoveToRack(zoneId, rackId) {
  const z = zones.find((x) => x.id === zoneId);
  if (!z) return;
  const zoneBags = getZoneBags(zoneId);
  const rackIds = new Set(z.racks.map((r) => r.id));
  const directBags = Object.entries(zoneBags).filter(([, b]) => !rackIds.has(b.loc));
  if (!directBags.length) return;
  const entries = directBags.map(([bagId, b]) => ({
    action: 'MOVE',
    batch: b.batchId,
    bag: bagId,
    from: b.loc,
    to: rackId,
    species: b.species,
    strain: b.strain,
    time: new Date().toISOString(),
    client_uuid: newScanUuid(),
    // I-12: optimistic concurrency snapshot for offline-queue replays.
    expected_current_zone: b.loc ? toZone(b.loc) : null
  }));
  const res = await apiPost('/api/scan-log', { entries });
  if (handleZoneMismatch(res, entries)) return; // I-12
  if (res.error) {
    toast(res.error, 'err');
    return;
  }
  entries.forEach((e) => scanLog.push(e));
  document.getElementById('m-locmove').classList.remove('open');
  renderZones();
  renderStatus();
  setFb('ok', t('zones.movedToRack', { count: directBags.length, rack: rackId }));
}

// ─── ZONE QR CODES ──────────────────────────────────────────
async function renderZoneQrPanel(zoneId) {
  const panel = document.getElementById('zone-qr-' + zoneId);
  if (!panel) return;
  // Toggle if already loaded
  if (panel.dataset.loaded) {
    const show = panel.style.display === 'none';
    panel.style.display = show ? '' : 'none';
    const btn = panel.closest('.zone-row').querySelector('[data-action="toggle-qr"]');
    if (btn) btn.textContent = show ? t('zones.hideQr') : t('zones.showQr');
    return;
  }
  panel.style.display = '';
  panel.dataset.loaded = '1';
  const btn = panel.closest('.zone-row').querySelector('[data-action="toggle-qr"]');
  if (btn) btn.textContent = t('zones.hideQr');
  const z = zones.find((x) => x.id === zoneId);
  if (!z) return;
  const items = [zoneId, ...z.racks.map((r) => r.id)];
  const grid = document.createElement('div');
  grid.className = 'zone-qr-grid';
  for (const val of items) {
    const cell = document.createElement('div');
    cell.className = 'zone-qr-cell';
    const img = await makeQR(val);
    if (img) {
      img.style.cssText = 'width:80px;height:80px';
      cell.appendChild(img);
    }
    const lbl = document.createElement('div');
    lbl.className = 'zone-qr-label';
    lbl.textContent = val;
    cell.appendChild(lbl);
    grid.appendChild(cell);
  }
  panel.innerHTML = '';
  panel.appendChild(grid);
}

async function printZoneQrBrowser(zoneId) {
  const z = zones.find((x) => x.id === zoneId);
  if (!z) return;
  const items = [zoneId, ...z.racks.map((r) => r.id)];
  await printQrSheet(items, z.name);
}

async function printAllZoneQrBrowser() {
  const items = [...ZONES, ...ALL_RACKS];
  await printQrSheet(items, 'All Zones');
}

async function printQrSheet(items, title) {
  const sheet = document.getElementById('ref-print-sheet');
  sheet.innerHTML = '';
  const hdr = document.createElement('div');
  // px-auf-papier: this is a printed sheet, and 15px there is a sixth of an
  // inch of paper. A rem would follow the reader's browser setting and change
  // how much fits on the page, which is not what a browser setting is for.
  hdr.style.cssText = 'font-family:Arial,sans-serif;font-size:15px;font-weight:bold;margin-bottom:12px;padding:8px';
  hdr.textContent = 'QR Codes: ' + title;
  sheet.appendChild(hdr);
  const row = document.createElement('div');
  row.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;padding:0 8px';
  for (const val of items) {
    const cell = document.createElement('div');
    cell.style.cssText =
      'border:1px solid var(--c-border);border-radius:5px;padding:5px 7px;text-align:center;background:var(--c-surface);page-break-inside:avoid';
    const img = await makeQR(val);
    if (img) {
      img.style.width = '80px';
      img.style.height = '80px';
      cell.appendChild(img);
    }
    const lbl = document.createElement('div');
    lbl.className = 'fs-micro';
    lbl.style.cssText = 'font-weight:bold;font-family:Arial,sans-serif';
    lbl.textContent = val;
    cell.appendChild(lbl);
    row.appendChild(cell);
  }
  sheet.appendChild(row);
  setTimeout(() => window.print(), 600);
}

// ─── VORHABEN (Forschung · Produkte · Bau) ───────────────────
//
// Drei Unterlagen, die an der Werkbank gebraucht werden und nicht am
// Schreibtisch. Ihr Wortlaut steht nicht hier, sondern in der Datenbank
// (/api/project-docs): diesen Code liest jeder, der das Repository sieht, die
// Unterlagen gehören dem Betrieb. Hier steht nur, wie sie gezeichnet werden.
// Gepflegt werden sie außerhalb des Trackers und kommen per Import herein.
//
// Der Text ist Inhalt, keine Oberfläche, und geht deshalb nicht durch t().
// Übersetzt werden die Reiter und die Knöpfe. Das ist dieselbe Grenze, die eine
// Zone oder ein Substratrezept schon hat: wie die Dinge heißen, steht in der
// Datenbank und bleibt wie es ist; was man mit ihnen tun kann, steht im
// Wörterbuch. Drei Rechercheberichte in drei Sprachen zu halten hieße, sie
// dreimal zu pflegen, und gepflegt würde dann einer.
//
// Bausteine je Abschnitt: p, ul, ol, note, table, cards, steps, tasks, plan,
// copy. Welche Form ein Dokument haben muss, prüft der Server beim Import
// (checkProjectDoc in db.js), damit hier nie eine Datei ankommt, die der
// Zeichner nicht lesen kann.
//
// Geladen wird erst, wenn jemand einen der drei Reiter öffnet: die Texte sind
// lang, und /api/data läuft bei jedem Sync. /api/data trägt nur eine Marke;
// ändert sie sich, holt der nächste Reiterwechsel den neuen Stand.
let pjDocsAbruf = null; // laufender Abruf, damit zwei Reiter nicht zweimal holen
function pjDocsLaden() {
  if (!pjDocsAbruf) {
    pjDocsAbruf = apiGet('/api/project-docs')
      .then((r) => {
        projectDocs = (r && r.docs) || {};
      })
      .catch(() => {
        /* projectDocs bleibt null; der Reiter zeigt dann den Knopf zum Nachladen */
      })
      .finally(() => {
        pjDocsAbruf = null;
      });
  }
  return pjDocsAbruf;
}

// **fett** ist die einzige Auszeichnung, die diese drei Dokumente brauchen, und
// sie wird nach dem Escapen eingesetzt: der Inhalt geht durch esc(), erst danach
// entsteht Markup. Andersherum wäre jedes Sternchen im Text ein offenes Tor.
function pjText(s) {
  return esc(s).replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
}
function pjTable(tb) {
  // .t-cards ist der Kartenmodus, den zwölf Tabellen dieser Anwendung unter
  // 769px schon benutzen: thead aus, jede Zeile eine Karte, und die
  // Beschriftung kommt aus data-mlabel. Deshalb sind die Spaltenköpfe hier
  // kurz — sie stehen am Telefon in einer 84px breiten Spalte.
  const head = tb.head.map((h) => `<th>${pjText(h)}</th>`).join('');
  const rows = tb.rows
    .map(
      (r) =>
        '<tr>' + r.map((c, i) => `<td data-mlabel="${esc(tb.head[i] || '')}">${pjText(c)}</td>`).join('') + '</tr>'
    )
    .join('');
  return `<table class="t-cards pj-t"><thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table>`;
}
function pjCards(cards) {
  return (
    '<div class="pj-cards">' +
    cards
      .map((c) => {
        const rows = (c.rows || [])
          .map((r) => `<li><span class="pj-k">${pjText(r[0])}</span><span class="pj-v">${pjText(r[1])}</span></li>`)
          .join('');
        return (
          '<div class="pj-rx">' +
          `<div class="pj-rx-t">${pjText(c.t)}</div>` +
          (c.sub ? `<div class="pj-rx-sub">${pjText(c.sub)}</div>` : '') +
          `<ul class="pj-ing">${rows}</ul>` +
          (c.foot ? `<div class="pj-rx-foot">${pjText(c.foot)}</div>` : '') +
          '</div>'
        );
      })
      .join('') +
    '</div>'
  );
}
function pjSteps(steps) {
  return (
    '<div class="pj-steps">' +
    steps.map((s) => `<div class="pj-step"><div class="pj-step-k">${pjText(s.k)}</div><div>${pjText(s.v)}</div></div>`).join('') +
    '</div>'
  );
}
// Ein Schritt, den man anfassen kann. Die Liste allein ist eine Liste; was
// daraus wird, entscheidet sich erst, wenn sie im Kalender steht — deshalb
// trägt jede Zeile ihren eigenen Knopf. Angelegt wird eine ganz normale
// manuelle Aufgabe, mit heutigem Datum, weil eine Aufgabe ohne Datum im
// Kalender nicht gezeichnet wird (renderCalendar überspringt sie).
function pjTasks(tasks) {
  return (
    '<ul class="pj-tasks">' +
    tasks
      .map(
        (x) =>
          `<li><span>${pjText(x)}</span>` +
          `<button class="btn btn-sm fs-xs pj-add" data-pj-task="${esc(x)}">${esc(t('proj.asTask'))}</button></li>`
      )
      .join('') +
    '</ul>'
  );
}
// Der Tagesplan. Eine Zeile ist ein Handgriff, die Marke links sagt wo
// (Einkauf, Bank, Autoklav, Flow), und abgehakt heisst weg — am Tisch zeigt
// die Liste, was noch zu tun ist, nicht was schon war. Ausgeblendet, nicht
// geloescht: ein Knopf holt die erledigten zum Korrigieren zurueck. Dieselbe
// Mechanik und dieselben Worte wie die Laborliste, die es vorher schon gab,
// damit nicht zwei Werkzeuge zwei Sprachen sprechen.
//
// Der Haken liegt im Browser, nicht auf dem Server: er gilt fuer einen Ansatz
// an einem Tag an einem Geraet, und dafuer waere eine Tabelle mit Sync die
// falsche Groesse. Ist der Versuch durch, setzt der Knopf alles zurueck.
// ── Experimente ─────────────────────────────────────────────
//
// Ein Experiment ist ein Ansatz: "Ansatz A", "Ansatz B". Die Gefaesse darin
// sind seine Wiederholungen und seine Kontrolle — A-01, A-02, A-K. Das ist die
// Ebene, auf der eine Frage beantwortet wird, und deshalb die Ebene, die ein
// Ergebnis, ein Rezept und Fotos traegt.
//
// Vorher hing alles an einem Versuchstag, mit allen Gefaessen in einer flachen
// Liste. Das war die falsche Ebene: Zeilen, die nicht sagen, welche
// zusammengehoeren, und ein Fazit fuer alles zusammen, wo es doch mehrere
// verschiedene Fragen waren.
//
// Zwei Ansichten: die Liste und ein Experiment. Ein Tipp auf die Zeile geht
// hinein, der Pfeil wieder heraus.
const PJ_AUSGANG = ['open', 'good', 'contam', 'discarded'];
let pjOffen = null; // id des geoeffneten Experiments, null = Liste
function pjLaufend() {
  return experiments.filter((v) => v.status === 'running' && !v.archived);
}
function pjExp(id) {
  return experiments.find((v) => v.id === id) || null;
}
function pjAusgangSelect(r) {
  return (
    `<select class="pj-out" data-pj-run="${r.id}" data-pj-feld="outcome" aria-label="${esc(t('exp.outcome'))}">` +
    PJ_AUSGANG.map(
      (o) => `<option value="${o}"${r.outcome === o ? ' selected' : ''}>${esc(t('exp.out.' + o))}</option>`
    ).join('') +
    '</select>'
  );
}
// Eine Zeile in der Liste sagt in einem Blick, was der Ansatz ist, woraus er
// besteht und wie weit er ist. Alles andere steht drinnen.
function pjListenzeile(v) {
  // Das Arbeitspaket steht vor den Gefaessen: ein Blick sagt, wofuer der Ansatz
  // laeuft.
  const paket = v.workPackageId != null ? workPackages.find((w) => w.id === v.workPackageId) : null;
  const gefaesse = [paket ? paket.code : '', v.runs.map((r) => r.code).join(', ')].filter(Boolean).join(' · ');
  const offen = v.runs.filter((r) => r.outcome === 'open').length;
  const zustand = v.runs.length
    ? offen
      ? t('exp.openOf', { n: offen, sum: v.runs.length })
      : t('exp.allIn')
    : t('exp.noVessels');
  return (
    `<button type="button" class="pj-liste-zeile" data-pj-open="${v.id}">` +
    `<span class="pj-liste-code">${esc(v.code)}</span>` +
    `<span class="pj-liste-mitte"><span class="pj-liste-titel">${esc(v.title)}</span>` +
    `<span class="pj-liste-meta">${esc(gefaesse || '—')}</span></span>` +
    `<span class="pj-liste-rechts"><span class="pj-liste-meta">${esc(zustand)}</span>` +
    (v.photos.length ? `<span class="pj-liste-meta">${esc(t('exp.photos', { n: v.photos.length }))}</span>` : '') +
    '</span><span class="pj-liste-pfeil" aria-hidden="true">›</span></button>'
  );
}
function pjListe() {
  const laufend = pjLaufend();
  return (
    '<div class="card pj-sec">' +
    `<div class="sec">${esc(t('exp.running', { n: laufend.length }))}</div>` +
    (laufend.length
      ? '<div class="pj-liste">' + laufend.map(pjListenzeile).join('') + '</div>'
      : `<p class="pj-empty">${esc(t('exp.none'))}</p>`) +
    '<div class="pj-run pj-run-new">' +
    `<input id="pj-new-vcode" placeholder="${esc(t('exp.newCodePh'))}" maxlength="20">` +
    `<input id="pj-new-vtitle" placeholder="${esc(t('exp.newTitlePh'))}" maxlength="200">` +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-newexp="1">${esc(t('exp.new'))}</button>` +
    '</div></div>' +
    pjArchiv() +
    pjArbeitspakete() +
    pjLbZeitraum()
  );
}
// ── Arbeitspakete ───────────────────────────────────────────
//
// Die Gliederung eines Vorhabens in Arbeitspakete: AP1, AP2
// und so weiter. Anlegen, umbenennen und ausblenden darf ein Admin, hier unter
// der Liste; einen Versuch zuordnen darf jeder, in seiner Ansicht. Was die
// Pakete heissen, steht in der Datenbank und nicht hier.
//
// Ein Paket als "AP2 · Titel", und eines, das es nicht mehr gibt, als seine
// Kennung: der Verlauf zeigt auch dann, dass da eines war.
function pjApName(pakete, id) {
  const w = (pakete || []).find((x) => x.id === Number(id));
  return w ? w.code + ' · ' + w.title : '#' + id;
}
// Die Auswahl im Versuch. Angeboten werden die sichtbaren Pakete; ein
// ausgeblendetes bleibt stehen, wo es schon steht. Ohne Pakete keine Auswahl.
function pjApAuswahl(v) {
  const angeboten = workPackages.filter((w) => !w.archived || w.id === v.workPackageId);
  if (!angeboten.length) return '';
  return (
    `<label class="pj-ap">${esc(t('exp.wp'))}` +
    `<select data-pj-exp="${v.id}" data-pj-feld="workPackageId">` +
    `<option value=""${v.workPackageId == null ? ' selected' : ''}>${esc(t('exp.wpNone'))}</option>` +
    angeboten
      .map(
        (w) =>
          `<option value="${w.id}"${w.id === v.workPackageId ? ' selected' : ''}>${esc(w.code + ' · ' + w.title)}</option>`
      )
      .join('') +
    '</select></label>'
  );
}
let pjApOffen = false;
function pjArbeitspakete() {
  if (!(currentUser && currentUser.role === 'admin')) return '';
  const zeilen = workPackages
    .map(
      (w) =>
        `<div class="pj-run pj-ap-zeile${w.archived ? ' pj-ap-weg' : ''}">` +
        `<input class="pj-ap-code" data-pj-ap="${w.id}" data-pj-apfeld="code" value="${esc(w.code)}" ` +
        `maxlength="20" aria-label="${esc(t('exp.wpCode'))}">` +
        `<input class="pj-ap-titel" data-pj-ap="${w.id}" data-pj-apfeld="title" value="${esc(w.title)}" ` +
        `maxlength="200" aria-label="${esc(t('exp.wpTitle'))}">` +
        `<button type="button" class="btn btn-sm fs-xs" data-pj-aparch="${w.id}">` +
        `${esc(w.archived ? t('exp.wpShow') : t('exp.wpHide'))}</button></div>`
    )
    .join('');
  return (
    `<details class="card pj-sec pj-fold" data-pj-apfold="1"${pjApOffen ? ' open' : ''}>` +
    `<summary class="sec">${esc(t('exp.wps', { n: workPackages.length }))}</summary>` +
    `<p class="pj-count">${esc(t('exp.wpHint'))}</p>` +
    zeilen +
    '<div class="pj-run pj-run-new">' +
    `<input id="pj-ap-new-code" class="pj-ap-code" placeholder="${esc(t('exp.wpCodePh'))}" maxlength="20" ` +
    `aria-label="${esc(t('exp.wpCode'))}">` +
    `<input id="pj-ap-new-title" class="pj-ap-titel" placeholder="${esc(t('exp.newTitlePh'))}" maxlength="200" ` +
    `aria-label="${esc(t('exp.wpTitle'))}">` +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-apadd="1">${esc(t('exp.wpAdd'))}</button>` +
    '</div></details>'
  );
}
// Zwei Zeilen je Gefaess, auf jedem Geraet gleich: oben der Code und wofuer es
// steht, unten das Ergebnis, der Ausgang und das Etikett. Alles in eine Zeile zu
// zwingen hiess am Telefon drei Zeilen, weil der Etikettenknopf allein umbrach —
// und drei Gefaesse waren dann neun Zeilen fuer drei Kolben.
function pjGefaessZeile(r) {
  return (
    `<div class="pj-run" data-pj-runrow="${r.id}">` +
    '<div class="pj-run-kopf">' +
    `<span class="pj-run-code">${esc(r.code)}</span>` +
    (r.what ? `<span class="pj-run-what">${esc(r.what)}</span>` : '') +
    `<button type="button" class="btn btn-sm fs-xs pj-run-etikett" data-pj-label="${r.id}">${esc(t('exp.label'))}</button>` +
    `<button type="button" class="pj-run-weg" data-pj-rundel="${r.id}" aria-label="${esc(t('exp.removeRunNamed', { code: r.code }))}" ` +
    `title="${esc(t('exp.removeRunNamed', { code: r.code }))}">&times;</button>` +
    '</div><div class="pj-run-tools">' +
    `<input class="pj-run-res" data-pj-run="${r.id}" data-pj-feld="result" value="${esc(r.result)}" ` +
    `placeholder="${esc(t('exp.resultPh'))}" maxlength="1000">` +
    pjAusgangSelect(r) +
    '</div></div>'
  );
}
// ── Entfernte Gefaesse und Fotos ────────────────────────────
//
// Entfernt ist nicht geloescht: was jemand herausgenommen hat, steht zugeklappt
// unter der Liste, nur zum Lesen, mit einem Knopf, der es zurueckholt. Wer es
// wann entfernt hat, steht im Verlauf.
function pjEntferntesGefaess(r) {
  return (
    '<div class="pj-run pj-run-ro">' +
    '<div class="pj-run-kopf">' +
    `<span class="pj-run-code">${esc(r.code)}</span>` +
    (r.what ? `<span class="pj-run-what">${esc(r.what)}</span>` : '') +
    `<button type="button" class="btn btn-sm fs-xs pj-run-zurueck" data-pj-runback="${r.id}" ` +
    `aria-label="${esc(t('exp.restoreRunNamed', { code: r.code }))}">${esc(t('exp.restore'))}</button>` +
    '</div><div class="pj-run-tools">' +
    `<span class="pj-run-res">${esc(r.result || '—')}</span>` +
    `<span class="pj-out-${esc(r.outcome)}">${esc(t('exp.out.' + r.outcome))}</span>` +
    `<span class="pj-count">${esc(t('exp.removedAt', { d: fmtDt(r.removedAt) }))}</span>` +
    '</div></div>'
  );
}
// Welche Klappen "Entfernte ..." offen sind, je Versuch und Art. Jede Aktion
// zeichnet die Ansicht neu; ohne das klappte die Liste nach jedem Zurueckholen
// wieder zu, und wer drei Fotos zurueckholte, oeffnete sie dreimal.
const pjWegOffen = {};
function pjEntfernte(titel, n, inhalt, schluessel) {
  if (!n) return '';
  return (
    `<details class="pj-fold pj-weg" data-pj-weg="${esc(schluessel)}"${pjWegOffen[schluessel] ? ' open' : ''}>` +
    `<summary class="sec">${esc(t(titel, { n }))}</summary>` +
    inhalt +
    '</details>'
  );
}
function pjFotoKachel(v, f, nr) {
  // Endgueltig geloescht: kein Bild mehr, nur der Platz, an dem es war. Dass es
  // da war, steht mit Pruefsumme im Verlauf.
  if (f.purged) {
    return (
      '<figure class="pj-foto pj-foto-entfernt">' +
      `<div class="pj-foto-leer">${esc(t('exp.purged'))}</div>` +
      `<figcaption>${esc(fmtDt(f.uploadedAt))}</figcaption></figure>`
    );
  }
  const url = '/api/experiments/' + v.id + '/photos/' + encodeURIComponent(f.uuid);
  // Ein entferntes Foto kann ein Admin endgueltig loeschen, fuer das Bild, das
  // nicht gespeichert bleiben darf.
  const admin = !!(currentUser && currentUser.role === 'admin');
  // Ein Bildschirmleser liest die Knoepfe einzeln vor: "Zurueckholen" dreimal
  // sagt nicht, welches Foto. Deshalb traegt jeder Knopf, wovon er spricht.
  // Fotos aus einem Zug tragen dieselbe Minute; die Nummer in der Liste macht
  // ihre Namen verschieden.
  const wann = fmtDtTime(f.uploadedAt);
  const name = { n: nr || 1, d: wann };
  return (
    `<figure class="pj-foto${f.removedAt ? ' pj-foto-entfernt' : ''}"><a href="${esc(url)}" target="_blank" rel="noopener">` +
    `<img src="${esc(url)}?thumb=1" alt="${esc(t('exp.photoAlt', name))}" loading="lazy"></a>` +
    `<figcaption>${esc(fmtDt(f.uploadedAt))}` +
    // Das Original in voller Aufloesung, wo es eins gibt: zum Heranzoomen, zum
    // Ausmessen, zum Beilegen.
    (f.original
      ? ` · <a class="pj-foto-original" href="${esc(url)}?original=1" target="_blank" rel="noopener" ` +
        `aria-label="${esc(t('exp.originalNamed', name))}">${esc(t('exp.original'))}</a>`
      : '') +
    // Ohne Original, weil die App geschlossen wurde, das Netz zu lange weg war
    // oder das Foto von vor den Originalen ist: wer es hochgeladen hat, oder
    // ein Admin, reicht es nach. Der Server prueft dasselbe.
    (!f.original &&
    !f.removedAt &&
    !pjOriginaleUnterwegs.has(f.id) &&
    (admin || (f.uploadedBy && currentUser && f.uploadedBy === currentUser.userId))
      ? ` · <button type="button" class="pj-foto-original-neu" data-pj-original="${f.id}" ` +
        `aria-label="${esc(t('exp.originalAddNamed', name))}">${esc(t('exp.originalAdd'))}</button>`
      : '') +
    '</figcaption>' +
    (f.removedAt
      ? `<button type="button" class="btn btn-sm fs-xs pj-foto-zurueck" data-pj-photoback="${f.id}" ` +
        `aria-label="${esc(t('exp.restorePhotoNamed', name))}">${esc(t('exp.restore'))}</button>` +
        (admin
          ? `<button type="button" class="btn btn-sm fs-xs pj-foto-zurueck" data-pj-photopurge="${f.id}" ` +
            `aria-label="${esc(t('exp.purgePhotoNamed', name))}">${esc(t('exp.purge'))}</button>`
          : '')
      : `<button type="button" class="pj-foto-weg" data-pj-photodel="${f.id}" ` +
        `aria-label="${esc(t('exp.removePhotoNamed', name))}">&times;</button>`) +
    '</figure>'
  );
}
// Ein Experiment, von oben nach unten so, wie der Tag laeuft: was drinsteht,
// wie es aussieht, womit es angesetzt wurde, was dabei herauskam.
function pjDetail(v) {
  const wegG = v.removedRuns;
  const wegF = v.removedPhotos;
  const kopf =
    '<div class="card pj-sec">' +
    '<div class="pj-v-head">' +
    `<div><button type="button" class="pj-zurueck" data-pj-back="1">← ${esc(t('exp.back'))}</button>` +
    `<div><span class="pj-v-code">${esc(v.code)}</span> <span class="pj-v-title">${esc(v.title)}</span></div>` +
    `<div class="pj-v-meta">${esc(t('exp.since', { d: v.started }))}${v.ended ? ' – ' + esc(v.ended) : ''}</div></div>` +
    '<div class="pj-v-knoepfe">' +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-lbexp="${v.id}" ` +
    `aria-label="${esc(t('exp.lbPrintNamed', { code: v.code }))}">${esc(t('exp.lbPrint'))}</button>` +
    (v.status === 'running'
      ? `<button type="button" class="btn btn-sm fs-xs" data-pj-finish="${v.id}">${esc(t('exp.finish'))}</button>`
      : '') +
    '</div></div>' +
    pjApAuswahl(v) +
    (v.runs.length ? v.runs.map(pjGefaessZeile).join('') : `<p class="pj-empty">${esc(t('exp.noVessels'))}</p>`) +
    '<div class="pj-run pj-run-new">' +
    `<input id="pj-new-code" placeholder="${esc(t('exp.codePh'))}" maxlength="40">` +
    `<input id="pj-new-what" placeholder="${esc(t('exp.whatPh'))}" maxlength="200">` +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-addrun="${v.id}">${esc(t('exp.addRun'))}</button>` +
    '</div>' +
    pjEntfernte('exp.removedRuns', wegG.length, wegG.map(pjEntferntesGefaess).join(''), v.id + ':runs') +
    '</div>';
  const fotos =
    '<div class="card pj-sec">' +
    `<div class="sec">${esc(t('exp.photos', { n: v.photos.length }))}</div>` +
    '<div class="pj-fotos">' +
    v.photos.map((f, i) => pjFotoKachel(v, f, i + 1)).join('') +
    '</div>' +
    '<input type="file" id="pj-cam" accept="image/*" capture="environment" multiple hidden>' +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-cam="${v.id}">${esc(t('exp.takePhoto'))}</button>` +
    `<span class="pj-count" id="pj-cam-status">${esc(pjKameraZeile.id === v.id ? pjKameraZeile.text : '')}</span>` +
    '<input type="file" id="pj-orig" accept="image/jpeg" hidden>' +
    pjEntfernte(
      'exp.removedPhotos',
      wegF.length,
      '<div class="pj-fotos">' + wegF.map((f, i) => pjFotoKachel(v, f, i + 1)).join('') + '</div>',
      v.id + ':photos'
    ) +
    '</div>';
  const text =
    '<div class="card pj-sec">' +
    `<label for="pj-v-recipe">${esc(t('exp.recipe'))}</label>` +
    `<textarea id="pj-v-recipe" data-pj-exp="${v.id}" data-pj-feld="recipe" rows="3" ` +
    `placeholder="${esc(t('exp.recipePh'))}">${esc(v.recipe)}</textarea>` +
    `<label for="pj-v-outcome">${esc(t('exp.conclusion'))}</label>` +
    `<textarea id="pj-v-outcome" data-pj-exp="${v.id}" data-pj-feld="outcome" rows="3" ` +
    `placeholder="${esc(t('exp.conclusionPh'))}">${esc(v.outcome)}</textarea>` +
    '</div>';
  return kopf + fotos + text + pjVerlauf(v);
}
function pjArchiv() {
  const alte = experiments.filter((v) => v.status !== 'running' || v.archived);
  if (!alte.length) return '';
  return (
    '<details class="card pj-sec pj-fold"><summary class="sec">' +
    esc(t('exp.archive', { n: alte.length })) +
    '</summary><div class="pj-liste">' +
    alte.map(pjListenzeile).join('') +
    '</div></details>'
  );
}
// ── Verlauf ─────────────────────────────────────────────────
//
// Wer wann was geaendert hat: am Experiment, an seinen Gefaessen, an seinen
// Fotos. Die Felder darueber zeigen den Stand von jetzt; hier steht, wie er
// zustande kam. Das Neueste oben, der Anfang unten.
//
// Zugeklappt, weil man darin nachschlaegt und nicht arbeitet. Geholt wird er
// erst beim Aufklappen und nicht mit /api/data: er waechst mit jeder Aenderung,
// und /api/data laeuft bei jedem Sync. Geholt wird seitenweise: beim Aufklappen
// die juengsten Eintraege, nach einer Aenderung nur, was seitdem dazukam, und
// Aelteres auf Wunsch. Einmal aufgeklappt bleibt er offen, auch wenn die
// Ansicht darunter neu gezeichnet wird.
let pjVerlaufOffen = null; // id des Experiments, dessen Verlauf offen ist
let pjVerlaufStand = null; // { id, eintraege, mehr } oder { id, fehler: true }
let pjVerlaufNr = 0; // ein neuer Anfang verwirft Antworten auf fruehere Abrufe
function pjVerlauf(v) {
  const offen = pjVerlaufOffen === v.id;
  // Die Liste steht nur im offenen Verlauf; zugeklappt waere sie Arbeit fuer
  // nichts, bei jedem Neuzeichnen.
  return (
    `<details class="card pj-sec pj-fold pj-verlauf" data-pj-verlauf="${v.id}"${offen ? ' open' : ''}>` +
    `<summary class="sec">${esc(t('exp.hist'))}</summary>` +
    `<div id="pj-verlauf-liste">${offen ? pjVerlaufListe(v) : ''}</div>` +
    '</details>'
  );
}
// Ein Gefaess heisst im Verlauf so, wie es zuletzt hiess: wer es umbenennt,
// steht als eigener Eintrag da. Der Verlauf kann neuer sein als die geladenen
// Daten; ein Gefaess, das ein anderes Geraet eben angelegt hat, kennt dann nur
// er. Tragen zwei Gefaesse denselben Code (ein entferntes und das, das danach
// unter seinem Code angelegt wurde), kommt die Beschreibung dazu, und reicht die
// nicht, die Kennung.
function pjVerlaufCodes(v, eintraege) {
  const gefaesse = {};
  for (const e of eintraege) {
    if (e.entity !== 'run') continue;
    const g = gefaesse[e.entityId] || { code: '', what: '' };
    if (e.record && e.record.code) {
      g.code = e.record.code;
      g.what = e.record.what || '';
    }
    if (e.field === 'code' && e.to) g.code = e.to;
    if (e.field === 'what') g.what = e.to || '';
    if (g.code) gefaesse[e.entityId] = g;
  }
  for (const r of v.runs.concat(v.removedRuns)) gefaesse[r.id] = { code: r.code, what: r.what || '' };
  const anzahl = (schluessel) => {
    const n = {};
    for (const g of Object.values(gefaesse)) n[schluessel(g)] = (n[schluessel(g)] || 0) + 1;
    return n;
  };
  const jeCode = anzahl((g) => g.code.toLowerCase());
  const jeCodeUndWas = anzahl((g) => g.code.toLowerCase() + '\u0000' + g.what);
  const codes = {};
  for (const [id, g] of Object.entries(gefaesse)) {
    let name = g.code;
    if (jeCode[g.code.toLowerCase()] > 1) {
      if (g.what) name += ' (' + g.what + ')';
      if (jeCodeUndWas[g.code.toLowerCase() + '\u0000' + g.what] > 1) name += ' #' + id;
    }
    codes[id] = name;
  }
  return codes;
}
function pjVerlaufWert(e, x) {
  if (x == null || x === '') return '—';
  if (e.entity === 'run' && e.field === 'outcome') return t('exp.out.' + x);
  if (e.field === 'status') return t('exp.hist.status.' + x);
  if (e.field === 'archived') return x === 'true' ? t('exp.hist.yes') : t('exp.hist.no');
  if (e.field === 'workPackageId') return pjApName(workPackages, x);
  return x;
}
function pjVerlaufZeile(e, codes, fotoBild) {
  const gefaess = e.entity === 'run' ? codes[e.entityId] || '#' + e.entityId : '';
  let was;
  let wert = '';
  if (e.action === 'update') {
    const feld = t('exp.hist.f.' + e.entity + '.' + e.field);
    was = gefaess ? gefaess + ' · ' + feld : feld;
    wert =
      '<div class="pj-hist-wert">' +
      `<del>${esc(pjVerlaufWert(e, e.from))}</del> → <ins>${esc(pjVerlaufWert(e, e.to))}</ins></div>`;
  } else if (e.action === 'backup') {
    // Eine zurueckgespielte Sicherung: was danach stand, ist nicht mehr da, aber
    // in der Kopie von vorher, wenn der Server sie aufgehoben hat.
    was = t(e.entity === 'work_package' ? 'exp.hist.backupWp' : 'exp.hist.backup', {
      n: (e.record && e.record.discarded) || 0
    });
    if (e.record && e.record.kept) was += ' ' + t('exp.hist.backupKept', { file: e.record.kept });
  } else {
    was = t('exp.hist.' + e.action + '.' + e.entity, { code: gefaess });
    // Ein Foto sagt, zu welchem Gefaess es gehoert, wenn es eins hat.
    const runId = e.entity === 'photo' && e.record ? e.record.runId : null;
    if (runId && codes[runId]) was += ' · ' + codes[runId];
  }
  // Ein Foto zeigt sich selbst: drei "Foto hinzugefuegt" aus einem Zug waren
  // sonst nicht auseinanderzuhalten. Die Kachel ist zwischengespeichert.
  const bild = e.entity === 'photo' && e.record && e.record.uuid && fotoBild ? fotoBild(e.record.uuid) : '';
  // Ein Name, dessen Konto es nicht mehr gibt, sagt das: ein neues Konto mit
  // demselben Namen ist ein anderer Mensch.
  const wer = e.user ? ' · ' + esc(e.user) + (e.userGone ? ' ' + esc(t('exp.hist.userGone')) : '') : '';
  return (
    '<li class="pj-hist">' +
    `<div class="pj-hist-kopf">${esc(fmtDtTime(e.at))}${wer}</div>` +
    '<div class="pj-hist-was">' +
    (bild ? `<img class="pj-hist-foto" src="${esc(bild)}" alt="" loading="lazy">` : '') +
    `${esc(was)}</div>` +
    wert +
    '</li>'
  );
}
// Der Ausgangsstand ist ein Eintrag je Datensatz, der beim Einfuehren des
// Verlaufs da war. Einzeln gezeigt waeren das zwanzig gleiche Zeilen am Ende;
// gemeint ist eine: ab hier wird mitgeschrieben.
function pjVerlaufListe(v) {
  const s = pjVerlaufStand;
  if (!s || s.id !== v.id) return `<p class="pj-empty">${esc(t('common.loading'))}</p>`;
  if (s.fehler) return `<p class="pj-empty">${esc(t('exp.histErr'))}</p>`;
  const codes = pjVerlaufCodes(v, s.eintraege);
  const fotos = {};
  for (const f of v.photos.concat(v.removedPhotos)) fotos[f.uuid] = f;
  const fotoBild = (uuid) =>
    fotos[uuid] && !fotos[uuid].purged
      ? '/api/experiments/' + v.id + '/photos/' + encodeURIComponent(uuid) + '?thumb=1'
      : '';
  const zeilen = s.eintraege
    .filter((e) => e.action !== 'baseline')
    .reverse()
    .map((e) => pjVerlaufZeile(e, codes, fotoBild));
  const anfang = s.eintraege.find((e) => e.action === 'baseline');
  if (anfang) {
    zeilen.push(
      '<li class="pj-hist">' +
        `<div class="pj-hist-kopf">${esc(fmtDtTime(anfang.at))}</div>` +
        `<div class="pj-hist-was">${esc(t('exp.hist.baseline'))}</div></li>`
    );
  }
  if (s.mehr) {
    zeilen.push(
      `<li class="pj-hist pj-hist-mehr"><button type="button" class="btn btn-sm fs-xs" data-pj-hist-mehr="${v.id}">` +
        `${esc(t('exp.histMore'))}</button></li>`
    );
  }
  return zeilen.length
    ? '<ul class="pj-hist-liste">' + zeilen.join('') + '</ul>'
    : `<p class="pj-empty">${esc(t('exp.histNone'))}</p>`;
}
// Wie viel Neues ein Nachladen hoechstens holt (der Server nimmt bis 500).
const PJ_VERLAUF_NEU = 500;
// Zwei Seiten zu einer: nach Kennung, jeder Eintrag einmal.
function pjVerlaufMischen(alt, neu) {
  const nachId = new Map();
  for (const e of alt) nachId.set(e.id, e);
  for (const e of neu) nachId.set(e.id, e);
  return [...nachId.values()].sort((a, b) => a.id - b.id);
}
// art: 'erste' die juengsten Eintraege (ersetzt, was da war), 'neu' was seit
// dem letzten bekannten dazukam, 'aelter' die Seite vor dem aeltesten. Ohne
// Stand fuer diesen Versuch ist jeder Abruf ein erster.
function pjVerlaufLaden(id, art) {
  const da = pjVerlaufStand && pjVerlaufStand.id === id && !pjVerlaufStand.fehler ? pjVerlaufStand : null;
  if (!da || !da.eintraege.length) art = 'erste';
  if (art === 'erste') pjVerlaufNr++;
  const nr = pjVerlaufNr;
  let pfad = '/api/experiments/' + id + '/history';
  if (art === 'neu') pfad += '?after=' + da.eintraege[da.eintraege.length - 1].id + '&limit=' + PJ_VERLAUF_NEU;
  if (art === 'aelter') pfad += '?before=' + da.eintraege[0].id;
  return apiGet(pfad)
    .then((r) => ({
      eintraege: (r && r.entries) || [],
      mehr: !!(r && r.more),
      neuester: r && typeof r.newest === 'number' ? r.newest : null
    }))
    .catch(() => null)
    .then((seite) => {
      if (nr !== pjVerlaufNr) return;
      const jetzt = pjVerlaufStand && pjVerlaufStand.id === id && !pjVerlaufStand.fehler ? pjVerlaufStand : null;
      // Juenger als alles, was der Server hat? Dann wurde eine Sicherung
      // zurueckgespielt, und die Kennungen fangen wieder frueher an: von vorn.
      const bekannt = jetzt && jetzt.eintraege.length ? jetzt.eintraege[jetzt.eintraege.length - 1].id : 0;
      if (seite && art !== 'erste' && seite.neuester !== null && seite.neuester < bekannt) {
        pjVerlaufLaden(id, 'erste');
        return;
      }
      if (!seite) {
        // Ein Nachladen, das scheitert, laesst stehen, was schon da ist.
        if (art === 'erste' || !jetzt) pjVerlaufStand = { id, fehler: true };
      } else if (art === 'erste' || !jetzt) {
        pjVerlaufStand = { id, eintraege: seite.eintraege, mehr: seite.mehr };
      } else {
        pjVerlaufStand = {
          id,
          eintraege: pjVerlaufMischen(jetzt.eintraege, seite.eintraege),
          mehr: art === 'aelter' ? seite.mehr : jetzt.mehr
        };
      }
      const el = document.getElementById('pj-verlauf-liste');
      const v = pjExp(pjOffen);
      if (el && v && v.id === id && pjVerlaufOffen === id) el.innerHTML = pjVerlaufListe(v);
      // Eine volle Seite Neues heisst: es kam mehr dazu, als eine Seite fasst.
      if (seite && art === 'neu' && seite.eintraege.length >= PJ_VERLAUF_NEU) pjVerlaufLaden(id, 'neu');
    });
}
// Nach einem Feld, das gespeichert wird, ohne dass die Ansicht neu gezeichnet
// wird: Ergebnis, Mengen, Fazit. Nur die Liste, damit ein halb getippter Satz
// im naechsten Feld stehen bleibt, und nur das Neue.
function pjVerlaufNeu() {
  if (pjOffen && pjVerlaufOffen === pjOffen) pjVerlaufLaden(pjOffen, 'neu');
}
// <details> meldet das Auf- und Zuklappen mit "toggle", und das steigt nicht
// auf; der Zuhoerer haengt deshalb in der Capture-Phase an der Seite. Ein
// Verlauf, der schon als offen gilt, wurde nicht von Hand geoeffnet, sondern
// mit der Ansicht neu gezeichnet; das Holen uebernimmt dann renderVersuch().
function pjToggle(e) {
  const det = e.target;
  if (det && det.dataset && det.dataset.pjWeg) {
    pjWegOffen[det.dataset.pjWeg] = det.open;
    return;
  }
  if (det && det.dataset && det.dataset.pjLb) {
    pjLbOffen = det.open;
    return;
  }
  if (det && det.dataset && det.dataset.pjApfold) {
    pjApOffen = det.open;
    return;
  }
  if (!det || !det.dataset || !det.dataset.pjVerlauf) return;
  const id = Number(det.dataset.pjVerlauf);
  if (det.open) {
    if (pjVerlaufOffen === id) return;
    pjVerlaufOffen = id;
    const el = document.getElementById('pj-verlauf-liste');
    const v = pjExp(id);
    if (el && v) el.innerHTML = pjVerlaufListe(v);
    pjVerlaufLaden(id, 'erste');
  } else if (pjVerlaufOffen === id) {
    // Zu ist zu: der Stand faellt weg, und Antworten, die noch unterwegs sind,
    // zaehlen nicht mehr. Beim naechsten Aufklappen kommt der Verlauf frisch.
    pjVerlaufOffen = null;
    pjVerlaufStand = null;
    pjVerlaufNr++;
  }
}
// Was die Versuchsseite zuletzt gezeichnet hat: die Versuche und welcher offen
// war. Aendert sich das unter ihr, ist sie veraltet.
let pjVersuchGezeigt = null;
function pjVersuchStand() {
  // Die Arbeitspakete mit: ein Paket, das ein anderes Geraet anlegt oder
  // umbenennt, steht sonst erst beim naechsten Neuzeichnen in der Auswahl.
  return JSON.stringify([pjOffen, experiments, workPackages]);
}
// Wann die offene Vorhaben-Seite bei einem neuen Datenstand neu gezeichnet wird.
//
// Die Unterlagen haengen nicht an jedem Datenstand, sie kommen ueber ihren
// eigenen Abruf (pjDocsLaden). Sie werden gezeichnet, wenn noch nichts dasteht,
// und nach einem Sprachwechsel, sonst nicht: niemand soll alle 30 Sekunden ein
// Dokument unter den Augen neu gebaut bekommen.
//
// Der Versuch dagegen zeigt Daten, die sich unter ihm aendern. Ein Gefaess, das
// ein anderes Geraet entfernt hat, stand sonst weiter mit Eingabefeldern da, und
// was man hineintippte, landete im entfernten. Er wird deshalb neu gezeichnet,
// sobald sich an den Versuchen etwas geaendert hat, ausser jemand gibt darin
// gerade etwas ein: dann wartet er, bis das Feld verlassen ist.
function pjRefresh() {
  const offen = document.querySelector('#p-proj .sp.active > div');
  if (!offen) return;
  const versuch = offen.id === 'pj-versuch';
  const leer = !offen.innerHTML;
  const andereSprache = offen.dataset.lang !== currentLang;
  // Beschaeftigt ist, wer in ein Feld tippt. Ein Knopf mit dem Fokus zaehlt
  // nicht: in Safari bekommt ein angetippter Knopf keinen, und nach Entfernen
  // oder Zurueckholen steht der Fokus auf einem, ohne dass jemand etwas tut.
  const fokus = document.activeElement;
  const tippt = !!fokus && offen.contains(fokus) && /^(INPUT|TEXTAREA|SELECT)$/.test(fokus.tagName || '');
  const veraltet = versuch && pjVersuchGezeigt !== pjVersuchStand() && !tippt;
  if (!leer && !andereSprache && !veraltet) return;
  if (versuch) renderVersuch();
  else renderProjekte(offen.id.replace('pj-', ''));
}
// Die Felder zum Anlegen und der Zeitraum fuers Laborbuch: was darin steht und
// noch nicht abgeschickt ist, uebersteht das Neuzeichnen derselben Ansicht.
const PJ_ANLEGEN_FELDER = [
  'pj-new-code',
  'pj-new-what',
  'pj-new-vcode',
  'pj-new-vtitle',
  'pj-ap-new-code',
  'pj-ap-new-title',
  'pj-lb-von',
  'pj-lb-bis',
  'pj-lb-ap'
];
let pjGezeichnetFuer; // pjOffen beim letzten Zeichnen
function renderVersuch() {
  const el = document.getElementById('pj-versuch');
  if (!el) return;
  const v = pjOffen ? pjExp(pjOffen) : null;
  const angefangen = {};
  if (pjGezeichnetFuer === pjOffen) {
    for (const id of PJ_ANLEGEN_FELDER) {
      const feld = document.getElementById(id);
      if (feld && feld.value) angefangen[id] = feld.value;
    }
  }
  el.innerHTML = v ? pjDetail(v) : pjListe();
  pjGezeichnetFuer = pjOffen;
  for (const [id, wert] of Object.entries(angefangen)) {
    const feld = document.getElementById(id);
    if (feld) feld.value = wert;
  }
  el.dataset.lang = currentLang;
  pjVersuchGezeigt = pjVersuchStand();
  if (v && pjVerlaufOffen === v.id) pjVerlaufLaden(v.id, 'neu');
}
// Ein Etikett je Gefaess — dieselbe Vorlage, die die Kulturen drucken. Ein
// Kolben und ein Glas bekommen dasselbe Etikett, und das ist der Punkt: am
// Regal unterscheidet sie nur der Code.
async function pjPrintRun(id) {
  const v = pjExp(pjOffen);
  const r = v && v.runs.find((x) => x.id === id);
  if (!r) return;
  const zpl = itemsToZPL(
    labLabelItems(
      r.code,
      {
        species: v.code + (r.what ? ' · ' + r.what : ''),
        strainText: '',
        notes: '',
        created: v.started,
        parentId: null
      },
      'full',
      false
    )
  );
  const fehler = await sendToPrinter(zpl);
  if (fehler) {
    const blob = new Blob([zpl], { type: 'text/plain' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = r.code + '_label.zpl';
    a.click();
  } else {
    printedFb(t('exp.printed', { code: r.code }));
  }
}
// ── Laborbuch drucken ───────────────────────────────────────
//
// Fuer einen Bericht, fuer eine Pruefung und fuers Archiv: ein Versuch oder
// alle eines Zeitraums auf Papier, mit ihren Gefaessen, den Fotos samt
// Pruefsumme und dem ganzen Verlauf. Gedruckt wird ueber den Druckdialog des
// Browsers, und dort ist "Als PDF sichern" das, was man ablegt. Ein eigenes PDF
// waere eine Bibliothek mehr fuer etwas, das jeder Browser schon kann.
//
// Ein eigenes Fenster wie bei der Arbeitsliste: das Blatt hat Papiermasse und
// keine Seitenleiste, und die Anwendung dahinter bleibt, wie sie war. Die
// Groessen stehen in pt und mm, weil Papier keine Schrifteinstellung liest.
// Der Verlauf ist derselbe wie in der Anwendung (pjVerlaufZeile), nur ohne
// Vorschaubilder: die Fotos stehen gross darueber.
const PJ_LB_STIL =
  '@page{size:A4;margin:14mm 14mm 16mm;@bottom-right{content:counter(page) " / " counter(pages);font:8pt Arial,sans-serif}}' +
  'body{font:10pt/1.35 Arial,Helvetica,sans-serif;color:#000;margin:0}' +
  '@media screen{body{max-width:182mm;margin:10mm auto;padding:0 4mm}}' +
  'h1{font-size:16pt;margin:0 0 2pt}h2{font-size:13pt;margin:0 0 3pt;padding-bottom:2pt;border-bottom:1.5pt solid #000}' +
  'h3{font-size:10.5pt;margin:10pt 0 3pt}.kopf{color:#444;font-size:9pt;margin-bottom:3pt}' +
  'section{break-before:page}section:first-of-type{break-before:auto;margin-top:10pt}' +
  '.meta{color:#333;font-size:9pt}.code{font-weight:bold}.leer{color:#666;font-style:italic;margin:0}' +
  'table{width:100%;border-collapse:collapse;font-size:9pt}' +
  'th,td{text-align:left;vertical-align:top;padding:2pt 4pt;border-bottom:0.5pt solid #bbb}' +
  'th{border-bottom:1pt solid #000;font-size:8pt}tr,li,figure{break-inside:avoid}' +
  '.text{white-space:pre-wrap;border-left:2pt solid #ccc;padding-left:6pt}.weg{color:#666}' +
  '.fotos{display:flex;flex-wrap:wrap;gap:6pt}figure{margin:0;width:calc(50% - 3pt)}' +
  'figure img{display:block;width:100%;height:auto;border:0.5pt solid #999}' +
  'figure .leer{border:0.5pt dashed #999;padding:18pt 6pt;text-align:center}' +
  'figcaption{font-size:8pt;margin-top:2pt}.hash{font-family:monospace;font-size:7pt;overflow-wrap:anywhere}' +
  '.hist{list-style:none;margin:0;padding:0;font-size:9pt}.pj-hist{padding:2pt 0;border-bottom:0.5pt solid #ddd}' +
  '.pj-hist-kopf{color:#444;font-size:8pt}.pj-hist-wert{white-space:pre-wrap}' +
  'del{color:#555}ins{text-decoration:none;font-weight:bold}' +
  '.kette{margin-top:14pt;border-top:1pt solid #000;padding-top:4pt;font-size:8.5pt;break-inside:avoid}' +
  '.kette p{margin:2pt 0}';
// Gedruckt wird, wenn alle Bilder da sind; sonst kaemen leere Rahmen aufs Papier.
const PJ_LB_DRUCK =
  'function drucken(){var b=[].slice.call(document.images);' +
  'Promise.all(b.map(function(i){return i.complete?0:new Promise(function(r){i.onload=i.onerror=r})}))' +
  '.then(function(){setTimeout(function(){window.print()},200)})}' +
  "if(document.readyState==='complete')drucken();else window.addEventListener('load',drucken)";
// Ein Tag aus dem Datumsfeld so, wie er in der Anwendung steht.
function pjLbTag(tag) {
  return tag ? fmtDt(parseDateStr(tag)) : '—';
}
// Wer etwas entfernt hat und wann. Auf dem Papier gibt es keine Klappe, hinter
// der das Entfernte liegt; es steht mit in der Liste und sagt, dass es weg ist.
function pjLbEntfernt(x) {
  if (!x.removedAt) return '';
  return x.removedBy
    ? t('exp.lbRemovedBy', { d: fmtDtTime(x.removedAt), user: x.removedBy })
    : t('exp.removedAt', { d: fmtDtTime(x.removedAt) });
}
function pjLbGefaess(r) {
  const verknuepft = [r.cultureId, r.batchId].filter(Boolean).join(' · ');
  return (
    `<tr${r.removedAt ? ' class="weg"' : ''}>` +
    `<td class="code">${esc(r.code)}</td><td>${esc(r.what)}</td><td>${esc(r.result)}</td>` +
    `<td>${esc(t('exp.out.' + r.outcome))}</td><td>${esc(verknuepft)}</td>` +
    `<td>${esc(pjLbEntfernt(r) || t('exp.lbActive'))}</td></tr>`
  );
}
// Ein Foto mit allem, was es belegt: wann, von wem, an welchem Gefaess, und
// seine Pruefsumme. Mit ihr laesst sich spaeter zeigen, dass eine Datei im
// Archiv genau die ist, die an dem Tag hochgeladen wurde. Ein endgueltig
// geloeschtes Foto hat kein Bild mehr, seine Pruefsumme steht trotzdem da.
function pjMb(bytes) {
  return (Number(bytes || 0) / (1024 * 1024)).toLocaleString(loc(), { maximumFractionDigits: 1 });
}
function pjLbFoto(v, f, nr, codes) {
  const wann = fmtDtTime(f.uploadedAt);
  const bild = f.purged
    ? `<div class="leer">${esc(t('exp.purged'))}</div>`
    : `<img src="${esc('/api/experiments/' + v.id + '/photos/' + encodeURIComponent(f.uuid))}" ` +
      `alt="${esc(t('exp.photoAlt', { n: nr, d: wann }))}">`;
  const zeile = [t('exp.lbPhoto', { n: nr }), wann, f.uploadedBy, f.runId ? codes[f.runId] : '']
    .filter(Boolean)
    .join(' · ');
  const weg = pjLbEntfernt(f);
  // Das Original belegt, was die Kamera aufgenommen hat; das gedruckte Bild ist
  // die verkleinerte Fassung. Beide Pruefsummen, damit sich jede Datei im
  // Archiv zuordnen laesst.
  const o = f.original;
  const original = o
    ? `<div class="hash">${esc(t('exp.lbOriginal', { w: o.width || '?', h: o.height || '?', mb: pjMb(o.bytes) }))}` +
      `<br>SHA-256 ${esc(o.sha256)}</div>`
    : '';
  return (
    `<figure${f.removedAt ? ' class="weg"' : ''}>${bild}<figcaption>${esc(zeile)}` +
    (weg ? '<br>' + esc(weg) : '') +
    `<div class="hash">SHA-256 ${esc(f.sha256)}</div>${original}</figcaption></figure>`
  );
}
function pjLbVersuch(v, pakete) {
  // Das Laborbuch kennt jedes Gefaess, auch die entfernten, in einer Liste.
  const codes = pjVerlaufCodes({ runs: v.runs, removedRuns: [] }, v.history);
  const meta = [
    v.workPackageId != null ? t('exp.wp') + ' ' + pjApName(pakete, v.workPackageId) : '',
    t('exp.hist.f.experiment.started') + ' ' + pjLbTag(v.started),
    t('exp.hist.f.experiment.ended') + ' ' + pjLbTag(v.ended),
    t('exp.hist.status.' + v.status),
    v.archived ? t('exp.lbArchived') : ''
  ]
    .filter(Boolean)
    .join(' · ');
  const text = (titel, inhalt) =>
    `<h3>${esc(titel)}</h3>` + (inhalt ? `<div class="text">${esc(inhalt)}</div>` : '<p class="leer">—</p>');
  const spalten = [
    t('exp.hist.f.run.code'),
    t('exp.hist.f.run.what'),
    t('exp.hist.f.run.result'),
    t('exp.hist.f.run.outcome'),
    t('exp.lbLink'),
    t('exp.lbState')
  ];
  const gefaesse = v.runs.length
    ? '<table><thead><tr>' +
      spalten.map((s) => `<th>${esc(s)}</th>`).join('') +
      '</tr></thead><tbody>' +
      v.runs.map(pjLbGefaess).join('') +
      '</tbody></table>'
    : `<p class="leer">${esc(t('exp.noVessels'))}</p>`;
  const fotos = v.photos.length
    ? '<div class="fotos">' + v.photos.map((f, i) => pjLbFoto(v, f, i + 1, codes)).join('') + '</div>'
    : `<p class="leer">${esc(t('exp.lbNoPhotos'))}</p>`;
  // Von oben nach unten, wie ein Laborbuch sich liest: das Aelteste zuerst. Der
  // Ausgangsstand ist eine Zeile, wie in der Anwendung.
  const zeilen = v.history.filter((e) => e.action !== 'baseline').map((e) => pjVerlaufZeile(e, codes, null));
  const anfang = v.history.find((e) => e.action === 'baseline');
  if (anfang) {
    zeilen.unshift(
      `<li class="pj-hist"><div class="pj-hist-kopf">${esc(fmtDtTime(anfang.at))}</div>` +
        `<div class="pj-hist-was">${esc(t('exp.hist.baseline'))}</div></li>`
    );
  }
  const verlauf = zeilen.length
    ? '<ul class="hist">' + zeilen.join('') + '</ul>'
    : `<p class="leer">${esc(t('exp.lbHistNone'))}</p>`;
  return (
    `<section><h2><span class="code">${esc(v.code)}</span> ${esc(v.title)}</h2>` +
    `<div class="meta">${esc(meta)}</div>` +
    `<h3>${esc(t('exp.lbRuns'))}</h3>` +
    gefaesse +
    text(t('exp.hist.f.experiment.recipe'), v.recipe) +
    text(t('exp.conclusion'), v.outcome) +
    `<h3>${esc(t('exp.photos', { n: v.photos.length }))}</h3>` +
    fotos +
    `<h3>${esc(t('exp.hist'))}</h3>` +
    verlauf +
    '</section>'
  );
}
// Wer die Arbeitspakete angelegt, umbenannt oder ausgeblendet hat: je Paket
// sein heutiger Name, darunter sein Verlauf, das Aelteste zuerst. Ein Paket
// ohne Eintrag im Zeitraum kommt nicht vor, und ohne Eintraege gibt es den
// Abschnitt nicht.
function pjLbArbeitspakete(buch, pakete) {
  const jePaket = new Map();
  for (const e of buch.workPackageHistory || []) {
    if (!jePaket.has(e.entityId)) jePaket.set(e.entityId, []);
    jePaket.get(e.entityId).push(e);
  }
  if (!jePaket.size) return '';
  const teile = [...jePaket.entries()].map(([id, eintraege]) => {
    const zeilen = eintraege.filter((e) => e.action !== 'baseline').map((e) => pjVerlaufZeile(e, {}, null));
    const anfang = eintraege.find((e) => e.action === 'baseline');
    if (anfang) {
      zeilen.unshift(
        `<li class="pj-hist"><div class="pj-hist-kopf">${esc(fmtDtTime(anfang.at))}</div>` +
          `<div class="pj-hist-was">${esc(t('exp.hist.baseline'))}</div></li>`
      );
    }
    const paket = pakete.find((w) => w.id === id);
    const name = pjApName(pakete, id) + (paket && paket.archived ? ' (' + t('exp.lbWpHidden') + ')' : '');
    return `<h3>${esc(name)}</h3><ul class="hist">${zeilen.join('')}</ul>`;
  });
  return `<section><h2>${esc(t('exp.lbWpHist'))}</h2>${teile.join('')}</section>`;
}
// Die Pruefkette unter dem Blatt: ob der Verlauf noch so ist, wie er geschrieben
// wurde, das juengste Glied und der juengste Zeitstempel darauf. Wer das Blatt
// spaeter neben die Datei legt, sieht an dem Glied, ob seitdem etwas geaendert
// wurde; der Zeitstempel belegt, dass es das Glied an dem Tag schon gab, und
// seine Signatur, ob er von der Stelle kommt.
function pjLbKette(buch) {
  const k = buch.chain;
  if (!k) return '';
  const hash = (h) => `<div class="hash">SHA-256 ${esc(h)}</div>`;
  const zeilen = [
    esc(k.ok ? t('exp.lbChainOk', { n: k.entries }) : t('exp.lbChainBroken', { id: k.broken[0] ? k.broken[0].id : '?' }))
  ];
  for (const a of k.adopted || []) {
    zeilen.push(esc(t('exp.lbChainAdopted', { d: fmtDtTime(a.at), n: a.count ?? '?', from: a.from ?? '?', to: a.to ?? '?' })));
  }
  // Jede zurueckgespielte Sicherung: bis wohin ihr Verlauf reicht, was dabei
  // verworfen wurde, je Versuch und Paket, auch was es seitdem nicht mehr gibt,
  // und wo der Stand davor liegt. Ein Blatt von vorher, das ein spaeteres Glied
  // nennt, passt danach nicht mehr zur Datei; hier steht, warum.
  const je = (liste) =>
    liste
      .map((x) => (x.code || '#' + x.id) + ': ' + x.discarded + (x.inBackup === false ? ' (' + t('exp.lbChainRestoreGone') + ')' : ''))
      .join(', ');
  for (const r of k.restores || []) {
    // Eine Sicherung ohne Verlauf (von bevor es ihn gab) verwirft alles, und
    // nach Kennung gezaehlt ist das dann genau.
    const teile = [
      r.upTo
        ? t('exp.lbChainRestore', { d: fmtDtTime(r.at), user: r.user || '—', last: r.upTo, n: r.discarded ?? '?' })
        : t('exp.lbChainRestoreNone', { d: fmtDtTime(r.at), user: r.user || '—', n: r.discarded ?? '?' })
    ];
    if (r.experiments && r.experiments.length) teile.push(t('exp.lbChainRestoreExp', { list: je(r.experiments) }));
    if (r.workPackages && r.workPackages.length) teile.push(t('exp.lbChainRestoreWp', { list: je(r.workPackages) }));
    if (r.counted === 'id' && r.upTo) teile.push(t('exp.lbChainRestoreById'));
    if (r.counted === 'migrated') teile.push(t('exp.lbChainRestoreMigrated'));
    if (r.kept) teile.push(t('exp.lbChainRestoreKept', { file: r.kept }));
    zeilen.push(esc(teile.join(' ')));
  }
  if (k.head) zeilen.push(esc(t('exp.lbChainHead', { id: k.head.historyId })) + hash(k.head.hash));
  const s = k.lastStamp;
  if (s) {
    zeilen.push(esc(t('exp.lbChainStamp', { d: fmtDtTime(s.genTime), id: s.historyId, tsa: s.tsa })) + hash(s.hash));
    if (s.signature === 'ok') zeilen.push(esc(t('exp.lbChainSigOk', { signer: s.signer || '?' })));
    else if (s.signature === 'bad') zeilen.push(esc(t('exp.lbChainSigBad')));
    else if (s.signature === 'unchecked') zeilen.push(esc(t('exp.lbChainSigUnchecked')));
    if (k.head && k.head.historyId > s.historyId) zeilen.push(esc(t('exp.lbChainAfter', { id: s.historyId })));
  } else {
    zeilen.push(esc(t('exp.lbChainNoStamp')));
  }
  // Halten aeltere Stempel nicht, oder lassen sie sich nicht pruefen, steht
  // das auch auf dem Blatt, nicht nur der juengste.
  const sig = k.signatures;
  if (sig && k.stamps > 1 && (sig.bad || sig.unchecked)) {
    zeilen.push(esc(t('exp.lbChainSigAll', { total: k.stamps, bad: sig.bad, unchecked: sig.unchecked })));
  }
  return `<div class="kette"><h3>${esc(t('exp.lbChain'))}</h3>${zeilen.map((z) => '<p>' + z + '</p>').join('')}</div>`;
}
// Das ganze Blatt. buch ist die Antwort von /api/lab-book, wer der Name dessen,
// der druckt.
function pjLbHtml(buch, titel, wer) {
  const zeitraum = buch.from || buch.to;
  const pakete = buch.workPackages || [];
  const kopf = [
    buch.workPackageId != null ? t('exp.lbWpFilter', { name: pjApName(pakete, buch.workPackageId) }) : '',
    zeitraum ? t('exp.lbRange', { from: pjLbTag(buch.from), to: pjLbTag(buch.to) }) : '',
    t('exp.lbCreated', { d: fmtDtTime(buch.createdAt), user: wer || '—' })
  ]
    .filter(Boolean)
    .join(' · ');
  const inhalt = buch.experiments.length
    ? buch.experiments.map((v) => pjLbVersuch(v, pakete)).join('')
    : `<p class="leer">${esc(t('exp.lbNone'))}</p>`;
  // Der Titel des Fensters ist der Dateiname, den der Druckdialog fuer das PDF
  // vorschlaegt. Mit Paket und Zeitraum heissen zwei Berichte nicht gleich, und
  // mit den Tagen als JJJJ-MM-TT stehen sie im Ordner in ihrer Reihenfolge.
  const paket = buch.workPackageId != null ? pakete.find((w) => w.id === buch.workPackageId) : null;
  const dateiname = [
    titel,
    paket ? paket.code : '',
    zeitraum ? t('exp.lbRange', { from: buch.from || '…', to: buch.to || '…' }) : ''
  ]
    .filter(Boolean)
    .join(' ');
  return (
    `<!doctype html><html lang="${esc(currentLang)}"><head><meta charset="utf-8">` +
    `<title>${esc(dateiname)}</title><style>${PJ_LB_STIL}</style></head><body>` +
    `<h1>${esc(titel)}</h1><div class="kopf">${esc(kopf)}</div>` +
    (zeitraum ? `<div class="kopf">${esc(t('exp.lbNote'))}</div>` : '') +
    pjLbArbeitspakete(buch, pakete) +
    inhalt +
    pjLbKette(buch) +
    '<scr' +
    'ipt>' +
    PJ_LB_DRUCK +
    '<\/scr' +
    'ipt></body></html>'
  );
}
// Das Fenster geht im Tippen selbst auf und nicht erst, wenn die Daten da sind:
// eines, das eine Anfrage spaeter kommt, haelt der Browser fuer Werbung und
// blockiert es. Bis die Daten da sind, sagt es, dass es arbeitet.
function pjLbDrucken(pfad, titel) {
  const win = window.open('', '_blank');
  if (!win) {
    toast(t('worklist.popupBlocked'), 'err');
    return Promise.resolve(false);
  }
  win.document.write(
    `<!doctype html><html><head><meta charset="utf-8"><title>${esc(titel)}</title></head>` +
      `<body><p>${esc(t('exp.lbPreparing'))}</p></body></html>`
  );
  win.document.close();
  const wer = (currentUser && currentUser.username) || '';
  return apiGet(pfad).then(
    (buch) => {
      // Wer das Fenster schon zugemacht hat, will nichts mehr drucken.
      if (win.closed) return false;
      win.document.open();
      win.document.write(pjLbHtml(buch, titel, wer));
      win.document.close();
      return true;
    },
    (e) => {
      if (!win.closed) win.close();
      toast(t('exp.lbErr', { err: (e && e.message) || '' }), 'err');
      return false;
    }
  );
}
// Der Zeitraum fuer das Laborbuch, unter der Liste. Vorgeschlagen ist das
// laufende Jahr bis heute: so fragen Berichte meist.
let pjLbOffen = false;
function pjLbZeitraum() {
  if (!experiments.length) return '';
  const heute = new Date();
  return (
    `<details class="card pj-sec pj-fold" data-pj-lb="1"${pjLbOffen ? ' open' : ''}>` +
    `<summary class="sec">${esc(t('exp.lb'))}</summary>` +
    `<p class="pj-count">${esc(t('exp.lbHint'))}</p>` +
    '<div class="pj-bar pj-lb-bar">' +
    `<label class="pj-lb-feld">${esc(t('exp.lbFrom'))}` +
    `<input type="date" id="pj-lb-von" value="${localDateStr(new Date(heute.getFullYear(), 0, 1))}"></label>` +
    `<label class="pj-lb-feld">${esc(t('exp.lbTo'))}` +
    `<input type="date" id="pj-lb-bis" value="${localDateStr(heute)}"></label>` +
    // Fuer den Bericht je Arbeitspaket; ohne Pakete gibt es nichts zu waehlen.
    (workPackages.length
      ? `<label class="pj-lb-feld">${esc(t('exp.wp'))}<select id="pj-lb-ap">` +
        `<option value="">${esc(t('exp.lbWpAll'))}</option>` +
        workPackages.map((w) => `<option value="${w.id}">${esc(w.code + ' · ' + w.title)}</option>`).join('') +
        '</select></label>'
      : '') +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-lbdruck="1">${esc(t('exp.lbPrint'))}</button>` +
    // Das Archiv: dasselbe als ZIP, mit Fotos, Originalen, Pruefkette und
    // Zeitstempeln, pruefbar ohne den Tracker. Es kann gross werden; nur fuer
    // Admins, und der Server baut eins zur Zeit.
    (currentUser && currentUser.role === 'admin'
      ? `<button type="button" class="btn btn-sm fs-xs" data-pj-lbarchiv="1" title="${esc(t('exp.lbArchiveHint'))}">` +
        `${esc(t('exp.lbArchive'))}</button>`
      : '') +
    '</div></details>'
  );
}
// Die Auswahl unter der Liste als Abfrage fuer /api/lab-book und das Archiv,
// oder null, wenn das Ende vor dem Anfang liegt.
function pjLbFrage() {
  const von = (document.getElementById('pj-lb-von') || {}).value || '';
  const bis = (document.getElementById('pj-lb-bis') || {}).value || '';
  const paket = (document.getElementById('pj-lb-ap') || {}).value || '';
  if (von && bis && von > bis) return null;
  return [
    von ? 'from=' + encodeURIComponent(von) : '',
    bis ? 'to=' + encodeURIComponent(bis) : '',
    paket ? 'workPackage=' + encodeURIComponent(paket) : ''
  ]
    .filter(Boolean)
    .join('&');
}
// Der Griff zur Kamera. `capture="environment"` oeffnet am Telefon direkt die
// Ruecklinse statt der Galerie. Zusammengedrueckt wird im Browser mit derselben
// Funktion, die die Kontaminationsfotos benutzt: 1280 px fuers Bild, 200 px
// fuer die Kachel — ein Telefonfoto sind sonst 4 MB.
// Die gewaehlten Bilder an pjKamera. Erst abschreiben, dann leeren: files ist
// die Liste des Feldes selbst, und value = '' leert genau diese Liste. Mit der
// Liste statt einer Abschrift kam bei pjKamera nie ein Bild an. Geleert wird,
// damit dasselbe Bild ein zweites Mal gewaehlt werden kann.
function pjKameraAuswahl(eingabe, id) {
  const dateien = Array.from(eingabe.files || []);
  eingabe.value = '';
  if (id) pjKamera(id, dateien);
}
// Mehr nimmt der Server in einem Zug nicht an (EXP_MAX_PHOTOS_PER_CALL).
const PJ_MAX_FOTOS = 8;
// Die Zeile unter "Foto aufnehmen": was die Kamera eines Versuchs gerade tut.
// Sie steht im Zustand, nicht nur im Element: der Sync nach dem eigenen
// Speichern zeichnet die Seite neu, und eine gemerkte Zeile schrieb danach in
// ein Element, das nicht mehr auf der Seite hing. pjDetail zeichnet sie mit.
let pjKameraZeile = { id: null, text: '' };
function pjKameraStatus(versuchId, text) {
  pjKameraZeile = { id: versuchId, text: text || '' };
  const el = document.getElementById('pj-cam-status');
  if (el && pjOffen === versuchId) el.textContent = pjKameraZeile.text;
}
async function pjKamera(versuchId, dateien) {
  const bilder = Array.from(dateien || []).filter((f) => f && f.type && f.type.startsWith('image/'));
  if (!bilder.length) return;
  // Was ueber die Grenze geht, bleibt liegen, aber nicht stillschweigend: wer
  // zwoelf Bilder waehlt und acht wiederfindet, sucht sonst nach den vier.
  if (bilder.length > PJ_MAX_FOTOS) {
    toast(t('exp.photoLimit', { n: PJ_MAX_FOTOS, rest: bilder.length - PJ_MAX_FOTOS }), 'err');
  }
  const fertig = [];
  for (const datei of bilder.slice(0, PJ_MAX_FOTOS)) {
    pjKameraStatus(versuchId, t('contam.compressing', { name: datei.name }));
    try {
      fertig.push(await _crCompressFile(datei));
    } catch (e) {
      pjKameraStatus(versuchId, t('contam.compressErr'));
      return;
    }
  }
  pjKameraStatus(versuchId, t('exp.uploading', { n: fertig.length }));
  const r = await apiPost('/api/experiment-photos', { experimentId: versuchId, photos: fertig });
  // apiPost wirft nicht, es meldet {error}. Ohne diese Pruefung sah ein
  // gescheiterter Upload aus wie ein gelungener: die Statuszeile wurde leer,
  // das Nachladen setzte den Sync wieder auf gruen, und die Bilder waren weg.
  if (!r || r.error) {
    const warum = t('exp.uploadErr', { err: (r && r.error) || '' });
    pjKameraStatus(versuchId, warum);
    toast(warum, 'err');
    return;
  }
  // Kein vorlaeufiges Einhaengen: die Kennung des Bildes vergibt der Server,
  // und eine Kachel ohne sie zeigt ein kaputtes Bild. Einmal nachladen ist
  // schneller geschrieben und immer richtig. Die Fotos sind gespeichert und
  // erscheinen sofort; die Originale kommen danach.
  await loadData();
  renderVersuch();
  await pjOriginaleHochladen(versuchId, bilder.slice(0, PJ_MAX_FOTOS), r.ids || []);
  pjKameraStatus(versuchId, '');
  await loadData();
  renderVersuch();
}
// Die Originale zu den Fotos, die eben gespeichert wurden: dieselbe Reihenfolge
// wie die Kennungen, die der Server zurueckgab. Das Foto selbst ist schon da, in
// 1280 px; scheitert ein Original, bleibt es dabei, und das wird gesagt.
// Nur JPEG: ein anderes Format haette der Server nicht von seinem Standort
// befreien koennen. Eins nach dem anderen, roh, ohne Base64.
function pjIstJpeg(datei) {
  return datei.type === 'image/jpeg' || (!datei.type && /\.jpe?g$/i.test(datei.name || ''));
}
// Mehr nimmt der Server fuer ein Original nicht an (ORIGINAL_MAX_BYTES).
const PJ_ORIGINAL_MAX = 40 * 1024 * 1024;
// Wie lange ein Original vor jedem neuen Versuch wartet: knapp eine Minute in
// allem. Ohne Netz antwortet der Service Worker sofort mit 503, und zwei
// Versuche ohne Pause waren in Millisekunden verbraucht.
const PJ_ORIGINAL_PAUSEN = [2000, 5000, 15000, 30000];
function pjWarten(ms) {
  return new Promise((r) => setTimeout(r, ms));
}
// Ein Original zu seinem Foto. Wiederholt wird, was sich durch Warten aendern
// kann: kein Netz, ein Fehler am Server. Nicht eine Absage (4xx), die beim
// naechsten Mal dieselbe waere, und nicht 507: ein voller Speicher wird nicht
// leerer, waehrend das Handy 40 MB noch einmal schickt. Gibt den Status der
// letzten Antwort zurueck, 0 ohne Netz. beimWarten(): vor jeder Pause.
async function pjOriginalSenden(fotoId, datei, beimWarten) {
  for (let i = 0; ; i++) {
    let status = 0;
    try {
      const antwort = await authFetch('/api/experiment-photos/' + fotoId + '/original', {
        method: 'PUT',
        headers: { 'Content-Type': 'image/jpeg' },
        body: datei
      });
      status = antwort.status;
    } catch (e) {
      // authFetch wirft nach einem 401, auf dem Weg zur Anmeldung.
      if (e && e.message === 'unauthorized') return 401;
    }
    if (status && (status < 500 || status === 507)) return status;
    if (i >= PJ_ORIGINAL_PAUSEN.length) return status;
    if (beimWarten) beimWarten();
    await pjWarten(PJ_ORIGINAL_PAUSEN[i]);
  }
}
async function pjOriginaleHochladen(versuchId, dateien, ids) {
  const paare = dateien.map((d, i) => [d, ids[i]]).filter(([d, id]) => id && pjIstJpeg(d));
  const senden = paare.filter(([d]) => !(d.size > PJ_ORIGINAL_MAX));
  const zuGross = paare.length - senden.length;
  const ohne = dateien.filter((d) => !pjIstJpeg(d)).length;
  let fehl = 0;
  let voll = 0;
  for (const [, id] of senden) pjOriginaleUnterwegs.add(id);
  try {
    for (let i = 0; i < senden.length; i++) {
      // Ist der Speicher voll, bleiben auch die uebrigen draussen, ohne dass
      // jedes noch einmal ganz hochgeht, um dasselbe zu hoeren.
      if (voll) {
        voll++;
        continue;
      }
      const [datei, id] = senden[i];
      const zeile = t('exp.originalsUploading', { done: i + 1, total: senden.length });
      pjKameraStatus(versuchId, zeile);
      const status = await pjOriginalSenden(id, datei, () =>
        pjKameraStatus(versuchId, zeile + ' ' + t('exp.originalsRetry'))
      );
      if (status === 507) voll++;
      else if (status === 401) {
        fehl += senden.length - i;
        break;
      } else if (status !== 200) fehl++;
    }
  } finally {
    for (const [, id] of senden) pjOriginaleUnterwegs.delete(id);
  }
  // Eine Meldung fuer alles: zwei nacheinander teilen sich einen Platz, und die
  // zweite ueberschrieb die erste, den Fehler eingeschlossen.
  const teile = [];
  if (voll) teile.push(t('exp.originalsFull', { n: voll }));
  if (fehl) teile.push(t('exp.originalsFailed', { n: fehl }));
  if (zuGross) teile.push(tp('exp.originalsTooBig', zuGross));
  if (ohne) teile.push(tp('exp.originalsNotJpeg', ohne));
  if (teile.length) toast(teile.join(' '), voll || fehl || zuGross ? 'err' : undefined);
}
// Ein Original nachreichen, fuer ein Foto, das noch keins hat. Gewaehlt wird
// die Datei, die die Kamera geschrieben hat; der Server prueft, dass sie zu
// diesem Foto passt.
async function pjOriginalNachreichen(versuchId, fotoId, datei) {
  if (!datei) return;
  if (!pjIstJpeg(datei)) {
    toast(tp('exp.originalsNotJpeg', 1), 'err');
    return;
  }
  if (datei.size > PJ_ORIGINAL_MAX) {
    toast(tp('exp.originalsTooBig', 1), 'err');
    return;
  }
  const zeile = t('exp.originalsUploading', { done: 1, total: 1 });
  pjKameraStatus(versuchId, zeile);
  pjOriginaleUnterwegs.add(fotoId);
  let status;
  try {
    status = await pjOriginalSenden(fotoId, datei, () =>
      pjKameraStatus(versuchId, zeile + ' ' + t('exp.originalsRetry'))
    );
  } finally {
    pjOriginaleUnterwegs.delete(fotoId);
  }
  pjKameraStatus(versuchId, '');
  if (status === 200) toast(t('exp.originalAdded'));
  else if (status === 422) toast(t('exp.originalMismatch'), 'err');
  else if (status === 507) toast(t('exp.originalsFull', { n: 1 }), 'err');
  else toast(t('exp.originalsFailed', { n: 1 }), 'err');
  await loadData();
  renderVersuch();
}
// apiPost, apiPatch und apiDelete werfen nicht, sie melden {error}. Wer das
// nicht prueft, zeigt einen gescheiterten Schreibvorgang wie einen gelungenen:
// der Sync-Punkt wird kurz rot, und das naechste Nachladen setzt ihn wieder auf
// gruen. pjFehlgeschlagen sagt es laut und gibt zurueck, ob etwas schiefging.
function pjFehlgeschlagen(r) {
  if (r && !r.error) return false;
  toast(t('proj.saveErr', { err: (r && r.error) || '' }), 'err');
  return true;
}
// Den Fokus auf ein Element nach dem Neuzeichnen; gibt es es nicht (mehr),
// bleibt alles, wie es ist.
function pjFokus(sel) {
  const el = document.querySelector(sel);
  if (el && typeof el.focus === 'function') el.focus();
}
// Tippen speichert beim Verlassen des Feldes, nicht bei jedem Zeichen: ein
// Ergebnis wird in einem Stueck eingetragen, und ein PATCH je Tastendruck waere
// eine Zeile Nutzen und hundert Anfragen.
function pjChange(e) {
  if (e.target.dataset && e.target.dataset.pjDocFor) {
    const datei = e.target.files && e.target.files[0];
    e.target.value = '';
    if (datei) pjDocImportieren(e.target.dataset.pjDocFor, datei);
    return;
  }
  // Code oder Titel eines Arbeitspakets. Leer gibt es nicht: das Feld zeigt
  // dann wieder, was gespeichert ist.
  if (e.target.dataset && e.target.dataset.pjAp) {
    const w = workPackages.find((x) => x.id === Number(e.target.dataset.pjAp));
    const feldName = e.target.dataset.pjApfeld;
    if (!w || !feldName) return;
    const neuerWert = String(e.target.value || '').trim();
    if (!neuerWert || neuerWert === w[feldName]) {
      e.target.value = w[feldName];
      return;
    }
    const alt = w[feldName];
    w[feldName] = neuerWert;
    apiPatch('/api/work-packages/' + w.id, { [feldName]: neuerWert }).then((antwort) => {
      if (pjFehlgeschlagen(antwort)) {
        w[feldName] = alt;
        renderVersuch();
      }
    });
    return;
  }
  const feld = e.target.closest('[data-pj-feld]');
  if (!feld) return;
  const name = feld.dataset.pjFeld;
  // Das Arbeitspaket kommt aus einer Auswahl als Text; gespeichert wird die
  // Kennung, und keins heisst null.
  const wert = name === 'workPackageId' ? (feld.value ? Number(feld.value) : null) : feld.value;
  if (feld.dataset.pjRun) {
    const id = Number(feld.dataset.pjRun);
    const v = pjExp(pjOffen);
    const r = v && v.runs.find((x) => x.id === id);
    // Eine veraltete Zeile: das Gefaess ist inzwischen entfernt, etwa auf einem
    // anderen Geraet. Nichts schicken, neu zeichnen und sagen, warum.
    if (!r) {
      toast(t('exp.runGone'), 'err');
      renderVersuch();
      return;
    }
    const vorher = r[name];
    r[name] = wert;
    apiPatch('/api/experiment-runs/' + id, { [name]: wert }).then((antwort) => {
      // Nicht gespeichert: der alte Wert gilt wieder. Ein Ausgang steht in
      // einer Auswahl, die dann den gespeicherten zeigen muss; ein Ergebnis
      // bleibt im Feld stehen, damit das Getippte nicht verloren ist.
      if (pjFehlgeschlagen(antwort)) {
        r[name] = vorher;
        if (name === 'outcome') renderVersuch();
        return;
      }
      pjVerlaufNeu();
    });
    if (name === 'outcome') renderVersuch();
    return;
  }
  if (feld.dataset.pjExp) {
    const id = Number(feld.dataset.pjExp);
    const v = pjExp(id);
    const vorher = v ? v[name] : undefined;
    if (v) v[name] = wert;
    apiPatch('/api/experiments/' + id, { [name]: wert }).then((antwort) => {
      // Der Text bleibt im Feld, nur der Stand dahinter gilt wieder als alt.
      if (pjFehlgeschlagen(antwort)) {
        if (v) v[name] = vorher;
        return;
      }
      pjVerlaufNeu();
    });
  }
}
// Ein Anlegen, dessen Antwort noch aussteht; ein zweiter Tipp wartet.
let pjGefaessUnterwegs = false;
let pjVersuchUnterwegs = false;
let pjPaketUnterwegs = false;
function pjVersuchClick(e) {
  const aelter = e.target.closest('[data-pj-hist-mehr]');
  if (aelter) {
    pjVerlaufLaden(Number(aelter.dataset.pjHistMehr), 'aelter');
    return true;
  }
  const rein = e.target.closest('[data-pj-open]');
  if (rein) {
    pjOffen = Number(rein.dataset.pjOpen);
    renderVersuch();
    return true;
  }
  if (e.target.closest('[data-pj-back]')) {
    pjOffen = null;
    renderVersuch();
    return true;
  }
  const nachreichen = e.target.closest('[data-pj-original]');
  if (nachreichen) {
    const eingabe = document.getElementById('pj-orig');
    if (eingabe) {
      const versuchId = pjOffen;
      const fotoId = Number(nachreichen.dataset.pjOriginal);
      // Wie bei der Kamera: der Zuhoerer haengt am Feld, das Feld wird nach
      // der Auswahl geleert, damit dieselbe Datei noch einmal gewaehlt werden kann.
      eingabe.onchange = () => {
        const datei = (eingabe.files || [])[0];
        eingabe.value = '';
        pjOriginalNachreichen(versuchId, fotoId, datei);
      };
      eingabe.click();
    }
    return true;
  }
  const kamera = e.target.closest('[data-pj-cam]');
  if (kamera) {
    const eingabe = document.getElementById('pj-cam');
    if (eingabe) {
      const id = Number(kamera.dataset.pjCam);
      // Der Zuhoerer haengt am Feld selbst, nicht an der Seite: wird die Ansicht
      // neu gezeichnet, waehrend die Auswahl offen ist, haengt das Feld nicht
      // mehr in der Seite, und ein Zuhoerer dort hoerte die Auswahl nie.
      eingabe.onchange = () => pjKameraAuswahl(eingabe, id);
      eingabe.click();
    }
    return true;
  }
  // Entfernen und Zurueckholen: danach einmal neu laden, statt die Listen hier
  // von Hand umzuhaengen. Was entfernt ist, bestimmt der Server. Der Knopf, der
  // den Fokus hatte, ist nach dem Neuzeichnen weg; der Fokus geht dorthin, wo
  // das Ding jetzt steht, statt auf die ganze Seite zu fallen.
  const neuZeichnen = (fokus) => async (r) => {
    pjFehlgeschlagen(r);
    await loadData();
    renderVersuch();
    if (fokus) pjFokus(fokus);
  };
  const versuchId = pjOffen;
  const fotoWeg = e.target.closest('[data-pj-photodel]');
  if (fotoWeg) {
    const id = Number(fotoWeg.dataset.pjPhotodel);
    confirm2(t('exp.photoDelTitle'), t('exp.photoDelMsg'), t('exp.remove'), () => {
      apiDelete('/api/experiment-photos/' + id).then(neuZeichnen('[data-pj-weg="' + versuchId + ':photos"] > summary'));
    });
    return true;
  }
  const fotoZurueck = e.target.closest('[data-pj-photoback]');
  if (fotoZurueck) {
    const id = Number(fotoZurueck.dataset.pjPhotoback);
    apiPost('/api/experiment-photos/' + id + '/restore').then(neuZeichnen('[data-pj-photodel="' + id + '"]'));
    return true;
  }
  const fotoEndgueltig = e.target.closest('[data-pj-photopurge]');
  if (fotoEndgueltig) {
    const id = Number(fotoEndgueltig.dataset.pjPhotopurge);
    confirm2(t('exp.purgeTitle'), t('exp.purgeMsg'), t('exp.purge'), () => {
      apiPost('/api/experiment-photos/' + id + '/purge').then((r) => {
        // Die Zeile ist geloescht, eine Datei aber nicht: sonst stuende hier
        // "geloescht", waehrend das Bild noch auf der Platte liegt.
        if (r && r.leftoverFiles) toast(t('exp.purgeLeftover'), 'err');
        return neuZeichnen('[data-pj-weg="' + versuchId + ':photos"] > summary')(r);
      });
    });
    return true;
  }
  const gefaessWeg = e.target.closest('[data-pj-rundel]');
  if (gefaessWeg) {
    const v = pjExp(pjOffen);
    const r = v && v.runs.find((x) => x.id === Number(gefaessWeg.dataset.pjRundel));
    if (!r) {
      toast(t('exp.runGone'), 'err');
      renderVersuch();
      return true;
    }
    confirm2(t('exp.removeRunTitle'), t('exp.removeRunMsg', { code: r.code }), t('exp.remove'), () => {
      apiDelete('/api/experiment-runs/' + r.id).then(neuZeichnen('[data-pj-weg="' + versuchId + ':runs"] > summary'));
    });
    return true;
  }
  const gefaessZurueck = e.target.closest('[data-pj-runback]');
  if (gefaessZurueck) {
    const id = Number(gefaessZurueck.dataset.pjRunback);
    apiPost('/api/experiment-runs/' + id + '/restore').then(neuZeichnen('[data-pj-rundel="' + id + '"]'));
    return true;
  }
  const drucken = e.target.closest('[data-pj-label]');
  if (drucken) {
    pjPrintRun(Number(drucken.dataset.pjLabel));
    return true;
  }
  // Das Laborbuch: ein Versuch aus seiner Ansicht, die eines Zeitraums aus der
  // Liste. Ohne Datum bleibt die Seite offen: ohne Anfang ab dem ersten Versuch,
  // ohne Ende bis heute.
  const buchVersuch = e.target.closest('[data-pj-lbexp]');
  if (buchVersuch) {
    const v = pjExp(Number(buchVersuch.dataset.pjLbexp));
    if (v) pjLbDrucken('/api/lab-book?experiment=' + v.id, t('exp.lbTitle') + ' · ' + v.code);
    return true;
  }
  if (e.target.closest('[data-pj-lbdruck]')) {
    const frage = pjLbFrage();
    if (frage === null) {
      toast(t('exp.lbBadRange'), 'err');
      return true;
    }
    pjLbDrucken('/api/lab-book' + (frage ? '?' + frage : ''), t('exp.lbTitle'));
    return true;
  }
  // Das Archiv laedt der Browser selbst herunter: ein Link mit download, den
  // der Server mit Content-Disposition beantwortet. Die Seite bleibt, wo sie ist.
  if (e.target.closest('[data-pj-lbarchiv]')) {
    const frage = pjLbFrage();
    if (frage === null) {
      toast(t('exp.lbBadRange'), 'err');
      return true;
    }
    const a = document.createElement('a');
    a.href = '/api/lab-book/archive' + (frage ? '?' + frage : '');
    a.download = '';
    document.body.appendChild(a);
    a.click();
    a.remove();
    toast(t('exp.lbArchiveStarted'));
    return true;
  }
  // Ein Arbeitspaket anlegen: Code und Titel, und der Code ist frei, gross
  // oder klein geschrieben. Danach steht es in der Liste und in jeder Auswahl.
  const paketNeu = e.target.closest('[data-pj-apadd]');
  if (paketNeu) {
    if (pjPaketUnterwegs) return true;
    const code = ((document.getElementById('pj-ap-new-code') || {}).value || '').trim();
    const title = ((document.getElementById('pj-ap-new-title') || {}).value || '').trim();
    if (!code || !title) {
      toast(t('exp.needCodeTitle'), 'err');
      return true;
    }
    if (workPackages.some((w) => w.code.toLowerCase() === code.toLowerCase())) {
      toast(t('exp.wpCodeTaken', { code }), 'err');
      return true;
    }
    pjPaketUnterwegs = true;
    paketNeu.disabled = true;
    apiPost('/api/work-packages', { code, title }).then((r) => {
      pjPaketUnterwegs = false;
      if (!r || !r.id) {
        paketNeu.disabled = false;
        pjFehlgeschlagen(r || null);
        return;
      }
      workPackages.push({ id: r.id, code, title, archived: false });
      for (const id of ['pj-ap-new-code', 'pj-ap-new-title']) {
        const feld = document.getElementById(id);
        if (feld) feld.value = '';
      }
      renderVersuch();
    });
    return true;
  }
  // Ausblenden und wieder anbieten. Ein ausgeblendetes Paket bleibt an den
  // Versuchen, die es schon tragen.
  const paketWeg = e.target.closest('[data-pj-aparch]');
  if (paketWeg) {
    const w = workPackages.find((x) => x.id === Number(paketWeg.dataset.pjAparch));
    if (!w) return true;
    const archived = !w.archived;
    apiPatch('/api/work-packages/' + w.id, { archived }).then((r) => {
      if (pjFehlgeschlagen(r)) return;
      w.archived = archived;
      renderVersuch();
    });
    return true;
  }
  const gefaess = e.target.closest('[data-pj-addrun]');
  if (gefaess) {
    if (pjGefaessUnterwegs) return true;
    const code = (document.getElementById('pj-new-code').value || '').trim();
    if (!code) {
      toast(t('exp.needCode'), 'err');
      return true;
    }
    const daten = {
      experimentId: Number(gefaess.dataset.pjAddrun),
      code,
      what: (document.getElementById('pj-new-what').value || '').trim()
    };
    // Dieselbe Pruefung wie auf dem Server, nur vor dem Abschicken: ein Code
    // bezeichnet in einem Versuch ein Gefaess, gross oder klein geschrieben.
    const hier = pjExp(daten.experimentId);
    if (hier && hier.runs.some((x) => String(x.code).toLowerCase() === code.toLowerCase())) {
      toast(t('exp.runCodeTaken', { code }), 'err');
      return true;
    }
    // Bis die Antwort da ist, nimmt der Knopf keinen zweiten Tipp an: ein
    // Doppeltipp auf langsamer Verbindung legte sonst zwei gleiche Gefaesse an.
    // Die Sperre haengt nicht am Knopf: wird die Ansicht zwischendurch neu
    // gezeichnet, ist der Knopf ein neuer und waere wieder frei.
    pjGefaessUnterwegs = true;
    gefaess.disabled = true;
    apiPost('/api/experiment-runs', daten).then((r) => {
      pjGefaessUnterwegs = false;
      if (!r || !r.id) {
        // Die Eingaben bleiben stehen; gezeichnet wird nichts neu.
        gefaess.disabled = false;
        pjFehlgeschlagen(r || null);
        return;
      }
      const v = pjExp(daten.experimentId);
      if (v) v.runs.push({ ...daten, id: r.id, result: '', outcome: 'open', removedAt: null });
      for (const id of ['pj-new-code', 'pj-new-what']) {
        const feld = document.getElementById(id);
        if (feld) feld.value = '';
      }
      renderVersuch();
    });
    return true;
  }
  const neu = e.target.closest('[data-pj-newexp]');
  if (neu) {
    if (pjVersuchUnterwegs) return true;
    const code = (document.getElementById('pj-new-vcode').value || '').trim();
    const title = (document.getElementById('pj-new-vtitle').value || '').trim();
    if (!code || !title) {
      toast(t('exp.needCodeTitle'), 'err');
      return true;
    }
    // Ein Code gehoert einem Versuch, auch einem archivierten. Das zu sagen,
    // bevor etwas abgeschickt ist, erspart die Suche nach dem Grund.
    if (experiments.some((x) => String(x.code).toLowerCase() === code.toLowerCase())) {
      toast(t('exp.codeTaken', { code }), 'err');
      return true;
    }
    const daten = { code, title, started: localDateStr(new Date()) };
    pjVersuchUnterwegs = true;
    neu.disabled = true;
    apiPost('/api/experiments', daten).then((r) => {
      pjVersuchUnterwegs = false;
      if (!r || !r.id) {
        // Code und Titel bleiben in den Feldern stehen.
        neu.disabled = false;
        pjFehlgeschlagen(r || null);
        return;
      }
      for (const id of ['pj-new-vcode', 'pj-new-vtitle']) {
        const feld = document.getElementById(id);
        if (feld) feld.value = '';
      }
      experiments.push({
        ...daten,
        id: r.id,
        ended: null,
        status: 'running',
        archived: false,
        recipe: '',
        outcome: '',
        // Dieselbe Form wie aus /api/data, damit nichts, was sie liest, einen
        // eben angelegten Versuch als Sonderfall kennen muss.
        runs: [],
        removedRuns: [],
        photos: [],
        removedPhotos: []
      });
      // Direkt hinein: wer gerade einen Ansatz angelegt hat, will jetzt die
      // Gefaesse dazuschreiben und nicht erst eine Liste ansehen.
      pjOffen = r.id;
      renderVersuch();
    });
    return true;
  }
  // Abgeschlossen heisst: Enddatum setzen und aus der laufenden Liste nehmen.
  // Die Gefaesse bleiben, das Fazit bleibt, alles steht im Archiv darunter.
  const fertig = e.target.closest('[data-pj-finish]');
  if (fertig) {
    const id = Number(fertig.dataset.pjFinish);
    const v = pjExp(id);
    if (!v) return true;
    confirm2(t('exp.finishTitle'), t('exp.finishMsg', { code: v.code }), t('exp.finish'), () => {
      const vorher = { status: v.status, ended: v.ended };
      v.status = 'done';
      v.ended = localDateStr(new Date());
      apiPatch('/api/experiments/' + id, { status: 'done', ended: v.ended }).then((antwort) => {
        // Nicht abgeschlossen: der Versuch laeuft weiter und steht wieder da.
        if (pjFehlgeschlagen(antwort)) {
          v.status = vorher.status;
          v.ended = vorher.ended;
          renderVersuch();
        }
      });
      pjOffen = null;
      renderVersuch();
    });
    return true;
  }
  return false;
}

const PJ_CHK = 'mp_vorhaben_chk';
function pjChkLoad() {
  try {
    return JSON.parse(localStorage.getItem(PJ_CHK) || '{}');
  } catch (e) {
    return {};
  }
}
function pjChkSave(d) {
  try {
    localStorage.setItem(PJ_CHK, JSON.stringify(d));
  } catch (e) {
    /* privater Modus, voller Speicher: die Liste funktioniert, sie merkt es sich nur nicht */
  }
}
// Ein Haken gehoert zu einem Schritt, nicht zu einer Zeilennummer. Mit der
// Nummer wanderte er nach einem Neuimport, der oben eine Zeile einfuegt, auf den
// naechsten Schritt, und weil erledigte Zeilen ausgeblendet werden, verschwand
// damit ein Schritt, der noch offen war. Der Schluessel ist deshalb der Plan
// und der Wortlaut der Zeile (Marke und Handgriff); steht derselbe Wortlaut
// zweimal im Plan, zaehlt ein Zusatz mit. Plan und Rest trennt ein |, das ein
// Planschluessel nicht enthalten kann (siehe _docBaustein in db.js).
function pjChkSchluessel(plan, it, gesehen) {
  const text = String(it[0] || '') + '\u0000' + String(it[1] || '');
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  const basis = (h >>> 0).toString(36);
  const n = (gesehen[basis] = (gesehen[basis] || 0) + 1);
  return plan + '|' + basis + (n > 1 ? '~' + n : '');
}
// Ein Haken im alten Format dieses Plans: Plan, Bindestrich, Zeilennummer.
function pjChkAlt(k, plan) {
  return k.length > plan.length + 1 && k.startsWith(plan + '-') && /^\d+$/.test(k.slice(plan.length + 1));
}
function pjPlan(pl) {
  const st = pjChkLoad();
  const gesehen = {};
  let umgezogen = false;
  const rows = pl.items
    .map((it, i) => {
      const k = pjChkSchluessel(pl.key, it, gesehen);
      // Haken aus der Zeit, als die Zeilennummer der Schluessel war, ziehen
      // einmal um. Das nimmt an, dass sich die Unterlage seit dem Haken nicht
      // geaendert hat; mehr weiss heute niemand mehr darueber.
      const alt = pl.key + '-' + i;
      if (alt in st) {
        if (st[alt] && !st[k]) st[k] = 1;
        delete st[alt];
        umgezogen = true;
      }
      const id = 'pjc-' + k;
      const an = !!st[k];
      // Die Zeile ist kurz. Was daran noch zu wissen ist — Mengen, Temperaturen,
      // die Begruendung — steht dahinter und kommt erst auf Antippen. Eine
      // Liste, die man lesen muss, ist keine Liste mehr.
      const det = it[2]
        ? `<button type="button" class="pj-more" data-pj-more="${esc(k)}" aria-expanded="false" aria-label="${esc(t('proj.moreOn'))}">…</button>` +
          `<div class="pj-det" id="pjd-${esc(k)}" hidden>${pjText(it[2])}</div>`
        : '';
      return (
        `<div class="pj-chk${an ? ' is-done' : ''}">` +
        `<input type="checkbox" id="${esc(id)}" data-pj-chk="${esc(k)}"${an ? ' checked' : ''}>` +
        `<div class="pj-body"><span class="pj-tag">${pjText(it[0])}</span>` +
        `<label for="${esc(id)}">${pjText(it[1])}</label>${det}</div></div>`
      );
    })
    .join('');
  // Was nach alter Zeilennummer uebrig ist (eine Zeile, die es nicht mehr
  // gibt), geht ebenfalls: sonst hakte es spaeter eine neue Zeile ab, die an
  // dieselbe Stelle rueckt, und die verschwaende als erledigt.
  for (const k of Object.keys(st)) {
    if (pjChkAlt(k, pl.key)) {
      delete st[k];
      umgezogen = true;
    }
  }
  if (umgezogen) pjChkSave(st);
  return (
    `<div class="pj-plan" data-pj-plan="${esc(pl.key)}">` +
    rows +
    `<p class="pj-empty" hidden>${esc(t('proj.allDone'))}</p>` +
    '<div class="pj-bar">' +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-show="${esc(pl.key)}" hidden></button>` +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-reset="${esc(pl.key)}" hidden>${esc(t('proj.resetChecks'))}</button>` +
    '<span class="pj-count"></span></div></div>'
  );
}
/** Zaehlt, blendet aus und beschriftet die beiden Knoepfe — eine Stelle für alles. */
function pjPlanRefresh(box) {
  if (!box) return;
  const st = pjChkLoad();
  const zeilen = box.querySelectorAll('.pj-chk');
  let fertig = 0;
  // Den Schluessel jeder Zeile traegt ihr Kasten, pjPlan hat ihn vergeben.
  zeilen.forEach((row) => {
    const cb = row.querySelector('input');
    const an = !!(cb && st[cb.dataset.pjChk]);
    if (an) fertig++;
    row.classList.toggle('is-done', an);
    if (cb) cb.checked = an;
  });
  const zeigt = box.classList.contains('pj-show-done');
  const zahl = box.querySelector('.pj-count');
  if (zahl) zahl.textContent = t('proj.doneOf', { n: fertig, sum: zeilen.length });
  const leer = box.querySelector('.pj-empty');
  if (leer) leer.hidden = !(fertig === zeilen.length && !zeigt);
  const zeigen = box.querySelector('[data-pj-show]');
  if (zeigen) {
    zeigen.hidden = !fertig;
    zeigen.textContent = t(zeigt ? 'proj.hideDone' : 'proj.showDone', { n: fertig });
  }
  const zurueck = box.querySelector('[data-pj-reset]');
  if (zurueck) zurueck.hidden = !fertig;
}
function pjPlansRefresh(wurzel) {
  (wurzel || document).querySelectorAll('.pj-plan').forEach(pjPlanRefresh);
}
function pjItem(it) {
  const head = it.t ? `<div class="pj-h">${pjText(it.t)}</div>` : '';
  let body = '';
  if (it.p) body = `<p class="pj-p">${pjText(it.p)}</p>`;
  else if (it.ul) body = '<ul class="pj-ul">' + it.ul.map((x) => `<li>${pjText(x)}</li>`).join('') + '</ul>';
  else if (it.ol) body = '<ol class="pj-ul">' + it.ol.map((x) => `<li>${pjText(x)}</li>`).join('') + '</ol>';
  else if (it.note) body = `<div class="pj-note${it.tone === 'warn' ? ' pj-note-warn' : ''}">${pjText(it.note)}</div>`;
  else if (it.table) body = pjTable(it.table);
  else if (it.cards) body = pjCards(it.cards);
  else if (it.steps) body = pjSteps(it.steps);
  else if (it.tasks) body = pjTasks(it.tasks);
  else if (it.plan) body = pjPlan(it.plan);
  else if (it.copy)
    body =
      `<pre class="pj-pre">${esc(it.copy.text)}</pre>` +
      `<button class="btn btn-sm fs-xs" data-pj-copy="1">${esc(t('common.copy'))}</button>`;
  return head + body;
}
// ── Notizen ─────────────────────────────────────────────────
//
// Der Reiter trug zwei Sorten Text nebeneinander: die Handgriffe eines Tages
// und die Recherche dahinter. Beide standen als gleich grosse Karten
// untereinander, und die Recherche war die laengere — ein Dutzend zugeklappter
// Karten unter den offenen. Am Telefon heisst das scrollen an etwas vorbei,
// das heute niemand braucht.
//
// Jetzt gibt es dafuer eine Tuer, und hinter derselben Tuer steht, was hier
// selbst entsteht. Das ist derselbe Gedanke wie beim Ansatz, dessen Ergebnis
// eine Zeile ist: was laenger ist als die Zeile, gehoert nach hinten. Der
// Versuch bleibt eine Tabelle, die man ueberfliegt.
function pjNotizDatum(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  return d.toLocaleDateString(loc(), { day: 'numeric', month: 'long', year: 'numeric' });
}
function pjNotizZeile(n) {
  return (
    `<li class="pj-note" data-pj-note-id="${n.id}">` +
    '<div class="pj-note-top">' +
    `<span class="pj-note-date">${esc(pjNotizDatum(n.created))}${n.updated ? ' · ' + esc(t('proj.noteEdited')) : ''}</span>` +
    '<span class="pj-note-btns">' +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-note-edit="${n.id}">${esc(t('proj.noteEdit'))}</button>` +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-note-del="${n.id}">${esc(t('common.delete'))}</button>` +
    '</span></div>' +
    // Der Text steht doppelt da: einmal gelesen, einmal zum Aendern. Umgeschaltet
    // wird mit einer Klasse, nicht mit neuem HTML — sonst waere der halb
    // getippte Satz beim naechsten Datenstand weg.
    `<div class="pj-note-body">${pjText(n.body)}</div>` +
    `<textarea class="pj-note-edit" rows="6" maxlength="20000" aria-label="${esc(t('proj.notes'))}">${esc(n.body)}</textarea>` +
    '<div class="pj-note-bar">' +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-note-save="${n.id}">${esc(t('common.save'))}</button>` +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-note-cancel="${n.id}">${esc(t('common.cancel'))}</button>` +
    '</div></li>'
  );
}
function pjNotizen(key, zu) {
  const meine = projectNotes.filter((n) => n.tab === key);
  const liste = meine.length
    ? '<ul class="pj-notes">' + meine.map(pjNotizZeile).join('') + '</ul>'
    : `<p class="pj-empty">${esc(t('proj.noteNone'))}</p>`;
  const recherche = zu.length
    ? '<details class="pj-fold pj-refs">' +
      `<summary class="sec">${esc(t('proj.research', { n: zu.length }))}</summary>` +
      zu
        .map(
          (s) =>
            '<details class="pj-fold pj-ref">' +
            `<summary class="sec">${pjText(s.t)}</summary>` +
            s.items.map(pjItem).join('') +
            '</details>'
        )
        .join('') +
      '</details>'
    : '';
  return (
    '<div class="card pj-sec pj-notebox">' +
    `<div class="sec">${esc(t('proj.notes'))}</div>` +
    `<p class="pj-p">${esc(t('proj.noteLead'))}</p>` +
    `<textarea id="pj-note-new" rows="3" maxlength="20000" placeholder="${esc(t('proj.notePh'))}" aria-label="${esc(t('proj.notes'))}"></textarea>` +
    '<div class="pj-note-bar">' +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-note-add="${esc(key)}">${esc(t('proj.noteAdd'))}</button>` +
    '</div>' +
    liste +
    recherche +
    '</div>'
  );
}
// Anlegen, aendern, wegwerfen. Aendern schaltet nur eine Klasse um und schreibt
// nichts neu, damit ein halb getippter Satz einen Datenstand ueberlebt.
function pjNotizClick(e) {
  const anlegen = e.target.closest('[data-pj-note-add]');
  if (anlegen) {
    const feld = document.getElementById('pj-note-new');
    const body = ((feld && feld.value) || '').trim();
    if (!body) {
      toast(t('proj.noteEmpty'), 'err');
      return true;
    }
    if (anlegen.disabled) return true;
    const tab = anlegen.dataset.pjNoteAdd;
    const daten = { tab, body };
    anlegen.disabled = true;
    apiPost('/api/project-notes', daten).then((r) => {
      if (!r || !r.id) {
        // Der Text bleibt im Feld; gezeichnet wird nichts neu.
        anlegen.disabled = false;
        pjFehlgeschlagen(r || null);
        return;
      }
      projectNotes.unshift({ ...daten, id: r.id, created: new Date().toISOString(), updated: '' });
      renderProjekte(tab);
    });
    return true;
  }
  const aendern = e.target.closest('[data-pj-note-edit]');
  if (aendern) {
    const zeile = aendern.closest('.pj-note');
    if (zeile) {
      zeile.classList.add('is-edit');
      const feld = zeile.querySelector('.pj-note-edit');
      if (feld) feld.focus();
    }
    return true;
  }
  const abbrechen = e.target.closest('[data-pj-note-cancel]');
  if (abbrechen) {
    const zeile = abbrechen.closest('.pj-note');
    const n = projectNotes.find((x) => x.id === Number(abbrechen.dataset.pjNoteCancel));
    if (zeile) {
      zeile.classList.remove('is-edit');
      const feld = zeile.querySelector('.pj-note-edit');
      if (feld && n) feld.value = n.body;
    }
    return true;
  }
  const sichern = e.target.closest('[data-pj-note-save]');
  if (sichern) {
    const id = Number(sichern.dataset.pjNoteSave);
    const zeile = sichern.closest('.pj-note');
    const feld = zeile && zeile.querySelector('.pj-note-edit');
    const body = ((feld && feld.value) || '').trim();
    if (!body) {
      toast(t('proj.noteEmpty'), 'err');
      return true;
    }
    const n = projectNotes.find((x) => x.id === id);
    if (n) {
      // Derselbe Text ist keine Aenderung; der Server schreibt dann nichts, und
      // "geaendert" stuende hier nur bis zum naechsten Datenstand.
      if (n.body !== body) {
        const vorher = { body: n.body, updated: n.updated };
        n.body = body;
        n.updated = new Date().toISOString();
        apiPatch('/api/project-notes/' + id, { body }).then((r) => {
          if (!pjFehlgeschlagen(r)) return;
          // Nicht gespeichert: der alte Stand gilt wieder, damit ein zweites
          // Speichern mit demselben Text auch wirklich geschickt wird, und die
          // Notiz geht mit dem Getippten wieder zum Bearbeiten auf.
          n.body = vorher.body;
          n.updated = vorher.updated;
          renderProjekte(n.tab);
          const knopf = document.querySelector('[data-pj-note-save="' + id + '"]');
          const offen = knopf && knopf.closest('.pj-note');
          if (offen) {
            offen.classList.add('is-edit');
            const eingabe = offen.querySelector('.pj-note-edit');
            if (eingabe) eingabe.value = body;
          }
        });
      }
      renderProjekte(n.tab);
    }
    return true;
  }
  const weg = e.target.closest('[data-pj-note-del]');
  if (weg) {
    const id = Number(weg.dataset.pjNoteDel);
    const n = projectNotes.find((x) => x.id === id);
    if (!n) return true;
    confirm2(t('proj.noteDelTitle'), t('proj.noteDelMsg'), t('common.delete'), () => {
      const stelle = projectNotes.indexOf(n);
      projectNotes = projectNotes.filter((x) => x.id !== id);
      apiDelete('/api/project-notes/' + id).then((r) => {
        // Nicht geloescht: die Notiz steht wieder an ihrem Platz.
        if (!pjFehlgeschlagen(r)) return;
        if (!projectNotes.some((x) => x.id === id)) projectNotes.splice(Math.max(0, stelle), 0, n);
        renderProjekte(n.tab);
      });
      renderProjekte(n.tab);
    });
    return true;
  }
  return false;
}
// Solange nichts geladen ist, steht ein Platzhalter da. Schlägt der Abruf fehl,
// bleibt ein Knopf zum Nachladen stehen, statt dass es endlos weiterlädt.
function pjDocsWarten(el, key) {
  el.innerHTML = `<div class="card pj-sec"><p class="pj-empty">${esc(t('proj.docLoading'))}</p></div>`;
  pjDocsLaden().then(() => {
    if (projectDocs) {
      renderProjekte(key);
      return;
    }
    el.innerHTML =
      '<div class="card pj-sec">' +
      `<p class="pj-empty">${esc(t('proj.docLoadErr'))}</p>` +
      '<div class="pj-note-bar">' +
      `<button type="button" class="btn btn-sm fs-xs" data-pj-doc-retry="${esc(key)}">${esc(t('proj.docRetry'))}</button>` +
      '</div></div>';
  });
}
// Der Import nimmt die Datei, die außerhalb des Trackers gepflegt wird: ein
// Objekt mit research, products und build, oder ein einzelnes Dokument für den
// offenen Reiter. Den Knopf sieht nur ein Admin; der Server prüft das ohnehin.
// Dasselbe Muster wie die Kamera: ein verstecktes Dateifeld, ein Knopf davor.
function pjDocImport(key, ersetzen) {
  if (!currentUser || currentUser.role !== 'admin') return '';
  return (
    '<div class="pj-note-bar">' +
    `<input type="file" id="pj-doc-datei-${esc(key)}" accept=".json,application/json" data-pj-doc-for="${esc(key)}" hidden>` +
    `<button type="button" class="btn btn-sm fs-xs" data-pj-doc-import="${esc(key)}">` +
    `${esc(t(ersetzen ? 'proj.docReplace' : 'proj.docImport'))}</button>` +
    '</div>'
  );
}
async function pjDocImportieren(key, datei) {
  let daten;
  try {
    daten = JSON.parse(await datei.text());
  } catch (e) {
    toast(t('proj.docBadFile'), 'err');
    return;
  }
  // Ein einzelnes Dokument gehört zum offenen Reiter; die gepflegte Datei trägt
  // alle drei und geht, wie sie ist.
  const body = daten && Array.isArray(daten.sections) ? { [key]: daten } : daten;
  const r = await apiPut('/api/project-docs', body);
  if (!r || r.error) {
    toast(t('proj.docBadFile') + (r && r.error ? ': ' + r.error : ''), 'err');
    return;
  }
  projectDocs = null;
  toast(t('proj.docImported', { n: (r.tabs || []).length }));
  renderProjekte(key);
}
function renderProjekte(key) {
  const el = document.getElementById('pj-' + key);
  if (!el) return;
  el.dataset.lang = currentLang;
  if (!projectDocs) {
    pjDocsWarten(el, key);
    return;
  }
  const doc = projectDocs[key];
  if (!doc) {
    // Noch nichts importiert. Die Notizen hängen nicht an der Unterlage und
    // bleiben auch ohne sie benutzbar.
    el.innerHTML =
      '<div class="card pj-sec">' +
      `<p class="pj-empty">${esc(t('proj.docNone'))}</p>` +
      pjDocImport(key, false) +
      '</div>' +
      (key === 'research' ? pjNotizen(key, []) : '');
    return;
  }
  const offen = doc.sections.filter((s) => !s.fold);
  const zu = doc.sections.filter((s) => s.fold);
  // Nur die Forschung hat die Notizen-Tuer. Produkte und Bau behalten ihre
  // zugeklappten Karten, bis jemand dort dieselbe Ordnung will — dann ist es
  // diese eine Bedingung.
  const hinten =
    key === 'research'
      ? pjNotizen(key, zu)
      : zu
          .map(
            (s) =>
              '<details class="card pj-sec pj-fold">' +
              `<summary class="sec">${pjText(s.t)}</summary>` +
              s.items.map(pjItem).join('') +
              '</details>'
          )
          .join('');
  el.innerHTML =
    '<div class="card pj-head">' +
    `<div class="pj-title">${pjText(doc.title)}</div>` +
    `<div class="pj-meta">${pjText(doc.meta)}</div>` +
    `<p class="pj-lead">${pjText(doc.lead)}</p>` +
    '</div>' +
    offen
      .map(
        (s) =>
          '<div class="card pj-sec">' +
          `<div class="sec">${pjText(s.t)}</div>` +
          s.items.map(pjItem).join('') +
          '</div>'
      )
      .join('') +
    hinten +
    pjDocImport(key, true);
  pjPlansRefresh(el);
}
// Beide Knöpfe dieser Seite hängen an einem Zuhörer an der Seite selbst: der
// Inhalt wird bei jedem Reiterwechsel neu geschrieben, und Zuhörer, die an den
// Knöpfen selbst hängen, gingen dabei jedes Mal mit verloren.
function pjClick(e) {
  // Ein Tipp auf die Beschriftung schaltet den Kasten, und der Klick des
  // Kastens landet hier — ein Zuhoerer je Seite statt einer je Zeile, weil
  // der Inhalt bei jedem Reiterwechsel neu geschrieben wird.
  const kasten = e.target.closest('[data-pj-chk]');
  if (kasten) {
    const stand = pjChkLoad();
    if (kasten.checked) stand[kasten.dataset.pjChk] = 1;
    else delete stand[kasten.dataset.pjChk];
    pjChkSave(stand);
    pjPlanRefresh(kasten.closest('.pj-plan'));
    return;
  }
  if (pjVersuchClick(e)) return;
  if (pjNotizClick(e)) return;
  const importieren = e.target.closest('[data-pj-doc-import]');
  if (importieren) {
    const feld = document.getElementById('pj-doc-datei-' + importieren.dataset.pjDocImport);
    if (feld) feld.click();
    return;
  }
  const nachladen = e.target.closest('[data-pj-doc-retry]');
  if (nachladen) {
    renderProjekte(nachladen.dataset.pjDocRetry);
    return;
  }
  const mehr = e.target.closest('[data-pj-more]');
  if (mehr) {
    const det = document.getElementById('pjd-' + mehr.dataset.pjMore);
    if (det) {
      det.hidden = !det.hidden;
      mehr.setAttribute('aria-expanded', det.hidden ? 'false' : 'true');
      mehr.textContent = det.hidden ? '…' : '×';
    }
    return;
  }
  const zeigen = e.target.closest('[data-pj-show]');
  if (zeigen) {
    const feld = zeigen.closest('.pj-plan');
    if (feld) {
      feld.classList.toggle('pj-show-done');
      pjPlanRefresh(feld);
    }
    return;
  }
  const zuruecksetzen = e.target.closest('[data-pj-reset]');
  if (zuruecksetzen) {
    const feld = zuruecksetzen.closest('.pj-plan');
    const schluessel = feld && feld.dataset.pjPlan;
    if (!schluessel) return;
    const stand = pjChkLoad();
    // Genau dieser Plan: der Schluessel bis zum letzten |. Mit dem Anfang
    // allein nahm das Zuruecksetzen von "tag" die Haken von "tag-2" mit.
    Object.keys(stand).forEach((k) => {
      const trenner = k.lastIndexOf('|');
      if ((trenner > 0 && k.slice(0, trenner) === schluessel) || pjChkAlt(k, schluessel)) delete stand[k];
    });
    pjChkSave(stand);
    feld.classList.remove('pj-show-done');
    pjPlanRefresh(feld);
    return;
  }
  const kopieren = e.target.closest('[data-pj-copy]');
  if (kopieren) {
    const pre = kopieren.previousElementSibling;
    if (pre) copyToClipboardWithFeedback(pre.textContent, kopieren);
    return;
  }
  const btn = e.target.closest('[data-pj-task]');
  if (!btn) return;
  const text = btn.dataset.pjTask;
  // Zweimal tippen darf nicht zweimal anlegen. Der Vergleich geht über den
  // Text, weil das die einzige Kennung ist, die diese Seite und eine schon
  // bestehende Aufgabe teilen.
  if (manualTasks.some((x) => x.text === text && !x.done)) {
    toast(t('proj.taskExists'));
    return;
  }
  const task = {
    text,
    priority: 'med',
    done: false,
    created: new Date().toISOString(),
    assignee: (currentUser && currentUser.username) || null,
    dueDate: localDateStr(new Date()),
    dueTime: null,
    dueEndTime: null,
    description: '',
    caldavUid: null,
    caldavSynced: null,
    private: false,
    recurrence: null,
    recurrenceUntil: null
  };
  manualTasks.push(task);
  apiPost('/api/tasks', task).then((r) => {
    if (r && r.id) {
      task.id = r.id;
      if (caldav.enabled) pushTaskCaldav(task);
    }
    renderCalendar();
    updateTodoBadge();
  });
  toast(t('proj.taskAdded'));
}

// ─── MUSHROOM STRAINS ────────────────────────────────────────
function fillStrainSelects() {
  const opts =
    '<option value="">' +
    t('strains.selectPlaceholder') +
    '</option>' +
    mushroomStrains.map((ms) => `<option value="${ms.id}">${esc(ms.name)} (${esc(ms.kuerzel)})</option>`).join('');
  const hint = mushroomStrains.length === 0;
  ['nb-strain-sel', 'lw-st'].forEach((id) => {
    const el = document.getElementById(id);
    if (!el) return;
    // Skip rewrite when options are unchanged: SSE-pushed re-syncs (any other
    // user moving bags / scanning / harvesting) would otherwise clobber the
    // <select> mid-tap, which on Android closes the native picker and drops
    // the selection.
    if (el.innerHTML === opts) return;
    const cur = el.value;
    el.innerHTML = opts;
    if (cur) el.value = cur;
  });
  const nbHint = document.getElementById('nb-no-strains-hint');
  if (nbHint) nbHint.style.display = hint ? 'block' : 'none';
}

// Navigate to the Pilzsorten page and focus the name input so the user can
// create a strain without hunting for it. Called from the "Create now →"
// shortcut in the new-batch form and from createBatch / createGrainBatch
// when no strains are defined yet.
function goCreateStrain() {
  go('strains', 'n-strains');
  setTimeout(() => {
    const el = document.getElementById('ms-name');
    if (el) el.focus();
  }, 60);
}

function renderStrains() {
  const body = document.getElementById('strains-body');
  if (!body) return;
  // Die Stämme stehen auf derselben Seite und hängen an denselben Daten — also
  // werden sie mit ihr gezeichnet, an jeder Stelle, die die Sorten neu zeichnet.
  renderStaemme();
  _msFillRecCopyOptions(parseInt((document.getElementById('ms-edit-id') || {}).value, 10) || null);
  if (!mushroomStrains.length) {
    body.innerHTML = '<tr><td colspan="7" class="empty">' + t('strains.empty') + '</td></tr>';
    return;
  }
  // Count usage
  const batchCount = (id) => batches.filter((b) => b.strainId === id).length;
  const cultureCount = (id) => cultures.filter((c) => c.strainId === id).length;
  body.innerHTML = mushroomStrains
    .map((ms) => {
      const bc = batchCount(ms.id),
        cc = cultureCount(ms.id);
      const inUse = bc > 0 || cc > 0;
      const usageParts = [];
      if (bc > 0) usageParts.push(bc + ' ' + t('strains.batches'));
      if (cc > 0) usageParts.push(cc + ' ' + t('strains.cultures'));
      const usageText = usageParts.join(', ') || '—';
      // Quick-create straight from this Sorte. "+ Charge" needs a recipe;
      // "+ Labor" only needs the Sorte (cultures carry no substrate recipe).
      const chargeBtn = ms.recBatchType
        ? `<button class="btn btn-sm btn-p" onclick="msQuickCharge(${ms.id})" style="padding:2px 7px" title="${t('strains.addChargeHint')}">${t('strains.addCharge')}</button> `
        : '';
      // One tap, no dialog, no save button. This gets flipped twice a year for
      // a handful of Sorten; a confirm step would cost more than a mis-tap,
      // which is undone by tapping again.
      const prog = ms.imProgramm !== false;
      return `<tr data-find="strain:${ms.id}"${prog ? '' : ' class="ms-off"'}>
      <td><label class="ms-prog"><input type="checkbox" ${prog ? 'checked' : ''} data-action="toggle-programm" data-id="${ms.id}" aria-label="${esc(t('strains.imProgrammAria', { name: ms.name }))}" /><span>${prog ? esc(t('strains.progOn')) : esc(t('strains.progOff'))}</span></label></td>
      <td style="font-weight:500">${esc(ms.name)}</td>
      <td><span class="fs-meta" style="font-family:monospace;background:var(--c-bg);padding:2px 7px;border-radius:4px">${esc(ms.kuerzel)}</span></td>
      <td class="fs-meta" style="color:var(--c-text-sec)">${ms.description ? esc(ms.description) : '<span style="color:var(--c-text-muted)">—</span>'}</td>
      <td class="fs-meta" style="color:var(--c-text-sec)">${msRecipeSummary(ms)}</td>
      <td class="fs-meta" style="color:var(--c-text-sec)">${esc(usageText)}</td>
      <td style="white-space:nowrap">
        ${chargeBtn}<button class="btn btn-sm" onclick="msQuickLabor(${ms.id})" style="padding:2px 7px" title="${t('strains.addLaborHint')}">${t('strains.addLabor')}</button>
        <button class="btn btn-sm" onclick="editMStrain(${ms.id})" style="padding:2px 7px">${t('strains.editBtn')}</button>
        <button class="btn btn-sm btn-r" onclick="deleteMStrain(${ms.id})" ${inUse ? 'disabled title="' + t('strains.deleteProtected') + '"' : ''} style="padding:2px 7px">&#x2715;</button>
      </td>
    </tr>`;
    })
    .join('');
}

function saveMStrain() {
  const name = document.getElementById('ms-name').value.trim();
  const kuerzel = document.getElementById('ms-kuerzel').value.trim().toUpperCase();
  const desc = document.getElementById('ms-desc').value.trim();
  const editId = document.getElementById('ms-edit-id').value;
  if (!name || !kuerzel) {
    fieldError(name ? 'ms-kuerzel' : 'ms-name', t('strains.required'));
    return;
  }
  if (kuerzel.length < 2 || kuerzel.length > 4) {
    fieldError('ms-kuerzel', t('strains.kuerzelLength'));
    return;
  }
  const rec = _msReadRecipe();
  const payload = { name, kuerzel, description: desc, ...rec };
  const num = (v, d) => (isFinite(parseFloat(v)) ? parseFloat(v) : d);
  const recLocal = {
    recBatchType: rec.recBatchType || '',
    recSubstrate: rec.recSubstrate || 'holzkleie',
    recBagKg: num(rec.recBagKg, 0),
    recRhPct: num(rec.recRhPct, 0),
    recHardwoodPct: num(rec.recHardwoodPct, 0),
    recWheatbranPct: num(rec.recWheatbranPct, 0),
    recCoirPct: num(rec.recCoirPct, 0),
    recGypsum: !!rec.recGypsum,
    recGrainKg: num(rec.recGrainKg, 0),
    recGrainRhPct: num(rec.recGrainRhPct, 52),
    recIncDays: num(rec.recIncDays, 14)
  };
  const req = editId ? apiPatch('/api/mushroom-strains/' + editId, payload) : apiPost('/api/mushroom-strains', payload);
  req.then((r) => {
    if (r && r.error) {
      toast(t('common.error') + ': ' + r.error, 'err');
      return;
    }
    if (!editId && r && r.id) {
      mushroomStrains.push({
        id: r.id,
        name,
        kuerzel,
        description: desc,
        created: new Date().toISOString(),
        ...recLocal
      });
    } else if (editId) {
      const ms = mushroomStrains.find((x) => x.id === parseInt(editId));
      if (ms) {
        ms.name = name;
        ms.kuerzel = kuerzel;
        ms.description = desc;
        Object.assign(ms, recLocal);
      }
    }
    mushroomStrains.sort((a, b) => a.name.localeCompare(b.name));
    fillStrainSelects();
    renderStrains();
    cancelMStrain();
  });
}

function editMStrain(id) {
  const ms = mushroomStrains.find((x) => x.id === id);
  if (!ms) return;
  document.getElementById('ms-name').value = ms.name;
  document.getElementById('ms-kuerzel').value = ms.kuerzel;
  document.getElementById('ms-desc').value = ms.description || '';
  document.getElementById('ms-edit-id').value = id;
  const sv = (eid, val) => {
    const el = document.getElementById(eid);
    if (el) el.value = val;
  };
  sv('ms-rec-type', ms.recBatchType || '');
  sv('ms-rec-substrate', ms.recSubstrate || 'holzkleie');
  sv('ms-rec-bagkg', ms.recBagKg || 0);
  sv('ms-rec-rh', ms.recRhPct || 0);
  sv('ms-rec-hw', ms.recHardwoodPct || 0);
  sv('ms-rec-wb', ms.recWheatbranPct || 0);
  sv('ms-rec-coir', ms.recCoirPct || 0);
  sv('ms-rec-corn', ms.recCornPct || 0);
  sv('ms-rec-gyppct', ms.recGypsumPct || 0);
  sv('ms-rec-spawn', ms.recSpawnPct || 0);
  sv('ms-min-spawn', ms.minSpawnKg || 0);
  sv('ms-min-lc', ms.minLc || 0);
  sv('ms-min-mc', ms.minMc || 0);
  sv('ms-min-pd', ms.minPd || 0);
  msRecShowRef(ms);
  const gyp = document.getElementById('ms-rec-gyp');
  if (gyp) gyp.checked = !!ms.recGypsum;
  sv('ms-rec-grainkg', ms.recGrainKg || 0);
  sv('ms-rec-grainrh', ms.recGrainRhPct != null ? ms.recGrainRhPct : 52);
  sv('ms-rec-days', ms.recIncDays != null ? ms.recIncDays : 14);
  sv('ms-rec-fruitdays', ms.recFruitDays || 0);
  msRecTypeChange();
  _msFillRecCopyOptions(id);
  document.getElementById('ms-save-btn').textContent = t('strains.saveChanges');
  document.getElementById('ms-cancel-btn').style.display = '';
  document.getElementById('ms-name').focus();
}

function cancelMStrain() {
  document.getElementById('ms-name').value = '';
  document.getElementById('ms-kuerzel').value = '';
  document.getElementById('ms-desc').value = '';
  document.getElementById('ms-edit-id').value = '';
  document.getElementById('ms-save-btn').setAttribute('data-i18n', 'strains.save');
  document.getElementById('ms-save-btn').textContent = t('strains.save');
  document.getElementById('ms-cancel-btn').style.display = 'none';
  const sv = (eid, val) => {
    const el = document.getElementById(eid);
    if (el) el.value = val;
  };
  sv('ms-rec-type', '');
  sv('ms-rec-substrate', 'holzkleie');
  sv('ms-rec-bagkg', 0);
  sv('ms-rec-rh', 0);
  sv('ms-rec-hw', 75);
  sv('ms-rec-wb', 25);
  sv('ms-rec-coir', 100);
  // 1 % gypsum and 5 % spawn are common starting points, so a blank Sorte starts
  // there rather than at 0, which would silently mix without either.
  sv('ms-rec-corn', 0);
  sv('ms-rec-gyppct', 1);
  sv('ms-rec-spawn', 5);
  sv('ms-min-spawn', 0);
  sv('ms-min-lc', 0);
  sv('ms-min-mc', 0);
  sv('ms-min-pd', 0);
  msRecShowRef(null);
  const gyp = document.getElementById('ms-rec-gyp');
  if (gyp) gyp.checked = false;
  sv('ms-rec-grainkg', 0);
  sv('ms-rec-grainrh', 52);
  sv('ms-rec-days', 14);
  sv('ms-rec-fruitdays', 0);
  msRecTypeChange();
  _msFillRecCopyOptions(null);
}

function deleteMStrain(id) {
  const ms = mushroomStrains.find((x) => x.id === id);
  if (!ms) return;
  confirm2(t('strains.deleteTitle'), t('strains.deleteMsg', { name: ms.name }), t('strains.delete'), () => {
    apiDelete('/api/mushroom-strains/' + id).then((r) => {
      if (r && r.error) {
        toast(t('common.error') + ': ' + r.error, 'err');
        return;
      }
      mushroomStrains = mushroomStrains.filter((x) => x.id !== id);
      fillStrainSelects();
      renderStrains();
    });
  });
}

// ─── STÄMME ──────────────────────────────────────────────────
// Die Linien einer Pilzsorte (v87): Nordlicht, Blue Seestern 01, SHIKQ07. An Charge
// und Kultur steht der Name in strainText — dort, wo vorher der frei getippte
// Text stand; die Liste ist das Vokabular, aus dem er jetzt gewählt wird. Siehe
// db.js, listStaemme.

// Wie in der Datenbank zählt Groß- und Kleinschreibung nicht: "nordlicht" ist der
// Stamm "Nordlicht". Leerzeichen am Rand und doppelte in der Mitte auch nicht.
function stammNameSauber(v) {
  return String(v == null ? '' : v)
    .trim()
    .replace(/\s+/g, ' ');
}
function stammGleich(a, b) {
  return stammNameSauber(a).toLowerCase() === stammNameSauber(b).toLowerCase();
}
function staemmeFor(strainId) {
  return staemme
    .filter((s) => s.strainId === strainId)
    .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }));
}

// Der Wähler im Schnelldialog ('ms-q') und im Chargen-Assistenten ('wkb'). `wert`
// ist der gewählte Name, '' für ohne Stamm; `neu` heißt, dass statt der Auswahl
// gerade das Feld für einen neuen Stamm dasteht, und `getippt`, was darin steht.
// Der Zustand lebt hier und nicht im DOM, weil beide Dialoge sich bei jedem
// Wechsel von Sorte, Art oder Schritt neu zeichnen.
const STAMM = {};
function stammState(prefix) {
  return STAMM[prefix] || (STAMM[prefix] = { strainId: null, wert: '', neu: false, getippt: '' });
}
function stammReset(prefix) {
  STAMM[prefix] = { strainId: null, wert: '', neu: false, getippt: '' };
}
// Der Name, mit dem gleich angelegt wird — auch einer, der noch getippt im Feld
// steht (siehe stammFertig). '' für ohne Stamm.
function stammAnzeige(prefix) {
  const st = stammState(prefix);
  return (st.neu && stammNameSauber(st.getippt)) || st.wert;
}
// Vor dem Anlegen: Steht noch ein neuer Name im Feld, ohne dass "Hinzufügen"
// gedrückt wurde, ist das trotzdem die Antwort auf die Frage — also wird er
// jetzt angelegt, statt still unter den Tisch zu fallen. Gibt den Namen zurück,
// '' für ohne Stamm, null wenn das Anlegen fehlschlug (gemeldet ist es dann).
async function stammFertig(prefix) {
  const st = stammState(prefix);
  const sel = document.getElementById(prefix + '-stamm');
  if (sel && !st.neu) st.wert = sel.value;
  const feld = document.getElementById(prefix + '-stamm-neu');
  if (feld && st.neu) st.getippt = feld.value;
  if (st.neu && stammNameSauber(st.getippt)) {
    const s = await stammAnlegen(st.strainId, st.getippt);
    if (!s) return null;
    st.wert = s.name;
    st.neu = false;
    st.getippt = '';
  }
  return st.wert;
}

// Zeichnet den Wähler in `<prefix>-stamm-wrap`. Ohne Sorte bleibt er leer —
// welche Stämme es gibt, hängt an ihr. Wechselt die Sorte, fällt ein Name, den
// die neue nicht kennt, auf "ohne Stamm" zurück: Nordlicht beim Lions Mane ist kein
// Stamm des Shiitake.
//
// "+ Neu" legt einen Stamm gleich hier an. Bei der Inventur steht das Glas in der
// Hand, und der Weg über die Sortenseite verwürfe alles, was im Dialog schon
// eingetragen ist.
function stammRender(prefix, strainId) {
  const box = document.getElementById(prefix + '-stamm-wrap');
  if (!box) return;
  const st = stammState(prefix);
  if (st.strainId !== (strainId || null)) {
    st.strainId = strainId || null;
    st.neu = false;
    st.getippt = '';
    if (st.wert && !staemmeFor(st.strainId).some((s) => stammGleich(s.name, st.wert))) st.wert = '';
  }
  if (!st.strainId) {
    box.innerHTML = '';
    return;
  }
  const zeile = st.neu
    ? `<input type="text" id="${prefix}-stamm-neu" data-stamm-neu="${prefix}" maxlength="60" autocomplete="off" value="${esc(st.getippt)}" placeholder="${esc(t('stamm.newPh'))}" />` +
      // Kein Hauptknopf: der Dialog hat schon einen ("Anlegen"), und der legt
      // einen getippten Stamm ohnehin mit an (stammFertig).
      `<button type="button" class="btn" data-stamm="save" data-prefix="${prefix}">${esc(t('stamm.add'))}</button>` +
      `<button type="button" class="btn" data-stamm="cancel" data-prefix="${prefix}" aria-label="${esc(t('common.cancel'))}">&times;</button>`
    : `<select id="${prefix}-stamm" data-stamm-select="${prefix}"><option value="">${esc(t('stamm.none'))}</option>` +
      staemmeFor(st.strainId)
        .map((s) => `<option value="${esc(s.name)}"${stammGleich(s.name, st.wert) ? ' selected' : ''}>${esc(s.name)}</option>`)
        .join('') +
      '</select>' +
      `<button type="button" class="btn" data-stamm="new" data-prefix="${prefix}">${esc(t('stamm.new'))}</button>`;
  box.innerHTML =
    `<label for="${prefix}-stamm${st.neu ? '-neu' : ''}">${esc(t('stamm.label'))}</label>` +
    `<div class="stamm-row">${zeile}</div>`;
}

async function stammKlick(was, prefix, knopf) {
  const st = stammState(prefix);
  if (was === 'new' || was === 'cancel') {
    st.neu = was === 'new';
    st.getippt = '';
    stammRender(prefix, st.strainId);
    const inp = st.neu && document.getElementById(prefix + '-stamm-neu');
    if (inp) inp.focus();
    return;
  }
  // Das Feld selbst ist die letzte Wahrheit: eine Tastatur mit Wortvorschlägen
  // meldet das letzte Wort manchmal erst beim Verlassen.
  const feld = document.getElementById(prefix + '-stamm-neu');
  if (feld) st.getippt = feld.value;
  const name = stammNameSauber(st.getippt);
  if (!name) {
    fieldError(prefix + '-stamm-neu', t('stamm.nameMissing'));
    return;
  }
  // Gesperrt, solange die Anfrage läuft: ein zweiter Tipp legte sonst denselben
  // Namen noch einmal an, und der Server wiese ihn als doppelt ab.
  if (knopf) knopf.disabled = true;
  const s = await stammAnlegen(st.strainId, name);
  if (knopf) knopf.disabled = false;
  if (!s) return;
  st.wert = s.name;
  st.neu = false;
  st.getippt = '';
  stammRender(prefix, st.strainId);
}

// Legt einen Stamm an und gibt ihn zurück — oder den vorhandenen, wenn die Sorte
// ihn schon hat; dann ohne Anfrage. null bei einem Fehler, der dann schon
// gemeldet ist.
async function stammAnlegen(strainId, roh) {
  const name = stammNameSauber(roh);
  if (!strainId || !name) return null;
  const da = staemmeFor(strainId).find((s) => stammGleich(s.name, name));
  if (da) {
    toast(t('stamm.exists'));
    return da;
  }
  const r = await apiPost('/api/staemme', { strainId, name });
  if (!r || r.error) {
    toast(t('common.error') + ': ' + ((r && r.error) || '?'), 'err');
    return null;
  }
  const s = { id: r.id, strainId, name, notes: '', created: new Date().toISOString(), updated: null };
  staemme.push(s);
  renderStaemme();
  toast(t('stamm.added', { name }));
  return s;
}

// ── Die Karte "Stämme" auf der Sortenseite ──
function renderStaemme() {
  const box = document.getElementById('staemme-list');
  if (!box) return;
  const sorten = mushroomStrains.slice().sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  const sel = document.getElementById('st-sorte');
  if (sel) {
    const opts =
      `<option value="">${esc(t('stamm.pickSorte'))}</option>` +
      sorten.map((ms) => `<option value="${ms.id}">${esc(ms.name)} (${esc(ms.kuerzel)})</option>`).join('');
    // Nur neu schreiben, wenn sich etwas geändert hat — siehe fillStrainSelects.
    if (sel.innerHTML !== opts) {
      const cur = sel.value;
      sel.innerHTML = opts;
      if (cur) sel.value = cur;
    }
  }
  // Wie oft ein Name an Chargen und Kulturen steht, je Sorte. `lebt` heißt: an
  // mindestens einer, die nicht verunreinigt ist — in verunreinigten Kulturen
  // standen Versuchsnotizen im Feld, keine Stämme, und die sollen nicht als
  // Vorschlag zurückkommen.
  const zaehler = new Map();
  const zaehle = (strainId, text, tot) => {
    const name = stammNameSauber(text);
    if (!strainId || !name) return;
    const k = strainId + '|' + name.toLowerCase();
    const e = zaehler.get(k) || { strainId, name, n: 0, lebt: false };
    e.n++;
    if (!tot) e.lebt = true;
    zaehler.set(k, e);
  };
  for (const b of batches) zaehle(b.strainId, b.strainText, false);
  for (const c of cultures) zaehle(c.strainId, c.strainText, c.status === 'contam');
  const gruppen = sorten
    .map((ms) => {
      const liste = staemmeFor(ms.id);
      // Was schon an Chargen und Kulturen steht, aber nicht in der Liste: ein Tipp
      // übernimmt es. So kommt der Bestand aus der Zeit des freien Textes in die
      // Liste, ohne dass jemand ihn abschreibt.
      const fremd = [...zaehler.values()].filter(
        (e) => e.strainId === ms.id && e.lebt && !liste.some((s) => stammGleich(s.name, e.name))
      );
      if (!liste.length && !fremd.length) return '';
      const zeilen = liste
        .map((s) => {
          const e = zaehler.get(ms.id + '|' + s.name.toLowerCase());
          return (
            `<div class="stamm-zeile"><div class="stamm-name">${esc(s.name)}` +
            `<span class="fs-meta stamm-use">${esc(e ? t('stamm.used', { n: e.n }) : t('stamm.unused'))}</span></div>` +
            `<button type="button" class="btn btn-sm" data-st-act="rename" data-id="${s.id}">${esc(t('stamm.rename'))}</button>` +
            `<button type="button" class="btn btn-sm btn-r" data-st-act="delete" data-id="${s.id}" aria-label="${esc(t('stamm.delete'))}" title="${esc(t('stamm.delete'))}">&#x2715;</button></div>`
          );
        })
        .join('');
      const vorschlaege = fremd.length
        ? `<div class="fs-meta stamm-fremd">${esc(t('stamm.adoptHint'))} ` +
          fremd
            .map(
              (e) =>
                `<button type="button" class="btn btn-sm" data-st-act="adopt" data-sorte="${ms.id}" data-name="${esc(e.name)}" title="${esc(t('stamm.adoptTitle'))}">+ ${esc(e.name)}</button>`
            )
            .join(' ') +
          '</div>'
        : '';
      return (
        `<div class="stamm-gruppe"><div class="stamm-sorte">${esc(ms.name)} <span class="fs-meta stamm-kz">${esc(ms.kuerzel)}</span></div>` +
        zeilen +
        vorschlaege +
        '</div>'
      );
    })
    .join('');
  box.innerHTML = gruppen || `<div class="fs-meta stamm-leer">${esc(t('stamm.empty'))}</div>`;
}

async function stammVerwaltungAnlegen() {
  const sel = document.getElementById('st-sorte');
  const inp = document.getElementById('st-name');
  const strainId = parseInt(sel && sel.value, 10) || null;
  if (!strainId) {
    fieldError('st-sorte', t('lab.selectPilzsorte'));
    return;
  }
  if (!stammNameSauber(inp && inp.value)) {
    fieldError('st-name', t('stamm.nameMissing'));
    return;
  }
  const knopf = document.getElementById('st-add-btn');
  if (knopf) knopf.disabled = true;
  const s = await stammAnlegen(strainId, inp.value);
  if (knopf) knopf.disabled = false;
  if (s) {
    inp.value = '';
    inp.focus();
  }
}

// Umbenennen zieht Chargen und Kulturen mit, die den alten Namen tragen — der
// Server tut es in der Datenbank (updateStamm), hier geschieht dasselbe mit dem,
// was schon geladen ist, damit die Tabellen nicht bis zum nächsten Abgleich den
// alten Namen zeigen.
function stammUmbenennen(id) {
  const s = staemme.find((x) => x.id === id);
  if (!s) return;
  prompt2(
    t('stamm.renameTitle'),
    t('stamm.newPh'),
    async (roh) => {
      const name = stammNameSauber(roh);
      if (!name || name === s.name) return;
      if (staemmeFor(s.strainId).some((x) => x.id !== id && stammGleich(x.name, name))) {
        toast(t('stamm.exists'), 'err');
        return;
      }
      const r = await apiPatch('/api/staemme/' + id, { name });
      if (!r || r.error) {
        toast(t('common.error') + ': ' + ((r && r.error) || '?'), 'err');
        return;
      }
      for (const x of [...batches, ...cultures]) {
        if (x.strainId === s.strainId && stammGleich(x.strainText, s.name)) x.strainText = name;
      }
      s.name = name;
      renderStaemme();
    },
    { value: s.name }
  );
}

function stammLoeschen(id) {
  const s = staemme.find((x) => x.id === id);
  if (!s) return;
  confirm2(t('stamm.deleteTitle'), t('stamm.deleteMsg', { name: s.name }), t('stamm.delete'), async () => {
    const r = await apiDelete('/api/staemme/' + id);
    if (r && r.error) {
      toast(t('common.error') + ': ' + r.error, 'err');
      return;
    }
    staemme = staemme.filter((x) => x.id !== id);
    renderStaemme();
  });
}

// ─── ANGESETZT AM ────────────────────────────────────────────
// Bei der Inventur kommt Bestand in die App, der schon steht: eine Flüssigkultur
// von vor drei Wochen, eine Platte vom Monatsanfang. Mit dem heutigen Tag
// angelegt, wäre sie auf dem Papier jung und im Regal alt — und ihr Alter ist
// das, worauf man beim Weiterimpfen schaut. Deshalb darf ein Anlegen einen
// früheren Tag tragen.
//
// Die Vorgabe bleibt heute, und das Feld bleibt zu, bis jemand es braucht: der
// Normalfall kostet keinen Tipp mehr als vorher. Der Zustand gilt je Dialog
// ('ms-q', 'wkb') und wird bei jedem Öffnen zurückgesetzt — ein Datum, das für
// die letzte Inventurzeile galt, soll nicht still an der nächsten hängen.
const ANLAGE = {};
function anlageState(prefix) {
  return ANLAGE[prefix] || (ANLAGE[prefix] = { offen: false, datum: '' });
}
function anlageReset(prefix) {
  ANLAGE[prefix] = { offen: false, datum: '' };
}
function anlageRender(prefix) {
  const box = document.getElementById(prefix + '-anlage-wrap');
  if (!box) return;
  const a = anlageState(prefix);
  if (!a.offen) {
    // Zu ist es eine Zeile, kein Feld: gelesen wird "angesetzt heute", und wer
    // es anders braucht, tippt auf den Rest.
    box.innerHTML =
      `<div class="anlage-zu fs-meta"><span class="anlage-k">${esc(t('anlage.label'))}</span><b>${esc(t('anlage.today'))}</b>` +
      `<button type="button" class="wkf-link" data-anlage="open" data-prefix="${prefix}">${esc(t('anlage.change'))}</button></div>`;
    return;
  }
  const heute = localDateStr(new Date());
  box.innerHTML =
    `<label for="${prefix}-anlage">${esc(t('anlage.label'))}</label>` +
    `<div class="stamm-row"><input type="date" id="${prefix}-anlage" data-anlage-input="${prefix}" max="${heute}" value="${esc(a.datum || heute)}" />` +
    `<button type="button" class="btn" data-anlage="today" data-prefix="${prefix}">${esc(t('anlage.backToday'))}</button></div>` +
    `<div class="wkf-hint">${esc(t('anlage.hint'))}</div>`;
}
function anlageKlick(was, prefix) {
  const a = anlageState(prefix);
  a.offen = was === 'open';
  if (!a.offen) a.datum = '';
  anlageRender(prefix);
  anlageGeaendert(prefix);
  const inp = a.offen && document.getElementById(prefix + '-anlage');
  if (!inp) return;
  inp.focus();
  // Der Tipp auf "anderes Datum" ist schon die Bitte um den Kalender; ohne das
  // müsste man am Telefon ein zweites Mal ins Feld tippen.
  try {
    if (typeof inp.showPicker === 'function') inp.showPicker();
  } catch (e) {
    /* ältere Browser: das Feld hat den Fokus, ein Tipp öffnet ihn */
  }
}

// Der Schnelldialog nennt unter den Feldern, was vom Lager ginge; ob etwas geht,
// hängt jetzt am Datum, also rechnet die Zeile neu, sobald es sich ändert. Der
// Assistent zeichnet seinen zweiten Schritt ohnehin frisch.
function anlageGeaendert(prefix) {
  if (prefix === 'ms-q') msQuickPreview();
  if (prefix === 'bmp') bmpPreview();
}

// Der Tag, an dem angesetzt wurde, als JJJJ-MM-TT — '' heißt heute. null, wenn
// er in der Zukunft liegt; dann steht die Meldung schon am Feld, und der
// Aufrufer bricht ab, solange sein Dialog noch offen ist.
function anlageLesen(prefix) {
  const a = anlageState(prefix);
  const inp = document.getElementById(prefix + '-anlage');
  if (inp) a.datum = inp.value || '';
  if (!a.offen || !a.datum) return '';
  const heute = localDateStr(new Date());
  if (a.datum > heute) {
    fieldError(prefix + '-anlage', t('anlage.future'));
    return null;
  }
  return a.datum === heute ? '' : a.datum;
}

// Liegt der gewählte Tag vor heute? Dann ist es Bestand aus der Inventur, und es
// wird angelegt, ohne etwas abzubuchen: das Material ist längst verbraucht, und
// das Regal wird bei der Inventur gezählt, nicht nachgerechnet. Still — die
// Prüfung mit Meldung am Feld macht anlageLesen.
function anlageFrueher(prefix) {
  const a = anlageState(prefix);
  return !!(a.offen && /^\d{4}-\d{2}-\d{2}$/.test(a.datum || '') && a.datum < localDateStr(new Date()));
}

// JJJJ-MM-TT → der Zeitpunkt, der als `created` gespeichert wird. Ein früherer
// Tag wird Mittag an diesem Tag, Ortszeit: weit genug von beiden Mitternächten,
// dass keine Zeitzone und keine Sommerzeitumstellung ihn in den Nachbartag
// schiebt. Leer heißt jetzt — der Augenblick des Anlegens, wie bisher.
function anlageZeitpunkt(ymd) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(ymd || '');
  if (!m) return new Date();
  return new Date(+m[1], +m[2] - 1, +m[3], 12, 0, 0, 0);
}

// nb-created und lw-created werden nur von den Arbeitsgängen gesetzt, direkt vor
// dem Anlegen. Gelesen wird einmal, und dabei geleert: stünde ein Datum still
// weiter darin, bekäme die nächste Charge es mit.
function anlageNehmen(el) {
  const v = el ? el.value : '';
  if (el) el.value = '';
  return v;
}

(function wireStaemme() {
  document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-stamm],[data-anlage],[data-st-act]');
    if (!b || b.disabled) return;
    if (b.dataset.stamm) return stammKlick(b.dataset.stamm, b.dataset.prefix, b);
    if (b.dataset.anlage) return anlageKlick(b.dataset.anlage, b.dataset.prefix);
    const id = parseInt(b.dataset.id, 10);
    if (b.dataset.stAct === 'rename') stammUmbenennen(id);
    else if (b.dataset.stAct === 'delete') stammLoeschen(id);
    else if (b.dataset.stAct === 'adopt') stammAnlegen(parseInt(b.dataset.sorte, 10), b.dataset.name);
  });
  document.addEventListener('change', (e) => {
    const sel = e.target.closest('[data-stamm-select]');
    if (sel) stammState(sel.dataset.stammSelect).wert = sel.value;
    const tag = e.target.closest('[data-anlage-input]');
    if (tag) {
      anlageState(tag.dataset.anlageInput).datum = tag.value;
      anlageGeaendert(tag.dataset.anlageInput);
    }
  });
  // Mitschreiben, was im Feld für den neuen Namen steht: der Dialog zeichnet sich
  // beim Wechsel der Art oder des Schritts neu, und das Getippte soll das
  // überstehen.
  document.addEventListener('input', (e) => {
    const inp = e.target.closest && e.target.closest('[data-stamm-neu]');
    if (inp) stammState(inp.dataset.stammNeu).getippt = inp.value;
  });
  // Enter im Feld für den neuen Namen legt an, wie der Knopf daneben.
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' || !e.target.closest) return;
    const inp = e.target.closest('[data-stamm-neu]');
    if (!inp) return;
    e.preventDefault();
    const knopf = inp.parentNode && inp.parentNode.querySelector('[data-stamm="save"]');
    stammKlick('save', inp.dataset.stammNeu, knopf);
  });
  const add = document.getElementById('st-add-btn');
  if (add) add.addEventListener('click', stammVerwaltungAnlegen);
  const name = document.getElementById('st-name');
  if (name)
    name.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter') return;
      e.preventDefault();
      stammVerwaltungAnlegen();
    });
})();

// ── Sorte production recipe (rec_*) — editor toggle + per-bag need preview ───
function _msReadRecipe() {
  const v = (id) => {
    const el = document.getElementById(id);
    return el ? el.value : '';
  };
  const chk = (id) => {
    const el = document.getElementById(id);
    return el && el.checked ? 1 : 0;
  };
  return {
    recBatchType: v('ms-rec-type') || '',
    recSubstrate: v('ms-rec-substrate') || 'holzkleie',
    recBagKg: v('ms-rec-bagkg'),
    recRhPct: v('ms-rec-rh'),
    recHardwoodPct: v('ms-rec-hw'),
    recWheatbranPct: v('ms-rec-wb'),
    recCoirPct: v('ms-rec-coir'),
    recCornPct: v('ms-rec-corn'),
    recGypsumPct: v('ms-rec-gyppct'),
    recSpawnPct: v('ms-rec-spawn'),
    // The old flag and the new share have to agree, or a Charge created the
    // per-bag way would skip gypsum that the mix puts in — same recipe, two
    // answers depending on which screen made it.
    recGypsum: chk('ms-rec-gyp') || v('ms-rec-gyppct') > 0,
    minSpawnKg: v('ms-min-spawn'),
    minLc: v('ms-min-lc'),
    minMc: v('ms-min-mc'),
    minPd: v('ms-min-pd'),
    recGrainKg: v('ms-rec-grainkg'),
    recGrainRhPct: v('ms-rec-grainrh'),
    recIncDays: v('ms-rec-days'),
    recFruitDays: v('ms-rec-fruitdays')
  };
}
// Map a recipe (rec_*) onto the product spec shape so we can reuse the shared
// _ohProdNeedCompute charge math (same hydration formula as the Charge form).
function _msRecipeToProd(rec) {
  return {
    prodType: rec.recBatchType || 'buy',
    prodSubstrate: rec.recSubstrate,
    prodBagKg: rec.recBagKg,
    prodRhPct: rec.recRhPct,
    prodHardwoodPct: rec.recHardwoodPct,
    prodWheatbranPct: rec.recWheatbranPct,
    prodCoirPct: rec.recCoirPct,
    prodGypsum: rec.recGypsum,
    prodGrainKg: rec.recGrainKg,
    prodGrainRhPct: rec.recGrainRhPct
  };
}
function _msStrainToRecipe(ms) {
  return {
    recBatchType: ms.recBatchType,
    recSubstrate: ms.recSubstrate,
    recBagKg: ms.recBagKg,
    recRhPct: ms.recRhPct,
    recHardwoodPct: ms.recHardwoodPct,
    recWheatbranPct: ms.recWheatbranPct,
    recCoirPct: ms.recCoirPct,
    recGypsum: ms.recGypsum,
    recGrainKg: ms.recGrainKg,
    recGrainRhPct: ms.recGrainRhPct
  };
}
const _MS_MAT_KEY = {
  grain: 'inv.grain',
  hardwood: 'inv.hardwood',
  wheatbran: 'inv.wheatBran',
  gypsum: 'inv.gypsum',
  coir: 'inv.coir'
};
function _msNeedParts(rec, mult) {
  const fmt = (n) => (Math.round(n * 1000) / 1000).toString();
  const need = _ohProdNeedCompute(_msRecipeToProd(rec));
  const m = mult || 1;
  return Object.keys(need)
    .filter((k) => need[k] > 0)
    .map((k) => `${esc(t(_MS_MAT_KEY[k] || k))} ${fmt(need[k] * m)} kg`);
}
function msRecTypeChange() {
  const type = (document.getElementById('ms-rec-type') || {}).value || '';
  const sub = (document.getElementById('ms-rec-substrate') || {}).value || 'holzkleie';
  const set = (id, disp) => {
    const el = document.getElementById(id);
    if (el) el.style.display = disp;
  };
  set('ms-rec-subgroup', type === 'block' || type === 'allinone' ? 'block' : 'none');
  set('ms-rec-graingroup', type === 'grain' || type === 'allinone' ? 'block' : 'none');
  set('ms-rec-holzgroup', sub === 'holzkleie' ? 'grid' : 'none');
  set('ms-rec-coirgroup', sub === 'cvg' ? 'grid' : 'none');
  set('ms-rec-daysrow', type ? 'grid' : 'none');
  msRecNeed();
}
function msRecNeed() {
  const el = document.getElementById('ms-rec-need');
  if (!el) return;
  const rec = _msReadRecipe();
  if (!rec.recBatchType) {
    el.textContent = '';
    return;
  }
  const parts = _msNeedParts(rec, 1);
  el.textContent = parts.length ? t('orders.p.needPrefix') + ' ' + parts.join(' · ') : '';
}
// Populate the "copy recipe from another Sorte" dropdown with Sorten that have a
// recipe (excluding the one being edited).
function _msFillRecCopyOptions(excludeId) {
  const sel = document.getElementById('ms-rec-copy');
  if (!sel) return;
  const list = mushroomStrains
    .filter((x) => x.recBatchType && x.id !== excludeId)
    .sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  sel.innerHTML =
    '<option value="">' +
    esc(t('strains.recCopyNone')) +
    '</option>' +
    list.map((x) => `<option value="${x.id}">${esc(x.name)}${x.kuerzel ? ' (' + esc(x.kuerzel) + ')' : ''}</option>`).join('');
  sel.value = '';
}
// Copy another Sorte's recipe into the form (most Sorten share the same recipe).
function msRecCopyFrom() {
  const sel = document.getElementById('ms-rec-copy');
  if (!sel || !sel.value) return;
  const src = mushroomStrains.find((x) => x.id === parseInt(sel.value, 10));
  if (!src) return;
  const sv = (eid, val) => {
    const el = document.getElementById(eid);
    if (el) el.value = val;
  };
  sv('ms-rec-type', src.recBatchType || '');
  sv('ms-rec-substrate', src.recSubstrate || 'holzkleie');
  sv('ms-rec-bagkg', src.recBagKg || 0);
  sv('ms-rec-rh', src.recRhPct || 0);
  sv('ms-rec-hw', src.recHardwoodPct || 0);
  sv('ms-rec-wb', src.recWheatbranPct || 0);
  sv('ms-rec-coir', src.recCoirPct || 0);
  sv('ms-rec-corn', src.recCornPct || 0);
  sv('ms-rec-gyppct', src.recGypsumPct || 0);
  sv('ms-rec-spawn', src.recSpawnPct || 0);
  sv('ms-min-spawn', src.minSpawnKg || 0);
  sv('ms-min-lc', src.minLc || 0);
  sv('ms-min-mc', src.minMc || 0);
  sv('ms-min-pd', src.minPd || 0);
  msRecShowRef(src);
  const gyp = document.getElementById('ms-rec-gyp');
  if (gyp) gyp.checked = !!src.recGypsum;
  sv('ms-rec-grainkg', src.recGrainKg || 0);
  sv('ms-rec-grainrh', src.recGrainRhPct != null ? src.recGrainRhPct : 52);
  sv('ms-rec-days', src.recIncDays != null ? src.recIncDays : 14);
  sv('ms-rec-fruitdays', src.recFruitDays || 0);
  sel.value = '';
  msRecTypeChange();
}
function msRecShowRef(ms) {
  const el = document.getElementById('ms-rec-ref');
  if (!el) return;
  const colon = ms && ms.recColonText;
  const steril = ms && ms.recSterilText;
  if (!colon && !steril) {
    el.textContent = '';
    return;
  }
  el.textContent = t('strains.recRef', { colon: colon || '—', steril: steril || '—' });
}
function msRecipeSummary(ms) {
  const type = ms.recBatchType || '';
  if (!type) return '<span style="color:var(--c-text-muted)">—</span>';
  const typeLabel =
    { block: t('strains.recBlock'), allinone: t('strains.recAllinone'), grain: t('strains.recGrain') }[type] || type;
  const parts = [esc(typeLabel)];
  if (type === 'block' || type === 'allinone') {
    if ((ms.recSubstrate || 'holzkleie') === 'cvg') parts.push(esc(t('orders.sub.cvg')));
    else parts.push('HW' + (ms.recHardwoodPct || 0) + '/WB' + (ms.recWheatbranPct || 0));
    if (ms.recBagKg) parts.push((ms.recBagKg || 0) + ' kg');
  }
  if ((type === 'allinone' || type === 'grain') && ms.recGrainKg) parts.push('Grain ' + ms.recGrainKg + ' kg');
  return '<span class="fs-xs">' + parts.join(' · ') + '</span>';
}
function msRecipeSummaryText(ms) {
  // Plain-text variant of msRecipeSummary for the quick-create modal subtitle.
  const div = document.createElement('div');
  div.innerHTML = msRecipeSummary(ms);
  return div.textContent || '';
}

// ── Quick-create: spin a Charge or Laborarbeit straight from a Sorte recipe ──
let _msQuickCtx = null;

function msQuickCharge(id) {
  const ms = mushroomStrains.find((x) => x.id === id);
  if (!ms) return;
  if (!ms.recBatchType) {
    toast(t('msq.noRecipe'), 'err');
    return;
  }
  msQuickOpen('charge', ms);
}
function msQuickLabor(id) {
  const ms = mushroomStrains.find((x) => x.id === id);
  if (!ms) return;
  msQuickOpen('labor', ms);
}
// Dashboard entry points: open the dialog with a Sorte dropdown (none preselected),
// so "Neue Charge" / "Laborarbeit" go straight to the create dialog instead of the
// Pilzsorten list. The recipe still comes from whichever Sorte is then chosen.
function msQuickChargeNew() {
  msQuickOpen('charge', null);
}
function msQuickLaborNew() {
  msQuickOpen('labor', null);
}
// Last quantity used per quick-create mode, so the dialog reopens on the batch
// size actually being run instead of 1. Stored per mode: a Charge is typically
// many bags, a Laborarbeit only a few.
function _msqLastQty(mode) {
  try {
    const s = JSON.parse(localStorage.getItem('mp-msq-qty') || '{}');
    const n = parseInt(s[mode], 10);
    if (n > 0) return n;
  } catch (e) {
    /* storage disabled — fall back to 1 */
  }
  return 1;
}
// Die Art, mit der die Laborarbeit aufgeht: die zuletzt angelegte, sonst
// Petrischale. Vorher stand immer "Slant registrieren" da — die eine Art ohne
// Herkunft, also ohne "Beimpft mit", und genau das Feld fehlte dann.
function _msqLastArt() {
  try {
    const a = localStorage.getItem('mp-msq-art');
    if (a && LAB_PARENT_TYPES[a]) return a;
  } catch (e) {
    /* storage disabled */
  }
  return 'PD';
}
function _msqSaveArt(art) {
  try {
    localStorage.setItem('mp-msq-art', art);
  } catch (e) {
    /* storage disabled — next open starts at Petrischale */
  }
}
function _msqSaveQty(mode, qty) {
  if (!(qty > 0)) return;
  try {
    const s = JSON.parse(localStorage.getItem('mp-msq-qty') || '{}');
    s[mode] = qty;
    localStorage.setItem('mp-msq-qty', JSON.stringify(s));
  } catch (e) {
    /* storage disabled — next open just starts at 1 */
  }
}
// Why a recipe can't be turned into a Charge, or null if it can.
// A recipe only needs rec_batch_type to qualify for the picker, but the columns
// behind it all default to 0 — so a Sorte could be offered here and then be
// rejected by createBatch for a missing bag weight or a substrate split that
// doesn't total 100. Those rejections fire after msQuickClose(), i.e. against a
// modal that is already gone, discarding whatever was typed. Catch it up front
// and keep the reason on screen instead.
function _msRecipeProblem(ms) {
  const type = ms.recBatchType || '';
  if (!type) return t('msq.noRecipe');
  if (type === 'block' || type === 'allinone') {
    if (!(ms.recBagKg > 0)) return t('msq.recNoBagKg');
    if ((ms.recSubstrate || 'holzkleie') === 'cvg') {
      if (!(ms.recCoirPct > 0)) return t('msq.recNoCoir');
    } else {
      const sum = (ms.recHardwoodPct || 0) + (ms.recWheatbranPct || 0);
      if (Math.abs(sum - 100) > 0.01) return t('msq.recBadSplit', { sum });
    }
  }
  if ((type === 'grain' || type === 'allinone') && !(ms.recGrainKg > 0)) return t('msq.recNoGrainKg');
  return null;
}
// Shared opener. ms === null → show the Sorte picker (charge mode lists only Sorten
// that have a recipe, since a Charge needs one).
function msQuickOpen(mode, ms) {
  // ml gilt nur für eine aufgenommene Spritze (genau eine, eine Größe); sonst
  // zählen Spritzen und Körnerbrut je Größe, und jede Größe fängt bei 0 an.
  // Jedes Öffnen beginnt mit einer Art; "Mehrere" ist ein Tipp
  // (msqMehrereUmschalten).
  _msQuickCtx = { mode, ms: ms || null, ml: 10, mehrere: false, arten: [], n: { MC: 0, PD: 0, LC: 0 } };
  const syBox = document.getElementById('ms-q-sy');
  if (syBox) syBox.innerHTML = syMengenHtml('ms-q', {});
  const kbBox = document.getElementById('ms-q-sizes');
  if (kbBox) kbBox.innerHTML = kbMengenHtml('ms-q', {});
  // Fresh dialog, fresh inoculant list — one left over from an abandoned dialog
  // would otherwise be offered up for the next batch.
  _inoc = [];
  const cSel = document.getElementById('ms-q-culture');
  if (cSel) {
    cSel.value = '';
    cSel.style.display = 'none';
  }
  const wrap = document.getElementById('ms-q-sorte-wrap');
  const sel = document.getElementById('ms-q-sorte');
  if (!ms && wrap && sel) {
    let list = mushroomStrains.slice();
    if (mode === 'charge') list = list.filter((x) => x.recBatchType);
    // No Sorte has a production recipe yet: the dialog would open on an empty
    // dropdown with Anlegen disabled and no hint why. Point at the page where a
    // recipe is actually defined instead of opening a dead end.
    if (mode === 'charge' && !list.length) {
      _msQuickCtx = null;
      confirm2(t('msq.noRecipesTitle'), t('msq.noRecipesMsg'), t('msq.noRecipesGo'), goCreateStrain);
      return;
    }
    list.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    sel.innerHTML =
      '<option value="">' +
      esc(t('msq.pickSortePrompt')) +
      '</option>' +
      list.map((x) => `<option value="${x.id}">${esc(x.name)}${x.kuerzel ? ' (' + esc(x.kuerzel) + ')' : ''}</option>`).join('');
    sel.value = '';
    wrap.style.display = '';
  } else if (wrap) {
    wrap.style.display = 'none';
  }
  // qty/strain reset only on open (not when the Sorte changes). qty restores the
  // last value used in this mode rather than snapping back to 1: batch size is
  // the one number the recipe cannot supply, it barely changes between runs, and
  // stepping it back up to 20 costs 19 taps on a phone. The manual form already
  // persists its qty the same way (nbSaveDefaults).
  const qtyEl = document.getElementById('ms-q-qty');
  if (qtyEl) qtyEl.value = _msqLastQty(mode);
  // Stamm und Datum gehören zu genau einem Anlegen: jedes Öffnen fängt bei
  // "ohne Stamm" und heute an.
  stammReset('ms-q');
  anlageReset('ms-q');
  const art = document.getElementById('ms-q-labtype');
  if (art && mode === 'labor') art.value = _msqLastArt();
  msQuickRender();
  document.getElementById('ms-quick-modal').style.display = 'flex';
}
// Render the modal for the current ctx. Safe when no Sorte is chosen yet (picker
// mode): shows a prompt and disables "Anlegen" until one is selected.
function msQuickRender() {
  if (!_msQuickCtx) return;
  const mode = _msQuickCtx.mode;
  const ms = _msQuickCtx.ms;
  const titleEl = document.getElementById('ms-q-title');
  const subEl = document.getElementById('ms-q-sub');
  const goEl = document.getElementById('ms-q-go');
  const intake = _msQuickCtx.intake || null;
  if (titleEl)
    titleEl.textContent = intake
      ? t('intake.dialogTitle', { id: intake.id })
      : mode === 'charge'
        ? t('msq.chargeTitle')
        : t('msq.laborTitle');
  const lt = document.getElementById('ms-q-labtype-wrap');
  if (lt) lt.style.display = mode === 'labor' ? '' : 'none';
  const artEl = document.getElementById('ms-q-labtype');
  // Bei mehreren Arten zeigt jede angetippte ihre Felder; die gemeinsame
  // Anzahl fällt weg, jede Art zählt für sich.
  const mehrere = msqMehrere();
  const arten = msqArten();
  // Auch bei einer Charge: was von "Mehrere" noch dasteht, geht weg.
  msqArtenRender();
  if (goEl && !mehrere) goEl.textContent = t('msq.create');
  const mlWrap = document.getElementById('ms-q-ml-wrap');
  const istSy = mode === 'labor' && (mehrere ? arten.includes('SY') : !!artEl && artEl.value === 'SY');
  // Eine aufgenommene Spritze ist genau eine: eine Größe zum Wählen. Sonst je
  // Größe eine Anzahl, und die gemeinsame Anzahl fällt weg.
  const syEine = istSy && !!intake;
  const syViele = istSy && !intake;
  if (mlWrap) mlWrap.style.display = syEine ? '' : 'none';
  if (syEine) document.getElementById('ms-q-ml').innerHTML = syMlKnoepfe('msq-ml', _msQuickCtx.ml);
  const syWrap = document.getElementById('ms-q-sy-wrap');
  if (syWrap) syWrap.style.display = syViele ? '' : 'none';
  // Grain spawn is a Charge in everything but name: it is weighed, incubates,
  // and produces barcoded bags. So it wants the days and kg fields that the
  // count-based culture types don't.
  const isKb = mehrere ? arten.includes('KB') : _msqIsGrainspawn();
  const dw = document.getElementById('ms-q-days-wrap');
  if (dw) dw.style.display = mode === 'charge' || isKb ? '' : 'none';
  // Koernerbrut zaehlt nach Groesse, alles andere nach Stueck. Die Zeilenliste
  // und der gemeinsame Anzahl-Zaehler sind zwei Antworten auf dieselbe Frage,
  // also steht immer nur eine davon da -- sonst haette ein Ansatz aus 10x1 und
  // 5x2 eine Anzahl darueber, die zu keiner der beiden Zeilen gehoert.
  const grain = mehrere ? isKb : _msqIsGrain();
  const sw = document.getElementById('ms-q-sizes-wrap');
  if (sw) sw.style.display = grain ? '' : 'none';
  const qw = document.getElementById('ms-q-qty-wrap');
  // Ein aufgenommenes Etikett ist genau ein Glas.
  if (qw) qw.style.display = grain || intake || syViele || mehrere ? 'none' : '';
  const grid = document.getElementById('ms-q-grid');
  if (grid) grid.style.gridTemplateColumns = grain ? 'minmax(0, 1fr)' : '';
  // Der Stamm hängt an der Sorte, das Datum an nichts. Beide behalten beim
  // Neuzeichnen, was schon gewählt ist.
  stammRender('ms-q', ms ? ms.id : null);
  anlageRender('ms-q');
  if (!ms) {
    if (subEl) subEl.textContent = t('msq.pickSortePrompt');
    if (goEl) goEl.disabled = true;
    const prev = document.getElementById('ms-q-preview');
    if (prev) prev.textContent = '';
    // Die Herkunft scannen geht schon jetzt: sie bringt die Sorte mit.
    msQuickFillCulture();
    return;
  }
  // An incomplete recipe is rejected downstream by createBatch, long after this
  // dialog has closed — so block it here, while the reason is still readable.
  const problem = mode === 'charge' ? _msRecipeProblem(ms) : null;
  if (goEl) goEl.disabled = !!problem;
  if (subEl)
    subEl.textContent =
      ms.name + (ms.kuerzel ? ' (' + ms.kuerzel + ')' : '') + (mode === 'charge' ? ' — ' + msRecipeSummaryText(ms) : '');
  if (mode === 'charge') {
    const d = document.getElementById('ms-q-days');
    if (d) d.value = ms.recIncDays || 14;
  } else if (isKb) {
    // Körnerbrut als Laborarbeit hat kein Rezept mit Inkubationstagen.
    const d = document.getElementById('ms-q-days');
    if (d && !(parseInt(d.value, 10) > 0)) d.value = 14;
  }
  msQuickPreview();
  msQuickFillCulture();
  inocRender('ms-q');
  if (problem) {
    const prev = document.getElementById('ms-q-preview');
    if (prev) {
      prev.textContent = '⚠ ' + problem;
      prev.style.color = 'var(--c-red-dark)';
    }
  }
}
// Woraus die gewählte Laborarbeit angesetzt werden darf, oder null, wenn der
// Dialog keine Laborarbeit ist.
function msqParentTypes() {
  if (!_msQuickCtx || _msQuickCtx.mode !== 'labor') return null;
  // Mehrere Arten teilen sich die eine Herkunft: sie muss zu jeder passen.
  if (msqMehrere())
    return msqArten().reduce(
      (passt, a) => passt.filter((x) => (LAB_PARENT_TYPES[a] || []).includes(x)),
      ['MC', 'PD', 'LC', 'SY']
    );
  const el = document.getElementById('ms-q-labtype');
  return LAB_PARENT_TYPES[(el && el.value) || 'MC'] || [];
}
// Etwas für "Beimpft mit" im Schnelldialog, gescannt oder gewählt. Bei einer
// Laborarbeit muss es zur Art passen, und es gibt genau eine Herkunft: die
// zweite ersetzt die erste, statt ungenutzt danebenzustehen. Ist noch keine
// Sorte gewählt, kommen Sorte und Stamm von der gescannten Kultur — die steht
// auf dem Glas in der Hand, niemand soll sie noch einmal heraussuchen.
// null wenn genommen, sonst der Grund in Worten.
function msqInocAdd(rawId) {
  const types = msqParentTypes();
  const id = String(rawId || '').trim();
  const c = cultures.find((x) => x.id.toUpperCase() === id.toUpperCase());
  if (types) {
    const art = document.getElementById('ms-q-labtype');
    const artName = art && art.selectedOptions[0] ? art.selectedOptions[0].textContent : '';
    const mehrere = msqMehrere();
    const isKb = !mehrere && art && art.value === 'KB';
    // Körnerbrut darf auch aus einem Körnerbeutel kommen (Körner aus Körnern) —
    // aber nur allein: eine Petrischale wächst nicht aus einem Körnerbeutel.
    if (!(isKb && !c) && (!c || !types.includes(c.type)))
      return mehrere
        ? t('msq.parentWrongTypeMulti', {
            id: id,
            art: msqArten()
              .map((a) => t('msq.art.' + a))
              .join(', '),
            types: types.join(', ')
          })
        : t('msq.parentWrongType', { id: id, art: artName, types: types.join(', ') });
    const ms = _msQuickCtx.ms;
    if (c && ms && c.strainId && c.strainId !== ms.id)
      return t('msq.parentOtherSorte', { id: c.id, sorte: c.strainName || c.species || '', ziel: ms.name });
    if (!isKb) _inoc = [];
  }
  const err = inocAdd(id);
  if (err) return err;
  // Noch keine Sorte: die vom gescannten Glas oder Körnerbeutel. Eine Charge
  // nimmt sie nur, wenn die Sorte ein Rezept hat — sonst steht sie nicht in der
  // Liste, und die Wahl bleibt beim Arbeiter.
  const bag = c ? null : nbAvailableSpawnBags().find((b) => b.bag.toUpperCase() === id.toUpperCase());
  const von = c || bag;
  if (von && !_msQuickCtx.ms && von.strainId) {
    const ms = mushroomStrains.find((x) => x.id === von.strainId);
    if (ms && (types || ms.recBatchType)) {
      _msQuickCtx.ms = ms;
      const sel = document.getElementById('ms-q-sorte');
      if (sel) sel.value = String(ms.id);
      const st = stammState('ms-q');
      st.strainId = ms.id;
      const name = (von.strainText || '').trim();
      const hit = staemmeFor(ms.id).find((x) => stammGleich(x.name, name));
      st.wert = hit ? hit.name : '';
    }
  }
  return null;
}
// ── Ein Etikett aufnehmen, das das System nicht kennt ────────
// Ein gedrucktes Kultur-Etikett, zu dem es keine Kultur gibt: meist eine, deren
// Speichern fehlschlug, nachdem das Etikett schon gedruckt war (cprShow druckt
// dann mit der Kennung als Barcode). Statt "gibt es nicht" nimmt die App sie
// wieder auf — mit genau dieser Kennung, damit das Etikett am Glas gilt.
// Art, Sorte, Stamm und Tag stehen in der Kennung und sind vorausgefüllt.
function kulturKennungLesen(id) {
  const parts = String(id).toUpperCase().split('-');
  if (parts.length < 4) return null;
  const type = parts[0];
  const tag = parts[parts.length - 2];
  const kz = parts[1];
  const stamm = parts.length === 5 ? parts[2] : '';
  const ms =
    mushroomStrains.find((x) => (x.kuerzel || '').toUpperCase() === kz) ||
    mushroomStrains.find((x) => abbrev(x.name) === kz) ||
    null;
  // TTMMJJ → JJJJ-MM-TT; ein Tag in der Zukunft oder Unsinn bleibt leer (= heute).
  let datum = '';
  if (/^\d{6}$/.test(tag)) {
    const d = '20' + tag.slice(4, 6) + '-' + tag.slice(2, 4) + '-' + tag.slice(0, 2);
    const dt = new Date(d + 'T12:00:00');
    if (!isNaN(dt) && localDateStr(dt) === d && d <= localDateStr(new Date())) datum = d;
  }
  return { id: String(id).toUpperCase(), type, ms, stamm, datum };
}
function kulturAufnehmenAnbieten(id) {
  _scanBeep(500, 120);
  const k = kulturKennungLesen(id);
  // Aufnehmen geht über den Laborarbeit-Dialog, und der kennt diese Arten.
  if (!k || !['MC', 'PD', 'LC', 'SY'].includes(k.type)) {
    setFb('err', t('scanFb.cultureNotInSystem', { id: id }));
    return;
  }
  closeCamScan();
  confirm2(t('intake.title'), t('intake.msg', { id: k.id }), t('intake.yes'), () => msQuickOpenIntake(k));
}
function msQuickOpenIntake(k) {
  msQuickOpen('labor', null);
  if (!_msQuickCtx) return;
  _msQuickCtx.intake = k;
  const art = document.getElementById('ms-q-labtype');
  if (art) {
    art.value = k.type;
    art.disabled = true;
  }
  if (k.ms) {
    _msQuickCtx.ms = k.ms;
    const sel = document.getElementById('ms-q-sorte');
    if (sel) sel.value = String(k.ms.id);
    if (k.stamm) {
      const st = stammState('ms-q');
      st.strainId = k.ms.id;
      const hit = staemmeFor(k.ms.id).find((x) => x.name.replace(/[^A-Za-z0-9]/g, '').toUpperCase() === k.stamm);
      st.wert = hit ? hit.name : '';
    }
  }
  if (k.datum) ANLAGE['ms-q'] = { offen: true, datum: k.datum };
  const qty = document.getElementById('ms-q-qty');
  if (qty) qty.value = 1;
  msQuickRender();
}
// True when the quick dialog is in Laborarbeit mode with Grainspawn selected.
// Grain spawn (KB) is not a culture: it goes through createGrainBatch, not
// logLabWork, and produces G-prefixed barcoded bags.
function _msqIsGrainspawn() {
  if (!_msQuickCtx || _msQuickCtx.mode !== 'labor') return false;
  const el = document.getElementById('ms-q-labtype');
  return !!el && el.value === 'KB';
}
// Koernerbrut in BEIDEM Sinn: als Laborarbeit (Art = KB) und als Charge einer
// Sorte, deren Rezept auf Koerner lautet. Beide Wege landen in
// createGrainBatch(), beide wiegen ihre Beutel -- und der zweite hatte bisher
// gar kein Gewichtsfeld, sondern nahm stumm recGrainKg aus dem Rezept.
function _msqIsGrain() {
  if (!_msQuickCtx) return false;
  if (_msQuickCtx.mode === 'charge') return !!(_msQuickCtx.ms && _msQuickCtx.ms.recBatchType === 'grain');
  return _msqIsGrainspawn();
}
// Die Größe einer Spritze, im Schnelldialog: ein Tipp auf 10, 20 oder 50 ml.
(function wireMsqMl() {
  document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-msq-ml]');
    if (!b || !_msQuickCtx) return;
    _msQuickCtx.ml = parseInt(b.dataset.msqMl, 10) || 10;
    document.getElementById('ms-q-ml').innerHTML = syMlKnoepfe('msq-ml', _msQuickCtx.ml);
    msQuickPreview();
  });
})();
// ── Mehrere Arten auf einmal ─────────────────────────────────
// Ein Labortag mit einer Sorte: aus demselben Glas gehen Petrischalen,
// Flüssigkulturen und Körnerbrut. Einzeln hieß das, für jede Art den Dialog zu
// öffnen, dieselbe Herkunft neu zu scannen und jedes Mal zu drucken. Der Knopf
// "Mehrere" macht aus der Liste Knöpfe zum Antippen: jede angetippte Art
// bekommt ihre Zahlen, Sorte, Stamm, Tag und die eine Herkunft gelten für alle,
// und am Ende steht ein Etiketten-Fenster mit einem Druck (etikettenFuerAlles).
// Slants gehören dazu: sie kommen meist von derselben Petrischale. Jede Zahl
// fängt bei 0 an.
const MSQ_MEHRERE = ['MC', 'PD', 'LC', 'SY', 'KB'];
// Die Arten, die eine Anzahl zählen, ohne Größen.
const MSQ_STUECK = ['MC', 'PD', 'LC'];
function msqMehrere() {
  return !!(_msQuickCtx && _msQuickCtx.mode === 'labor' && _msQuickCtx.mehrere && !_msQuickCtx.intake);
}
function msqArten() {
  return msqMehrere() ? _msQuickCtx.arten : [];
}
function msqMehrereUmschalten() {
  if (!_msQuickCtx || _msQuickCtx.intake) return;
  const sel = document.getElementById('ms-q-labtype');
  _msQuickCtx.mehrere = !_msQuickCtx.mehrere;
  if (_msQuickCtx.mehrere) {
    // Die Art, die gerade dasteht, ist die erste angetippte.
    _msQuickCtx.arten = sel && MSQ_MEHRERE.includes(sel.value) ? [sel.value] : [];
    _msQuickCtx.n = { MC: 0, PD: 0, LC: 0 };
    const syBox = document.getElementById('ms-q-sy');
    if (syBox) syBox.innerHTML = syMengenHtml('ms-q', {});
    const kbBox = document.getElementById('ms-q-sizes');
    if (kbBox) kbBox.innerHTML = kbMengenHtml('ms-q', {});
  } else if (sel && _msQuickCtx.arten.length) {
    // Zurück zu einer Art: der ersten angetippten.
    sel.value = _msQuickCtx.arten[0];
  }
  msQuickRender();
}
// Die Art als Liste (eine) oder als Knöpfe (mehrere), dazu die Zähler der
// Arten ohne eigene Felder. Spritzen und Körnerbrut bringen ihre mit (ms-q-sy,
// ms-q-sizes). Bei mehreren steht über jeder Art ihr Name, gleich gesetzt wie
// MSQ_ART_KOPF, so dass jede angetippte Art ein Abschnitt für sich ist.
const MSQ_ART_KOPF = 'font-weight:600;padding-top:8px;border-top:1px solid var(--c-border-light)';
function msqArtenRender() {
  const mehrere = msqMehrere();
  const arten = msqArten();
  const sel = document.getElementById('ms-q-labtype');
  if (sel) sel.style.display = mehrere ? 'none' : '';
  const knopf = document.getElementById('ms-q-mehrere');
  if (knopf) {
    knopf.style.display = _msQuickCtx.intake ? 'none' : '';
    knopf.classList.toggle('btn-p', mehrere);
    knopf.setAttribute('aria-pressed', mehrere ? 'true' : 'false');
  }
  const box = document.getElementById('ms-q-arten');
  if (box) {
    box.style.display = mehrere ? 'flex' : 'none';
    box.innerHTML = mehrere
      ? MSQ_MEHRERE.map((a) => {
          const an = arten.includes(a);
          return `<button type="button" class="btn${an ? ' btn-p' : ''}" data-msq-art="${a}" aria-pressed="${an}" style="min-height:var(--tap);font-weight:600">${esc(t('msq.art.' + a))}</button>`;
        }).join('')
      : '';
  }
  const zaehler = document.getElementById('ms-q-multi');
  if (zaehler) {
    const gezaehlt = MSQ_STUECK.filter((a) => arten.includes(a));
    zaehler.style.display = gezaehlt.length ? '' : 'none';
    zaehler.innerHTML = gezaehlt
      .map(
        (a) =>
          `<div style="${MSQ_ART_KOPF};margin-bottom:6px">${esc(t('msq.art.' + a))}</div>` +
          zaehlerZeileHtml('ms-q-n-' + a, _msQuickCtx.n[a], '')
      )
      .join('');
  }
  for (const id of ['ms-q-sy-head', 'ms-q-kb-head']) {
    const h = document.getElementById(id);
    if (h) h.style.display = mehrere ? '' : 'none';
  }
}
// Die Zahlen, so wie sie dastehen: je Art, Spritzen je Größe, Körnerbrut je
// Beutelgröße. Was nicht angetippt ist, zählt nicht mit.
function msqMehrereLesen() {
  const arten = msqArten();
  for (const a of MSQ_STUECK) {
    const el = document.getElementById('ms-q-n-' + a);
    if (el) _msQuickCtx.n[a] = Math.max(0, Math.min(500, parseInt(el.value, 10) || 0));
  }
  const z = {
    MC: arten.includes('MC') ? _msQuickCtx.n.MC : 0,
    PD: arten.includes('PD') ? _msQuickCtx.n.PD : 0,
    LC: arten.includes('LC') ? _msQuickCtx.n.LC : 0,
    sy: arten.includes('SY') ? syMengenLesen('ms-q') : {},
    kb: arten.includes('KB') ? msqReadSizes() : []
  };
  z.summe = z.MC + z.PD + z.LC + sySumme(z.sy) + z.kb.reduce((a, l) => a + l.qty, 0);
  return z;
}
function msqMehrerePreview(el) {
  const z = msqMehrereLesen();
  const teile = [];
  if (z.MC) teile.push(z.MC + ' ' + t('bmp.MC'));
  if (z.PD) teile.push(z.PD + ' ' + t('bmp.PD'));
  if (z.LC) teile.push(z.LC + ' ' + t('bmp.LC'));
  teile.push(...syTeile(z.sy));
  for (const l of z.kb) teile.push(t('bmp.previewGrain', { n: l.qty, kg: String(l.kg).replace('.', ',') }));
  el.textContent = teile.length ? t('bmp.preview', { list: teile.join(' · ') }) : t('bmp.nothing');
  // Früher angesetzte Körnerbrut bucht kein Korn ab, wie im Dialog für eine Art.
  if (z.kb.length && anlageFrueher('ms-q')) el.textContent += ' — ' + t('anlage.notBooked');
  const go = document.getElementById('ms-q-go');
  if (go) go.textContent = z.summe ? t('msq.createN', { n: z.summe }) : t('msq.create');
}
(function wireMsqMehrere() {
  document.addEventListener('click', (e) => {
    if (!_msQuickCtx) return;
    if (e.target.closest('#ms-q-mehrere')) return msqMehrereUmschalten();
    const b = e.target.closest('[data-msq-art]');
    if (!b || !msqMehrere()) return;
    const a = b.dataset.msqArt;
    const arten = _msQuickCtx.arten.includes(a)
      ? _msQuickCtx.arten.filter((x) => x !== a)
      : _msQuickCtx.arten.concat(a);
    _msQuickCtx.arten = MSQ_MEHRERE.filter((x) => arten.includes(x));
    msQuickRender();
  });
})();
function msQuickLabTypeChanged() {
  // Full re-render, not just the culture list: switching to Grainspawn shows
  // the days field and the size rows, and switching away hides them again.
  msQuickRender();
}
function msQuickSorteChanged() {
  if (!_msQuickCtx) return;
  const id = parseInt(document.getElementById('ms-q-sorte').value, 10);
  _msQuickCtx.ms = mushroomStrains.find((x) => x.id === id) || null;
  msQuickRender();
}
function msQuickClose() {
  _msQuickCtx = null;
  const art = document.getElementById('ms-q-labtype');
  if (art) art.disabled = false;
  _inocScanPrefix = null;
  // Drop the inoculant list. Abandoning the dialog must not leave it armed for
  // whatever batch is created next. The confirm path closes the dialog before
  // createBatch runs, so it carries the list across itself — see msQuickConfirm.
  _inoc = [];
  const m = document.getElementById('ms-quick-modal');
  if (m) m.style.display = 'none';
}
// ── Die Größen einer Körnerbrut, im Schnelldialog ─────────
//
// Ein Ansatz geht in Beutel verschiedener Größe: dieselbe Flüssigkultur,
// dieselbe Charge, und trotzdem 1 kg neben 2 neben 5. Beutel gibt es in diesen
// drei Größen, also je Größe ein Zähler wie bei den Spritzen: ein Tipp auf +,
// kein Gewicht zum Eintippen, und jede Zahl fängt bei 0 an. Die Anzahl wandert
// damit aus dem gemeinsamen Zähler in die Zeile; für alles andere im Dialog —
// Petrischalen, Flüssigkultur, Blöcke — bleibt sie oben, dort gibt es nur eine
// Sorte Stück. Das Beimpfen-Fenster zählt Körnerbeutel genauso.
const KB_KG = [1, 2, 5];
function kbMengenHtml(pre, n) {
  return KB_KG.map((kg) => zaehlerZeileHtml(pre + '-kb-' + kg, n && n[kg], kg + ' kg')).join('');
}
// {1: n, 2: n, 5: n} aus den Feldern, 0 bis 500 wie die anderen Zähler.
function kbMengenLesen(pre) {
  const n = {};
  for (const kg of KB_KG) {
    const el = document.getElementById(pre + '-kb-' + kg);
    n[kg] = el ? Math.max(0, Math.min(500, parseInt(el.value, 10) || 0)) : 0;
  }
  return n;
}
// [{kg, qty}] je Größe mit Anzahl, die Form, die gsSetLines() nimmt. Was hier
// herauskommt, ist was angelegt wird.
function msqReadSizes() {
  const n = kbMengenLesen('ms-q');
  return KB_KG.filter((kg) => n[kg] > 0).map((kg) => ({ kg, qty: n[kg] }));
}
function msqQtyStep(d) {
  const el = document.getElementById('ms-q-qty');
  if (!el) return;
  el.value = Math.max(1, (parseInt(el.value, 10) || 0) + d);
  msQuickPreview();
}
function msQuickPreview() {
  const el = document.getElementById('ms-q-preview');
  if (!el) return;
  el.style.color = ''; // clear the recipe-problem styling from a previous render
  if (!_msQuickCtx || !_msQuickCtx.ms) {
    el.textContent = '';
    return;
  }
  if (_msQuickCtx.mehrere) return msqMehrerePreview(el);
  const qty = parseInt(document.getElementById('ms-q-qty').value) || 0;
  // Körnerbrut zuerst, auch wenn sie als Charge kommt: eine Körner-Sorte fiel
  // vorher in den Charge-Zweig und wurde dort mit der Anzahl oben gerechnet —
  // der Zahl, die es für sie nicht mehr gibt.
  //
  // Beide anderen Zweige rechnen die Menge ein, also darf keiner mehr "pro
  // Stück:" darüberschreiben — der Vorspann des Rezepteditors, der dort mit
  // Anzahl 1 rechnet und hier seit jeher die Summe beschriftet hat.
  if (_msqIsGrain()) {
    // Drei Zahlen hingen an einer Überschrift, die zu keiner davon gehörte:
    // "pro Stück: 7.6 kg" stand unter 10 × 2 kg. 2 kg kommt in einen Beutel,
    // 20 kg setzt man an, und 7,6 kg ist davon das trockene Korn, das vom Lager
    // abgeht — ausgerechnet die eine Zahl, die nicht pro Stück gilt. Alle drei
    // stehen jetzt da, jede benannt — und die erste ist jetzt die Aufstellung
    // der Größen, weil ein Ansatz aus mehr als einer bestehen darf.
    //
    // Die Feuchte kommt aus dem Rezept der Sorte, nicht aus getAvgComp():
    // msQuickConfirm schreibt genau diesen Wert nach gs-rh, und createGrainBatch
    // bucht damit (siehe koernerfeuchte-quelle.test.js). Der Schnitt über alle
    // Rezepte kündigte hier eine andere Menge an, als gleich gebucht wird.
    const lines = msqReadSizes();
    const rh = _msQuickCtx.ms.recGrainRhPct != null ? _msQuickCtx.ms.recGrainRhPct : 52;
    const num = (v) => (Math.round(v * 1000) / 1000).toString();
    const totalQty = lines.reduce((a, l) => a + l.qty, 0);
    const totalWet = lines.reduce((a, l) => a + l.kg * l.qty, 0);
    const totalDry = lines.reduce((a, l) => a + l.qty * mtDryKg(l.kg, rh), 0);
    el.textContent = totalQty
      ? t('msq.grainPreview', { n: totalQty }) +
        ' — ' +
        lines.map((l) => l.qty + ' × ' + num(l.kg) + ' kg').join(' + ') +
        ' · ' +
        t('msq.grainTotal', { total: num(totalWet) }) +
        ' · ' +
        t('msq.grainDry', { dry: num(totalDry) })
      : '';
  } else if (_msQuickCtx.mode === 'charge') {
    const parts = qty > 0 ? _msNeedParts(_msStrainToRecipe(_msQuickCtx.ms), qty) : [];
    el.textContent = parts.length ? t('msq.needFor', { n: qty }) + ' ' + parts.join(' · ') : '';
  } else if (document.getElementById('ms-q-labtype').value === 'SY') {
    // Die Größen stehen im Satz, damit vor dem Anlegen noch einmal dasteht, welche.
    const teile = syTeile(_msQuickCtx.intake ? { [_msQuickCtx.ml]: 1 } : syMengenLesen('ms-q'));
    el.textContent = teile.length ? t('bmp.preview', { list: teile.join(' · ') }) : '';
  } else {
    el.textContent = qty > 0 ? t('msq.laborPreview', { n: qty }) : '';
  }
  // Die Mengen oben sind, was ein Ansatz von heute nähme. Bestand aus der
  // Inventur nimmt nichts, und das muss danebenstehen, sonst liest man eine
  // Abbuchung, die nicht kommt. Kulturen buchen nie etwas, dort fehlt der Satz.
  if (el.textContent && (_msqIsGrain() || _msQuickCtx.mode === 'charge') && anlageFrueher('ms-q')) {
    el.textContent += ' — ' + t('anlage.notBooked');
  }
}
// Populate the modal's source-culture select, reusing the same culture filter the
// old forms use (none for a new MC isolation). Re-runs when the lab type changes.
function msQuickFillCulture() {
  const wrap = document.getElementById('ms-q-culture-wrap');
  const sel = document.getElementById('ms-q-culture');
  // Steht vor der Sorte und gilt schon ohne sie: die gescannte Herkunft bringt
  // die Sorte mit.
  if (!wrap || !sel || !_msQuickCtx) {
    if (wrap) wrap.style.display = 'none';
    return;
  }
  let types;
  if (_msQuickCtx.mode === 'charge') {
    // Körner aus Körnern: eine bestehende Körnerbrut darf die nächste ansetzen.
    const ms = _msQuickCtx.ms;
    types = ms && ms.recBatchType === 'grain' ? ['PD', 'LC', 'GS'] : ['PD', 'LC', 'G2G', 'GS'];
  } else {
    types = msqParentTypes();
    // Eine Herkunft, die zur neuen Art nicht mehr passt, fällt heraus.
    _inoc = _inoc.filter((x) => {
      if (x.kind === 'bag') return types === LAB_PARENT_TYPES.KB;
      const c = cultures.find((y) => y.id === x.id);
      return !!c && types.includes(c.type);
    });
  }
  if (!types || !types.length) {
    sel.value = '';
    wrap.style.display = 'none';
    return;
  }
  // The hidden select still carries a culture through to nb-culture/gs-culture.
  fillCultureSelect('ms-q-culture', types);
  wrap.style.display = '';
  inocRender('ms-q');
}
// The camera modal is z-index 200 and this dialog is 1200, so the camera would
// open behind it. Hide the dialog for the duration and put it back on close —
// _msQuickCtx survives, so nothing typed is lost. _inocScanPrefix doubles as the
// record of who opened the camera, so 'ms-q' is what says to restore.
function msqOpenScan(prefix) {
  _inocScanPrefix = prefix;
  const m = document.getElementById('ms-quick-modal');
  if (m) m.style.display = 'none';
  scan.action = null;
  scan.to = null;
  scan.from = null;
  updateSD();
  openCamScan();
}
// Takes the prefix as an argument because closeCamScan clears _inocScanPrefix,
// and reading it here after that would always see null.
function msqRestoreAfterScan(prefix) {
  if (prefix !== 'ms-q') return;
  if (!_msQuickCtx) return; // confirmed or dismissed while the camera was up
  const m = document.getElementById('ms-quick-modal');
  if (m) m.style.display = 'flex';
  msQuickRender();
}
async function msQuickConfirm() {
  if (!_msQuickCtx) return;
  if (!_msQuickCtx.ms) {
    toast(t('msq.pickSortePrompt'), 'err');
    return;
  }
  const ms = _msQuickCtx.ms;
  const mode = _msQuickCtx.mode;
  // Körnerbrut bringt ihre Anzahl je Größe mit, alles andere die eine oben.
  // Geprüft wird HIER, solange der Dialog noch steht: eine leere Liste
  // erreichte createGrainBatch als "keine Zeilen" — dessen Meldung erschien dann
  // gegen einen Dialog, der längst zu war, und alles Getippte war weg.
  // Mehrere Arten zählen je Art (msqMehrereLesen), auch das wird hier geprüft.
  const zahlen = msqMehrere() ? msqMehrereLesen() : null;
  const grain = !zahlen && _msqIsGrain();
  const sizes = grain ? msqReadSizes() : [];
  // Spritzen ebenso je Größe, außer der einen aufgenommenen.
  const artSel = document.getElementById('ms-q-labtype');
  const syN =
    !zahlen && mode === 'labor' && !_msQuickCtx.intake && artSel && artSel.value === 'SY'
      ? syMengenLesen('ms-q')
      : null;
  let qty;
  if (zahlen) {
    qty = zahlen.summe;
    if (qty < 1) {
      toast(t('bmp.nothing'), 'err');
      return;
    }
  } else if (grain) {
    if (!sizes.length) {
      fieldError('ms-q-sizes', t('batch.fillQty'));
      return;
    }
    qty = sizes.reduce((a, l) => a + l.qty, 0);
  } else if (syN) {
    qty = sySumme(syN);
    if (qty < 1) {
      fieldError('ms-q-sy', t('batch.fillQty'));
      return;
    }
  } else {
    qty = parseInt(document.getElementById('ms-q-qty').value) || 0;
    if (qty < 1) {
      fieldError('ms-q-qty', t('batch.fillQty'));
      return;
    }
    if (!_msQuickCtx.intake) _msqSaveQty(mode, qty);
  }
  // Ein Tag in der Zukunft wird hier abgewiesen, solange der Dialog noch steht.
  const angesetzt = anlageLesen('ms-q');
  if (angesetzt === null) return;
  // Steht noch ein getippter, nicht hinzugefügter Stamm im Feld, wird er jetzt
  // angelegt. Solange das läuft, nimmt der Knopf keinen zweiten Tipp an.
  const goBtn = document.getElementById('ms-q-go');
  if (goBtn) goBtn.disabled = true;
  const strainText = await stammFertig('ms-q');
  if (goBtn) goBtn.disabled = false;
  // Fehlgeschlagen (gemeldet ist es), oder der Dialog wurde währenddessen zu.
  if (strainText === null || !_msQuickCtx) return;
  const setv = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.value = val;
  };
  // Die Kultur, mit der beimpft wird, steht in der Beimpf-Liste (gescannt oder
  // gewählt). Das versteckte Feld hier setzt seit dieser Liste niemand mehr —
  // so kam ein gescanntes Elternteil bei der Laborarbeit nie an.
  const sourceCulture =
    (document.getElementById('ms-q-culture') && document.getElementById('ms-q-culture').value) || inocCultureId();
  // msQuickClose() leert die Liste, damit ein abgebrochener Dialog nichts in die
  // nächste Charge trägt. Wer anlegt, nimmt sie mit hinüber.
  const inocMit = _inoc.slice();
  const intake = _msQuickCtx.intake || null;
  if (zahlen) {
    const days = parseInt(document.getElementById('ms-q-days').value) || 14;
    msQuickClose();
    msqMehrereAnlegen({ ms, strainText, angesetzt, quelle: sourceCulture, inoc: inocMit, zahlen, days });
    return;
  }
  if (mode === 'labor') {
    const labType = document.getElementById('ms-q-labtype').value || 'MC';
    if (!intake) _msqSaveArt(labType);
    // Grainspawn is not a culture: it is weighed, incubates and yields
    // G-prefixed barcoded bags, so it goes through createGrainBatch like the
    // full Körnerbrut form rather than logLabWork.
    if (labType === 'KB') {
      setv('lw-st', ms.id);
      setv('lw-strain-text', strainText);
      setv('lw-created', angesetzt);
      gsSetLines(sizes);
      setv('gs-days', parseInt(document.getElementById('ms-q-days').value) || 14);
      // Die Feuchte der Sorte, nicht der Schnitt über alle: ms steht hier, und
      // der Zweig 40 Zeilen tiefer liest sie längst so. getAvgComp() mittelt
      // recGrainRhPct über die Rezepte — für eine Sorte, deren Rezept den Wert
      // trägt, ist das die ungenauere Zahl, und sie entscheidet, wie viel
      // trockenes Korn vom Lagerbestand abgeht.
      setv('gs-rh', ms.recGrainRhPct != null ? ms.recGrainRhPct : 52);
      fillCultureSelect('gs-culture', ['PD', 'LC', 'SY', 'GS']);
      const gsc = document.getElementById('gs-culture');
      if (gsc) gsc.value = sourceCulture;
      setv('lw-notes', '');
      msQuickClose();
      // createGrainBatch() liest die Liste: die Kultur wird Herkunft, ein
      // gescannter Körnerbeutel (Körner aus Körnern) geht als verbraucht raus.
      _inoc = inocMit;
      createGrainBatch();
      return;
    }
    setv('lw-type', labType);
    setv('lw-st', ms.id);
    setv('lw-strain-text', strainText);
    setv('lw-created', angesetzt);
    setv('lw-qty', qty);
    setv('lw-ml', _msQuickCtx.ml);
    setv('lw-source', '');
    setv('lw-notes', '');
    msQuickClose();
    // Kein Wechsel auf die Laborseite. Der ging dorthin, damit openStab()
    // lwUpdate() rief — und ließ den Arbeiter dann auf dem langen Formular
    // stehen, ohne ein Etikett. lwUpdate() füllt lw-parent auch so; das
    // Etiketten-Fenster kommt aus logLabWork() von selbst, egal wo man steht.
    lwUpdate();
    const parent = document.getElementById('lw-parent');
    if (parent) parent.value = sourceCulture; // valid: the modal used the same culture types
    logLabWork(intake ? { id: intake.id } : syN ? { sy: syN } : undefined);
    return;
  }
  // Charge: prefill the existing Charge form from the recipe and reuse its
  // create logic (validation, inventory deduction, zone picker, barcodes).
  const days = parseInt(document.getElementById('ms-q-days').value) || ms.recIncDays || 14;
  if (ms.recBatchType === 'grain') {
    setv('lw-st', ms.id);
    setv('lw-strain-text', strainText);
    setv('lw-created', angesetzt);
    // Die Größen aus dem Dialog, nicht mehr recGrainKg: das Rezept hat die
    // Zeilen beim Öffnen gefüllt, danach gehören sie diesem einen Ansatz.
    gsSetLines(sizes);
    setv('gs-days', days);
    setv('gs-rh', ms.recGrainRhPct != null ? ms.recGrainRhPct : 52);
    fillCultureSelect('gs-culture', ['PD', 'LC', 'SY', 'GS']);
    const gsc = document.getElementById('gs-culture');
    if (gsc) gsc.value = sourceCulture;
    setv('lw-notes', '');
    msQuickClose();
    _inoc = inocMit;
    createGrainBatch();
    return;
  }
  // block / all-in-one — die Liste geht über nbFillFromStrain mit (inocMit).
  // Formular bereitmachen, BEVOR das Rezept hineingeschrieben wird: beim ersten
  // Mal in einer Sitzung setzt nbEnsureReady() die gemerkten Vorgaben, und die
  // überschrieben sonst jedes Feld, das das Rezept gleich setzt. Ein Wechsel auf
  // die Chargenseite ist dafür nicht nötig — der Etiketten-Dialog kommt von
  // selbst hoch, egal wo man steht.
  msQuickClose();
  nbEnsureReady();
  nbFillFromStrain(ms, { qty, days, strainText, culture: sourceCulture, inoc: inocMit, created: angesetzt });
  createBatch();
}
// Mehrere Arten aus einer Herkunft anlegen: jede Art ihre eigenen Nummern, alle
// mit derselben Herkunft, Sorte, Stamm und demselben Tag. Erst die Kulturen,
// dann die Körnerbrut über denselben Weg wie aus dem Dialog für eine Art, und
// am Ende ein Etiketten-Fenster für alles.
// spec: { ms, strainText, angesetzt, quelle, inoc, zahlen, days }
function msqMehrereAnlegen(spec) {
  const { ms, strainText, angesetzt, zahlen } = spec;
  const wann = anlageZeitpunkt(angesetzt);
  const posten = [];
  if (zahlen.MC > 0) posten.push(['MC', zahlen.MC, null]);
  if (zahlen.PD > 0) posten.push(['PD', zahlen.PD, null]);
  if (zahlen.LC > 0) posten.push(['LC', zahlen.LC, null]);
  for (const ml of SY_ML) if (zahlen.sy[ml] > 0) posten.push(['SY', zahlen.sy[ml], ml]);
  const ids = [];
  const saves = [];
  for (const [type, qty, ml] of posten) {
    const r = kulturenAnlegen({ type, ms, wann, qty, parentId: spec.quelle || null, strainText, ml });
    ids.push(...r.newC.map((x) => x.id));
    saves.push(r.saved);
  }
  let korn = null;
  if (zahlen.kb.length) {
    const setv = (id, val) => {
      const el = document.getElementById(id);
      if (el) el.value = val;
    };
    setv('lw-st', ms.id);
    setv('lw-strain-text', strainText);
    setv('lw-created', angesetzt);
    gsSetLines(zahlen.kb);
    setv('gs-days', spec.days || 14);
    setv('gs-rh', ms.recGrainRhPct != null ? ms.recGrainRhPct : 52);
    setv('lw-notes', '');
    // createGrainBatch nimmt die Herkunft aus der Beimpf-Liste.
    _inoc = spec.inoc.slice();
    korn = createGrainBatch({ ohneFenster: true }) || null;
  }
  renderLabLog();
  etikettenFuerAlles(ids, Promise.all(saves), korn);
}

// Das lange Chargenformular aus einem Rezept füllen.
//
// Zwei Wege führen hierher: der Schnelldialog (msQuickConfirm) und der
// geführte Assistent (wkbCreateFromShelf). Beide schrieben ihre eigene
// Feldliste, und die waren schon auseinandergelaufen — dem Assistenten
// fehlten Gips, Kultur und Körnerfeuchte, bis die Nachprüfung sie fand.
// createBatch() liest all diese Felder; wer eines vergisst, bucht den Altwert
// des letzten Benutzers mit. Deshalb steht die Liste nur noch hier.
//
// `ms` ist die Sorte. Alles in `o` überschreibt deren Rezept: qty, bagKg,
// days, hw, wb, rh kommen als Zahlen aus dem Assistenten, strainText und
// notes als Text, culture als Kultur-Id, inoc als Beimpf-Auswahl und created
// als der Tag, an dem angesetzt wurde (JJJJ-MM-TT, leer für heute).
function nbFillFromStrain(ms, o) {
  const opt = o || {};
  const setv = (id, v) => {
    const el = document.getElementById(id);
    if (el) el.value = v;
  };
  const oder = (v, ersatz) => (v != null ? v : ersatz);
  const isCvg = (ms.recSubstrate || 'holzkleie') === 'cvg';
  // Ein Ansatz aus einer früheren Charge steht sonst noch in der Auswahl, und
  // createBatch nimmt dann den Weg über den Ansatz und übergeht die
  // Zusammensetzung, die hier gerade gesetzt wird. Der Schnelldialog hat das
  // nie geleert.
  setv('nb-substrate-batch', '');
  setv('nb-strain-sel', ms.id);
  setv('nb-strain-text', opt.strainText || '');
  // Angesetzt am, JJJJ-MM-TT; leer heißt heute. Immer gesetzt, auch leer — ein
  // Datum aus dem letzten Anlegen darf nicht an diesem hängen bleiben.
  setv('nb-created', opt.created || '');
  setv('nb-qty', oder(opt.qty, 1));
  setv('nb-days', oder(opt.days, ms.recIncDays || 14));
  setBagWeight(parseDecimal(oder(opt.bagKg, ms.recBagKg)) || 0);
  setv('nb-rh', oder(opt.rh, ms.recRhPct || 0));
  // Eine CVG-Sorte hat ihre ganze Masse im Kokos, eine All-in-One ihre
  // Körnerbrut. Hart auf 0 gesetzt legt der Aufrufer sie an, ohne ein Gramm
  // abzubuchen.
  setv('nb-hw', isCvg ? 0 : oder(opt.hw, ms.recHardwoodPct || 0));
  setv('nb-wb', isCvg ? 0 : oder(opt.wb, ms.recWheatbranPct || 0));
  setv('nb-coir', isCvg ? ms.recCoirPct || 100 : 0);
  setv('nb-grainkg', ms.recBatchType === 'allinone' ? ms.recGrainKg || 0 : 0);
  setv('nb-grainrh', oder(ms.recGrainRhPct, 52));
  const gyp = document.getElementById('nb-gyp');
  if (gyp) gyp.checked = !!ms.recGypsum;
  // Die Kultur wird zur Herkunft der Charge, und eine G2G-/GS-Kultur schreibt
  // createBatch anschließend als verbraucht ab — eine stehengebliebene aus
  // einer abgebrochenen Vorbelegung darf hier nicht überleben.
  fillCultureSelect('nb-culture', ['PD', 'LC', 'G2G', 'GS']);
  setv('nb-culture', opt.culture || '');
  _inoc = opt.inoc || [];
  inocRender('nb');
  setv('nb-notes', opt.notes || '');
  // Erst am Ende nachrechnen lassen: jeder dieser Aufrufe zieht eine Vorschau
  // nach sich, und mittendrin gerufen rechnen sie mit halb gefüllten Feldern
  // etwas aus, das die nächste Zeile sofort ersetzt.
  if (typeof nbSubstrateChanged === 'function') nbSubstrateChanged();
  if (typeof nbStrainChanged === 'function') nbStrainChanged();
}

function nbStrainChanged() {
  // The mix line below quotes block weight and spawn rate off the Sorte.
  if (typeof nbSubstrateNeed === 'function') setTimeout(nbSubstrateNeed, 0);
  nbPreview();
}
function renderNbGrainBanner() {
  const banner = document.getElementById('nb-source-banner');
  if (!banner) return;
  const sel = document.getElementById('nb-culture');
  const id = sel ? sel.value : '';
  if (!id) {
    banner.style.display = 'none';
    banner.textContent = '';
    return;
  }
  const c = cultures.find((x) => x.id === id);
  if (!c) {
    banner.style.display = 'none';
    return;
  }
  const isGrain = c.type === 'G2G' || c.type === 'GS';
  const base = t('scanFb.cultureAutofilled', { id: c.id });
  const suffix = isGrain ? ' \u2014 ' + t('batch.willMarkUsed') : '';
  banner.textContent = base + suffix;
  banner.style.display = '';
}

// ─── CULTURES ────────────────────────────────────────────────
// The class comes from a lookup, so it is safe by construction — the label does
// not. It renders a value straight from the cultures table, and it goes into
// the page via innerHTML, so an unescaped label is stored XSS that
// fires on render with no click involved. Escaping here rather than at the
// call sites covers all of them at once, and covers rows already in the
// database, which validating new writes cannot.
const ctBadge = (t) => {
  const m = { MC: 'badge-mc', PD: 'badge-pd', LC: 'badge-lc', G2G: 'badge-g2g', SY: 'badge-sy' };
  return `<span class="badge ${m[t] || ''}">${esc(t)}</span>`;
};
function fillCultureSelect(id, types) {
  const s = document.getElementById(id);
  if (!s) return;
  const opts =
    '<option value="">— none —</option>' +
    cultures
      .filter((c) => (c.status === 'active' || c.status === 'stored') && (!types || types.includes(c.type)))
      .map((c) => {
        const kz = c.strainKuerzel || c.strain || '';
        const name = c.strainName || c.species || '';
        const st = (c.strainText || '').trim();
        const label =
          (kz ? '[' + esc(kz) + '] ' : '') +
          esc(c.id) +
          ' — ' +
          esc(name) +
          (st ? ' ' + esc(st) : '') +
          ' (' +
          esc(c.type) +
          ')';
        return `<option value="${esc(c.id)}">${label}</option>`;
      })
      .join('');
  // Skip rewrite when options are unchanged — see fillStrainSelects for why.
  if (s.innerHTML === opts) return;
  const cur = s.value;
  s.innerHTML = opts;
  if (cur) s.value = cur;
}
function setCultureStatus(id, status) {
  const c = cultures.find((x) => x.id === id);
  if (!c) return;
  const prev = c.status;
  c.status = status;
  renderCultures();
  apiPatch('/api/cultures/' + encodeURIComponent(id), { status }).then((r) => {
    if (r && r.error) {
      c.status = prev;
      renderCultures();
      setFb('err', t('common.error') + ': ' + r.error);
    }
  });
}
// ─── LAB WORK ────────────────────────────────────────────────
// Woraus eine Laborarbeit angesetzt werden darf, je Art. Dieselben Regeln wie
// VALID_CULTURE_PARENT_TYPES in db.js — standen hier andere, bot das Formular
// eine Herkunft an, die der Server dann abwies. Ein Slant (MC) kommt meist von
// einer guten Petrischale; gekauft oder vom Abdruck hat er keine, und deshalb
// bleibt die Herkunft freiwillig. Körnerbrut (KB) ist keine Kultur und geht
// über createGrainBatch.
const LAB_PARENT_TYPES = {
  MC: ['MC', 'PD', 'LC', 'SY'],
  PD: ['MC', 'PD', 'LC', 'SY'],
  LC: ['MC', 'PD', 'LC', 'SY'],
  SY: ['MC', 'PD', 'LC'],
  KB: ['PD', 'LC', 'SY']
};
// Spritzen gibt es in drei Größen, wie SYRINGE_SIZES in db.js. Eine Spritze
// ohne Angabe ist eine 10er: so war jede, bevor es die Wahl gab.
const SY_ML = [10, 20, 50];
const syMl = (c) => (c && c.type === 'SY' ? c.ml || 10 : null);
// Drei Knöpfe, der gewählte gefüllt — dieselbe Form wie die Gewichte der
// Körnerbrut (gs-wbtn). `attr` ist das data-Attribut, an dem der Klick hängt.
function syMlKnoepfe(attr, aktiv) {
  return (
    '<div role="group" style="display:flex;gap:6px;flex-wrap:wrap">' +
    SY_ML.map(
      (ml) =>
        `<button type="button" class="btn${ml === aktiv ? ' btn-p' : ''}" data-${attr}="${ml}" aria-pressed="${ml === aktiv}" style="min-height:var(--tap);min-width:64px;font-weight:600">${ml} ml</button>`
    ).join('') +
    '</div>'
  );
}
// Eine Zeile mit Zähler: − Zahl + und dahinter, was gezählt wird (ohne
// Beschriftung, wenn eine Überschrift darüber steht). Die Knöpfe hängen an
// data-zaehler (wireZaehler), das Feld an seiner id.
const ZAEHLER_KNOPF =
  'width:var(--tap);height:var(--tap);min-width:44px;min-height:44px;flex:none;border-radius:10px;border:1px solid var(--c-border);background:var(--c-surface);font-size:1.25rem;font-weight:600;cursor:pointer';
function zaehlerZeileHtml(id, n, label) {
  return (
    `<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">` +
    `<button type="button" data-zaehler="-1" data-zaehler-feld="${id}" aria-label="${esc(t('bmp.less'))}" style="${ZAEHLER_KNOPF}">−</button>` +
    `<input type="number" inputmode="numeric" min="0" max="500" id="${id}" value="${n || 0}" style="width:64px;text-align:center;font-weight:600" />` +
    `<button type="button" data-zaehler="1" data-zaehler-feld="${id}" aria-label="${esc(t('bmp.more'))}" style="${ZAEHLER_KNOPF}">+</button>` +
    (label ? `<span class="fs-base" style="font-weight:600">${esc(label)}</span>` : '') +
    '</div>'
  );
}
// Abgefüllt wird in einem Durchgang oft mehr als eine Größe: 3 × 10, 5 × 20 und
// 3 × 50 ml. Also je Größe eine Zeile mit Zähler, und ein Tipp legt alle an und
// bringt alle Etiketten in ein Fenster. `pre` ist das Präfix der Felder
// (pre-sy-10 …).
function syMengenHtml(pre, n) {
  return SY_ML.map((ml) => zaehlerZeileHtml(pre + '-sy-' + ml, n && n[ml], ml + ' ml')).join('');
}
// {10: n, 20: n, 50: n} aus den Feldern, 0 bis 500 wie die anderen Zähler.
function syMengenLesen(pre) {
  const n = {};
  for (const ml of SY_ML) {
    const el = document.getElementById(pre + '-sy-' + ml);
    n[ml] = el ? Math.max(0, Math.min(500, parseInt(el.value, 10) || 0)) : 0;
  }
  return n;
}
const sySumme = (n) => SY_ML.reduce((a, ml) => a + ((n && n[ml]) || 0), 0);
// "3 Spritzen à 10 ml", "5 Spritzen à 20 ml" — nur die Größen, die vorkommen.
const syTeile = (n) => SY_ML.filter((ml) => n[ml] > 0).map((ml) => t('bmp.previewSy', { n: n[ml], ml }));
// Ein Tipp auf − oder + ändert das Feld und zieht die Vorschau des Fensters
// nach, in dem es steht (getippt macht das der input-Listener des Fensters).
(function wireZaehler() {
  document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-zaehler]');
    if (!b) return;
    const el = document.getElementById(b.dataset.zaehlerFeld);
    if (!el) return;
    el.value = Math.max(0, Math.min(500, (parseInt(el.value, 10) || 0) + parseInt(b.dataset.zaehler, 10)));
    if (b.closest('#m-beimpfen')) bmpPreview();
    else msQuickPreview();
  });
})();
function lwUpdate() {
  const type = document.getElementById('lw-type').value;
  const pr = document.getElementById('lw-parent-row'),
    sr = document.getElementById('lw-source-row'),
    ql = document.getElementById('lw-qty-lbl');
  const kbRows = document.getElementById('lw-kb-rows'),
    qtyRow = document.getElementById('lw-qty-row');
  const strainTextRow = document.getElementById('lw-strain-text-row');
  const mlRow = document.getElementById('lw-ml-row');
  if (mlRow) mlRow.style.display = type === 'SY' ? 'block' : 'none';
  if (type === 'KB') {
    pr.style.display = 'none';
    sr.style.display = 'none';
    if (qtyRow) qtyRow.style.display = 'none';
    if (kbRows) kbRows.style.display = 'flex';
    if (strainTextRow) strainTextRow.style.display = 'block';
    document.getElementById('lw-prev-box').style.display = 'none';
    fillCultureSelect('gs-culture', ['PD', 'LC', 'SY', 'GS']);
    // Prefill grain hydration % from current inventory default
    const gsRh = document.getElementById('gs-rh');
    if (gsRh) gsRh.value = getAvgComp().grainRhPct;
    gsPreview();
  } else {
    if (kbRows) kbRows.style.display = 'none';
    if (strainTextRow) strainTextRow.style.display = type === 'G2G' ? 'none' : 'block';
    if (qtyRow) qtyRow.style.display = 'block';
    if (type === 'MC') {
      // Von einer Petrischale abgeimpft, oder gekauft: beides kann dastehen.
      pr.style.display = 'block';
      document.getElementById('lw-parent-lbl').textContent = t('lab.parentMcPdLc');
      fillParentSelect(LAB_PARENT_TYPES.MC);
      sr.style.display = 'block';
      ql.textContent = t('lab.qtyTubes');
    } else if (type === 'PD') {
      pr.style.display = 'block';
      document.getElementById('lw-parent-lbl').textContent = t('lab.parentMcPdLc');
      fillParentSelect(LAB_PARENT_TYPES.PD);
      sr.style.display = 'none';
      ql.textContent = t('lab.qtyDishes');
    } else if (type === 'LC') {
      pr.style.display = 'block';
      document.getElementById('lw-parent-lbl').textContent = t('lab.sourceLcPdMc');
      fillParentSelect(LAB_PARENT_TYPES.LC);
      sr.style.display = 'none';
      ql.textContent = t('lab.qtyFlasks');
    } else if (type === 'SY') {
      // Drawn from anything liquid or from a plate, which is the same set the
      // lineage rules in db.js allow — grain cannot go into a syringe.
      pr.style.display = 'block';
      document.getElementById('lw-parent-lbl').textContent = t('lab.sourceLcPdMc');
      fillParentSelect(LAB_PARENT_TYPES.SY);
      sr.style.display = 'none';
      ql.textContent = t('lab.qtySyringes');
    } else {
      pr.style.display = 'none';
      sr.style.display = 'none';
      ql.textContent = t('lab.qtyBags');
    }
    lwPreview();
  }
}
function fillParentSelect(types) {
  const s = document.getElementById('lw-parent');
  const cur = s.value;
  s.innerHTML =
    '<option value="">' +
    t('lab.noneNewIsolation') +
    '</option>' +
    cultures
      .filter((c) => (c.status === 'active' || c.status === 'stored') && types.includes(c.type))
      .map((c) => {
        const kz = c.strainKuerzel || c.strain || '';
        const name = c.strainName || c.species || '';
        const st = (c.strainText || '').trim();
        const label = (kz ? '[' + esc(kz) + '] ' : '') + esc(c.id) + ' — ' + esc(name) + (st ? ' ' + esc(st) : '');
        return `<option value="${esc(c.id)}">${label}</option>`;
      })
      .join('');
  if (cur) s.value = cur;
}
// Highest numeric suffix currently in use for a culture-id prefix. Generating
// the next id from this (not from the count) means deleting an earlier culture
// and creating a new one can't reuse an id — the server's
// INSERT … ON CONFLICT(id) DO UPDATE would otherwise silently overwrite the
// surviving culture's data.
function maxCultureSuffix(prefix) {
  return cultures.reduce((mx, c) => {
    if (!c.id || !c.id.startsWith(prefix)) return mx;
    const n = parseInt(c.id.slice(prefix.length), 10);
    return Number.isFinite(n) && n > mx ? n : mx;
  }, 0);
}
function lwPreview() {
  const type = document.getElementById('lw-type').value;
  const strainId = parseInt(document.getElementById('lw-st')?.value) || null;
  const ms = strainId ? mushroomStrains.find((x) => x.id === strainId) : null;
  const sp = ms ? ms.name : '';
  const qty = parseInt(document.getElementById('lw-qty').value) || 1;
  const box = document.getElementById('lw-prev-box'),
    prev = document.getElementById('lw-prev');
  if (!sp || type === 'G2G' || type === 'KB') {
    box.style.display = 'none';
    return;
  }
  const stRaw = (document.getElementById('lw-strain-text')?.value || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
  const wann = anlageZeitpunkt(document.getElementById('lw-created')?.value);
  const prefix = type + '-' + abbrev(sp) + (stRaw ? '-' + stRaw : '') + '-' + todayStr(wann) + '-';
  const base = maxCultureSuffix(prefix);
  prev.textContent = Array.from({ length: qty }, (_, i) => prefix + String(base + i + 1).padStart(2, '0')).join('\n');
  box.style.display = 'block';
}
// lw-st change and lw-qty input listeners live in initEventListeners()
// opts.id: ein vorhandenes Etikett wird aufgenommen (msQuickOpenIntake) — genau
// eine Kultur mit genau dieser Kennung, und kein neues Etikett, das hängt schon.
function logLabWork(opts) {
  const intakeId = (opts && opts.id) || null;
  // Angesetzt am, wie in createBatch: einmal gelesen und geleert, bevor irgendeine
  // Prüfung abbricht. Die Kennung trägt diesen Tag, wie das Etikett am Glas.
  const angesetzt = anlageNehmen(document.getElementById('lw-created'));
  const wann = anlageZeitpunkt(angesetzt);
  if (intakeId && cultures.some((c) => c.id.toUpperCase() === intakeId)) {
    toast(t('intake.exists', { id: intakeId }), 'err');
    return;
  }
  const type = document.getElementById('lw-type').value;
  const strainSel = document.getElementById('lw-st');
  const strainId = strainSel ? parseInt(strainSel.value) || null : null;
  const ms = strainId ? mushroomStrains.find((x) => x.id === strainId) : null;
  if (!ms) {
    fieldError('lw-st', t('lab.selectPilzsorte'));
    return;
  }
  const parentId = document.getElementById('lw-parent')?.value || null;
  const strainText = (document.getElementById('lw-strain-text')?.value || '').trim();
  const source = document.getElementById('lw-source')?.value.trim() || null;
  const notes = document.getElementById('lw-notes').value.trim();
  // Spritzen kommen aus dem Schnelldialog in mehreren Größen auf einmal
  // (opts.sy = {10: 3, 20: 5, 50: 3}): jede Größe ihre eigenen Nummern, alle
  // Etiketten in einem Fenster. Sonst ein Posten: Anzahl und Größe des Formulars.
  const posten =
    opts && opts.sy
      ? SY_ML.filter((x) => opts.sy[x] > 0).map((x) => [opts.sy[x], x])
      : [
          [
            parseInt(document.getElementById('lw-qty').value) || 1,
            parseInt(document.getElementById('lw-ml')?.value, 10) || 10
          ]
        ];
  const angelegt = posten.map(([qty, ml]) =>
    kulturenAnlegen({ type, ms, wann, qty, id: intakeId, parentId, strainText, source, notes, ml })
  );
  const newC = angelegt.flatMap((r) => r.newC);
  const saved = Promise.all(angelegt.map((r) => r.saved));
  saved.catch(() => {}); // gemeldet in kulturenAnlegen
  document.getElementById('lw-notes').value = '';
  document.getElementById('lw-qty').value = '1';
  if (document.getElementById('lw-source')) document.getElementById('lw-source').value = '';
  lwPreview();
  if (intakeId) {
    saved.then(
      () => toast(t('intake.done', { id: intakeId })),
      () => {}
    );
    return;
  }
  // Der Schluss jedes Weges, der Kulturen anlegt: das Etiketten-Fenster, wie
  // nbPlaceAndPrint() für Beutel. Vorher stand hier eine Ergebniskarte mit
  // Druckknopf im langen Formular — und der Schnelldialog, der dieses Formular
  // nur noch als Ablage benutzt, ließ den Arbeiter ohne ein Etikett stehen.
  cprShow(
    newC.map((c) => c.id),
    saved
  );
}
// Legt qty Kulturen einer Art an, mit Kennung, Speichern und Barcodes — ohne ein
// Formular zu lesen. logLabWork() und das Beimpfen-Fenster (bmpGo) teilen sich
// das; jeder Weg zeigt danach sein eigenes Etiketten-Fenster.
// spec: { type, ms, wann, qty, id?, parentId?, strainText?, source?, notes?, ml? }
// ml zählt nur bei Spritzen; ohne Angabe eine 10er.
function kulturenAnlegen(spec) {
  const { type, ms, wann } = spec;
  const sp = ms.name,
    st = ms.kuerzel;
  const strainText = spec.strainText || '';
  const stId = strainText.replace(/[^A-Za-z0-9]/g, '').toUpperCase();
  const prefix = type + '-' + abbrev(sp) + (stId ? '-' + stId : '') + '-' + todayStr(wann) + '-';
  const base = maxCultureSuffix(prefix);
  const newC = Array.from({ length: spec.id ? 1 : spec.qty }, (_, i) => ({
    id: spec.id || prefix + String(base + i + 1).padStart(2, '0'),
    type,
    species: sp,
    strain: st || '',
    strainId: ms.id,
    strainName: sp,
    strainKuerzel: st || null,
    strainText,
    parentId: spec.parentId || null,
    source: spec.source || null,
    status: 'active',
    notes: spec.notes || '',
    created: wann.toISOString(),
    ml: type === 'SY' ? (SY_ML.includes(spec.ml) ? spec.ml : 10) : null
  }));
  cultures.push(...newC);
  const saved = apiPost('/api/cultures', { cultures: newC }).then((r) => {
    // Abgewiesen: vorher blieb die Kultur hier stehen, bis die App neu lud, und
    // das Etikett druckte trotzdem — ein Glas mit einem Etikett, das danach
    // "nicht im System" hieß. Jetzt geht sie gleich wieder raus, und es steht da.
    if (r && r.error) {
      const ids = new Set(newC.map((c) => c.id));
      cultures = cultures.filter((c) => !ids.has(c.id));
      renderLabLog();
      cprClose();
      toast(t('lab.saveFailed', { msg: r.error }), 'err');
      throw new Error(r.error);
    }
    if (r && r.cultureBarcodes) {
      for (const [id, bc] of Object.entries(r.cultureBarcodes)) {
        barcodeRegistry.set(bc, { type: 'culture', id });
        barcodeByEntity.set('culture:' + id, bc);
      }
    }
  });
  saved.catch(() => {}); // gemeldet im then oben; gedruckt wird nur nach Erfolg
  renderLabLog();
  fillCultureSelect('nb-culture', ['PD', 'LC', 'G2G', 'GS']);
  fillCultureSelect('gs-culture', ['PD', 'LC', 'SY', 'GS']);
  return { newC, saved };
}
function renderLabLog() {
  const body = document.getElementById('lab-log-body');
  const rows = [...cultures].sort((a, b) => b.created.localeCompare(a.created)).slice(0, 50);
  body.innerHTML = rows.length
    ? rows
        .map((c) => {
          const name = c.strainName || c.species || '';
          const kz = c.strainKuerzel || c.strain || '';
          return `<tr><td class="fs-micro" style="color:var(--c-text-muted)">${fmtDt(c.created)}</td><td>${ctBadge(c.type)}</td><td class="fs-xs" style="font-family:monospace">${esc(c.id)}</td><td class="fs-micro" style="font-family:monospace;color:var(--c-text-muted)">${esc(c.parentId) || '\u2014'}</td><td>${spDot(name)}${esc(name)}${kz ? ' / ' + esc(kz) : ''}</td></tr>`;
        })
        .join('')
    : '<tr><td colspan="5" class="empty">' + t('lab.noLabWork') + '</td></tr>';
}

// ─── GRAIN SPAWN (Lab tab) ──────────────────────────────────
// `d` ist der Tag, an dem angesetzt wurde (Inventur), sonst heute. Nummeriert
// nach der höchsten vergebenen Nummer, aus demselben Grund wie genBatchId.
const genGrainBatchId = (sp, strainText, d) => {
  const ab = abbrev(sp),
    dt = todayStr(d),
    st = (strainText || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
  const prefix = 'G-' + ab + (st ? '-' + st : '') + '-' + dt + '-';
  const n = batches.reduce((mx, b) => {
    const k = b.batchId.startsWith(prefix) ? parseInt(b.batchId.slice(prefix.length), 10) : 0;
    return Number.isFinite(k) && k > mx ? k : mx;
  }, 0);
  return prefix + String(n + 1).padStart(2, '0');
};
/** Read all weight-line rows from the grain spawn form */
function gsReadLines() {
  const lines = [];
  for (const row of document.querySelectorAll('.gs-wline')) {
    const kg = parseDecimal(row.querySelector('.gs-line-kg').value) || 0;
    const qty = parseInt(row.querySelector('.gs-line-qty').value) || 0;
    if (kg > 0 && qty > 0) lines.push({ kg, qty });
  }
  return lines;
}
/** Set weight for a specific weight-line row and highlight its preset button */
function gsLineSetWeight(row, kg) {
  row.querySelector('.gs-line-kg').value = kg;
  row.querySelectorAll('.gs-wbtn').forEach((btn) => {
    btn.className = 'btn btn-sm gs-wbtn' + (parseFloat(btn.dataset.kg) === kg ? ' btn-p' : '');
  });
  gsPreview();
}
/** Add a new weight line to the grain spawn form */
function gsAddLine() {
  const container = document.getElementById('gs-weight-lines');
  const first = container.querySelector('.gs-wline');
  const clone = first.cloneNode(true);
  clone.querySelector('.gs-line-kg').value = '1';
  clone.querySelector('.gs-line-qty').value = '10';
  clone.querySelectorAll('.gs-wbtn').forEach((btn) => {
    btn.className = 'btn btn-sm gs-wbtn' + (parseFloat(btn.dataset.kg) === 1 ? ' btn-p' : '');
  });
  container.appendChild(clone);
  gsUpdateRemoveButtons();
  gsPreview();
}
/** Remove a weight line */
function gsRemoveLine(row) {
  row.remove();
  gsUpdateRemoveButtons();
  gsPreview();
}
/** Show/hide remove buttons based on line count */
function gsUpdateRemoveButtons() {
  const rows = document.querySelectorAll('.gs-wline');
  const multi = rows.length > 1;
  rows.forEach((r) => {
    r.querySelector('.gs-line-rm').style.display = multi ? '' : 'none';
  });
}
// Die Gewichtszeilen des langen Formulars von aussen setzen.
//
// Der Schnelldialog fuellte sie vorher selbst: gsResetLines(), dann
// querySelector('.gs-wline') und zwei Werte hineinschreiben -- an zwei Stellen,
// und beide konnten nur EINE Zeile fuellen. Genau das war die Grenze: ein
// Ansatz, eine Groesse. Hier steht der Weg fuer beliebig viele, einmal.
function gsSetLines(lines) {
  gsResetLines();
  const container = document.getElementById('gs-weight-lines');
  if (!container || !lines || !lines.length) return;
  for (let i = 1; i < lines.length; i++) gsAddLine();
  const rows = container.querySelectorAll('.gs-wline');
  lines.forEach((l, i) => {
    const row = rows[i];
    if (!row) return;
    row.querySelector('.gs-line-kg').value = l.kg;
    row.querySelector('.gs-line-qty').value = l.qty;
    row.querySelectorAll('.gs-wbtn').forEach((btn) => {
      btn.className = 'btn btn-sm gs-wbtn' + (parseFloat(btn.dataset.kg) === l.kg ? ' btn-p' : '');
    });
  });
  gsUpdateRemoveButtons();
}
/** Reset grain spawn form to single default line */
function gsResetLines() {
  const container = document.getElementById('gs-weight-lines');
  const rows = container.querySelectorAll('.gs-wline');
  for (let i = rows.length - 1; i > 0; i--) rows[i].remove();
  const first = container.querySelector('.gs-wline');
  first.querySelector('.gs-line-kg').value = '1';
  first.querySelector('.gs-line-qty').value = '10';
  first.querySelectorAll('.gs-wbtn').forEach((btn) => {
    btn.className = 'btn btn-sm gs-wbtn' + (parseFloat(btn.dataset.kg) === 1 ? ' btn-p' : '');
  });
  gsUpdateRemoveButtons();
}
function gsPreview() {
  const strainSel = document.getElementById('lw-st');
  const strainId = strainSel ? parseInt(strainSel.value) || null : null;
  const ms = strainId ? mushroomStrains.find((x) => x.id === strainId) : null;
  const sp = ms ? ms.name : '';
  const lines = gsReadLines();
  const totalQty = lines.reduce((s, l) => s + l.qty, 0);
  const totalWet = lines.reduce((s, l) => s + l.kg * l.qty, 0);
  const grainRhInput = document.getElementById('gs-rh');
  const defaultGrainRh = getAvgComp().grainRhPct;
  const grainRh = grainRhInput ? parseDecimal(grainRhInput.value) || 0 : defaultGrainRh;
  const hydrationFactor = mtGrainFactor(grainRh);
  const totalDry = totalWet * hydrationFactor;
  const lwStrainText = (document.getElementById('lw-strain-text')?.value || '').trim();
  const wann = anlageZeitpunkt(document.getElementById('lw-created')?.value);
  document.getElementById('gs-prev').textContent = sp
    ? genGrainBatchId(sp, lwStrainText, wann) + ' (' + totalQty + ' bags)'
    : '\u2014';
  const el = document.getElementById('gs-mat-preview');
  if (!totalQty || !totalWet) {
    el.style.display = 'none';
    return;
  }
  const breakdown = lines.map((l) => l.qty + ' \u00d7 ' + l.kg + ' kg').join(' + ');
  const avail = inventory.stock?.grain || 0;
  const enough = avail >= totalDry;
  const hydrationNote =
    grainRh > 0
      ? ` <span class="fs-xs" style="color:var(--c-text-muted)">(${totalWet.toFixed(2)} kg wet − ${grainRh}% water)</span>`
      : '';
  el.innerHTML = `<strong>${t('batch.grainNeeded')}</strong> ${totalDry.toFixed(2)} kg dry${hydrationNote} (${breakdown})<br>${t('batch.inStock')} ${avail.toFixed(2)} kg \u2192 ${enough ? '\u2713 ' + t('batch.sufficient') : '\u26A0 ' + t('batch.notEnough')}`;
  el.style.display = 'block';
}
// opts.ohneFenster: das Fenster zum Einlagern und für die Etiketten kommt nicht
// von hier, sondern vom Aufrufer (bmpGo, nach den Kultur-Etiketten). Zurück kommt
// dann { batchObj, bagIds }, oder null, wenn nichts angelegt wurde.
function createGrainBatch(opts) {
  // Angesetzt am, wie in logLabWork: einmal gelesen und geleert, als Erstes. Ein
  // früherer Tag ist Bestand aus der Inventur und bucht kein Korn ab, wie
  // createBatch keine Pellets.
  const angesetzt = anlageNehmen(document.getElementById('lw-created'));
  const wann = anlageZeitpunkt(angesetzt);
  const bucht = !angesetzt;
  const strainSel = document.getElementById('lw-st');
  const strainId = strainSel ? parseInt(strainSel.value) || null : null;
  const ms = strainId ? mushroomStrains.find((x) => x.id === strainId) : null;
  if (!strainId || !ms) {
    if (!mushroomStrains.length) {
      confirm2(t('strains.noStrainsHint'), '', t('strains.createNow'), goCreateStrain);
    } else {
      toast(t('strains.noStrainsHint'), 'err');
    }
    return;
  }
  const sp = ms.name,
    st = ms.kuerzel;
  const lines = gsReadLines();
  if (!lines.length) {
    toast(t('batch.fillQty'), 'err');
    return;
  }
  const days = parseInt(document.getElementById('gs-days').value) || 14;
  const grainRhInput = document.getElementById('gs-rh');
  const defaultGrainRh = getAvgComp().grainRhPct;
  const grainRh = grainRhInput ? parseDecimal(grainRhInput.value) || 0 : defaultGrainRh;
  const totalQty = lines.reduce((s, l) => s + l.qty, 0);
  const lwStrainText = (document.getElementById('lw-strain-text') || {}).value?.trim() || '';
  const batchId = genGrainBatchId(sp, lwStrainText, wann);
  spColor(sp);
  const due = new Date(wann);
  due.setDate(due.getDate() + days);
  // Generate bags with per-bag weight
  const bags = [];
  const bagWeights = {};
  let idx = 1;
  for (const line of lines) {
    for (let i = 0; i < line.qty; i++) {
      const bagId = batchId + '-' + String(idx).padStart(2, '0');
      bags.push({ id: bagId, bagKg: line.kg });
      bagWeights[bagId] = line.kg;
      idx++;
    }
  }
  const bagIds = bags.map((b) => b.id);
  // Das Gewicht der CHARGE, wo jeder Beutel schon sein eigenes trägt.
  //
  // Bei gemischten Größen stand hier null — und insertBatch schreibt
  // `b.bagKg || 3` in die Spalte, also trug eine Charge aus 1- und 2-kg-Beuteln
  // hinterher eine 3, die nie jemand angesetzt hat. Die Zahl ist nicht
  // folgenlos: addBagsToBatch nimmt sie als Gewicht für nachträglich ergänzte
  // Beutel, und bagWeights fällt auf sie zurück. Also die Größe, aus der die
  // meisten Beutel sind — die Antwort, die am seltensten falsch ist.
  const batchBagKg = lines.reduce((best, l) => (l.qty > best.qty ? l : best), lines[0]).kg;
  batches.push({
    batchId,
    species: sp,
    strain: st,
    strainId,
    strainName: ms.name,
    strainKuerzel: ms.kuerzel,
    qty: totalQty,
    days,
    substrate: null,
    bagKg: batchBagKg,
    batchType: 'grain',
    grainRh,
    sourceId: inocCultureId() || document.getElementById('gs-culture').value || null,
    notes: document.getElementById('lw-notes').value.trim(),
    strainText: lwStrainText,
    created: wann.toISOString(),
    due: due.toISOString(),
    bags: bagIds,
    bagWeights
  });
  const batchObj = batches[batches.length - 1];
  // Deduct grain from inventory — apply hydration so only dry grain is subtracted
  // (wet bag weight includes water added during soaking, typically ~52% for wheat).
  // Computed up front so the delta travels with the POST and the server applies
  // it atomically, exactly like createBatch (I-02). The previous shape fired
  // invDeltas separately and unconditionally after the POST, so a rejected batch
  // (duplicate id, server error) still drained grain for a batch that never
  // existed — and nothing rolled the local stock back either.
  if (!inventory.stock) inventory.stock = { hardwood: 0, wheatbran: 0, gypsum: 0, grain: 0, coir: 0 };
  const stockSnapshot = { ...inventory.stock };
  const hydrationFactor = mtGrainFactor(grainRh);
  const grainUsed = lines.reduce((s, l) => s + l.kg * l.qty * hydrationFactor, 0);
  const deltas = [];
  if (grainUsed > 0 && bucht) {
    inventory.stock.grain = Math.max(0, (inventory.stock.grain || 0) - grainUsed);
    deltas.push({ mat: 'grain', deltaKg: -grainUsed, type: 'batch', ref: batchId });
  }
  // Send bags as [{id, bagKg}] to the server
  const apiPayload = Object.assign({}, batchObj, { bags, deltas });
  // Disable while in flight: genGrainBatchId numbers off the local batches array,
  // which already holds this batch, so a double-tap creates a second distinct
  // batch and deducts the grain twice.
  const createBtn = document.getElementById('btn-26');
  if (createBtn) createBtn.disabled = true;
  // Snapshot the inoculant list: the form is cleared below, before the POST
  // resolves, and nothing is written off until the batch is known to have saved.
  const _inocUsed = _inoc.slice();
  // Festgehalten für das gemeinsame Etiketten-Fenster: die Beutelnummern kommen
  // mit dieser Antwort, und gedruckt wird erst danach (printCultureLabelsInline).
  const saved = apiPost('/api/batches', apiPayload)
    .then((r) => {
      if (r && r.error) {
        const i = batches.findIndex((b) => b.batchId === batchObj.batchId);
        if (i >= 0) batches.splice(i, 1);
        // Roll back the optimistic stock mutation — server didn't apply the deltas.
        inventory.stock = stockSnapshot;
        toast(t('batch.saveFailed') + r.error, 'err');
        renderBatches();
        renderStatus();
        return;
      }
      if (r && r.bagBarcodes) {
        for (const [id, bc] of Object.entries(r.bagBarcodes)) {
          barcodeRegistry.set(bc, { type: 'bag', id });
          barcodeByEntity.set('bag:' + id, bc);
        }
      }
      // Grain spawn is usually made from a liquid culture that survives many
      // uses, so ask rather than assume. Ein Körnerbeutel (Körner aus Körnern)
      // geht dagegen ganz hinein und wird ohne Frage ausgebucht.
      inocAskConsume(batchObj, _inocUsed);
    })
    .finally(() => {
      if (createBtn) createBtn.disabled = false;
    });
  _inoc = [];
  inocRender('nb');
  inocRender('ms-q');
  if (strainSel) strainSel.value = '';
  const lwStrainEl = document.getElementById('lw-strain-text');
  if (lwStrainEl) lwStrainEl.value = '';
  gsResetLines();
  document.getElementById('gs-days').value = '14';
  document.getElementById('lw-notes').value = '';
  document.getElementById('gs-mat-preview').style.display = 'none';
  gsPreview();
  updateTodoBadge();
  renderBatches();
  if (opts && opts.ohneFenster) return { batchObj, bagIds, saved };
  // Einlagern, dann Etiketten — derselbe Schluss wie bei jeder anderen Charge.
  // Die Körnerbrut hatte ihren eigenen: eine Ergebniskarte im langen Formular
  // und ein Sprung auf die Druckseite. Vom Schnelldialog aus hieß das, auf einer
  // Seite zu landen, die man nie aufgemacht hatte, während die Charge aus dem
  // Assistenten ihr Fenster bekam, wo man stand. Ein Weg, ein Fenster.
  nbPlaceAndPrint(batchObj, bagIds);
  return { batchObj, bagIds, saved };
}

// ─── LINEAGE ─────────────────────────────────────────────────
// Lineage intentionally uses the legacy c.species / c.strain fields so that
// historical rows without a strain_id still render with their original
// species/kuerzel values. Do not swap to strainName here — old lineage nodes
// would lose their labels.
function fillLineageSelect() {
  const s = document.getElementById('lineage-sel');
  const cur = s.value;
  s.innerHTML =
    '<option value="">' +
    t('lab.selectCultureBatch') +
    '</option>' +
    (cultures.length
      ? `<optgroup label="Cultures">${cultures.map((c) => `<option value="C:${esc(c.id)}">${esc(c.id)} (${esc(c.type)} — ${esc(c.species)})</option>`).join('')}</optgroup>`
      : '') +
    (batches.length
      ? `<optgroup label="Batches">${batches.map((b) => `<option value="B:${esc(b.batchId)}">${esc(b.batchId)} (${esc(b.species)})</option>`).join('')}</optgroup>`
      : '');
  if (cur) s.value = cur;
}
function buildTree(rootId, rootType) {
  const seen = new Set();
  const getAnc = (id) => {
    if (seen.has(id)) return [];
    seen.add(id);
    const c = cultures.find((x) => x.id === id);
    if (!c) return [];
    const node = { id: c.id, type: c.type, species: c.species, strain: c.strain, status: c.status, created: c.created };
    if (c.parentId) {
      const p = cultures.find((x) => x.id === c.parentId);
      if (p) return [...getAnc(c.parentId), node];
    }
    return [node];
  };
  const getDesc = (id, depth) => {
    if (depth > 6) return [];
    const ch = [];
    cultures
      .filter((c) => c.parentId === id)
      .forEach((c) => ch.push({ ...c, harvest: 0, children: getDesc(c.id, depth + 1) }));
    batches
      .filter((b) => b.sourceId === id)
      .forEach((b) => {
        const { status } = getStatus(b.batchId);
        ch.push({
          id: b.batchId,
          type: 'BATCH',
          species: b.species,
          strain: b.strain,
          status,
          harvest: getHarvested(b.batchId),
          created: b.created,
          children: []
        });
      });
    return ch;
  };
  if (rootType === 'C') {
    const anc = getAnc(rootId);
    const c = cultures.find((x) => x.id === rootId);
    if (!c) return null;
    const root = {
      ...(anc[anc.length - 1] || {
        id: c.id,
        type: c.type,
        species: c.species,
        strain: c.strain,
        status: c.status,
        created: c.created
      })
    };
    root.children = getDesc(rootId, 0);
    if (anc.length > 1) {
      let tree = anc[0],
        cur = tree;
      for (let i = 1; i < anc.length; i++) {
        anc[i].children = i === anc.length - 1 ? root.children : [];
        cur.children = [anc[i]];
        cur = anc[i];
      }
      return tree;
    }
    return root;
  } else {
    const b = batches.find((x) => x.batchId === rootId);
    if (!b) return null;
    const { status } = getStatus(b.batchId);
    const bn = {
      id: b.batchId,
      type: 'BATCH',
      species: b.species,
      strain: b.strain,
      status,
      harvest: getHarvested(b.batchId),
      created: b.created,
      children: []
    };
    if (b.sourceId) {
      const anc = getAnc(b.sourceId);
      if (anc.length) {
        let tree = anc[0],
          cur = tree;
        for (let i = 1; i < anc.length; i++) {
          anc[i].children = [];
          cur.children = [anc[i]];
          cur = anc[i];
        }
        cur.children = [bn];
        return tree;
      }
    }
    return bn;
  }
}
const NODE_BG = { MC: '#f3e8ff', PD: '#dbeafe', LC: '#dcfce7', SY: '#e0f2fe', BATCH: '#fff7ed' };
const NODE_BD = { MC: '#c084fc', PD: '#93c5fd', LC: '#86efac', SY: '#7dd3fc', BATCH: '#fdba74' };
function treeHtml(node, depth) {
  const ch = node.children?.length
    ? `<div style="margin-left:${depth ? 20 : 0}px;padding-left:16px;border-left:2px solid var(--c-border);margin-top:5px">${node.children.map((c) => treeHtml(c, depth + 1)).join('')}</div>`
    : '';
  const harv = node.harvest > 0 ? `<span class="badge b-harvest" style="margin-left:4px">${node.harvest}g</span>` : '';
  return `<div style="margin-bottom:5px"><div style="display:inline-flex;align-items:center;gap:6px;flex-wrap:wrap;background:${NODE_BG[node.type] || '#f5f4f0'};border:1px solid ${NODE_BD[node.type] || '#e5e3dd'};border-radius:7px;padding:5px 10px"><span class="fs-micro" style="font-weight:600;color:var(--c-text-sec)">${esc(node.type)}</span><span class="fs-meta" style="font-family:monospace;font-weight:600">${esc(node.id)}</span><span class="fs-xs" style="color:var(--c-text-sec)">${esc(node.species) || ''}${node.strain ? ' / ' + esc(node.strain) : ''}</span><span class="fs-micro" style="color:var(--c-text-muted)">${esc(node.status) || ''}</span>${harv}<span class="fs-micro" style="color:var(--c-text-muted)">${node.created ? fmtDt(node.created) : ''}</span></div>${ch}</div>`;
}
function renderLineage() {
  const val = document.getElementById('lineage-sel').value,
    body = document.getElementById('lineage-body');
  if (!val) {
    body.innerHTML = '<div class="empty">' + t('lab.selectAbove') + '</div>';
    return;
  }
  const [type, id] = val.split(':');
  const tree = buildTree(id, type);
  body.innerHTML = tree
    ? `<div style="padding:4px 0">${treeHtml(tree, 0)}</div>`
    : '<div class="empty">' + t('lab.noLineageData') + '</div>';
}

// ─── BAG INFO MODAL ──────────────────────────────────────────
let biBagId = null,
  biBatchId = null;
function openBagInfo(bagId, batchId, batch) {
  biBagId = bagId;
  biBatchId = batchId;
  const b = batch || batches.find((x) => x.batchId.toUpperCase() === batchId.toUpperCase());
  const el = document.getElementById('bi-body');
  if (!b) {
    el.innerHTML = '<p style="color:var(--c-red-dark)">' + t('batch.notFound') + ': ' + esc(batchId) + '</p>';
    document.getElementById('bi-actions').innerHTML = '';
    renderBlockGoodButtons();
    renderBiNotes();
    document.getElementById('m-baginfo').classList.add('open');
    return;
  }
  document.getElementById('bi-title').textContent = bagId;
  // Current location
  const bagLogs = scanLog.filter((e) => (e.bag || '').toUpperCase() === bagId.toUpperCase());
  let currentLoc = t('bagInfo.notPlaced');
  if (bagLogs.length) {
    const last = bagLogs[bagLogs.length - 1];
    if (last.action === 'REMOVE') currentLoc = istVerbraucht(last) ? t('bagInfo.usedUp') : t('bagInfo.removed');
    else if (last.action === 'ADD' || last.action === 'MOVE') currentLoc = last.to || 'Unknown';
  }
  // Harvests for this bag
  const bagHarvests = harvests.filter((h) => (h.bag || '').toUpperCase() === bagId.toUpperCase());
  const totalHarv = bagHarvests.reduce((s, h) => s + (h.grams || 0), 0);
  // Pre-build last-scan-per-bag map so the bag-chip render below is O(1)/bag
  // instead of O(M)/bag for an M-length scan log.
  const lastByBag = buildLastScanByBag();
  el.innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">
      <div class="met"><div class="met-l">${t('batch.species')}</div><div class="fs-base" style="font-weight:600">${spDot(b.species)}${esc(b.species)}</div></div>
      <div class="met"><div class="met-l">${t('batch.strain')}</div><div class="fs-base" style="font-weight:600">${(b.strainText || '').trim() ? esc(b.strainText.trim()) : !b.strainId && b.strain ? esc(b.strain) : '\u2014'}</div></div>
      <div class="met"><div class="met-l">${t('bagInfo.currentLocation')}</div><div class="fs-base" style="font-weight:600;color:var(--c-blue-dark)">${esc(currentLoc)}</div></div>
      <div class="met"><div class="met-l">${t('dash.totalHarvested')}</div><div class="fs-base" style="font-weight:600;color:var(--c-amber-dark)">${totalHarv > 0 ? totalHarv + 'g' : t('bagInfo.noneYet')}</div></div>
    </div>
    ${biHerkunftHtml(b)}
    <div class="fs-xs" style="font-weight:600;color:var(--c-text-muted);text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px">${t('batch.batchId')} ${esc(b.batchId)} \u2014 ${t('bagInfo.allBags')}</div>
    <div style="display:flex;flex-wrap:wrap;gap:4px;max-height:120px;overflow-y:auto">
      ${b.bags
        .map((bag) => {
          const isThis = bag.toUpperCase() === bagId.toUpperCase();
          const bagNum = bag.split('-').pop();
          const bagLast = lastByBag.get(bag.toUpperCase());
          const loc = !bagLast ? '—' : bagLast.action === 'REMOVE' ? '✗' : bagLast.to || '?';
          return `<span class="fs-xs" style="font-family:monospace;padding:3px 8px;border-radius:5px;background:${isThis ? 'var(--c-text)' : 'var(--c-bg)'};color:${isThis ? '#fff' : 'var(--c-text-sec)'};border:1px solid ${isThis ? 'var(--c-text)' : 'var(--c-border)'}" title="${esc(loc)}">
          ${esc(bagNum)} <span class="fs-floor" style="--fs-own:9px;color:${isThis ? 'var(--c-text-muted)' : 'var(--c-border)'}">${esc(loc)}</span>
        </span>`;
        })
        .join('')}
    </div>
    ${bagHarvests.length ? `<div class="fs-meta" style="margin-top:10px;color:var(--c-amber-dark)"><strong>${t('harvest.log')}:</strong> ${bagHarvests.map((h) => `Flush ${h.flush}: ${h.grams}g`).join(' \u00b7 ')}</div>` : ''}
  `;
  closeCamScan();
  closeScanModal();
  biWholeBatch = false;
  renderBiActions();
  renderBlockGoodButtons();
  renderBiNotes();
  document.getElementById('m-baginfo').classList.add('open');
  setFb('info', t('scanFb.bagInfo', { bag: bagId }), { noModal: true });
}
// Die Kette einer Kultur nach oben, älteste zuerst: MC → PD → LC. Eine Herkunft,
// die nicht (mehr) in der Liste steht, wird trotzdem genannt.
function cultureChain(id) {
  const kette = [];
  const seen = new Set();
  let cur = id;
  while (cur && !seen.has(cur) && kette.length < 10) {
    seen.add(cur);
    const c = cultures.find((x) => x.id === cur);
    kette.unshift(c ? { id: c.id, type: c.type } : { id: cur, type: String(cur).split('-')[0] });
    cur = c ? c.parentId : null;
  }
  return kette;
}
function _biChainHtml(id) {
  return cultureChain(id)
    .map(
      (x) =>
        `<span style="display:inline-flex;align-items:center;gap:4px">${ctBadge(x.type)}<span class="fs-meta" style="font-family:monospace;font-weight:600">${esc(x.id)}</span></span>`
    )
    .join('<span class="fs-xs" style="color:var(--c-text-muted)"> → </span>');
}
// Die Körnerbrut einer Charge: die Beutel, die für sie abgebucht wurden, nach
// ihrer Körnerbrut-Charge gruppiert.
function grainSourcesFor(batchId) {
  const byBatch = new Map();
  for (const bag of spawnSourceFor(batchId)) {
    const g = batches.find((x) => (x.bags || []).some((y) => y.toUpperCase() === bag.toUpperCase()));
    const key = g ? g.batchId : '?';
    if (!byBatch.has(key)) byBatch.set(key, { batch: g || null, bags: [] });
    byBatch.get(key).bags.push(bag);
  }
  return [...byBatch.values()];
}
// Woraus der gescannte Beutel gemacht ist, sofort beim Scannen: Kultur,
// Körnerbrut, Substrat-Ansatz mit Soll- und Ist-Feuchte. Bisher stand davon
// nur die Quellkultur, und nur in der Chargenliste. Alles kommt aus dem, was
// das Gerät schon geladen hat — kein Warten beim Scannen.
function biHerkunftHtml(b) {
  const zeile = (label, inhalt) =>
    `<div style="margin-top:6px"><div class="met-l">${esc(label)}</div><div style="display:flex;flex-wrap:wrap;align-items:center;gap:4px;margin-top:2px">${inhalt}</div></div>`;
  const muted = (txt) => `<span class="fs-meta" style="color:var(--c-text-muted)">${esc(txt)}</span>`;
  const pct = (v) => fmtKg(v, v % 1 ? 1 : 0) + ' %';
  let html = '';
  if (b.sourceId) html += zeile(t('bagInfo.culture'), _biChainHtml(b.sourceId));
  for (const g of grainSourcesFor(b.batchId)) {
    const gb = g.batch;
    const teile = [
      `<span class="fs-meta" style="font-family:monospace;font-weight:600">${esc(gb ? gb.batchId : g.bags[0])}</span>`,
      muted(t('bagInfo.nBags', { n: g.bags.length }))
    ];
    if (gb && gb.grainRh) teile.push(muted('RH ' + pct(gb.grainRh)));
    html += zeile(t('bagInfo.grain'), teile.join(muted('·')));
    if (gb && gb.sourceId) html += zeile(t('bagInfo.grainCulture'), _biChainHtml(gb.sourceId));
  }
  const sb = b.substrateSubId ? (_sbList || []).find((x) => x.subId === b.substrateSubId) : null;
  if (sb) {
    const ist =
      sb.actualRhPct == null
        ? muted(t('bagInfo.rhActual') + ' ' + t('sub.rhNotMeasured'))
        : `<span class="fs-meta" style="font-weight:600">${esc(t('bagInfo.rhActual'))} ${esc(pct(sb.actualRhPct))}</span>`;
    html += zeile(
      t('bagInfo.substrate'),
      [
        `<span class="fs-meta" style="font-family:monospace;font-weight:600">${esc(sb.subId)}</span>`,
        muted(sb.recipeLabel),
        muted(t('bagInfo.rhTarget') + ' ' + pct(sb.composition.rhPct || sb.moisturePct)),
        ist
      ].join(muted('·'))
    );
  } else if (b.substrate && b.batchType !== 'grain' && b.substrate.rh) {
    html += zeile(
      t('bagInfo.substrate'),
      muted('HW ' + b.substrate.hardwood + ' % · WB ' + b.substrate.wheatbran + ' % · RH ' + b.substrate.rh + ' %')
    );
  }
  if (b.created) html += zeile(t('bagInfo.made'), muted(fmtDt(b.created)));
  return html
    ? `<div class="met" style="margin-bottom:12px"><div class="met-l" style="font-weight:700">${esc(t('bagInfo.herkunft'))}</div>${html}</div>`
    : '';
}
// Scope of a sheet move action: false = just the scanned bag, true = whole batch.
let biWholeBatch = false;
// Where is the scanned bag right now, and is it still placed?
function _biBagCurrentLoc() {
  const logs = scanLog.filter((e) => (e.bag || '').toUpperCase() === (biBagId || '').toUpperCase());
  if (!logs.length) return { loc: null, removed: false };
  const last = logs[logs.length - 1];
  if (last.action === 'REMOVE') return { loc: null, removed: true };
  if (last.action === 'ADD' || last.action === 'MOVE') return { loc: last.to || null, removed: false };
  return { loc: null, removed: false };
}
// The heart of the idiot-proof flow: render big, context-aware action buttons
// for the scanned bag. The primary action follows where the bag is now — in
// incubation/spawn it's "→ Fruchtung", in a fruiting tent it's "Ernten" — so
// the worker never picks a mode. Everything else (move elsewhere, contam,
// discard) is one tap below. The move actions honour the single/whole-batch
// toggle.
function renderBiActions() {
  const el = document.getElementById('bi-actions');
  if (!el) return;
  const b = batches.find((x) => x.batchId && x.batchId.toUpperCase() === (biBatchId || '').toUpperCase());
  if (!b) {
    el.innerHTML = '';
    return;
  }
  const cur = _biBagCurrentLoc();
  const role = cur.loc && ZONE_BY_ID[toZone(cur.loc)] ? ZONE_BY_ID[toZone(cur.loc)].role : null;
  const nBags = (b.bags || []).length;
  const hasFruiting = !!_fruitingDest();
  // Same as `btn` above: the size is a class at each use. It has to be, because
  // the three buttons built from this string are not all the same size -- the
  // two primary ones are 17px and the contamination one is 15px, and an inline
  // font-size here would silently win over both.
  const big =
    'width:100%;display:flex;align-items:center;justify-content:center;gap:8px;padding:15px;border-radius:12px;border:0;font-weight:600;margin-bottom:8px;cursor:pointer';
  let html = '';
  if (nBags > 1) {
    const seg = 'flex:1;text-align:center;padding:10px;cursor:pointer;border:0';
    html +=
      '<div style="display:flex;border:1px solid var(--c-border);border-radius:10px;overflow:hidden;margin-bottom:10px">' +
      `<button type="button" data-bi="scope-single" class="fs-sm" style="${seg};${!biWholeBatch ? 'background:var(--c-text);color:#fff' : 'background:transparent;color:var(--c-text-sec)'}">${esc(t('bagInfo.scopeSingle'))}</button>` +
      `<button type="button" data-bi="scope-batch" class="fs-sm" style="${seg};border-left:1px solid var(--c-border);${biWholeBatch ? 'background:var(--c-text);color:#fff' : 'background:transparent;color:var(--c-text-sec)'}">${esc(t('bagInfo.scopeBatch', { n: nBags }))}</button>` +
      '</div>';
  }
  // Körnerbrut kommt nie in die Fruchtung: ihr nächster Schritt ist, in Blöcke zu
  // gehen. Stand hier "→ Fruchtung", weil der Beutel im Spawn-Zelt steht, lag der
  // falsche Knopf am größten da.
  if (!cur.removed && b.batchType === 'grain') {
    html += `<button type="button" data-bi="used" class="fs-floor" style="--fs-own:1.0625rem;${big};background:var(--c-purple-dark);color:#fff">✓ ${esc(t('bagInfo.used'))}</button>`;
  } else if (!cur.removed && (role === 'incubation' || role === 'spawn') && hasFruiting) {
    html += `<button type="button" data-bi="fruchtung" class="fs-floor" style="--fs-own:1.0625rem;${big};background:var(--c-primary);color:#fff">→ ${esc(t('dash.toFruiting'))}</button>`;
  } else if (!cur.removed && role === 'fruiting') {
    html += `<button type="button" data-bi="harvest" class="fs-floor" style="--fs-own:1.0625rem;${big};background:var(--c-amber-dark);color:#fff">✂ ${esc(t('bagInfo.harvest'))}</button>`;
  }
  const sec =
    'flex:1;display:flex;align-items:center;justify-content:center;gap:6px;padding:13px;border-radius:10px;cursor:pointer;background:var(--c-surface);border:1px solid var(--c-border)';
  html +=
    '<div style="display:flex;gap:8px;margin-bottom:8px">' +
    `<button type="button" data-bi="move" class="fs-base" style="${sec};color:var(--c-text);font-weight:600">${esc(t('bagInfo.moveElsewhere'))}</button>` +
    `<button type="button" data-bi="remove" class="fs-base" style="${sec};color:var(--c-text-sec)">${esc(t('bagInfo.discard'))}</button>` +
    '</div>';
  html += `<button type="button" data-bi="contam" class="fs-base" style="${big};padding:13px;background:var(--c-red-light);color:var(--c-red-dark);border:1px solid var(--c-red-border)">${esc(t('bagInfo.reportContam'))}</button>`;
  el.innerHTML = html;
}
// Move the scanned bag (or whole batch, per the toggle) to dest, then drop the
// worker straight back into the camera for the next bag. moveBagsTo/moveBatchTo
// call back synchronously, so re-opening the camera stays inside the tap
// gesture (iOS requires that to start the camera).
function biMoveTo(dest) {
  const b = batches.find((x) => x.batchId && x.batchId.toUpperCase() === (biBatchId || '').toUpperCase());
  if (!b || !dest) return;
  document.getElementById('m-baginfo').classList.remove('open');
  // Re-open the camera BEFORE the move so its confirmation shows as a brief,
  // auto-dismissing toast over the live camera (setFb routes to the camera HUD
  // when the scanner is active). If we moved first, setFb would instead pop the
  // scan-log overlay, which the worker then has to close before scanning again.
  biRearmScanner();
  // Snapshot before the move so a mistap here is as reversible as one on the
  // dashboard. The undo bar sits at z-index 900, above the camera modal, so it
  // stays reachable while scanning continues.
  const snapBags = biWholeBatch ? [b] : [{ ...b, bags: [biBagId] }];
  const snap = _snapshotBeforeMove(snapBags, dest, buildLastScanByBag());
  const cb = function (moved, skipped) {
    if (!moved) {
      setFb(
        'ok',
        skipped ? t('batch.allAlreadyAt', { n: skipped, loc: zoneDisplayName(dest) }) : t('batch.noBagsToMove')
      );
    } else {
      setFb('ok', b.batchId + ': ' + moved + ' Bags → ' + zoneDisplayName(dest));
      if (snap.length) showUndoBar(b.batchId + ': ' + moved + ' → ' + zoneDisplayName(dest), () => _undoMove(snap));
    }
    updateSD();
    renderBatches();
    renderStatus();
  };
  if (biWholeBatch) moveBatchTo(b, dest, cb);
  else moveBagsTo(b, [biBagId], dest, cb);
}
// Verbraucht aus dem Beutel-Fenster: der gescannte Körnerbeutel, oder mit
// "Ganze Charge" alle, die noch dastehen. Danach zurück in die Kamera wie beim
// Umziehen, und ein Fehltipp kostet einen Tipp: Rückgängig, oder ↩ in der
// Kamera. Die Kamera geht vor dem Buchen auf, damit die Meldung dort steht.
function biMarkUsed() {
  const b = batches.find((x) => x.batchId && x.batchId.toUpperCase() === (biBatchId || '').toUpperCase());
  if (!b || !biBagId) return;
  document.getElementById('m-baginfo').classList.remove('open');
  biRearmScanner();
  const entries = spawnBuchen(biWholeBatch ? b.bags || [] : [biBagId], 'spawn', { sitzung: true });
  if (!entries.length) {
    setFb('warn', t('scanFb.alreadyUsed', { bag: biBagId }));
    return;
  }
  const msg =
    entries.length === 1 ? t('bagInfo.usedOne', { bag: entries[0].bag }) : t('bagInfo.usedN', { n: entries.length, id: b.batchId });
  setFb('ok', msg, entries.length === 1 ? entries[0] : undefined);
  showUndoBar(msg, () => spawnZuruecknehmen(entries));
  updateSD();
}
// Return to a clean scan state and re-open the camera, so scanning the next bag
// opens its sheet again (no action armed).
function biRearmScanner() {
  scan.action = null;
  scan.to = null;
  scan.from = null;
  scan.harvestBag = null;
  updateSD();
  openCamScan();
}
function biOpenHarvest() {
  if (!biBagId || !biBatchId) return;
  document.getElementById('m-baginfo').classList.remove('open');
  scan.action = 'HARVEST';
  scan.from = null;
  scan.to = null;
  scan.harvestBag = null;
  updateSD();
  showHarvestPanel(biBagId, biBatchId);
}

// Log a REMOVE entry after the confirmation dialog was accepted.
function biPerformRemove() {
  if (!biBagId) return;
  document.getElementById('m-baginfo').classList.remove('open');
  const bagLast = [...scanLog]
    .reverse()
    .find((e) => (e.bag || '').toUpperCase() === biBagId.toUpperCase() && (e.action === 'ADD' || e.action === 'MOVE'));
  const fromLoc = bagLast ? bagLast.to : null;
  const b = batches.find((x) => x.batchId.toUpperCase() === (biBatchId || '').toUpperCase());
  const tempId = 's' + ++_scanTempIdCounter;
  const entry = {
    time: new Date().toISOString(),
    action: 'REMOVE',
    batch: biBatchId,
    bag: biBagId,
    from: fromLoc,
    to: null,
    species: b?.species || null,
    strain: b?.strain || null,
    user: currentUser?.username || null,
    client_uuid: newScanUuid(),
    _tempId: tempId
  };
  scanLog.push(entry);
  movements.push(entry);
  if (!sessionStartTime) sessionStartTime = Date.now();
  sessionEntries.push(entry);
  scan.count++;
  apiPost('/api/scan-log', { entries: [entry] }).then(function (r) {
    if (r && r.ids && r.ids[0]) setEntryServerId(entry, r.ids[0]);
  });
  updateSD();
  const msg = fromLoc
    ? t('scanFb.removeFromLogged', { bag: biBagId, loc: zoneDisplayName(fromLoc) })
    : t('scanFb.removeLogged', { bag: biBagId });
  setFb('ok', msg, entry);
}

function biConfirmRemove() {
  if (!biBagId) return;
  const bagLast = [...scanLog]
    .reverse()
    .find((e) => (e.bag || '').toUpperCase() === biBagId.toUpperCase() && (e.action === 'ADD' || e.action === 'MOVE'));
  const fromLoc = bagLast ? bagLast.to : null;
  const body = fromLoc
    ? t('bagInfo.confirmRemoveBody', { bag: biBagId, loc: zoneDisplayName(fromLoc) })
    : t('bagInfo.confirmRemoveBodyNoLoc', { bag: biBagId });
  confirm2(t('bagInfo.confirmRemoveTitle'), body, t('bagInfo.confirmRemoveOk'), biPerformRemove);
}
document.getElementById('m-baginfo').addEventListener('click', (e) => {
  if (e.target.id === 'm-baginfo') document.getElementById('m-baginfo').classList.remove('open');
});

// ─── BLOCKBUCH ───────────────────────────────────────────────
// Gute Blöcke und Notizen je Block. Wer in der Fruchtung einen Block scannt, der
// besonders gut läuft, vermerkt ihn mit einem Tipp; das Blockbuch hält fest,
// woraus er gemacht war — Ansatz mit Soll- und Ist-Feuchte, Körnerbrut mit ihrer
// Feuchte — und legt die guten Blöcke je Sorte nebeneinander, bis sich zeigt,
// welches Rezept trägt. Notizen kommen aus dem Beutel-Fenster und beim Ernten.
//
// blockNotes reist in /api/data mit, damit das Beutel-Fenster beim Scannen nicht
// wartet. Herkunft und Ernte je Block holt erst der Reiter (/api/block-book).
let _bbEntries = null;
function blockNoteOf(bagId) {
  const k = String(bagId || '').toUpperCase();
  return blockNotes.find((n) => n.bagId.toUpperCase() === k) || null;
}
function _bbNoteFor(bagId, batchId) {
  let n = blockNoteOf(bagId);
  if (!n) {
    n = { bagId, batchId, good: false, goodAt: null, goodBy: null, comments: [] };
    blockNotes.push(n);
  }
  return n;
}
function _bbCanDelete(c) {
  return !!currentUser && (currentUser.role === 'admin' || (!!c.by && c.by === currentUser.username));
}
function _bbOpen() {
  const el = document.getElementById('sp-batch-blocks');
  return !!(el && el.classList.contains('active'));
}
// Körnerbrut ist kein Block: sie wird verbraucht, nicht geerntet.
function biIsBlock() {
  const b = batches.find((x) => x.batchId && x.batchId.toUpperCase() === (biBatchId || '').toUpperCase());
  return !!b && b.batchType !== 'grain';
}
// Beide Gut-Knöpfe, im Beutel-Fenster und in der Ernte-Leiste, zeigen den Stand
// des Beutels, um den es dort gerade geht.
function renderBlockGoodButtons() {
  const set = (id, bagId, show) => {
    const btn = document.getElementById(id);
    if (!btn) return;
    btn.hidden = !show;
    const on = !!(bagId && blockNoteOf(bagId)?.good);
    btn.setAttribute('aria-pressed', on ? 'true' : 'false');
  };
  set('bi-good', biBagId, !!biBagId && biIsBlock());
  set('hp-good', scan.harvestBag && scan.harvestBag.bagId, !!scan.harvestBag);
}
async function setBlockGoodFor(bagId, batchId, on, withUndo) {
  const n = _bbNoteFor(bagId, batchId);
  const vorher = { good: n.good, goodAt: n.goodAt, goodBy: n.goodBy };
  Object.assign(n, {
    good: on,
    goodAt: on ? new Date().toISOString() : null,
    goodBy: on ? currentUser?.username || null : null
  });
  renderBlockGoodButtons();
  const r = await apiPost('/api/block-notes/good', { bag: bagId, on });
  if (!r || r.error) {
    Object.assign(n, vorher);
    renderBlockGoodButtons();
    setFb('err', t('block.saveFailed', { msg: (r && r.error) || 'Network error' }), { noModal: true });
    return;
  }
  const msg = on ? t('block.markedGood', { bag: bagId }) : t('block.unmarkedGood', { bag: bagId });
  setFb('ok', msg, { noModal: true });
  if (withUndo) showUndoBar(msg, () => setBlockGoodFor(bagId, batchId, !on, false));
  if (_bbOpen()) loadBlockBook();
}
function toggleBlockGood(bagId, batchId) {
  if (!bagId) return;
  setBlockGoodFor(bagId, batchId, !blockNoteOf(bagId)?.good, true);
}
async function addBlockComment(bagId, batchId, text, flush) {
  const n = _bbNoteFor(bagId, batchId);
  const c = { id: null, text, flush: flush || null, at: new Date().toISOString(), by: currentUser?.username || null };
  n.comments.push(c);
  renderBiNotesList();
  const r = await apiPost('/api/block-notes/comments', { bag: bagId, text, flush: flush || undefined });
  if (!r || r.error) {
    n.comments.splice(n.comments.indexOf(c), 1);
    renderBiNotesList();
    setFb('err', t('block.saveFailed', { msg: (r && r.error) || 'Network error' }), { noModal: true });
    return false;
  }
  c.id = r.id;
  renderBiNotesList();
  if (_bbOpen()) loadBlockBook();
  return true;
}
// Ein Tipp löscht, Rückgängig schreibt dieselbe Notiz neu.
async function deleteBlockComment(id) {
  let n = null,
    c = null;
  for (const x of blockNotes) {
    const y = x.comments.find((k) => k.id === id);
    if (y) {
      n = x;
      c = y;
      break;
    }
  }
  if (!c) return;
  n.comments.splice(n.comments.indexOf(c), 1);
  renderBiNotesList();
  if (_bbEntries) {
    for (const e of _bbEntries) e.comments = e.comments.filter((k) => k.id !== id);
    renderBlockBook();
  }
  const r = await apiDelete('/api/block-notes/comments/' + id);
  if (!r || r.error) {
    n.comments.push(c);
    renderBiNotesList();
    if (_bbOpen()) loadBlockBook();
    setFb('err', t('block.saveFailed', { msg: (r && r.error) || 'Network error' }), { noModal: true });
    return;
  }
  showUndoBar(t('block.noteDeleted'), () => addBlockComment(n.bagId, n.batchId, c.text, c.flush));
}
function _bbCommentsHtml(comments) {
  return comments
    .map((c) => {
      const meta = [fmtDtTime(c.at), c.by ? esc(c.by) : '', c.flush ? esc(t('block.atFlush', { n: c.flush })) : '']
        .filter(Boolean)
        .join(' · ');
      const del =
        c.id && _bbCanDelete(c)
          ? `<button type="button" class="bb-note-del" data-bb-del="${c.id}" aria-label="${esc(t('block.deleteNote'))}" title="${esc(t('block.deleteNote'))}">×</button>`
          : '';
      return `<div class="bb-note"><div class="bb-note-text fs-meta">${esc(c.text)}</div><div class="bb-note-meta fs-micro">${meta}${del}</div></div>`;
    })
    .join('');
}
// Das Notizfeld wird einmal gebaut, wenn das Fenster aufgeht; danach ändert sich
// nur die Liste darüber. Sonst wischte jede Synchronisierung weg, was gerade
// getippt wird.
function renderBiNotes() {
  const el = document.getElementById('bi-notes');
  if (!el) return;
  if (!biBagId || !biIsBlock()) {
    el.innerHTML = '';
    return;
  }
  el.innerHTML =
    `<div class="met bb-bi-notes"><div class="met-l" style="font-weight:700">${esc(t('block.notes'))}</div>` +
    '<div id="bi-notes-list"></div>' +
    `<textarea id="bi-note-text" rows="2" maxlength="2000" placeholder="${esc(t('block.notePlaceholder'))}"></textarea>` +
    `<div class="bb-bi-save"><button type="button" class="btn btn-sm" id="bi-note-save">${esc(t('block.saveNote'))}</button></div></div>`;
  renderBiNotesList();
}
function renderBiNotesList() {
  const el = document.getElementById('bi-notes-list');
  if (!el || !biBagId) return;
  const n = blockNoteOf(biBagId);
  el.innerHTML = n && n.comments.length ? _bbCommentsHtml(n.comments) : '';
}
function biSaveNote() {
  const ta = document.getElementById('bi-note-text');
  const text = ta ? ta.value.trim() : '';
  if (!text || !biBagId) return;
  const bag = biBagId;
  ta.value = '';
  addBlockComment(bag, biBatchId, text, null).then((ok) => {
    if (ok) setFb('ok', t('block.noteSaved', { bag }), { noModal: true });
    else if (ta.isConnected && !ta.value) ta.value = text;
  });
}

async function loadBlockBook() {
  try {
    const r = await apiGet('/api/block-book');
    _bbEntries = (r && r.entries) || [];
    renderBlockBook();
  } catch (e) {
    const el = document.getElementById('bb-good');
    if (el) el.innerHTML = `<div class="empty">${esc(t('block.loadFailed', { msg: e.message }))}</div>`;
  }
}
const _bbPct = (v) => fmtKg(v, v % 1 ? 1 : 0) + ' %';
const _bbAvg = (a) => a.reduce((s, x) => s + x, 0) / a.length;
function _bbLineageHtml(l) {
  const muted = (txt) => `<span class="bb-muted">${esc(txt)}</span>`;
  const mono = (txt) => `<span class="bb-mono">${esc(txt)}</span>`;
  const zeile = (label, teile) =>
    `<div class="bb-line"><span class="met-l">${esc(label)}</span> ${teile.filter(Boolean).join(muted(' · '))}</div>`;
  let html = '';
  const s = l.substrate;
  if (s) {
    const ist =
      s.actualRh == null
        ? muted(t('bagInfo.rhActual') + ' ' + t('sub.rhNotMeasured'))
        : `<strong>${esc(t('bagInfo.rhActual') + ' ' + _bbPct(s.actualRh))}</strong>`;
    const mix = s.subId
      ? ''
      : muted(
          'HW ' + _bbPct(s.hardwoodPct) + ' · WB ' + _bbPct(s.wheatbranPct)
        );
    html += zeile(t('bagInfo.substrate'), [
      s.subId ? mono(s.subId) : '',
      s.recipe ? muted(s.recipe) : '',
      mix,
      s.targetRh ? muted(t('bagInfo.rhTarget') + ' ' + _bbPct(s.targetRh)) : '',
      ist
    ]);
  }
  for (const g of l.grain || []) {
    html += zeile(t('bagInfo.grain'), [
      g.batchId ? mono(g.batchId) : '',
      g.rh ? `<strong>${esc('RH ' + _bbPct(g.rh))}</strong>` : '',
      muted(t('bagInfo.nBags', { n: g.bags }))
    ]);
  }
  if (l.culture) html += zeile(t('bagInfo.culture'), [mono(l.culture)]);
  return html;
}
function _bbEntryHtml(e, withComments) {
  const l = e.lineage || {};
  const ernte =
    e.harvestG > 0
      ? `${fmtKg(e.harvestG, 0)} g (${e.harvestCount}×)`
      : `<span class="bb-muted">${esc(t('block.noHarvest'))}</span>`;
  const star = e.good ? '<svg class="bb-star" width="14" height="14" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3l2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1-4.4-4.3 6.1-.9z" /></svg>' : '';
  const head =
    `<div class="bb-head"><span class="bb-mono"><strong>${esc(e.bagId)}</strong></span>${star}` +
    `<span class="fs-meta">${l.species ? spDot(l.species) + esc(l.species) : ''}${l.strain ? ' / ' + esc(l.strain) : ''}</span>` +
    `<span class="fs-meta bb-harvest">${ernte}</span></div>`;
  const gone = e.live ? '' : `<div class="bb-line bb-muted fs-micro">${esc(t('block.batchGone'))}</div>`;
  const comments = withComments && e.comments.length ? `<div class="bb-notes">${_bbCommentsHtml(e.comments)}</div>` : '';
  return `<div class="bb-entry">${head}<div class="fs-meta">${_bbLineageHtml(l)}</div>${gone}${comments}</div>`;
}
// Je Sorte: wie viele gute Blöcke, aus welchem Rezept, mit welcher Feuchte im
// Substrat (gemessen, wo jemand gemessen hat) und in der Körnerbrut, und was sie
// im Schnitt getragen haben. Das ist die Zeile, die mit der Zeit zum Rezept wird.
function _bbSummaryHtml(good) {
  const bySp = new Map();
  for (const e of good) {
    const l = e.lineage || {};
    const k = l.species || '?';
    if (!bySp.has(k)) bySp.set(k, { n: 0, recipes: new Map(), ist: [], soll: [], grain: [], harvest: [] });
    const a = bySp.get(k);
    a.n++;
    const s = l.substrate;
    if (s) {
      const r = s.recipe || (s.subId ? s.subId : 'HW ' + _bbPct(s.hardwoodPct) + ' · WB ' + _bbPct(s.wheatbranPct));
      a.recipes.set(r, (a.recipes.get(r) || 0) + 1);
      if (s.actualRh != null) a.ist.push(s.actualRh);
      if (s.targetRh) a.soll.push(s.targetRh);
    }
    for (const g of l.grain || []) if (g.rh) a.grain.push(g.rh);
    if (e.harvestG > 0) a.harvest.push(e.harvestG);
  }
  return [...bySp.entries()]
    .sort((x, y) => y[1].n - x[1].n)
    .map(([sp, a]) => {
      const box = (label, wert) =>
        `<div class="met"><div class="met-l">${esc(label)}</div><div class="fs-meta" style="font-weight:600">${wert}</div></div>`;
      const dash = '<span class="bb-muted">—</span>';
      const recipes = [...a.recipes.entries()]
        .sort((x, y) => y[1] - x[1])
        .map(([r, c]) => esc(r) + (a.n > 1 ? ' <span class="bb-muted">×' + c + '</span>' : ''))
        .join('<br>');
      const sub = [
        a.ist.length
          ? esc(t('bagInfo.rhActual') + ' Ø ' + _bbPct(Math.round(_bbAvg(a.ist) * 10) / 10)) +
            ` <span class="bb-muted">(${esc(t('block.nMeasured', { n: a.ist.length }))})</span>`
          : '',
        a.soll.length
          ? `<span class="bb-muted">${esc(t('bagInfo.rhTarget') + ' Ø ' + _bbPct(Math.round(_bbAvg(a.soll) * 10) / 10))}</span>`
          : ''
      ]
        .filter(Boolean)
        .join('<br>');
      return (
        `<div class="bb-sum"><div class="bb-head"><span class="fs-base" style="font-weight:600">${spDot(sp)}${esc(sp)}</span>` +
        `<span class="fs-meta bb-muted">${esc(a.n === 1 ? t('block.oneBlock') : t('block.nBlocks', { n: a.n }))}</span></div>` +
        '<div class="bb-sum-grid">' +
        box(t('block.recipes'), recipes || dash) +
        box(t('block.substrateRh'), sub || dash) +
        box(t('block.grainRh'), a.grain.length ? esc('Ø ' + _bbPct(Math.round(_bbAvg(a.grain) * 10) / 10)) : dash) +
        box(t('block.avgHarvest'), a.harvest.length ? esc(fmtKg(Math.round(_bbAvg(a.harvest)), 0) + ' g') : dash) +
        '</div></div>'
      );
    })
    .join('');
}
function renderBlockBook() {
  const sumEl = document.getElementById('bb-summary'),
    goodEl = document.getElementById('bb-good'),
    notesEl = document.getElementById('bb-notes');
  if (!sumEl || !goodEl || !notesEl || !_bbEntries) return;
  const good = _bbEntries.filter((e) => e.good).sort((a, b) => (b.goodAt || '').localeCompare(a.goodAt || ''));
  const lastAt = (e) => (e.comments.length ? e.comments[e.comments.length - 1].at : '');
  const noted = _bbEntries.filter((e) => e.comments.length).sort((a, b) => lastAt(b).localeCompare(lastAt(a)));
  sumEl.innerHTML = good.length ? _bbSummaryHtml(good) : '';
  goodEl.innerHTML = good.length
    ? good.map((e) => _bbEntryHtml(e, false)).join('')
    : `<div class="empty">${esc(t('block.goodEmpty'))}</div>`;
  notesEl.innerHTML = noted.length
    ? noted.map((e) => _bbEntryHtml(e, true)).join('')
    : `<div class="empty">${esc(t('block.notesEmpty'))}</div>`;
}

document.getElementById('bi-good').addEventListener('click', () => toggleBlockGood(biBagId, biBatchId));
document.getElementById('hp-good').addEventListener('click', () => {
  if (scan.harvestBag) toggleBlockGood(scan.harvestBag.bagId, scan.harvestBag.batchId);
});
document.getElementById('hp-note').addEventListener('keydown', (e) => {
  if (e.key === 'Enter') confirmHarvest();
});
document.getElementById('bi-notes').addEventListener('click', (e) => {
  if (e.target.closest('#bi-note-save')) return biSaveNote();
  const del = e.target.closest('[data-bb-del]');
  if (del) deleteBlockComment(parseInt(del.dataset.bbDel, 10));
});
document.getElementById('sp-batch-blocks').addEventListener('click', (e) => {
  const del = e.target.closest('[data-bb-del]');
  if (del) deleteBlockComment(parseInt(del.dataset.bbDel, 10));
});

// ─── CONTAMINATION REPORT MODAL ──────────────────────────────
// MVP from audit Section 2 / PR 7. Captures bag/batch + type + severity +
// notes + up to 4 photos (compressed client-side to ~200 KB JPEG / ~15 KB
// thumb), POSTs to /api/contamination-reports.
// Die Beutel, über die dieses Formular berichtet: [{ bag, batch }].
//
// Es war ein Beutel, und das war die Reibung. Eine kontaminierte Reihe ist nicht
// ein Beutel, sondern acht, und für jeden ging dasselbe Fenster auf: Typ tippen,
// Schwere tippen, senden, Fenster zu, nächster Scan. Jetzt sammelt der Scanner,
// solange CONTAM steht, und das Formular kommt einmal für alle.
let _crTargets = [];
let _crBatchId = null;
let _crZoneId = null;
// Steht auf true, während die Kamera aus einem offenen Formular heraus geholt
// wurde ("+ Scannen"). closeCamScan() bringt das Formular dann zurück, mit Typ,
// Schwere, Fotos und Notiz so, wie sie vor dem Scannen standen.
let _crResumeForm = false;
let _crTypes = null; // lazily loaded from /api/contamination-types
// Der Typ ist freiwillig: Beutel scannen, Senden, fertig. Er stand vorher als
// Pflichtfeld davor, und für die meisten Meldungen war die Antwort "weiß ich
// nicht". Ohne Wahl legt der Server den Bericht unter "Unbekannt / Sonstiges"
// ab. Er wird auch nicht mehr vom letzten Bericht übernommen — ein Typ, den
// niemand für diesen Beutel gewählt hat, wäre eine stille Falschangabe.
let _crSelectedTypeId = null;
let _crSeverity = 'minor';
let _crPhotos = []; // [{ data_url, thumb_data_url, width, height }]
const CR_MAX_PHOTOS = 4;

function biReportContam() {
  if (!biBagId) return;
  document.getElementById('m-baginfo').classList.remove('open');
  openContamReport(biBagId, biBatchId, null);
}

function openContamReport(bagId, batchId, zoneId) {
  _crTargets = bagId ? [{ bag: bagId, batch: batchId || null }] : [];
  _crBatchId = batchId || null;
  _crZoneId = zoneId || null;
  _crOpenForm(false);
}

// Das Formular über die Beutel öffnen, die der Scanner schon gesammelt hat.
function crOpenCollected() {
  if (!_crTargets.length) return;
  // Bei einem Beutel steht die Charge im Kopf des Formulars; bei mehreren aus
  // verschiedenen Chargen gibt es keine gemeinsame, und jeder Bericht bekommt
  // seine eigene aus der Sammelliste.
  _crBatchId = _crTargets.length === 1 ? _crTargets[0].batch : null;
  _crZoneId = null;
  _crOpenForm(false);
}

// keep = true lässt Typ, Schwere, Fotos und Notiz stehen. Das ist der Rückweg
// aus "+ Scannen": wer zwei Beutel nachträgt, hat sein Foto schon gemacht und
// den Typ schon getippt.
function _crOpenForm(keep) {
  if (!keep) {
    _crSelectedTypeId = null;
    _crSeverity = 'minor';
    _crPhotos = [];
    // Reset form
    document.getElementById('cr-notes').value = '';
    document.getElementById('cr-photo-status').textContent = '';
    // Reset severity buttons to 'minor' active
    document.querySelectorAll('#cr-severity-row .contam-sev-btn').forEach((b) => {
      b.classList.toggle('active', b.dataset.sev === 'minor');
    });
    // Auto-MOVE default tracks severity: off for minor, on for major/lost.
    // Worker can still toggle it manually before submit.
    const autoMoveEl = document.getElementById('cr-auto-move');
    if (autoMoveEl) autoMoveEl.checked = false;
    // "Mehr" geht jedes Mal zu auf: ein neuer Bericht fängt schlank an.
    const mehr = document.getElementById('cr-more');
    if (mehr) mehr.open = false;
  }
  _crRenderTargets();
  _renderCrPhotos();
  // Lazy-load types on first open; refresh on later opens to pick up admin edits
  apiGet('/api/contamination-types')
    .then((types) => {
      _crTypes = Array.isArray(types) ? types : [];
      // Drop a remembered pre-selection if that type was since deleted/renamed.
      if (_crSelectedTypeId != null && !_crTypes.some((tp) => tp.id === _crSelectedTypeId)) _crSelectedTypeId = null;
      _renderCrTypeGrid();
    })
    .catch(() => {
      _crTypes = [];
      _renderCrTypeGrid();
    });
  document.getElementById('m-contam-report').classList.add('open');
}

// Die Beutel im Kopf des Formulars, jeder mit einem × zum Streichen, dahinter
// der Knopf, der die Kamera für weitere holt.
function _crRenderTargets() {
  const el = document.getElementById('cr-target');
  if (!el) return;
  const add =
    '<button type="button" id="cr-scan-more" class="cr-target-add">' + esc(t('contam.scanMore')) + '</button>';
  if (!_crTargets.length) {
    el.innerHTML = '<span class="cr-target-text">' + esc(t('contam.targetBatch', { batch: _crBatchId || '—' })) + '</span>' + add;
    return;
  }
  const chips = _crTargets
    .map(
      (tg) =>
        '<span class="cr-target-chip">' +
        esc(tg.bag) +
        '<button type="button" class="cr-target-x" data-cr-untarget="' +
        esc(tg.bag) +
        '" aria-label="' +
        esc(t('contam.removeBag', { bag: tg.bag })) +
        '">&times;</button></span>'
    )
    .join('');
  const head =
    _crTargets.length === 1
      ? '<span class="cr-target-text">' +
        esc(t('contam.targetBag', { bag: _crTargets[0].bag, batch: _crTargets[0].batch || '—' })) +
        '</span>'
      : '<span class="cr-target-text">' + esc(t('contam.targetBags', { n: _crTargets.length })) + '</span>';
  el.innerHTML = head + '<div class="cr-target-chips">' + chips + add + '</div>';
}

// Beutel in die Sammelliste legen — oder wieder heraus, wenn er schon drin ist.
// Zweimal denselben Beutel zu scannen ist am Regal das übliche Versehen; ihn
// stumm ein zweites Mal aufzunehmen wären zwei Berichte über einen Beutel.
function crToggleTarget(bagId, batchId) {
  const key = (bagId || '').toUpperCase();
  if (!key) return null;
  const i = _crTargets.findIndex((tg) => (tg.bag || '').toUpperCase() === key);
  if (i !== -1) {
    _crTargets.splice(i, 1);
    return { bag: bagId, added: false, count: _crTargets.length };
  }
  _crTargets.push({ bag: bagId, batch: batchId || null });
  return { bag: bagId, added: true, count: _crTargets.length };
}

// Aus dem offenen Formular zurück zum Scannen, ohne das Formular aufzugeben.
//
// Am Telefon ist die Kamera der Scanner. Am Tisch hängt ein Handscanner und oft
// gar keine Kamera — dort tritt das Formular nur zur Seite, und der
// Melden-Knopf in der Scan-Hülle holt es mit allem Ausgefüllten zurück.
function crScanMore() {
  _crResumeForm = true;
  document.getElementById('m-contam-report').classList.remove('open');
  const kamera = !window.matchMedia || window.matchMedia('(pointer: coarse)').matches;
  // Stumm scharfstellen, wo die Kamera aufgeht: die Quittung von
  // armScanAction() klappt sonst die grüne Scan-Hülle auf, und die liegt
  // (z-index 900) über dem Kamerabild.
  if (scan.action !== 'CONTAM') armScanAction('CONTAM', kamera ? { noModal: true } : undefined);
  if (kamera) openCamScan();
  else openScanModal();
  updateSD();
}

// Sammeln beenden: Kamera zu, Formular auf.
//
// Die Kamera muss zu, bevor das Formular aufgeht: beide liegen auf z-index 200,
// und die Kamera steht im Quelltext dahinter — offen läge sie obenauf und das
// Formular unsichtbar darunter.
//
// Die Marke fällt zuerst, sonst holt closeCamScan() das Formular ein zweites
// Mal, und zwar über den Weg, der den Entwurf verwirft.
function crFinishCollect() {
  const keep = _crResumeForm;
  _crResumeForm = false;
  if (document.getElementById('m-camscan').classList.contains('open')) closeCamScan();
  if (keep) _crOpenForm(true);
  else crOpenCollected();
}

// Das Formular zur Seite legen: × oben rechts und der Tipp neben das Fenster.
//
// Beides schloss den Bericht und warf alles weg. Bei einem Beutel war das ein
// Formular; bei acht sind es acht Scans, die ein Fehltipp am Rand kostet — und
// am Telefon ist der Rand da, wo der Daumen hält. Also bleibt beides stehen,
// und der ⚠-Knopf mit seiner Zahl bzw. "Melden (N)" holt es zurück.
function crStashReport() {
  document.getElementById('m-contam-report').classList.remove('open');
  if (_crTargets.length) _crResumeForm = true;
  updateSD();
}

// Abbrechen: weg ist weg. Der eine Weg, der die gesammelten Beutel wirklich
// verwirft — sonst stünden sie beim nächsten Bericht wieder da, und niemand
// würde sie dort suchen.
function closeContamReport() {
  document.getElementById('m-contam-report').classList.remove('open');
  _crPhotos = [];
  _crTargets = [];
  _crResumeForm = false;
  updateSD();
}

function _crLocalizedName(t) {
  if (currentLang === 'de') return t.name_de;
  if (currentLang === 'pt') return t.name_pt;
  return t.name_en;
}

function _renderCrTypeGrid() {
  const grid = document.getElementById('cr-type-grid');
  if (!_crTypes || !_crTypes.length) {
    grid.innerHTML =
      '<div class="fs-meta" style="color:var(--c-text-muted);grid-column:1/-1">' + t('contam.noTypes') + '</div>';
    return;
  }
  grid.innerHTML = _crTypes
    .map((tp) => {
      const isActive = _crSelectedTypeId === tp.id;
      return `<button type="button" class="contam-type-btn${isActive ? ' active' : ''}" data-type-id="${tp.id}" style="color:${esc(tp.color)}">
        <span class="contam-type-dot" style="background:${esc(tp.color)}"></span>
        <span style="color:var(--c-text)">${esc(_crLocalizedName(tp))}</span>
      </button>`;
    })
    .join('');
}

async function _crCompressFile(file) {
  // Decode → resize to 1280px long edge / quality 0.8 → also a 200px thumb.
  // Canvas re-encode strips EXIF (incl. GPS) automatically — privacy win.
  const img = await new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const i = new Image();
    i.onload = () => {
      URL.revokeObjectURL(url);
      resolve(i);
    };
    i.onerror = (e) => {
      URL.revokeObjectURL(url);
      reject(new Error('image decode failed'));
    };
    i.src = url;
  });
  function draw(maxEdge, quality) {
    const scale = Math.min(1, maxEdge / Math.max(img.width, img.height));
    const w = Math.max(1, Math.round(img.width * scale));
    const h = Math.max(1, Math.round(img.height * scale));
    const c = document.createElement('canvas');
    c.width = w;
    c.height = h;
    c.getContext('2d').drawImage(img, 0, 0, w, h);
    return new Promise((resolve, reject) => {
      c.toBlob(
        (blob) => {
          if (!blob) {
            reject(new Error('encode failed'));
            return;
          }
          const fr = new FileReader();
          fr.onload = () => resolve({ data_url: fr.result, width: w, height: h });
          fr.onerror = () => reject(new Error('read failed'));
          fr.readAsDataURL(blob);
        },
        'image/jpeg',
        quality
      );
    });
  }
  const main = await draw(1280, 0.8);
  const thumb = await draw(200, 0.7);
  return {
    data_url: main.data_url,
    width: main.width,
    height: main.height,
    thumb_data_url: thumb.data_url
  };
}

async function _crAddFiles(fileList) {
  const status = document.getElementById('cr-photo-status');
  const files = Array.from(fileList || []).filter((f) => f && f.type && f.type.startsWith('image/'));
  if (!files.length) return;
  for (const file of files) {
    if (_crPhotos.length >= CR_MAX_PHOTOS) {
      status.textContent = t('contam.photoLimit', { n: CR_MAX_PHOTOS });
      break;
    }
    status.textContent = t('contam.compressing', { name: file.name });
    try {
      const photo = await _crCompressFile(file);
      _crPhotos.push(photo);
      _renderCrPhotos();
    } catch (e) {
      console.error('photo compress failed', e);
      status.textContent = t('contam.compressErr');
      return;
    }
  }
  status.textContent = '';
}

function _renderCrPhotos() {
  const tiles = document.getElementById('cr-photo-tiles');
  const tilesHtml = _crPhotos
    .map(
      (p, i) =>
        `<div class="contam-photo-tile" data-cr-edit="${i}" title="${esc(t('contam.annotateHint'))}"><img src="${esc(p.thumb_data_url)}" alt=""><span class="annot-hint" aria-hidden="true">✏︎</span><button type="button" class="remove" data-cr-remove="${i}" aria-label="Remove">&times;</button></div>`
    )
    .join('');
  const addTile =
    _crPhotos.length < CR_MAX_PHOTOS
      ? `<button type="button" id="cr-add-photo" class="contam-photo-tile add" aria-label="${esc(t('contam.addPhoto'))}">${esc(t('contam.photoTile'))}</button>`
      : '';
  tiles.innerHTML = tilesHtml + addTile;
}

// Ein zweiter Tipp auf denselben Typ nimmt ihn wieder heraus — sonst gäbe es,
// einmal getippt, keinen Weg mehr zurück zu "ohne Typ".
function _crSelectType(typeId) {
  _crSelectedTypeId = _crSelectedTypeId === typeId ? null : typeId;
  _renderCrTypeGrid();
}

// ─── PHOTO ANNOTATION ─────────────────────────────────────────
// Tap a photo tile in the contamination capture modal to open a drawing
// surface over it. Workers circle / mark the contamination spot with a
// finger, hit Done, and the strokes get baked into the JPEG before submit.
// "Trichoderma along the lid seam" is much easier to communicate visually
// than in notes.
let _paIdx = -1;
let _paImg = null; // HTMLImageElement of the photo's full-res copy
let _paDrawing = false;
let _paStrokeWidth = 0;
function openAnnotate(idx) {
  if (idx < 0 || idx >= _crPhotos.length) return;
  _paIdx = idx;
  const photo = _crPhotos[idx];
  const canvas = document.getElementById('pa-canvas');
  const ctx = canvas.getContext('2d');
  const img = new Image();
  _paImg = img;
  img.onload = function () {
    // Fit canvas to image's natural pixels so strokes composite at the
    // same scale on submit (no resampling distortion).
    canvas.width = img.naturalWidth;
    canvas.height = img.naturalHeight;
    ctx.drawImage(img, 0, 0);
    // Stroke width scaled to image size — ~1% of the long edge feels
    // right on phone. Applied via lineWidth at draw time.
    _paStrokeWidth = Math.max(4, Math.round(Math.max(img.naturalWidth, img.naturalHeight) / 100));
    document.getElementById('m-photo-annotate').classList.add('open');
  };
  img.onerror = function () {
    setFb('err', t('contam.annotateLoadErr'));
  };
  img.src = photo.data_url;
}
function closeAnnotate() {
  document.getElementById('m-photo-annotate').classList.remove('open');
  _paIdx = -1;
  _paImg = null;
  _paDrawing = false;
}
function _paClear() {
  if (!_paImg) return;
  const canvas = document.getElementById('pa-canvas');
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(_paImg, 0, 0);
}
function _paPos(e) {
  const canvas = document.getElementById('pa-canvas');
  const r = canvas.getBoundingClientRect();
  // Translate page coords -> canvas coords (canvas is rendered at scaled
  // CSS size but its drawing space matches naturalWidth/Height).
  const sx = canvas.width / r.width;
  const sy = canvas.height / r.height;
  return { x: (e.clientX - r.left) * sx, y: (e.clientY - r.top) * sy };
}
function _paStart(e) {
  if (_paIdx < 0) return;
  e.preventDefault();
  const canvas = document.getElementById('pa-canvas');
  if (canvas.setPointerCapture && e.pointerId !== undefined) {
    try {
      canvas.setPointerCapture(e.pointerId);
    } catch (er) {
      /* ignore — some pointer types reject capture */
    }
  }
  const ctx = canvas.getContext('2d');
  const p = _paPos(e);
  ctx.strokeStyle = '#ef4444';
  ctx.lineWidth = _paStrokeWidth;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.beginPath();
  ctx.moveTo(p.x, p.y);
  _paDrawing = true;
}
function _paMove(e) {
  if (!_paDrawing) return;
  e.preventDefault();
  const ctx = document.getElementById('pa-canvas').getContext('2d');
  const p = _paPos(e);
  ctx.lineTo(p.x, p.y);
  ctx.stroke();
}
function _paEnd(e) {
  if (!_paDrawing) return;
  _paDrawing = false;
  e.preventDefault();
}
async function _paDone() {
  if (_paIdx < 0 || !_paImg) {
    closeAnnotate();
    return;
  }
  const canvas = document.getElementById('pa-canvas');
  // Re-encode the annotated full image at the same compression as the
  // original (1280 px long edge, q=0.8) so the photo size budget stays
  // honest and the server-side magic-byte check still sees JPEG.
  const longEdge = Math.max(canvas.width, canvas.height);
  const scale = Math.min(1, 1280 / longEdge);
  const w = Math.max(1, Math.round(canvas.width * scale));
  const h = Math.max(1, Math.round(canvas.height * scale));
  const out = document.createElement('canvas');
  out.width = w;
  out.height = h;
  out.getContext('2d').drawImage(canvas, 0, 0, w, h);
  const dataUrl = await new Promise((resolve) => {
    out.toBlob(
      (blob) => {
        if (!blob) {
          resolve(null);
          return;
        }
        const fr = new FileReader();
        fr.onload = () => resolve(fr.result);
        fr.onerror = () => resolve(null);
        fr.readAsDataURL(blob);
      },
      'image/jpeg',
      0.8
    );
  });
  if (!dataUrl) {
    setFb('err', t('contam.annotateSaveErr'));
    closeAnnotate();
    return;
  }
  // New thumbnail (200 px) from the same annotated canvas.
  const tScale = Math.min(1, 200 / longEdge);
  const tw = Math.max(1, Math.round(canvas.width * tScale));
  const th = Math.max(1, Math.round(canvas.height * tScale));
  const thumb = document.createElement('canvas');
  thumb.width = tw;
  thumb.height = th;
  thumb.getContext('2d').drawImage(canvas, 0, 0, tw, th);
  const thumbUrl = await new Promise((resolve) => {
    thumb.toBlob(
      (blob) => {
        if (!blob) {
          resolve(null);
          return;
        }
        const fr = new FileReader();
        fr.onload = () => resolve(fr.result);
        fr.onerror = () => resolve(null);
        fr.readAsDataURL(blob);
      },
      'image/jpeg',
      0.7
    );
  });
  // Save back to the photo entry. Width/height update to the resized
  // canvas dims so they stay consistent with what the server sees.
  _crPhotos[_paIdx] = {
    data_url: dataUrl,
    thumb_data_url: thumbUrl || _crPhotos[_paIdx].thumb_data_url,
    width: w,
    height: h
  };
  closeAnnotate();
  _renderCrPhotos();
}

// Ein Bericht je Beutel — Typ, Schwere, Fotos und Notiz gelten für alle. Ohne
// gescannten Beutel bleibt der Bericht über die Charge, wie er es immer war.
// Jeder Eintrag bekommt seine eigene report_uuid: die Warteschlange spielt den
// Rumpf unverändert nach, und ohne eigene Kennung fielen die Beutel dabei auf
// einen einzigen Bericht zusammen.
function crReportBags() {
  if (!_crTargets.length) return [{ bag_id: null, batch_id: _crBatchId || null, report_uuid: newScanUuid() }];
  return _crTargets.map((tg) => ({
    bag_id: tg.bag,
    batch_id: tg.batch || _crBatchId || null,
    report_uuid: newScanUuid()
  }));
}

async function _crSubmit() {
  // Alle Beutel wieder aus der Meldung genommen und trotzdem gesendet: ohne
  // Beutel und ohne Charge wäre das ein Bericht über nichts, und niemand könnte
  // ihm hinterher ansehen, worüber er sein sollte.
  if (!_crTargets.length && !_crBatchId && !_crZoneId) {
    setFb('err', t('contam.errNoTarget'));
    return;
  }
  const submitBtn = document.getElementById('cr-submit');
  submitBtn.disabled = true;
  try {
    const bags = crReportBags();
    const body = {
      bags,
      zone_id: _crZoneId,
      type_id: _crSelectedTypeId,
      severity: _crSeverity,
      notes: document.getElementById('cr-notes').value.trim(),
      photos: _crPhotos,
      auto_move: !!document.getElementById('cr-auto-move')?.checked
    };
    const r = await apiPost('/api/contamination-reports', body);
    if (r && r.error) {
      setFb('err', t('contam.errSave', { err: r.error }));
      return;
    }
    closeContamReport();
    if (r && r.queued) {
      // Service worker queued the report because the network was unreachable.
      // The browse list won't have this entry yet — replayed when WiFi returns.
      setFb('warn', t('contam.reportQueued'));
    } else if (bags.length > 1) {
      // Eine ganze Reihe auf einmal: die Nummer eines einzelnen Berichts sagt
      // hier nichts, die Anzahl schon.
      const moved = r.autoMovedCount || 0;
      setFb(
        'ok',
        moved
          ? t('contam.reportsSavedAutoMoved', { n: bags.length, moved: moved })
          : t('contam.reportsSaved', { n: bags.length })
      );
    } else {
      // If the server actually moved the bag to CONTAM, surface that in the
      // toast so the worker isn't surprised by the new scan-log entry.
      const msgKey = r.autoMovedScanId ? 'contam.reportSavedAutoMoved' : 'contam.reportSaved';
      setFb('ok', t(msgKey, { id: r.id, photos: (r.photoIds || []).length }));
      // Refresh browse view if it's the active sub-tab
      if (document.getElementById('sp-lab-contam')?.classList.contains('active')) {
        renderContamReports();
      }
    }
  } catch (e) {
    setFb('err', t('contam.errSave', { err: e.message || 'unknown' }));
  } finally {
    submitBtn.disabled = false;
  }
}

// ─── CONTAMINATION REPORTS — BROWSE / DRILL-DOWN ──────────────
// Lab → Kontaminationen sub-tab. Lists reports as cards, click opens
// the drill-down modal with full-size photos and delete action.
let _clReports = [];
let _cdReportId = null;

function _clTypeName(r) {
  if (currentLang === 'de') return r.name_de;
  if (currentLang === 'pt') return r.name_pt;
  return r.name_en;
}

function _clRelTime(iso) {
  const d = new Date(iso);
  const sec = Math.round((Date.now() - d.getTime()) / 1000);
  if (sec < 60) return t('time.justNow');
  const min = Math.floor(sec / 60);
  if (min < 60) return t('time.minsAgo', { n: min });
  const hr = Math.floor(min / 60);
  if (hr < 24) return t('time.hoursAgo', { n: hr });
  return t('time.daysAgo', { n: Math.floor(hr / 24) });
}

async function _clEnsureTypesLoaded() {
  if (_crTypes && _crTypes.length) return;
  try {
    _crTypes = await apiGet('/api/contamination-types');
  } catch {
    _crTypes = [];
  }
  // Populate the type filter dropdown if it exists
  const sel = document.getElementById('cl-type-filter');
  if (sel && sel.options.length <= 1) {
    for (const tp of _crTypes) {
      const o = document.createElement('option');
      o.value = String(tp.id);
      o.textContent = _clTypeName(tp);
      sel.appendChild(o);
    }
  }
}

async function renderContamReports() {
  await _clEnsureTypesLoaded();
  const list = document.getElementById('contam-list');
  const count = document.getElementById('contam-list-count');
  if (!list) return;
  list.innerHTML = '<div class="empty">' + t('contam.loading') + '</div>';
  const params = new URLSearchParams();
  const typeId = document.getElementById('cl-type-filter')?.value;
  const sev = document.getElementById('cl-sev-filter')?.value;
  const status = document.getElementById('cl-status-filter')?.value;
  const since = document.getElementById('cl-since-filter')?.value;
  if (typeId) params.set('typeId', typeId);
  if (sev) params.set('severity', sev);
  if (status) params.set('status', status);
  if (since) params.set('start', since);
  try {
    _clReports = await apiGet('/api/contamination-reports' + (params.toString() ? '?' + params.toString() : ''));
  } catch (e) {
    list.innerHTML =
      '<div class="empty" style="color:var(--c-red-dark)">' +
      t('contam.errLoad', { err: e.message || 'unknown' }) +
      '</div>';
    return;
  }
  if (!_clReports.length) {
    list.innerHTML = '<div class="empty">' + t('contam.empty') + '</div>';
    count.textContent = '';
    return;
  }
  count.textContent = t('contam.count', { n: _clReports.length });
  list.innerHTML = _clReports
    .map((r) => {
      const sevKey = r.severity === 'major' ? 'sevMajor' : r.severity === 'lost' ? 'sevLost' : 'sevMinor';
      const typeName = esc(_clTypeName(r));
      // first_photo_uuid is included in the list response so we can render a
      // real thumb without a second round-trip. Fall back to a placeholder
      // glyph when the report has no photos at all (rare — usually 1+).
      const thumbHtml = r.first_photo_uuid
        ? `<img src="/api/contamination-reports/${r.id}/photos/${esc(r.first_photo_uuid)}?thumb=1" alt="" loading="lazy">`
        : `<div class="fs-floor" style="--fs-own:1.125rem">—</div>`;
      const target = r.bag_id
        ? `<span class="contam-list-bag">${esc(r.bag_id)}</span><span class="contam-list-batch">${esc(r.batch_id || '')}</span>`
        : `<span class="contam-list-bag">${esc(r.batch_id || '—')}</span>`;
      const notes = r.notes ? `<div class="contam-list-notes">${esc(r.notes)}</div>` : '';
      const resolvedClass = r.resolved_at ? ' is-resolved' : '';
      const resolvedBadge = r.resolved_at
        ? `<span class="contam-resolved-badge">✓ ${esc(t('contam.res.' + r.resolution) || '')}</span>`
        : '';
      return `<div class="contam-list-card${resolvedClass}" data-cl-id="${r.id}">
        <div class="contam-list-thumb">${thumbHtml}</div>
        <div class="contam-list-meta">
          <div class="contam-list-row">${target}<span class="contam-list-when">${esc(_clRelTime(r.reported_at))}</span></div>
          <div class="contam-list-row">
            <span class="contam-type-badge"><span class="dot" style="background:${esc(r.type_color || '#888')}"></span>${typeName}</span>
            <span class="contam-sev-badge sev-${esc(r.severity)}">${esc(t('contam.' + sevKey))}</span>
            ${resolvedBadge}
            ${(r.photo_count || 0) > 0 ? `<span class="fs-xs" style="color:var(--c-text-muted)">${r.photo_count} 📷</span>` : ''}
          </div>
          ${notes}
        </div>
      </div>`;
    })
    .join('');
}

async function openContamDetail(id) {
  _cdReportId = id;
  const body = document.getElementById('cd-body');
  body.innerHTML = '<div class="empty">' + t('contam.loading') + '</div>';
  document.getElementById('m-contam-detail').classList.add('open');
  let r;
  try {
    r = await apiGet('/api/contamination-reports/' + id);
  } catch (e) {
    body.innerHTML =
      '<div class="empty" style="color:var(--c-red-dark)">' +
      t('contam.errLoad', { err: e.message || 'unknown' }) +
      '</div>';
    return;
  }
  const typeName = esc(_clTypeName(r));
  const sevKey = r.severity === 'major' ? 'sevMajor' : r.severity === 'lost' ? 'sevLost' : 'sevMinor';
  const photos = Array.isArray(r.photos) ? r.photos : [];
  const photosHtml = photos.length
    ? `<div class="cd-photos">${photos
        .map(
          (p) =>
            `<a class="cd-photo" href="/api/contamination-reports/${r.id}/photos/${esc(p.uuid)}" target="_blank" rel="noopener"><img src="/api/contamination-reports/${r.id}/photos/${esc(p.uuid)}?thumb=1" alt="" loading="lazy"></a>`
        )
        .join('')}</div>`
    : `<div class="empty" style="margin:8px 0 14px">${t('contam.noPhotos')}</div>`;
  const notesHtml = r.notes ? `<div class="cd-notes">${esc(r.notes)}</div>` : '';
  // Resolution status — when set, show the resolution + when in the metadata
  // grid and offer a Reopen action. When unset, render four resolve-action
  // buttons (Autoclaved / Discarded / Recovered / Other) below the metadata.
  const isResolved = !!r.resolved_at;
  const resolutionLabel = r.resolution ? esc(t('contam.res.' + r.resolution)) : '';
  const statusCell = isResolved
    ? `<div><div class="label">${esc(t('contam.statusLabel'))}</div><div><span class="contam-resolved-badge">✓ ${resolutionLabel}</span><div class="fs-xs" style="color:var(--c-text-muted);margin-top:2px">${esc(fmtDtTime(r.resolved_at))}</div></div></div>`
    : `<div><div class="label">${esc(t('contam.statusLabel'))}</div><div><span class="contam-open-badge">${esc(t('contam.statusOpen'))}</span></div></div>`;
  const resolveActions = isResolved
    ? `<div class="cd-resolve-row"><button id="cd-reopen" type="button" class="btn btn-sm" data-i18n="contam.reopen">Wieder öffnen</button></div>`
    : `<div class="cd-resolve-row">
        <span class="cr-label" style="margin:0 8px 0 0">${esc(t('contam.resolveAs'))}</span>
        <button type="button" class="btn btn-sm" data-cd-resolve="autoclaved" data-i18n="contam.res.autoclaved">Autoklaviert</button>
        <button type="button" class="btn btn-sm" data-cd-resolve="discarded" data-i18n="contam.res.discarded">Entsorgt</button>
        <button type="button" class="btn btn-sm" data-cd-resolve="recovered" data-i18n="contam.res.recovered">Gerettet</button>
        <button type="button" class="btn btn-sm" data-cd-resolve="other" data-i18n="contam.res.other">Sonstiges</button>
      </div>`;
  body.innerHTML = `
    ${photosHtml}
    <div class="cd-meta-grid">
      <div><div class="label">${esc(t('contam.type'))}</div><div><span class="contam-type-badge"><span class="dot" style="background:${esc(r.type_color || '#888')}"></span>${typeName}</span></div></div>
      <div><div class="label">${esc(t('contam.severity'))}</div><div><span class="contam-sev-badge sev-${esc(r.severity)}">${esc(t('contam.' + sevKey))}</span></div></div>
      <div><div class="label">${esc(t('contam.bag'))}</div><div style="font-family:monospace">${esc(r.bag_id || '—')}</div></div>
      <div><div class="label">${esc(t('contam.batch'))}</div><div style="font-family:monospace">${esc(r.batch_id || '—')}</div></div>
      <div><div class="label">${esc(t('contam.reportedBy'))}</div><div>${esc(r.reporter || '—')}</div></div>
      <div><div class="label">${esc(t('contam.reportedAt'))}</div><div>${esc(fmtDtTime(r.reported_at))}</div></div>
      ${statusCell}
    </div>
    ${notesHtml}
    ${resolveActions}
  `;
}

async function _cdResolve(resolution) {
  if (!_cdReportId) return;
  const id = _cdReportId;
  try {
    const r = await apiPatch('/api/contamination-reports/' + id + '/resolve', { resolution });
    if (r && r.error) {
      setFb('err', t('contam.errResolve', { err: r.error }));
      return;
    }
    setFb('ok', t('contam.resolved'));
    await openContamDetail(id); // re-render with resolved state
    renderContamReports();
  } catch (e) {
    setFb('err', t('contam.errResolve', { err: e.message || 'unknown' }));
  }
}

async function _cdReopen() {
  if (!_cdReportId) return;
  const id = _cdReportId;
  try {
    const r = await apiPatch('/api/contamination-reports/' + id + '/resolve', {});
    if (r && r.error) {
      setFb('err', t('contam.errResolve', { err: r.error }));
      return;
    }
    setFb('ok', t('contam.reopened'));
    await openContamDetail(id);
    renderContamReports();
  } catch (e) {
    setFb('err', t('contam.errResolve', { err: e.message || 'unknown' }));
  }
}

function closeContamDetail() {
  document.getElementById('m-contam-detail').classList.remove('open');
  _cdReportId = null;
}

function _cdDelete() {
  if (!_cdReportId) return;
  const id = _cdReportId;
  confirm2(t('contam.confirmDeleteTitle'), t('contam.confirmDeleteBody'), t('contam.delete'), async () => {
    try {
      const r = await apiDelete('/api/contamination-reports/' + id);
      if (r && r.error) {
        setFb('err', t('contam.errDelete', { err: r.error }));
        return;
      }
      setFb('ok', t('contam.deleted'));
      closeContamDetail();
      renderContamReports();
    } catch (e) {
      setFb('err', t('contam.errDelete', { err: e.message || 'unknown' }));
    }
  });
}

// ─── BAG-SELECT MODAL (subset-of-batch move) ─────────────────
// State: which batch we're selecting from, and which bag IDs are chosen.
let bsBatchId = null;
let bsSelected = new Set();

function renderBagSelect() {
  const b = batches.find((x) => x.batchId === bsBatchId);
  if (!b) return;
  document.getElementById('bs-subtitle').textContent = t('bagSelect.subtitle', {
    id: b.batchId,
    n: bsSelected.size,
    total: b.bags.length
  });
  document.getElementById('bs-count').textContent = t('bagSelect.countSelected', { n: bsSelected.size });
  const continueBtn = document.getElementById('bs-continue');
  if (continueBtn) {
    continueBtn.disabled = bsSelected.size === 0;
    continueBtn.style.opacity = bsSelected.size === 0 ? '0.4' : '1';
    continueBtn.style.cursor = bsSelected.size === 0 ? 'not-allowed' : 'pointer';
  }
  const container = document.getElementById('bs-bags');
  container.innerHTML = '';
  b.bags.forEach((bag) => {
    const bagNum = bag.split('-').pop();
    const last = [...scanLog]
      .reverse()
      .find(
        (e) =>
          (e.bag || '').toUpperCase() === bag.toUpperCase() &&
          (e.action === 'ADD' || e.action === 'MOVE' || e.action === 'REMOVE')
      );
    const isRemoved = last && last.action === 'REMOVE';
    const isUnplaced = !last;
    const loc = isUnplaced ? '\u2014' : isRemoved ? '\u2717' : last.to || '?';
    const isSelected = bsSelected.has(bag);
    const disabled = isRemoved || isUnplaced;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.disabled = disabled;
    btn.title = disabled ? (isRemoved ? t('bagInfo.removed') : t('bagInfo.notPlaced')) : loc;
    btn.innerHTML =
      '<div class="fs-floor" style="--fs-own:0.875rem;font-weight:700;font-family:monospace">' +
      esc(bagNum) +
      '</div>' +
      '<div class="fs-micro" style="margin-top:2px;opacity:0.85">' +
      esc(loc) +
      '</div>';
    btn.style.cssText =
      'min-width:56px;padding:8px 10px;border-radius:8px;text-align:center;cursor:' +
      (disabled ? 'not-allowed' : 'pointer') +
      ';opacity:' +
      (disabled ? '0.35' : '1') +
      ';background:' +
      (isSelected ? 'var(--c-blue-dark, #1e6dd8)' : 'var(--c-bg)') +
      ';color:' +
      (isSelected ? '#fff' : 'var(--c-text)') +
      ';border:2px solid ' +
      (isSelected ? 'var(--c-blue-dark, #1e6dd8)' : 'var(--c-border)') +
      ';';
    if (!disabled) {
      btn.addEventListener('click', () => bsToggleBag(bag));
    }
    container.appendChild(btn);
  });
}

// Toggle a bag in the selection (called from clicks and from scans).
// Returns {toggled: true, added: boolean} if the bag belongs to the current batch.
function bsToggleBag(bag) {
  const b = batches.find((x) => x.batchId === bsBatchId);
  if (!b) return { toggled: false };
  const canonical = b.bags.find((x) => x.toUpperCase() === bag.toUpperCase());
  if (!canonical) return { toggled: false };
  const last = [...scanLog]
    .reverse()
    .find(
      (e) =>
        (e.bag || '').toUpperCase() === canonical.toUpperCase() &&
        (e.action === 'ADD' || e.action === 'MOVE' || e.action === 'REMOVE')
    );
  if (!last || last.action === 'REMOVE') return { toggled: false };
  let added;
  if (bsSelected.has(canonical)) {
    bsSelected.delete(canonical);
    added = false;
  } else {
    bsSelected.add(canonical);
    added = true;
  }
  renderBagSelect();
  return { toggled: true, added: added, bag: canonical };
}

function bsConfirm() {
  const b = batches.find((x) => x.batchId === bsBatchId);
  if (!b) return;
  if (bsSelected.size === 0) {
    setFb('err', t('bagSelect.noneSelected'));
    return;
  }
  const selected = Array.from(bsSelected);
  bsClose();
  _openZonePicker(t('bagSelect.moveMenuTitle', { n: selected.length }), function (dest) {
    moveBagsTo(b, selected, dest, function (moved, skipped) {
      if (!moved) {
        if (skipped > 0) {
          setFb('ok', t('batch.allAlreadyAt', { n: skipped, loc: zoneDisplayName(dest) }));
        } else {
          setFb('err', t('batch.noBagsToMove'));
        }
        return;
      }
      setFb(
        'ok',
        b.batchId +
          ': ' +
          moved +
          ' Bags \u2192 ' +
          zoneDisplayName(dest) +
          (skipped ? ' (' + skipped + ' \u00fcbersprungen)' : '')
      );
      scan.count += moved;
      updateSD();
      renderBatches();
    });
  });
}

// Close the bag-select modal AND reset its module-level state so future scans
// don't get misrouted by stale bsBatchId / bsSelected values.
function bsClose() {
  document.getElementById('m-bagselect').classList.remove('open');
  bsBatchId = null;
  bsSelected = new Set();
}

document.getElementById('m-bagselect').addEventListener('click', (e) => {
  if (e.target.id === 'm-bagselect') bsClose();
});

// ─── PRINT — BAG LABELS ──────────────────────────────────────
// ─── PRINT via server → ZPL → Windows spooler → GK420d ──────
// Correct size/orientation automatically — no browser dialog issues.
// Hyphens encoded as underscores in barcode to fix German keyboard scanning.

// Legacy species abbreviation (only used for scanning old barcode labels).
function spAbbrev(species) {
  if (!species) return 'XX';
  const words = species.trim().split(/\s+/);
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
  return (words[0][0] + words[1][0]).toUpperCase();
}
// Calculate Code 128 module width + centered x-offset for ZPL labels.
// Label is 400 dots wide; need 20-dot quiet zone each side → 360 usable dots.
// Code 128 symbol ≈ (35 + chars*11) modules. Use mw=2 if it fits, else mw=1.
// Returns {mw, x} where x centers the barcode horizontally with minimum quiet zones.
// Code 128 quiet zone = 10× module width. Try mw=3, then 2, then 1.
// qzMult: quiet zone multiplier (default 10). Use 5 for lab labels to allow wider bars.
function bcParams(val, qzMult) {
  const mods = 35 + val.length * 11;
  let mw = 3;
  qzMult = qzMult || 10;
  const qz = (m) => m * qzMult;
  while (mw > 1 && mods * mw + 2 * qz(mw) > 400) mw--;
  const w = mods * mw;
  return { mw, x: Math.max(qz(mw), Math.round((400 - w) / 2)) };
}

// ─── Unified label layout: SINGLE SOURCE OF TRUTH for ZPL + preview ───
// Canvas is 400×240 dots (50×30mm @ 203dpi). bagLabelItems/labLabelItems
// describe one label as a plain array of items in that coordinate system;
// itemsToZPL turns them into printer output and buildPreviewCell renders
// the same items as an SVG with viewBox="0 0 400 240". Because both come
// from the same items array the preview cannot drift from what prints.
// Item shapes:
//   {type:'barcode', x, y, w, h, val, mw}
//   {type:'text',    x?, y, blockW?, fontH, fontW?, text, bold?}
//   {type:'qr',      x, y, size, val}

// Sanitize a string for use inside a ZPL ^FD...^FS field.
// ^ starts ZPL commands and ~ starts ZPL control sequences — both must be removed
// so user-supplied text (species names, notes, IDs) cannot inject ZPL commands.
function zplText(s) {
  return String(s || '').replace(/[\^~]/g, '');
}

function itemsToZPL(items) {
  // Label size from server config (LABEL_WIDTH_DOTS / LABEL_HEIGHT_DOTS env).
  // Default 400×240 dots = 50×30mm at 203dpi. Field positions in the
  // callers assume 400 dots wide; significantly different sizes need
  // their own layout.
  // ^LT0/^LS0 reset stored offsets, ^PON/^FWN force normal orientation.
  let z = '^XA^PW' + labelDims.widthDots + '^LL' + labelDims.heightDots + '^CI28^LH0,0^LT0^LS0^PON^FWN';
  for (const it of items) {
    if (it.type === 'barcode') {
      z +=
        '^FO' +
        it.x +
        ',' +
        it.y +
        '^BY' +
        it.mw +
        ',2.0,' +
        it.h +
        '^BCN,' +
        it.h +
        ',N,N,N^FD' +
        zplText(it.val) +
        '^FS';
    } else if (it.type === 'text') {
      const fw = it.fontW || it.fontH;
      const bw = it.blockW || 400;
      const bx = it.x || 0;
      z +=
        '^FO' + bx + ',' + it.y + '^FB' + bw + ',1,0,C^A0N,' + it.fontH + ',' + fw + '^FD' + zplText(it.text) + '^FS';
      // ZPL has no bold flag; double-draw at x+1 thickens strokes.
      if (it.bold)
        z +=
          '^FO' +
          (bx + 1) +
          ',' +
          it.y +
          '^FB' +
          bw +
          ',1,0,C^A0N,' +
          it.fontH +
          ',' +
          fw +
          '^FD' +
          zplText(it.text) +
          '^FS';
    } else if (it.type === 'qr') {
      // Reset label home immediately before QR to ensure ^FO works from true origin.
      z += '^LH0,0^FO' + it.x + ',' + it.y + '^BQN,2,' + (it.mag || 4) + '^FDMA,' + zplText(it.val) + '^FS';
    }
  }
  return z + '^XZ';
}

// Builds one preview cell as an SVG. Returns {cell, deferred} — insert cell
// into the DOM first, then call renderPreviewDeferred(deferred) to attach
// JsBarcode/QRCode content to the live nodes.
function buildPreviewCell(items) {
  const cell = document.createElement('div');
  cell.style.cssText =
    'position:relative;border:1px solid var(--c-border);border-radius:5px;background:#fff;overflow:hidden;aspect-ratio:5/3';
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 400 240');
  svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  svg.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;display:block';
  cell.appendChild(svg);
  const deferred = [];
  for (const it of items) {
    if (it.type === 'barcode') {
      const inner = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      inner.setAttribute('x', it.x);
      inner.setAttribute('y', it.y);
      inner.setAttribute('width', it.w);
      inner.setAttribute('height', it.h);
      svg.appendChild(inner);
      deferred.push({ kind: 'bc', el: inner, val: it.val, mw: it.mw, w: it.w, h: it.h });
    } else if (it.type === 'text') {
      const bw = it.blockW || 400;
      const cx = (it.x || 0) + bw / 2;
      // ZPL A0 font height ≈ character height; baseline ≈ 82% from top.
      const by = it.y + it.fontH * 0.82;
      const t = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      t.setAttribute('x', cx);
      t.setAttribute('y', by);
      t.setAttribute('text-anchor', 'middle');
      t.setAttribute('font-family', 'Helvetica,Arial,sans-serif');
      t.setAttribute('font-size', it.fontH);
      t.setAttribute('fill', '#000');
      if (it.bold) t.setAttribute('font-weight', 'bold');
      t.textContent = it.text;
      svg.appendChild(t);
    } else if (it.type === 'qr') {
      // QR as HTML overlay positioned with % from ZPL coords (qrcode.js → img/canvas).
      const qrDiv = document.createElement('div');
      const L = ((it.x / 400) * 100).toFixed(2);
      const T = ((it.y / 240) * 100).toFixed(2);
      const W = ((it.size / 400) * 100).toFixed(2);
      qrDiv.style.cssText =
        'position:absolute;left:' + L + '%;top:' + T + '%;width:' + W + '%;aspect-ratio:1;background:#fff';
      cell.appendChild(qrDiv);
      deferred.push({ kind: 'qr', el: qrDiv, val: it.val });
    }
  }
  return { cell, deferred };
}

function renderPreviewDeferred(deferred, baseDelay) {
  baseDelay = baseDelay || 20;
  // P-02: JsBarcode + QRCode are lazy-loaded. Wait for them before rendering
  // any deferred items. The setTimeout chain that staggered rendering is
  // preserved; we just delay the whole chain until the libs land.
  if (typeof JsBarcode === 'undefined' || typeof QRCode === 'undefined') {
    loadVendorLibs().then(() => renderPreviewDeferred(deferred, baseDelay));
    return;
  }
  deferred.forEach((d, i) => {
    setTimeout(
      () => {
        if (d.kind === 'bc') {
          try {
            JsBarcode(d.el, d.val, {
              format: 'CODE128',
              width: d.mw,
              height: d.h,
              displayValue: false,
              margin: 0,
              background: '#fff',
              lineColor: '#000'
            });
            // JsBarcode rewrites width/height on the svg; capture those as a
            // viewBox and restore our (x,y,w,h) so bars stretch to our cell.
            const w = parseFloat(d.el.getAttribute('width')) || d.w;
            const h = parseFloat(d.el.getAttribute('height')) || d.h;
            d.el.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
            d.el.setAttribute('width', d.w);
            d.el.setAttribute('height', d.h);
            d.el.setAttribute('preserveAspectRatio', 'none');
          } catch {}
        } else if (d.kind === 'qr') {
          try {
            new QRCode(d.el, {
              text: d.val,
              width: 64,
              height: 64,
              colorDark: '#000',
              colorLight: '#fff',
              correctLevel: QRCode.CorrectLevel.L
            });
            const img = d.el.querySelector('img') || d.el.querySelector('canvas');
            if (img) {
              img.style.cssText = 'display:block;width:100%;height:100%';
            }
          } catch {}
        }
      },
      baseDelay + i * 12
    );
  });
}

// detail levels for bag labels:
//   'minimal' — barcode + Line 1 (bag ID) only
//   'sorte'   — + Line 2 (Pilzsorte written out + notes)
//   'full'    — + Line 3 (Fälligkeit)
// No label carries a spelled-out type word. The only band one fitted in was the
// top edge, which this stock clips, and every ID already opens with its type
// (MC-/PD-/LC-/G-) — so it cost a row and told nobody anything.
// Batch size in the bottom-right corner. Which bag this is was already on the
// label — it is the ID's last segment — so only the total was missing: move 9
// of 10 and nothing said one was still out there. Set apart in its own corner
// rather than folded into a line of text, so it reads at arm's length.
// The slash is deliberate: a bare "10" next to bag …-06 invites being read as
// the bag number. "/10" cannot be.
const _BADGE = { w: 72, h: 30 };
function _bagTotalBadge(batch) {
  const total = (batch.bags || []).length;
  if (!total) return null;
  const x = 400 - _BADGE.w - 6; // 322
  const y = 240 - _BADGE.h - 8; // 202 → occupies 202..232
  return {
    x,
    y,
    h: _BADGE.h,
    items: [{ type: 'text', x, y, blockW: _BADGE.w, fontH: 28, text: '/' + total, bold: true }]
  };
}
// Width a centred text line may use. The bottom-right badge sits over the band
// the last line(s) occupy, so any line overlapping it vertically is narrowed to
// stop short — the text re-centres in the space left rather than running under
// the box. Lines clear of the badge keep the full width they always had.
function _lineBlockW(y, fontH, badge) {
  return badge && y < badge.y + badge.h && badge.y < y + fontH ? badge.x - 6 : 400;
}
// ─── Jede Zeile passt ────────────────────────────────────────
// Ein Textfeld auf dem Etikett ist ein ^FB-Block für eine Zeile, und der
// schneidet nichts ab: was nicht hineinpasst, bricht der Drucker um und druckt
// es ÜBER die Zeile. So stand der Stammcode mitten auf "Ganoderma", weil
// "Reishi – 2,0kg – Ganoderma multipileum KQ07" für eine Zeile zu lang war.
// Deshalb geht keine Zeile mehr zum Drucker, die nicht passt: sie wird hier
// gemessen, und was zu lang ist, kommt in die zweite Zeile. Eine Nummer wird
// stattdessen kleiner geschrieben, die liest man in einem Stück.
//
// Die Breiten sind die von Helvetica Bold, in Tausendsteln der Schriftbreite.
// Schrift 0 des Druckers (CG Triumvirate Bold Condensed), an diesem Etikett
// nachgemessen, ist bei Großbuchstaben so breit, bei Ziffern und
// Kleinbuchstaben schmaler; nur den Bindestrich zieht sie breiter, er steht mit
// 600. Dazu 5 % Luft in labelTextW(): was hier passt, passt auf dem Etikett.
// Ein Zeichen, das nicht in der Liste steht, zählt ganz breit.
//
// Dieser Block steht wortgleich in app.js und in mcp-server.js, die beide
// Etiketten drucken; test/etiketten-zeilen.test.js hält die zwei gleich.
const _LABEL_EM = [
  [" \u00a0,./\\|ijlI'\u00b7", 278],
  ['!():;[]ft', 333],
  ['r*{}', 389],
  ['z', 500],
  ['0123456789acekvsxyJ_#$"', 556],
  ['+<=>~', 584],
  ['-', 600],
  ['bdghnopquFLTZ?\u00df', 611],
  ['EPSVXY', 667],
  ['ABCDHKNRU&', 722],
  ['GOQw', 778],
  ['M', 833],
  ['m%', 889],
  ['W', 944],
  ['@', 975]
];
let _labelEmMap = null;
function labelTextW(text, fontW) {
  if (!_labelEmMap) {
    _labelEmMap = new Map();
    for (const [zeichen, breite] of _LABEL_EM) for (const c of zeichen) _labelEmMap.set(c, breite);
  }
  let em = 0;
  // Umlaute und Akzente zählen wie ihr Grundbuchstabe: ä wie a.
  for (const c of String(text)) em += _labelEmMap.get(c) || _labelEmMap.get(c.normalize('NFD')[0]) || 1000;
  return (em * fontW * 1.05) / 1000;
}
// Zeichen, die Schrift 0 nicht hat. Der Gedankenstrich zwischen "Reishi" und
// "2,0kg" kam auf demselben Etikett gar nicht erst heraus, an seiner Stelle
// stand eine Lücke. Ersetzt wird im Text der Zeile selbst und nicht erst beim
// Drucken: so misst labelTextW(), was gedruckt wird, und die Vorschau zeigt es.
const _LABEL_ERSATZ = {
  '\u2013': '-',
  '\u2014': '-',
  '\u2026': '...',
  '\u2190': '<-',
  '\u2192': '->',
  '\u2018': "'",
  '\u2019': "'",
  '\u201a': "'",
  '\u201c': '"',
  '\u201d': '"',
  '\u201e': '"'
};
function labelGlyphs(s) {
  return String(s || '').replace(
    /[\u2013\u2014\u2026\u2190\u2192\u2018-\u201a\u201c-\u201e]/g,
    (c) => _LABEL_ERSATZ[c]
  );
}
// Bricht `text` in höchstens `maxZeilen` Zeilen, keine breiter als `breite(i)`
// — wieviel Platz eine Zeile hat, hängt davon ab, wo sie steht, neben dem
// Zähler unten rechts ist es weniger. Umbrochen wird an Leerzeichen, ein Wort,
// das allein zu lang ist, hinter seinem letzten Bindestrich, der noch passt.
// Bleibt dann noch etwas übrig, endet die letzte Zeile mit "...", und das
// Ergebnis trägt `gekuerzt`.
//
// Der Gedankenstrich zwischen zwei Angaben steht nie am Anfang oder Ende einer
// Zeile, dort trennt schon der Umbruch. Ein geschütztes Leerzeichen hält
// zusammen, was zusammengehört ("<- PD-…"), und wird gedruckt wie ein normales.
function labelWrap(text, fontW, breite, maxZeilen) {
  const w = (s) => labelTextW(s, fontW);
  const rest = String(text || '')
    .split(' ')
    .filter(Boolean)
    .map((s) => ({ s: labelGlyphs(s).replace(/\u00a0/g, ' '), trenner: s === '\u2013' }));
  const alsZeile = (toks) => {
    let a = 0;
    let e = toks.length;
    while (a < e && toks[a].trenner) a++;
    while (e > a && toks[e - 1].trenner) e--;
    return toks
      .slice(a, e)
      .map((x) => x.s)
      .join(' ');
  };
  const zeilen = [];
  while (zeilen.length < maxZeilen) {
    while (rest.length && rest[0].trenner) rest.shift();
    if (!rest.length) break;
    const max = breite(zeilen.length);
    const toks = [];
    while (rest.length && w(alsZeile(toks.concat(rest[0]))) <= max) toks.push(rest.shift());
    if (!toks.length) {
      // Schon das erste Wort allein ist zu breit für die Zeile.
      const wort = rest[0].s;
      let n = Math.max(1, wort.length - 1);
      while (n > 1 && w(wort.slice(0, n)) > max) n--;
      const strich = wort.lastIndexOf('-', n - 1);
      if (strich > 0) n = strich + 1;
      toks.push({ s: wort.slice(0, n), trenner: false });
      if (n < wort.length) rest[0] = { s: wort.slice(n), trenner: false };
      else rest.shift();
    }
    zeilen.push(alsZeile(toks));
  }
  while (rest.length && rest[0].trenner) rest.shift();
  if (rest.length && zeilen.length) {
    // Lieber ein ganzes Wort weglassen als eines anschneiden. Angeschnitten wird
    // nur, was allein in der Zeile steht.
    const max = breite(zeilen.length - 1);
    const woerter = zeilen[zeilen.length - 1].split(' ');
    while (woerter.length > 1 && w(woerter.join(' ') + '...') > max) woerter.pop();
    let letzte = woerter.join(' ');
    while (letzte && w(letzte + '...') > max) letzte = letzte.slice(0, -1);
    zeilen[zeilen.length - 1] = letzte.replace(/[\s-]+$/, '') + '...';
    zeilen.gekuerzt = true;
  }
  return zeilen;
}
// Setzt Absätze untereinander, ab `y`. Ein Absatz ist { text, fontH, bold,
// maxZeilen, minH, kuerzbar }. Jede Zeile bekommt die Breite, die auf ihrer
// Höhe frei ist, und steht 4 Punkte unter der vorigen — die Abstände, die das
// Etikett immer hatte. Zurück kommen die Zeilen und die Unterkante der letzten.
//
// Mit minH ist der Absatz eine Nummer, und die liest man am besten in einem
// Stück: sie wird erst kleiner, bis minH, solange sie dann in eine Zeile
// passt. Passt sie auch so nicht, bekommt sie die größte Schrift, in der sie
// in ihren Zeilen ganz dasteht — umbrochen, aber nicht auch noch winzig.
function labelLines(absaetze, y, badge) {
  const items = [];
  let unten = y;
  for (const a of absaetze) {
    if (!a.text) continue;
    const setze = (h) => {
      const zeileY = (i) => y + i * (h + 4);
      const breite = (i) => _lineBlockW(zeileY(i), h, badge);
      const max = a.maxZeilen === undefined ? 1 : a.maxZeilen;
      return { h, zeileY, breite, zeilen: labelWrap(a.text, h, (i) => breite(i) - 6, max) };
    };
    let satz = null;
    if (a.minH) {
      const groessen = [];
      for (let h = a.fontH; h >= a.minH; h -= 2) groessen.push(h);
      const versuche = groessen.map(setze);
      satz =
        versuche.find((s) => s.zeilen.length === 1 && !s.zeilen.gekuerzt) ||
        versuche.find((s) => !s.zeilen.gekuerzt) ||
        versuche[versuche.length - 1];
    } else {
      satz = setze(a.fontH);
    }
    satz.zeilen.forEach((text, i) => {
      const item = { type: 'text', y: satz.zeileY(i), blockW: satz.breite(i), fontH: satz.h, text: text };
      if (a.bold) item.bold = true;
      items.push(item);
    });
    if (satz.zeilen.length) {
      unten = satz.zeileY(satz.zeilen.length - 1) + satz.h;
      y = unten + 4;
    }
  }
  return { items: items, unten: unten };
}
// Tiefer als die Unterkante des Zählers unten rechts (232) steht kein Text.
const LABEL_UNTEN = 234;
// Code und Zeilen zu einem Etikett. Passt der Text nicht unter den Code, wird
// ein kürzbarer Absatz — die Angaben zur Sorte — eine Zeile kürzer, und seine
// letzte endet mit "...". Reicht auch eine Zeile nicht (unter einem QR, neben
// einer Kultur mit langer Herkunft), fällt er ganz weg. Die Nummer und das
// Datum kürzt nichts.
function labelLayout(bcVal, qr, absaetze, badge) {
  let liste = absaetze;
  for (;;) {
    const versuch = qr ? _labelQr(bcVal, liste, badge) : _labelBarcode(bcVal, liste, badge);
    const i = liste.findIndex((a) => a.kuerzbar && a.maxZeilen > 0);
    if (versuch.passt || i < 0) return versuch.items;
    liste = liste.map((a, j) => (j === i ? Object.assign({}, a, { maxZeilen: a.maxZeilen - 1 }) : a));
  }
}
// Strichcode oben, die Zeilen darunter, das Ganze senkrecht mittig, aber nie
// über y=40: darüber schneidet dieses Material ab. Braucht der Text mehr Platz,
// als unter einem 90 Punkte hohen Code frei ist, gibt der Code Höhe ab, in
// Schritten bis 60 — 7,5 mm liest jede Kamera noch.
function _labelBarcode(bcVal, absaetze, badge) {
  const bc = bcParams(bcVal);
  const hoehe = labelLines(absaetze, 0, null).unten;
  let versuch = null;
  for (let bcH = 90; bcH >= 60; bcH -= 6) {
    const bcY = Math.max(40, Math.round((240 - (bcH + 6 + hoehe)) / 2));
    const text = labelLines(absaetze, bcY + bcH + 6, badge);
    const code = { type: 'barcode', x: bc.x, y: bcY, w: 400 - 2 * bc.x, h: bcH, val: bcVal, mw: bc.mw };
    versuch = { passt: text.unten <= LABEL_UNTEN, items: [code].concat(text.items) };
    if (versuch.passt) break;
  }
  return versuch;
}
// QR oben links, mag 5 → 125 Punkte (25 Module), die Zeilen darunter über die
// ganze Breite.
function _labelQr(bcVal, absaetze, badge) {
  const text = labelLines(absaetze, 155, badge);
  const code = { type: 'qr', x: 0, y: 10, size: 125, mag: 5, val: bcVal };
  return { passt: text.unten <= 240, items: [code].concat(text.items) };
}
// Was auf dem Beutel steht, wenn man sein Gewicht draufschreibt: 1 → "1kg",
// 2.5 → "2,5kg". Der Punkt ist eine Programmiersprache, das Etikett liest ein
// Mensch in einer deutschen Halle.
function labelKg(kg) {
  return String(Math.round(kg * 1000) / 1000).replace('.', ',') + 'kg';
}
// Das Gewicht EINES Beutels, so wie das Etikett es braucht.
//
// bagWeights kommt aus db.js und ist immer gefüllt (bag_kg der Zeile, sonst das
// der Charge). Vorher wurde es nur weitergereicht, wenn eine Charge GEMISCHTE
// Größen trug — die Idee war, nichts zu drucken, was ohnehin für alle gilt. Nur
// steht der Beutel später allein im Regal, und dann gilt für ihn gar nichts
// mehr: 1 kg und 2 kg Körnerbrut sind zwei verschiedene Dinge, und welches man
// in der Hand hält, sagte das Etikett nur in der einen Hälfte der Fälle.
function bagLabelKg(batch, bagId) {
  const w = batch && batch.bagWeights ? batch.bagWeights[bagId] : null;
  if (Number.isFinite(w) && w > 0) return w;
  return Number.isFinite(batch && batch.bagKg) && batch.bagKg > 0 ? batch.bagKg : null;
}
function bagLabelItems(bagId, batch, detail, _legacyFallbackIds, qr, bagKg) {
  // Numeric barcode: lookup from barcode registry, fall back to legacy encoding
  const numBc = barcodeByEntity.get('bag:' + bagId);
  let bcVal;
  if (numBc) {
    bcVal = String(numBc);
  } else {
    // Legacy fallback for bags without barcode assignment
    if (_legacyFallbackIds) _legacyFallbackIds.push(bagId);
    const isGrain = batch.batchType === 'grain';
    const parts = bagId.split('-');
    if (parts.length === 4) {
      const kz = (batch.strainKuerzel || batch.strain || 'BAGX').toUpperCase();
      const mmdd = parts[1].slice(2, 4) + parts[1].slice(0, 2);
      const bagNum = parseInt(parts[3], 10);
      bcVal = (isGrain ? 'G' : '') + kz + '_' + mmdd + '_' + bagNum;
    } else {
      bcVal = bagId.replace(/-/g, '_');
    }
  }
  // Bag labels carry no type word. Grainspawn had one, but the ID already opens
  // with G- and the top of the label is where this printer clips, so it cost a
  // line and printed cut off. Cultures keep theirs (see labLabelItems).
  const _badge = _bagTotalBadge(batch);
  const items = _badge ? _badge.items.slice() : [];
  // Von oben nach unten: die Nummer des Beutels — lieber kleiner als
  // umbrochen, sie muss ganz dastehen —, die Angaben zur Sorte, bis zwei
  // Zeilen, und bei "Vollständig" die Daten. Wo was steht, rechnet
  // labelLayout() aus: QR oben links und der Text darunter, oder der
  // Strichcode oben und alles senkrecht mittig.
  const absaetze = [{ text: bagId, fontH: qr ? 28 : 24, minH: 18, maxZeilen: 2 }];
  if (detail === 'sorte' || detail === 'full') {
    const species = batch.strainName || batch.species || '';
    const strainTxt = (batch.strainText || '').trim();
    const rawNotes = (batch.notes || '').trim();
    const notes = rawNotes.length > 13 ? rawNotes.slice(0, 13) + '\u2026' : rawNotes;
    const parts = [species];
    if (bagKg != null) parts.push(labelKg(bagKg));
    if (strainTxt) parts.push(strainTxt);
    if (notes) parts.push(notes);
    absaetze.push({ text: parts.filter(Boolean).join(' \u2013 '), fontH: 24, maxZeilen: 2, kuerzbar: true });
  }
  if (detail === 'full' && batch.due) {
    const daten = (batch.created ? fmtDt(batch.created) + ' - ' : '') + fmtDt(batch.due);
    absaetze.push({ text: daten, fontH: qr ? 24 : 28, minH: 18, bold: true });
  }
  return items.concat(labelLayout(bcVal, qr, absaetze, _badge));
}

function labLabelItems(id, c, detail, qr) {
  // Build info line matching batch label pattern: strainName – strainText – notes(13)
  const species = c.strainName || c.species || '';
  const strainTxt = (c.strainText || '').trim();
  const rawNotes = (c.notes || '').trim();
  const notes = rawNotes.length > 13 ? rawNotes.slice(0, 13) + '\u2026' : rawNotes;
  const spParts = [species];
  // Die Größe gleich hinter der Sorte: beim Packen ist sie, was man sucht.
  if (c.type === 'SY') spParts.push(syMl(c) + ' ml');
  if (strainTxt) spParts.push(strainTxt);
  if (notes) spParts.push(notes);
  // Numeric barcode: lookup from registry, fall back to legacy encoding
  const numBc = barcodeByEntity.get('culture:' + id);
  const bcVal = numBc ? String(numBc) : id.replace(/-/g, '_');
  // No type word: the ID already opens with MC-/PD-/LC-, and the only place one
  // fitted was the top edge, which this label stock clips.
  //
  // Die Herkunft hängt mit einem geschützten Leerzeichen an ihrem Pfeil: muss
  // die erste Zeile umbrechen, steht "<- PD-…" zusammen in der zweiten.
  const absaetze = [
    { text: c.parentId ? id + ' \u2190\u00a0' + c.parentId : id, fontH: qr ? 28 : 24, minH: 18, maxZeilen: 2 }
  ];
  if (detail === 'sorte' || detail === 'full') {
    absaetze.push({ text: spParts.filter(Boolean).join(' \u2013 '), fontH: 24, maxZeilen: 2, kuerzbar: true });
  }
  if (detail === 'full' && c.created) {
    absaetze.push({ text: fmtDt(c.created), fontH: qr ? 24 : 28, minH: 18, bold: true });
  }
  return labelLayout(bcVal, qr, absaetze, null);
}

// Vor dem Drucken: kennt dieses Telefon für einen Beutel die siebenstellige
// Nummer nicht, erst den Stand vom Server holen. Der Server vergibt sie beim
// Anlegen jedem Beutel; fehlt sie hier, ist nur die Liste auf dem Telefon alt
// (das Nachladen nach dem Anlegen kann still scheitern). Ohne diesen Schritt
// ging das Etikett mit dem alten Text-Strichcode hinaus, und der fand den
// Beutel beim Scannen nicht wieder.
async function ensureBagBarcodes(bags) {
  if ((bags || []).every((id) => barcodeByEntity.has('bag:' + id))) return;
  await loadData();
}

function makeBagZPL(bags, batch, detail, qr) {
  const legacyFallbackIds = [];
  const zpl = bags
    .map((bagId) =>
      itemsToZPL(bagLabelItems(bagId, batch, detail, legacyFallbackIds, qr, bagLabelKg(batch, bagId)))
    )
    .join('\n');
  if (legacyFallbackIds.length) {
    console.warn('makeBagZPL: numeric barcodes not found for bags, used legacy fallback:', legacyFallbackIds);
    toast(t('print.warnNumericBarcodes', { list: legacyFallbackIds.join(', ') }), 'err');
  }
  return zpl;
}

function makeLabZPL(ids, detail, qr) {
  return ids
    .map((id) => {
      const c = cultures.find((x) => x.id === id);
      return c ? itemsToZPL(labLabelItems(id, c, detail, qr)) : '';
    })
    .filter(Boolean)
    .join('\n');
}

function toggleBagRange() {
  document.getElementById('bag-range-inputs').style.display =
    document.getElementById('print-range').value === 'range' ? 'inline-flex' : 'none';
}

async function printBagLabels() {
  const b = batches.find((x) => x.batchId === document.getElementById('print-batch').value);
  if (!b) {
    toast(t('print.selectBatchFirst'), 'err');
    return;
  }
  let bags = b.bags;
  if (document.getElementById('print-range').value === 'range') {
    const from = parseInt(document.getElementById('bag-from').value) || 1;
    const to = parseInt(document.getElementById('bag-to').value) || b.bags.length;
    bags = b.bags.filter((bagId) => {
      const n = parseInt(bagId.split('-').pop());
      return n >= from && n <= to;
    });
    if (!bags.length) {
      toast(t('print.noBagsInRange'), 'err');
      return;
    }
  }
  await ensureBagBarcodes(bags);
  const zpl = makeBagZPL(
    bags,
    b,
    document.getElementById('print-mode').value,
    document.getElementById('bag-qr').checked
  );
  if (!zpl || !zpl.includes('^XA')) {
    toast(t('print.noLabels'), 'err');
    return;
  }
  const err = await sendToPrinter(zpl);
  if (err) {
    const blob = new Blob([zpl], { type: 'text/plain' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = b.batchId + '_labels.zpl';
    a.click();
  } else {
    // Stand als englischer Satz im Code, in einer App, die drei Sprachen
    // spricht — und es ist dieselbe Meldung, die der andere Beutel-Druckweg
    // längst übersetzt ausgibt.
    printedFb(t('print.printedBatch', { n: bags.length, id: b.batchId }));
  }
}

async function printLabLabels() {
  const ids = [...selectedLabIds];
  if (!ids.length) {
    toast(t('print.selectCulture'), 'err');
    return;
  }
  const zpl = makeLabZPL(ids, document.getElementById('lab-mode').value, document.getElementById('lab-qr').checked);
  if (!zpl || !zpl.includes('^XA')) {
    toast(t('print.noLabels'), 'err');
    return;
  }
  const err = await sendToPrinter(zpl);
  if (err) {
    const blob = new Blob([zpl], { type: 'text/plain' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'lab_labels.zpl';
    a.click();
  } else {
    printedFb(t('print.printedLab', { n: ids.length }));
  }
}

async function quickPrintCulture(id) {
  const zpl = makeLabZPL([id], 'full', false);
  const err = await sendToPrinter(zpl);
  if (err) {
    // fallback: download ZPL
    const blob = new Blob([zpl], { type: 'text/plain' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = id + '_label.zpl';
    a.click();
  }
}

async function sendToPrinter(zpl) {
  try {
    const r = await authFetch('/api/print', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ zpl })
    });
    const d = await r.json();
    if (d.ok) return null;
    refreshPrinterStatus();
    return d.error || 'Print failed';
  } catch (e) {
    refreshPrinterStatus();
    return 'Could not reach server: ' + e.message;
  }
}

// Reflect /api/printer-status into the Print-tab status banner. Called when
// the page is opened, when the banner is clicked, and after each print
// attempt so the user sees if the bridge / printer state changed.
const PRINTER_STATUS_STYLES = {
  online: {
    key: 'print.status.online',
    bg: 'var(--c-primary-light)',
    border: 'var(--c-green-border)',
    color: 'var(--c-green-dark)'
  },
  printer_offline: { key: 'print.status.printerOffline', bg: '#fef3c7', border: '#fbbf24', color: '#92400e' },
  bridge_unreachable: { key: 'print.status.bridgeUnreachable', bg: '#fee2e2', border: '#fca5a5', color: '#991b1b' },
  no_bridge: { key: 'print.status.noBridge', bg: '#dbeafe', border: '#93c5fd', color: '#1e40af' },
  local_unavailable: { key: 'print.status.localUnavailable', bg: '#fee2e2', border: '#fca5a5', color: '#991b1b' }
};
async function refreshPrinterStatus() {
  const banner = document.getElementById('printer-status-banner');
  const text = document.getElementById('printer-status-text');
  const detail = document.getElementById('printer-status-detail');
  if (!banner || !text) return;
  let payload;
  try {
    const r = await authFetch('/api/printer-status');
    payload = await r.json();
  } catch (e) {
    text.textContent = t('print.status.checkFailed');
    if (detail) detail.textContent = e.message || '';
    return;
  }
  const style = PRINTER_STATUS_STYLES[payload.state] || PRINTER_STATUS_STYLES.printer_offline;
  banner.style.background = style.bg;
  banner.style.borderColor = style.border;
  text.style.color = style.color;
  text.textContent = t(style.key, { name: payload.name || '' });
  if (detail) detail.textContent = payload.error || '';
}

// ── Settings → Drucker tab ──────────────────────────────────────────────
async function renderPrinterSettings() {
  const platformEl = document.getElementById('printer-cfg-platform');
  const nameEl = document.getElementById('printer-cfg-printername');
  const sourceEl = document.getElementById('printer-cfg-source');
  const enabledEl = document.getElementById('printer-bridge-enabled');
  const urlEl = document.getElementById('printer-bridge-url');
  const tokenEl = document.getElementById('printer-bridge-token');
  if (!platformEl) return;
  let cfg;
  try {
    const r = await authFetch('/api/printer/config');
    cfg = await r.json();
  } catch (e) {
    setPrinterCfgStatus('error', e.message || 'Failed to load printer config');
    return;
  }
  platformEl.textContent = cfg.platform || '—';
  nameEl.textContent = cfg.printerName || '—';
  const sourceKey =
    cfg.bridge.effectiveSource === 'db'
      ? 'printer.sourceDb'
      : cfg.bridge.effectiveSource === 'env'
        ? 'printer.sourceEnv'
        : 'printer.sourceNone';
  sourceEl.textContent = t(sourceKey);
  enabledEl.checked = !!cfg.bridge.enabled;
  urlEl.value = cfg.bridge.url || '';
  tokenEl.value = '';
  tokenEl.placeholder = cfg.bridge.hasToken ? '••••• ' + t('printer.tokenPlaceholder') : t('printer.tokenPlaceholder');
}

function setPrinterCfgStatus(kind, msg) {
  const el = document.getElementById('printer-cfg-status');
  if (!el) return;
  el.style.display = msg ? 'block' : 'none';
  el.textContent = msg || '';
  if (kind === 'ok') {
    el.style.background = 'var(--c-primary-light)';
    el.style.color = 'var(--c-green-dark)';
    el.style.border = '1px solid var(--c-green-border)';
  } else if (kind === 'error') {
    el.style.background = '#fee2e2';
    el.style.color = '#991b1b';
    el.style.border = '1px solid #fca5a5';
  }
}

async function savePrinterSettings() {
  const enabled = document.getElementById('printer-bridge-enabled').checked;
  const url = document.getElementById('printer-bridge-url').value.trim();
  const tokenInput = document.getElementById('printer-bridge-token').value;
  const body = { enabled, url };
  // Only send token field if user typed something — otherwise the server
  // would clear the existing token.
  if (tokenInput.length > 0) body.token = tokenInput;
  try {
    const r = await authFetch('/api/printer/config', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    if (!r.ok) {
      const err = await r.json().catch(() => ({}));
      setPrinterCfgStatus('error', err.error || 'Save failed');
      return;
    }
    setPrinterCfgStatus('ok', t('printer.saved'));
    await renderPrinterSettings();
    refreshPrinterStatus();
  } catch (e) {
    setPrinterCfgStatus('error', e.message);
  }
}

async function testPrintBridge() {
  setPrinterCfgStatus('', '');
  try {
    const r = await authFetch('/api/printer/test', { method: 'POST' });
    const d = await r.json();
    if (r.ok && d.ok) {
      setPrinterCfgStatus('ok', t('printer.testOk'));
    } else {
      setPrinterCfgStatus('error', t('printer.testFail', { err: d.error || 'Unknown error' }));
    }
    refreshPrinterStatus();
  } catch (e) {
    setPrinterCfgStatus('error', t('printer.testFail', { err: e.message }));
  }
}

async function downloadBridgeScript() {
  try {
    const r = await authFetch('/api/printer/bridge-script');
    if (!r.ok) {
      const err = await r.json().catch(() => ({}));
      setPrinterCfgStatus('error', t('printer.downloadFailed', { err: err.error || 'HTTP ' + r.status }));
      return;
    }
    const text = await r.text();
    const blob = new Blob([text], { type: 'text/plain' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'print-bridge.ps1';
    a.click();
    URL.revokeObjectURL(a.href);
  } catch (e) {
    setPrinterCfgStatus('error', t('printer.downloadFailed', { err: e.message }));
  }
}

function copyToClipboardWithFeedback(text, btn) {
  const restore = btn.textContent;
  navigator.clipboard
    .writeText(text)
    .then(() => {
      btn.textContent = t('printer.copied');
      setTimeout(() => {
        btn.textContent = restore;
      }, 1200);
    })
    .catch(() => {
      btn.textContent = '!';
      setTimeout(() => {
        btn.textContent = restore;
      }, 1200);
    });
}

function batchOptionLabel(b) {
  const kz = b.strainKuerzel || b.strain || '';
  const name = b.strainName || b.species || '';
  const st = (b.strainText || '').trim();
  return (kz ? '[' + esc(kz) + '] ' : '') + esc(b.batchId) + ' — ' + esc(name) + (st ? ' ' + esc(st) : '');
}
function fillBatchSelect(filter) {
  const s = document.getElementById('print-batch');
  const cur = s.value;
  const searchInput = document.getElementById('print-batch-search');
  const q = (filter != null ? filter : searchInput ? searchInput.value : '').toLowerCase().trim();
  // Newest first; when no search, limit to 50 most recent
  let list = [...batches].reverse();
  if (q) {
    list = list.filter((b) => batchOptionLabel(b).toLowerCase().includes(q));
  } else {
    list = list.slice(0, 50);
  }
  s.innerHTML =
    '<option value="">— ' +
    t('print.chooseBatch') +
    ' —</option>' +
    list.map((b) => `<option value="${esc(b.batchId)}">${batchOptionLabel(b)}</option>`).join('');
  if (cur) s.value = cur;
}

function renderBagPreview() {
  const id = document.getElementById('print-batch').value;
  const el = document.getElementById('bag-preview');
  const mode = document.getElementById('print-mode').value;
  const qr = document.getElementById('bag-qr').checked;
  if (!id) {
    el.innerHTML = '<div class="empty">' + t('print.selectBatchAbove') + '</div>';
    return;
  }
  const batch = batches.find((b) => b.batchId === id);
  if (!batch) return;
  const wrap = document.createElement('div');
  wrap.style.cssText = 'display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px';
  const allDeferred = [];
  batch.bags.forEach((bagId) => {
    const bk = bagLabelKg(batch, bagId);
    const { cell, deferred } = buildPreviewCell(bagLabelItems(bagId, batch, mode, null, qr, bk));
    wrap.appendChild(cell);
    allDeferred.push(...deferred);
  });
  el.innerHTML = '';
  el.appendChild(wrap);
  renderPreviewDeferred(allDeferred, 30);
}

let selectedLabIds = new Set();
let lastCreatedCultureIds = [];
// Die Speicherung, auf die das Fenster wartet, bevor es druckt: die Nummern-
// Barcodes kommen mit der Antwort des Servers, und ein Etikett, das vorher
// gedruckt wird, trägt die alte Kodierung aus der ID (siehe labLabelItems).
let _cprSaved = null;
function goToPrintLabCulture() {
  selectedLabIds = new Set(lastCreatedCultureIds);
  go('print', 'n-print');
  setTimeout(() => {
    openStab('print', 'lab');
    renderLabList();
    renderLabPreview();
  }, 150);
}
// Der Schluss jedes Weges, der Kulturen anlegt: das Etiketten-Fenster — was
// nbPlaceAndPrint() für Beutel ist, ohne die Zonenwahl davor, weil eine Kultur
// keinen Standort hat. Kommt von selbst hoch, egal wo man steht; die Seite mit
// dem langen Formular ist seit dem Schnelldialog nur noch dessen Ablage.
// korn: { batchObj, bagIds, saved } — Körnerbeutel, die mit diesen Kulturen
// entstanden und schon eingelagert sind. Ihre Etiketten gehen im selben Druck
// mit (etikettenFuerAlles).
let _cprKorn = null;
function cprShow(ids, saved, korn) {
  lastCreatedCultureIds = ids.slice();
  _cprSaved = saved || null;
  _cprKorn = korn || null;
  const beutel = korn ? korn.bagIds : [];
  const head = document.getElementById('cpr-head');
  if (head)
    head.textContent = beutel.length
      ? t('lab.printForAll', { n: ids.length + beutel.length, kulturen: ids.length, beutel: beutel.length })
      : t('lab.printFor', { n: ids.length });
  const titel = document.getElementById('cpr-ids-title');
  if (titel) titel.textContent = t(beutel.length ? 'lab.createdIdsAll' : 'lab.createdIds');
  const knopf = document.getElementById('prt-cpr');
  if (knopf) knopf.textContent = t(beutel.length ? 'lab.printAllNow' : 'lab.printLabelsNow');
  const list = document.getElementById('cpr-ids');
  if (list)
    list.innerHTML = ids
      .concat(beutel)
      .map(
        (id) =>
          `<span class="fs-micro" style="font-family:monospace;background:var(--c-bg);padding:2px 6px;border-radius:4px;color:var(--c-text-sec)">${esc(id)}</span>`
      )
      .join('');
  const m = document.getElementById('m-culture-print');
  if (m) m.classList.add('open');
}
function cprClose() {
  const m = document.getElementById('m-culture-print');
  if (m) m.classList.remove('open');
}
// Der Schluss, wenn Kulturen und Körnerbrut zusammen entstehen (Mehrere,
// Beimpfen): erst die Körnerbeutel einlagern — die Zonenwahl ist ein Tor wie
// bei jeder Charge —, dann ein Etiketten-Fenster für alles und ein Druck.
// Vorher kamen zwei Fenster nacheinander, jedes mit seinem eigenen Druck.
function etikettenFuerAlles(ids, saved, korn) {
  if (korn && !ids.length) return nbPlaceAndPrint(korn.batchObj, korn.bagIds);
  if (!korn) {
    if (ids.length) cprShow(ids, saved);
    return;
  }
  openZonePickModal(korn.batchObj, korn.bagIds, () => cprShow(ids, saved, korn));
}
async function printCultureLabelsInline() {
  const ids = lastCreatedCultureIds;
  if (!ids.length) {
    toast(t('print.selectCulture'), 'err');
    return;
  }
  // Ein schneller Daumen schlägt sonst die Antwort des Servers: erst speichern
  // lassen, dann drucken. Schlägt das Speichern fehl, gibt es die Kultur nicht —
  // dann kein Etikett: eins am Glas hieße beim nächsten Scan "nicht im System".
  // Was schiefging, hat logLabWork schon gesagt.
  if (_cprSaved && !(await _cprSaved.then(() => true).catch(() => false))) return;
  const modeEl = document.getElementById('lab-mode');
  const qrEl = document.getElementById('lab-qr');
  let zpl = makeLabZPL(ids, modeEl ? modeEl.value : 'sorte', !!(qrEl && qrEl.checked));
  // Die Körnerbeutel im selben Druck, mit den Einstellungen der Beutel-Etiketten.
  // Ihre Nummern kommen mit der Antwort auf die Charge; ist die fehlgeschlagen
  // (gemeldet hat es createGrainBatch), gibt es die Beutel nicht, und gedruckt
  // werden nur die Kulturen.
  const korn = _cprKorn;
  let n = ids.length;
  if (korn) {
    if (korn.saved) await korn.saved.catch(() => {});
    const b = batches.find((x) => x.batchId === korn.batchObj.batchId);
    if (b) {
      const pm = document.getElementById('print-mode');
      const bq = document.getElementById('bag-qr');
      await ensureBagBarcodes(korn.bagIds);
      zpl += '\n' + makeBagZPL(korn.bagIds, b, pm ? pm.value : 'full', bq ? bq.checked : true);
      n += korn.bagIds.length;
    }
  }
  if (!zpl || !zpl.includes('^XA')) {
    toast(t('print.noLabels'), 'err');
    return;
  }
  const err = await sendToPrinter(zpl);
  if (err) {
    const blob = new Blob([zpl], { type: 'text/plain' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'lab_labels.zpl';
    a.click();
  } else {
    printedFb(korn ? t('print.printedAll', { n }) : t('print.printedLab', { n: ids.length }));
    cprClose();
  }
}
function renderLabList() {
  const filter = document.getElementById('lab-filter').value,
    el = document.getElementById('lab-list'),
    today = todayStr();
  const rows = cultures
    .filter((c) => {
      if (filter === 'all') return c.status === 'active' || c.status === 'stored';
      if (filter === 'today') {
        const d = new Date(c.created);
        // Must match todayStr()'s DDMMYY order — building YYMMDD here made the
        // "today" filter match only when day-of-month equalled the 2-digit year.
        return (
          String(d.getDate()).padStart(2, '0') +
            String(d.getMonth() + 1).padStart(2, '0') +
            String(d.getFullYear()).slice(2) ===
          today
        );
      }
      return c.type === filter;
    })
    .sort((a, b) => b.created.localeCompare(a.created));
  el.innerHTML = rows.length
    ? rows
        .map(
          (c) =>
            `<label class="fs-meta" style="display:flex;align-items:center;gap:7px;padding:4px 0;cursor:pointer;border-bottom:0.5px solid #f0ede8"><input type="checkbox" ${selectedLabIds.has(c.id) ? 'checked' : ''} onchange="toggleLabId('${esc(c.id)}',this.checked)" style="width:14px;height:14px;margin:0" /><span style="font-family:monospace;font-weight:500">${esc(c.id)}</span><span class="badge ${c.type === 'MC' ? 'badge-mc' : c.type === 'PD' ? 'badge-pd' : 'badge-lc'}">${esc(c.type)}</span><span style="color:var(--c-text-muted)">${esc(c.species)}${c.strain ? ' / ' + esc(c.strain) : ''}</span></label>`
        )
        .join('')
    : '<div class="fs-meta" style="color:var(--c-text-muted);padding:6px">No cultures match.</div>';
}
function toggleLabId(id, on) {
  if (on) selectedLabIds.add(id);
  else selectedLabIds.delete(id);
  renderLabPreview();
}
function renderLabPreview() {
  const el = document.getElementById('lab-preview');
  const ids = [...selectedLabIds];
  if (!ids.length) {
    el.innerHTML = '<div class="empty">' + t('print.tickCulturesPreview') + '</div>';
    return;
  }
  const detail = document.getElementById('lab-mode').value;
  const qr = document.getElementById('lab-qr').checked;
  const wrap = document.createElement('div');
  wrap.style.cssText = 'display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px';
  const allDeferred = [];
  ids.forEach((id) => {
    const c = cultures.find((x) => x.id === id);
    if (!c) return;
    const { cell, deferred } = buildPreviewCell(labLabelItems(id, c, detail, qr));
    wrap.appendChild(cell);
    allDeferred.push(...deferred);
  });
  el.innerHTML = '';
  el.appendChild(wrap);
  renderPreviewDeferred(allDeferred, 30);
}

// ─── REF BARCODES ────────────────────────────────────────────
async function makeQR(val) {
  // P-02: QRCode is lazy-loaded.
  if (typeof QRCode === 'undefined') await loadVendorLibs();
  return new Promise((resolve) => {
    const div = document.createElement('div');
    div.style.cssText = 'display:inline-block';
    try {
      new QRCode(div, {
        text: val,
        width: 120,
        height: 120,
        colorDark: '#000',
        colorLight: '#fff',
        correctLevel: QRCode.CorrectLevel.L
      });
      setTimeout(() => {
        const img = div.querySelector('img') || div.querySelector('canvas');
        if (img) {
          img.style.cssText = 'display:block;width:100%;height:auto';
          resolve(img);
        } else resolve(null);
      }, 100);
    } catch {
      resolve(null);
    }
  });
}

async function renderRefBarcodes() {
  // P-02: JsBarcode + QRCode are lazy-loaded.
  if (typeof JsBarcode === 'undefined' || typeof QRCode === 'undefined') await loadVendorLibs();
  const grid = document.getElementById('ref-grid');
  grid.innerHTML = '';
  const useQR = document.getElementById('ref-qr').checked;
  for (const group of REF_GROUPS) {
    const card = document.createElement('div');
    card.className = 'card';
    card.innerHTML = `<div class="sec">${group.g}</div>`;
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;flex-wrap:wrap;gap:20px;margin-top:12px;align-items:flex-end';
    for (const item of group.items) {
      const val = item.val,
        label = item.label;
      const cell = document.createElement('div');
      cell.className = 'bc-cell';
      cell.style.cssText =
        'min-width:140px;text-align:center;padding:8px 12px;border:1px solid var(--c-border);border-radius:6px;background:var(--c-surface)';
      if (useQR) {
        const img = await makeQR(val);
        if (img) cell.appendChild(img);
        const lbl = document.createElement('div');
        lbl.className = 'fs-meta';
        lbl.style.cssText = 'font-weight:700;color:var(--c-text-sec);margin-top:5px';
        lbl.textContent = label;
        cell.appendChild(lbl);
      } else {
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.style.cssText = 'display:block';
        cell.appendChild(svg);
        setTimeout(() => {
          try {
            JsBarcode(svg, val, {
              format: 'CODE128',
              width: 2,
              height: 60,
              displayValue: false,
              margin: 14,
              background: '#fff',
              lineColor: '#000'
            });
          } catch {}
        }, 20);
        const lbl = document.createElement('div');
        lbl.className = 'fs-meta';
        lbl.style.cssText = 'font-weight:700;color:var(--c-text-sec);margin-top:5px;text-align:center';
        lbl.textContent = label;
        cell.appendChild(lbl);
      }
      row.appendChild(cell);
    }
    card.appendChild(row);
    grid.appendChild(card);
  }
}
async function printRef() {
  // P-02: JsBarcode + QRCode are lazy-loaded.
  if (typeof JsBarcode === 'undefined' || typeof QRCode === 'undefined') await loadVendorLibs();
  const sheet = document.getElementById('ref-print-sheet');
  sheet.innerHTML = '';
  const useQR = document.getElementById('ref-qr').checked;
  const title = document.createElement('div');
  // px-auf-papier: this is a printed sheet, and 15px there is a sixth of an
  // inch of paper. A rem would follow the reader's browser setting and change
  // how much fits on the page, which is not what a browser setting is for.
  title.style.cssText = 'font-family:Arial,sans-serif;font-size:15px;font-weight:bold;margin-bottom:12px;padding:8px';
  title.textContent = 'Reference ' + (useQR ? 'QR Codes' : 'Barcodes');
  sheet.appendChild(title);
  let delay = 0;
  for (const group of REF_GROUPS) {
    const sec = document.createElement('div');
    sec.className = 'fs-micro';
    sec.style.cssText =
      'font-family:Arial,sans-serif;font-weight:bold;text-transform:uppercase;letter-spacing:.08em;color:var(--c-text-muted);margin:14px 8px 8px';
    sec.textContent = group.g;
    sheet.appendChild(sec);
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;flex-wrap:wrap;gap:20px;padding:0 8px';
    for (const item of group.items) {
      const val = item.val,
        label = item.label;
      const cell = document.createElement('div');
      cell.style.cssText =
        'border:1px solid var(--c-border);border-radius:6px;padding:12px 16px;text-align:center;background:var(--c-surface);page-break-inside:avoid';
      if (useQR) {
        const img = await makeQR(val);
        if (img) {
          img.style.width = '90px';
          img.style.height = '90px';
          cell.appendChild(img);
        }
        const lbl = document.createElement('div');
        lbl.className = 'fs-xs';
        lbl.style.cssText = 'font-weight:bold;font-family:Arial,sans-serif;margin-top:5px';
        lbl.textContent = label;
        cell.appendChild(lbl);
      } else {
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        cell.appendChild(svg);
        setTimeout(() => {
          try {
            JsBarcode(svg, val, {
              format: 'CODE128',
              width: 2,
              height: 60,
              displayValue: false,
              margin: 14,
              background: '#fff',
              lineColor: '#000'
            });
          } catch {}
        }, delay);
        delay += 25;
        const lbl = document.createElement('div');
        lbl.className = 'fs-xs';
        lbl.style.cssText = 'font-weight:bold;font-family:Arial,sans-serif;margin-top:5px';
        lbl.textContent = label;
        cell.appendChild(lbl);
      }
      row.appendChild(cell);
    }
    sheet.appendChild(row);
  }
  setTimeout(() => window.print(), useQR ? 800 : delay + 200);
}

// ─── GLOBAL SCAN ENGINE ──────────────────────────────────────
// Session tracking
let sessionEntries = [];
let sessionStartTime = null;
let sessionErrors = 0;
let _lastScanVal = null;
// Audio feedback
let _scanAudioCtx = null;
let scanAudioEnabled = true;
// iOS requires AudioContext creation during a user gesture; call this from gesture handlers
function _initScanAudio() {
  if (!_scanAudioCtx) {
    try {
      _scanAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    } catch {}
  }
  if (_scanAudioCtx && _scanAudioCtx.state === 'suspended') _scanAudioCtx.resume().catch(function () {});
}
function _scanBeep(freq, dur) {
  if (!scanAudioEnabled) return;
  try {
    _initScanAudio();
    if (!_scanAudioCtx) return;
    const o = _scanAudioCtx.createOscillator();
    const g = _scanAudioCtx.createGain();
    o.connect(g);
    g.connect(_scanAudioCtx.destination);
    o.frequency.value = freq;
    g.gain.value = 0.15;
    o.start();
    g.gain.exponentialRampToValueAtTime(0.001, _scanAudioCtx.currentTime + dur / 1000);
    o.stop(_scanAudioCtx.currentTime + dur / 1000);
  } catch {}
}
// Pleasant success chirp: 880Hz sine, 120ms with soft attack/release envelope
function _scanBeepOk() {
  if (!scanAudioEnabled) return;
  try {
    _initScanAudio();
    if (!_scanAudioCtx) return;
    const ctx = _scanAudioCtx;
    const now = ctx.currentTime;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(880, now);
    o.connect(g);
    g.connect(ctx.destination);
    g.gain.setValueAtTime(0.0001, now);
    g.gain.exponentialRampToValueAtTime(0.22, now + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, now + 0.12);
    o.start(now);
    o.stop(now + 0.13);
  } catch {}
}
// Sharp error buzz: two dissonant square waves (280Hz + 350Hz), 350ms with gap
function _scanBeepErr() {
  if (!scanAudioEnabled) return;
  try {
    _initScanAudio();
    if (!_scanAudioCtx) return;
    const ctx = _scanAudioCtx;
    const t0 = ctx.currentTime;
    function tone(start, dur) {
      const o1 = ctx.createOscillator();
      const o2 = ctx.createOscillator();
      const g = ctx.createGain();
      o1.type = 'square';
      o2.type = 'square';
      o1.frequency.setValueAtTime(280, start);
      o2.frequency.setValueAtTime(350, start);
      o1.connect(g);
      o2.connect(g);
      g.connect(ctx.destination);
      g.gain.setValueAtTime(0.0001, start);
      g.gain.exponentialRampToValueAtTime(0.18, start + 0.01);
      g.gain.setValueAtTime(0.18, start + dur - 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, start + dur);
      o1.start(start);
      o2.start(start);
      o1.stop(start + dur);
      o2.stop(start + dur);
    }
    tone(t0, 0.14);
    tone(t0 + 0.21, 0.14);
  } catch {}
}
// Tab navigation for 3-tab scan modal
function switchScanTab(tab) {
  const tabs = document.querySelectorAll('.scan-tab');
  const panels = document.querySelectorAll('.scan-tab-panel');
  for (let i = 0; i < tabs.length; i++) {
    const t = tabs[i];
    if (t.getAttribute('data-scan-tab') === tab) t.classList.add('active');
    else t.classList.remove('active');
  }
  for (let j = 0; j < panels.length; j++) {
    const p = panels[j];
    if (p.getAttribute('data-scan-panel') === tab) p.classList.add('active');
    else p.classList.remove('active');
  }
}
// Render the "Letzte Erfolge" tab from sessionEntries (session successes)
function renderScanSuccesses() {
  const list = document.getElementById('scan-successes-list');
  if (!list) return;
  list.innerHTML = '';
  const succ = (sessionEntries || []).filter(function (e) {
    return e && e.action && (e.batch || e.bag);
  });
  const cnt = document.getElementById('scan-tab-succ-count');
  if (cnt) cnt.textContent = String(succ.length);
  // Newest first
  for (let i = succ.length - 1; i >= 0; i--) {
    const e = succ[i];
    const row = document.createElement('div');
    row.className = 'scan-success-row';
    if (e._tempId) row.setAttribute('data-succ-id', e._tempId);
    const tm = e.time ? new Date(e.time) : new Date();
    const timeStr =
      tm.getHours().toString().padStart(2, '0') +
      ':' +
      tm.getMinutes().toString().padStart(2, '0') +
      ':' +
      tm.getSeconds().toString().padStart(2, '0');
    const label = e.bag || e.batch || '';
    const locStr =
      e.action === 'MOVE'
        ? (e.from || '?') + ' → ' + (e.to || '?')
        : e.action === 'ADD'
          ? '→ ' + (e.to || '')
          : e.action === 'REMOVE'
            ? '✕ ' + (e.from || '')
            : e.action === 'HARVEST'
              ? '🍄'
              : '';
    row.innerHTML =
      '<span class="scan-success-time">' +
      timeStr +
      '</span>' +
      '<span class="badge b-' +
      esc((e.action || '').toLowerCase()) +
      '">' +
      esc(e.action || '') +
      '</span>' +
      '<span class="scan-success-body"><b>' +
      esc(label) +
      '</b>' +
      (locStr ? ' <span class="scan-success-loc">' + esc(locStr) + '</span>' : '') +
      '</span>' +
      '<button class="scan-success-undo" onclick="undoSuccessRow(this)" title="Undo">↩ Undo</button>';
    list.appendChild(row);
  }
}
// Undo from "Letzte Erfolge" tab row
function undoSuccessRow(btn) {
  const row = btn.closest('.scan-success-row');
  const tempId = row ? row.getAttribute('data-succ-id') : null;
  if (!tempId) return;
  // Delegate to existing undoScanEntry via a matching log-entry button, or perform undo directly
  const logBtn = document.querySelector('.scan-log-entry[data-scan-id="' + tempId + '"] .sle-undo');
  if (logBtn) {
    undoScanEntry(logBtn);
    renderScanSuccesses();
    return;
  }
  // Fallback: mirror undoScanEntry logic for entries not in the visible log
  const idx = sessionEntries.findIndex(function (e) {
    return e._tempId === tempId;
  });
  if (idx === -1) return;
  const entry = sessionEntries[idx];
  const si = scanLog.findIndex(function (e) {
    return e._tempId === tempId;
  });
  if (si !== -1) scanLog.splice(si, 1);
  const mi = movements.findIndex(function (e) {
    return e._tempId === tempId;
  });
  if (mi !== -1) movements.splice(mi, 1);
  sessionEntries.splice(idx, 1);
  modeRunUntally(entry);
  if (entry._serverId) apiDelete('/api/scan-log/' + entry._serverId);
  // _queued: the SW holds it offline, so there is no server row to DELETE and
  // none is coming until replay — pull it out of the queue instead.
  else if (entry._queued && dropQueuedScanEntry(entry)) entry._queued = false;
  else entry._undoPending = true; // POST not resolved yet — delete once its id arrives
  scan.count = Math.max(0, scan.count - 1);
  _scanBeep(400, 100);
  setFb('info', undoneMsg(entry));
  updateSD();
  renderStatus();
  renderScanSuccesses();
}
// Transient overlay background flash to reinforce feedback
var _scanBgFlashTimer = null;
function _flashScanBg(type) {
  const ov = document.getElementById('scan-overlay');
  if (!ov) return;
  ov.classList.remove('scan-bg-ok', 'scan-bg-err');
  if (type === 'ok') ov.classList.add('scan-bg-ok');
  else if (type === 'err') ov.classList.add('scan-bg-err');
  else return;
  clearTimeout(_scanBgFlashTimer);
  _scanBgFlashTimer = setTimeout(function () {
    ov.classList.remove('scan-bg-ok', 'scan-bg-err');
  }, 800);
}
// Multi-tab scan dedup via BroadcastChannel
const scanChannel = typeof BroadcastChannel !== 'undefined' ? new BroadcastChannel('meister-scans') : null;
if (scanChannel) {
  scanChannel.onmessage = function (ev) {
    if (ev.data && ev.data.type === 'scan-entry') {
      // Add to sessionEntries for dedup checking across tabs
      sessionEntries.push(ev.data.entry);
    }
  };
}
// Duplicate detection
let _pendingDupe = null;
let _pendingDupeTimer = null;
// Beim Umziehen ein Beutel ohne Platz im System (nie eingelagert, oder als
// entfernt gebucht): der zweite Scan desselben Beutels legt ihn am Ziel ein.
let _pendingPlace = null;
let _pendingPlaceTimer = null;
// Wie lange ein "nochmal scannen zum Bestätigen" gilt. Die Kamera nimmt dasselbe
// Etikett frühestens nach SCAN_DEDUP_MS (3 s) wieder an — mit den 3 s, die die
// Doppel-Warnung hier hatte, ließ sich der zweite Scan mit der Kamera nie treffen.
const CONFIRM_SCAN_MS = 8000;

function openScanModal() {
  document.getElementById('scan-overlay').classList.add('open');
  if (window.innerWidth <= 768) document.body.style.overflow = 'hidden';
}
function closeScanModal() {
  document.getElementById('scan-overlay').classList.remove('open');
  document.body.style.overflow = '';
}
function _addLogEntry(type, msg, entryData) {
  const log = document.getElementById('scan-modal-log');
  const el = document.createElement('div');
  el.className = 'scan-log-entry log-' + type;
  if (entryData && entryData._tempId) el.setAttribute('data-scan-id', entryData._tempId);
  const tm = new Date();
  const timeStr =
    tm.getHours().toString().padStart(2, '0') +
    ':' +
    tm.getMinutes().toString().padStart(2, '0') +
    ':' +
    tm.getSeconds().toString().padStart(2, '0');
  if (entryData && entryData.action && entryData.batch) {
    const sp = entryData.species || '';
    const bagLabel = entryData.bag || entryData.batch;
    const locStr =
      entryData.action === 'MOVE'
        ? entryData.from + ' → ' + entryData.to
        : entryData.action === 'ADD'
          ? '→ ' + entryData.to
          : entryData.action === 'REMOVE'
            ? '✕ ' + (entryData.from || '')
            : entryData.action === 'HARVEST'
              ? entryData.grams
                ? entryData.grams + 'g (Flush ' + (entryData.flush || 1) + ')'
                : ''
              : '';
    // Harvest entries are not undoable via the scan-log endpoint (harvests live in a separate table)
    const canUndo = entryData.action !== 'HARVEST';
    el.innerHTML =
      '<span class="sle-time">' +
      timeStr +
      '</span>' +
      '<span class="badge b-' +
      esc(entryData.action.toLowerCase()) +
      '">' +
      esc(entryData.action) +
      '</span> ' +
      '<span class="sle-msg"><b>' +
      esc(bagLabel) +
      '</b>' +
      (sp ? ' <span class="fs-micro" style="color:var(--c-text-muted)">' + esc(sp) + '</span>' : '') +
      (locStr ? ' <span style="color:var(--c-text-muted)">' + esc(locStr) + '</span>' : '') +
      '</span>' +
      (canUndo ? '<button class="sle-undo" onclick="undoScanEntry(this)" title="Undo">↩</button>' : '');
  } else {
    el.innerHTML = '<span class="sle-time">' + timeStr + '</span><span class="sle-msg">' + esc(msg) + '</span>';
  }
  log.prepend(el);
  while (log.children.length > 80) log.lastChild.remove();
}
let _toastTimer = null;
let _camHudToastTimer = null;
function setFb(type, msg, opts) {
  const entryData = opts && opts._tempId ? opts : null;
  // When camera is active, show feedback on camera HUD instead of scan overlay
  if (_camScanner && (!opts || !opts.noModal)) {
    _showCamHudToast(type, msg);
    updateCamHud();
  } else {
    if (!opts || !opts.noModal) openScanModal();
  }
  // Always update scan overlay toast + log (for when user opens it later)
  const el = document.getElementById('scan-toast');
  el.className = 'scan-toast-inline fb-' + type;
  el.textContent = msg;
  requestAnimationFrame(() => el.classList.add('visible'));
  clearTimeout(_toastTimer);
  _toastTimer = setTimeout(() => el.classList.remove('visible'), fbShowMs(type));
  if (type === 'err') sessionErrors++;
  if (type === 'ok') {
    _scanBeepOk();
    _flashScanBg('ok');
    if (typeof switchScanTab === 'function') switchScanTab('current');
  } else if (type === 'err') {
    _scanBeepErr();
    _flashScanBg('err');
    if (typeof switchScanTab === 'function') switchScanTab('current');
  }
  _addLogEntry(type, msg, entryData);
  if (type === 'ok' && typeof renderScanSuccesses === 'function') renderScanSuccesses();
}
function _showCamHudToast(type, msg) {
  const el = document.getElementById('cam-hud-toast');
  el.className = 'cam-hud-toast ht-' + type;
  el.textContent = msg;
  requestAnimationFrame(() => el.classList.add('visible'));
  clearTimeout(_camHudToastTimer);
  _camHudToastTimer = setTimeout(() => el.classList.remove('visible'), fbShowMs(type));
}
// Wie lange eine Rückmeldung stehen bleibt. Fehler sagen jetzt, was los ist und
// was hilft — das liest niemand in vier Sekunden. Der nächste Scan ersetzt die
// Meldung ohnehin; lang steht sie nur, wenn man sie braucht.
function fbShowMs(type) {
  return type === 'err' ? 7000 : type === 'warn' ? 5000 : 3000;
}
function updateCamHud() {
  document.getElementById('ch-action').textContent = scan.action || '—';
  document.getElementById('ch-from').textContent = scan.from || '—';
  // Der Name des Platzes, wie auf dem Umziehen-Knopf daneben — nicht "TENT1".
  document.getElementById('ch-to').textContent = scan.to ? zoneDisplayName(scan.to) : '—';
  document.getElementById('ch-count').textContent = scan.count;
  // Action chip color
  const actionChip = document.getElementById('cam-chip-action');
  actionChip.className = 'cam-chip' + (scan.action ? ' ch-set ch-' + scan.action.toLowerCase() : '');
  // Show/hide from/arrow chips based on action
  const fromChip = document.getElementById('cam-chip-from');
  const arrowChip = document.getElementById('cam-chip-arrow');
  const toChip = document.getElementById('cam-chip-to');
  // MOVE no longer needs FROM — FROM is auto-derived per bag
  fromChip.style.display = 'none';
  arrowChip.style.display = 'none';
  // MOVE_BATCH needs a destination too, so show the chip for it as well —
  // otherwise the HUD hides the one field the worker still has to fill (and
  // with it the tap target that opens the destination picker).
  //
  // Und "noch gar kein Vorgang" gehört dazu, denn das ist der Zustand, in dem
  // der Scanner aufmacht. scanPickDestination() setzt selbst MOVE, wenn keiner
  // gesetzt ist — dieses Feld anzutippen IST also der Einstieg ins Umziehen.
  // Ausgeblendet, solange kein Vorgang steht, lag der Einstieg hinter dem
  // Zustand, den er herstellt: am Telefon blieb nur, einen gedruckten
  // MOVE-Barcode zu scannen, und den hat in der Kammer niemand dabei.
  const wantsTo =
    !scan.action || scan.action === 'ADD' || scan.action === 'MOVE' || scan.action === 'MOVE_BATCH';
  toChip.className = 'cam-chip' + (wantsTo && scan.to ? ' ch-set' : '');
  toChip.style.display = wantsTo ? '' : 'none';
  // Pulsieren nur, wenn ein Vorgang wirklich auf sein Ziel wartet. Ohne Vorgang
  // ist Scannen ein vollwertiger Zustand (Beutel scannen zeigt seine Infos), und
  // der Weg ins Umziehen ist jetzt der beschriftete Knopf darunter — ein
  // blinkendes Feld daneben zog den Blick auf die kleinere der zwei Türen.
  const toPulse = !!scan.action && wantsTo && !scan.to;
  toChip.classList.toggle('ch-pulse', toPulse);
  // Count chip highlight
  const countChip = document.getElementById('cam-chip-count');
  countChip.className = 'cam-chip' + (scan.count > 0 ? ' ch-set' : '');
  // Die ganze Reihe nur, wenn sie etwas sagt, was kein Knopf sagt: ein Vorgang
  // von einem gedruckten Etikett, für den es keinen Knopf gibt (ADD,
  // MOVE_BATCH), oder ein Umzug, dem das Ziel noch fehlt. Sonst sagt der
  // leuchtende Knopf, was läuft, und seine Zahl, wieviel — "ACTION — TO — 0"
  // daneben war nur Rauschen in der Sprache der Etiketten.
  const reihe = document.getElementById('cam-hud-chips');
  if (reihe) {
    const brauchtReihe =
      scan.action === 'ADD' || scan.action === 'MOVE_BATCH' || (scan.action === 'MOVE' && !scan.to);
    reihe.style.display = brauchtReihe ? '' : 'none';
  }
}
// Put the scanner into an action mode.
//
// This was the body of the `if (ACTIONS.includes(val))` branch in the barcode
// handler, which meant an action could be armed exactly one way: by scanning a
// printed barcode with the word on it. That is fine at the bench where the
// sheet is taped to the wall, and no use at all on a phone in a tent — and
// reporting contamination is precisely the thing you do standing in front of a
// bad bag, with the phone already in your hand.
//
// Nothing about the modes changed; they simply have a second door now. Toggling
// the same action off returns to plain scanning, so the button that armed it is
// also the way back out.
// opts.noModal: quittieren, ohne die grüne Scan-Hülle aufzuklappen. Die liegt
// über der Kamera, und wer den Vorgang setzt, um gleich zu scannen, will das
// Bild sehen und nicht die Hülle davor.
function armScanAction(val, opts) {
  if (!ACTIONS.includes(val)) return;
  const keepTo = val === scan.action && scan.to;
  scan.action = val;
  scan.from = null;
  scan.to = keepTo ? scan.to : null;
  scan.harvestBag = null;
  const hp = document.getElementById('harvest-panel');
  if (hp) hp.style.display = 'none';
  _pendingDupe = null;
  clearTimeout(_pendingDupeTimer);
  updateSD();
  setFb(
    'ok',
    {
      ADD: t('scanFb.actionAdd'),
      MOVE: t('scanFb.actionMove'),
      MOVE_BATCH: 'MOVE BATCH — Ziel scannen',
      REMOVE: t('scanFb.actionRemove'),
      HARVEST: t('scanFb.actionHarvest'),
      CONTAM: t('scanFb.actionContam')
    }[val],
    opts && opts.noModal ? { noModal: true } : undefined
  );
  // Ten places assign scan.action and only two used to refresh this, so the
  // button could sit lit while ADD was armed — and the next bag scanned got
  // added to a location instead of reported contaminated.
  updateCamContamBtn();
}
// Arm CONTAM, or stand down if it is already armed. The camera stays open
// either way: a worker walking a rack reports several bags in a row.
//
// Liegen Beutel in der Sammelliste, heißt derselbe Knopf "fertig, jetzt
// melden": das Formular geht auf, statt die gescannten Beutel wegzuwerfen.
// Wegwerfen kann man sie weiter — mit dem ✗ daneben, das den Scan zurücksetzt.
function toggleContamScan() {
  if (scan.action === 'CONTAM') {
    if (_crTargets.length) {
      crFinishCollect();
      return;
    }
    scan.action = null;
    updateSD();
    setFb('ok', t('scanFb.actionCleared'));
  } else {
    armScanAction('CONTAM');
  }
  updateCamContamBtn();
}
function updateCamContamBtn() {
  const b = document.getElementById('btn-cam-contam');
  if (!b) return;
  const on = scan.action === 'CONTAM';
  b.classList.toggle('on', on);
  b.setAttribute('aria-pressed', on ? 'true' : 'false');
  // Der Zähler ist die einzige Rückmeldung darüber, wieviel schon gesammelt
  // ist, solange die Kamera das Bild füllt.
  const badge = document.getElementById('cam-contam-count');
  if (badge) {
    const n = _crTargets.length;
    badge.textContent = String(n);
    badge.hidden = !n;
  }
  b.setAttribute(
    'aria-label',
    _crTargets.length ? t('contam.reportN', { n: _crTargets.length }) : t('scan.contamAria')
  );
}

// ── Vorgänge in Serie: Umziehen, Ernten, Kontamination, Entsorgen, Verbraucht ─
// Ein Knopf, dann Beutel für Beutel scannen, bis der Knopf wieder aus ist. So
// einfach muss es sein, sonst benutzt es niemand. Der Scanner konnte das schon
// (ein gesetzter Vorgang bleibt stehen), nur lag die Tür dazu hinter gedruckten
// Etiketten (MOVE, HARVEST, REMOVE) oder dem kleinen "Nach"-Feld, dessen Liste
// hinter der Kamera aufging. Am Telefon blieb so nur der Umweg über das
// Beutel-Fenster — für jeden Beutel von vorn.
//
// _modeRun zählt den Durchgang: welcher Vorgang, wohin (nur beim Umziehen),
// wieviele Beutel schon, wann zuletzt etwas geschah. Ob ein Knopf an ist, steht
// NICHT hier, sondern in scan — ein MOVE mit Ziel ist ein Umzug, egal durch
// welche Tür er kam. Die Kontamination zählt ihre Beutel selbst (_crTargets).
let _modeRun = null;
// Wie lange ein Umzug oder eine Ernte die geschlossene Kamera überlebt. Ein
// Anruf, die Bildschirmsperre oder ein Tipp neben das Bild schließen sie mitten
// in der Reihe; wer gleich weitermacht, soll nicht wieder bei null anfangen. Wer
// erst nach einer Pause wiederkommt, bekommt den neutralen Scanner wie bisher.
// Entsorgen und Verbraucht überleben sie nie: wer die Kamera später aufmacht, um
// nach einem Beutel zu sehen, darf ihn nicht versehentlich wegbuchen.
const MODE_RUN_KEEP_MS = 15 * 60 * 1000;

function toggleMoveScan() {
  if (scan.action === 'MOVE' && scan.to) {
    const to = scan.to;
    const n = modeRunCount('MOVE', to);
    endModeRun();
    setFb('ok', t('cam.moveEnded', { n: n, loc: zoneDisplayName(to) }));
    return;
  }
  if (contamPending()) return;
  _openZonePicker(t('cam.movePick'), armMoveRun);
}

// Ernten, Entsorgen und Verbraucht: ein Tipp stellt den Vorgang scharf, der
// zweite nimmt ihn zurück — wie beim Umziehen, nur ohne Ziel.
function toggleModeScan(action) {
  const [an, aus] = {
    HARVEST: ['cam.harvestArmed', 'cam.harvestEnded'],
    REMOVE: ['cam.trashArmed', 'cam.trashEnded']
  }[action];
  if (scan.action === action) {
    const n = modeRunCount(action, null);
    endModeRun();
    setFb('ok', t(aus, { n: n }));
    return;
  }
  if (contamPending()) return;
  armMode(action, null);
  setFb('ok', t(an));
}

// Gesammelte Kontaminations-Beutel gingen beim Umschalten still verloren:
// CONTAM wäre weg, die Liste bliebe liegen, und kein Knopf zeigte sie mehr an.
function contamPending() {
  if (scan.action !== 'CONTAM' || !_crTargets.length) return false;
  setFb('err', t('cam.moveContamPending', { n: _crTargets.length }));
  return true;
}

function endModeRun() {
  scan.action = null;
  scan.to = null;
  scan.from = null;
  scan.harvestBag = null;
  _modeRun = null;
  updateSD();
}

// Stellt einen Vorgang scharf: dieselben Aufräumschritte wie armScanAction().
// Derselbe Vorgang mit demselben Ziel noch einmal (das Platz-Etikett des
// laufenden Umzugs gescannt, das Ziel erneut gewählt) setzt den Durchgang fort,
// statt die Zahl auf dem Knopf zu löschen.
function armMode(action, to) {
  const weiter =
    scan.action === action && scan.to === to && _modeRun && _modeRun.action === action && _modeRun.to === to;
  scan.action = action;
  scan.to = to;
  scan.from = null;
  scan.harvestBag = null;
  const hp = document.getElementById('harvest-panel');
  if (hp) hp.style.display = 'none';
  _pendingDupe = null;
  _pendingPlace = null;
  clearTimeout(_pendingDupeTimer);
  clearTimeout(_pendingPlaceTimer);
  _modeRun = { action: action, to: to, n: weiter ? _modeRun.n : 0, at: Date.now() };
  updateSD();
}

function armMoveRun(dest) {
  armMode('MOVE', dest);
  rememberDest(dest);
  setFb('ok', t('cam.moveArmed', { loc: zoneDisplayName(dest) }));
}

// Wieviele Beutel der laufende Durchgang schon hat.
function modeRunCount(action, to) {
  return _modeRun && _modeRun.action === action && _modeRun.to === to ? _modeRun.n : 0;
}
// Ein Beutel mehr im Durchgang. Ein Vorgang, der durch eine andere Tür kam
// (gedrucktes Etikett, Platz-Etikett), beginnt hier seinen Durchgang. Der
// Eintrag wird markiert, damit nur zurückgenommen wird, was auch gezählt wurde.
function modeRunTally(action, to, entry) {
  if (!_modeRun || _modeRun.action !== action || _modeRun.to !== to) {
    _modeRun = { action: action, to: to, n: 0, at: Date.now() };
  }
  _modeRun.n++;
  _modeRun.at = Date.now();
  if (entry) entry._run = action;
  return _modeRun.n;
}
// Rückgängig, oder vom Server abgelehnt: der Beutel zählt doch nicht.
function modeRunUntally(entry) {
  if (!entry || !entry._run || !_modeRun || _modeRun.action !== entry._run) return;
  if (entry._run === 'MOVE' && _modeRun.to !== entry.to) return;
  _modeRun.n = Math.max(0, _modeRun.n - 1);
}
// Darf der Scannen-Knopf den Vorgang stehen lassen, statt neutral aufzumachen?
function modeRunResumable() {
  if (!_modeRun || scan.action !== _modeRun.action) return false;
  if (_modeRun.action !== 'MOVE' && _modeRun.action !== 'HARVEST') return false;
  if (_modeRun.action === 'MOVE' && (!scan.to || scan.to !== _modeRun.to)) return false;
  return Date.now() - _modeRun.at < MODE_RUN_KEEP_MS;
}

// Die Knöpfe, die hier gezählt werden. Die Kontamination hat ihren eigenen
// (updateCamContamBtn), weil ihr Knopf mehr tut: mit gesammelten Beuteln öffnet
// er das Formular.
function updateCamModeBtns() {
  const moveOn = scan.action === 'MOVE' && !!scan.to;
  const loc = moveOn ? zoneDisplayName(scan.to) : '';
  const knoepfe = [
    ['move', moveOn, moveOn ? t('cam.moveOnAria', { loc: loc }) : t('cam.moveAria'), modeRunCount('MOVE', scan.to)],
    ['harvest', scan.action === 'HARVEST', t('cam.harvestAria'), modeRunCount('HARVEST', null)],
    ['trash', scan.action === 'REMOVE', t('cam.trashAria'), modeRunCount('REMOVE', null)]
  ];
  for (const [name, on, aria, zahl] of knoepfe) {
    const b = document.getElementById('btn-cam-' + name);
    if (!b) continue;
    b.classList.toggle('on', on);
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
    b.setAttribute('aria-label', aria);
    const badge = document.getElementById('cam-' + name + '-count');
    if (badge) {
      const n = on ? zahl : 0;
      badge.textContent = String(n);
      badge.hidden = !n;
    }
  }
  // Umziehen an zeigt statt des Worts sein Ziel. Nur der Name: der Pfeil davor
  // ist schon das Zeichen des Knopfs.
  const idle = document.getElementById('cam-move-idle');
  if (idle) idle.hidden = moveOn;
  const ziel = document.getElementById('cam-move-to');
  if (ziel) {
    ziel.hidden = !moveOn;
    ziel.textContent = loc;
  }
}

function updateSD() {
  document.getElementById('s-action').textContent = scan.action || '—';
  document.getElementById('s-from').textContent = scan.from || '—';
  document.getElementById('s-to').textContent = scan.to || '—';
  document.getElementById('s-count').textContent = scan.count;
  // Action-colored header
  const modal = document.getElementById('scan-modal');
  modal.className = 'scan-modal' + (scan.action ? ' scan-action-' + scan.action.toLowerCase() : '');
  // MOVE: hide FROM chip — FROM is auto-derived per bag
  const fromChip = document.getElementById('chip-from');
  fromChip.style.display = scan.action === 'MOVE' || scan.action === 'MOVE_BATCH' ? 'none' : '';
  // Chip pulse hints
  const chipTo = document.getElementById('chip-to');
  const toPulse =
    (scan.action === 'ADD' && !scan.to) ||
    (scan.action === 'MOVE' && !scan.to) ||
    (scan.action === 'MOVE_BATCH' && !scan.to);
  chipTo.classList.toggle('chip-pulse', toPulse);
  // Last scan chip
  const lastChip = document.getElementById('chip-last');
  if (_lastScanVal) {
    lastChip.style.display = '';
    document.getElementById('s-last').textContent = _lastScanVal;
  }
  // Count bump animation
  const countChip = document.getElementById('chip-count');
  countChip.classList.remove('count-bump');
  void countChip.offsetWidth;
  if (scan.count > 0) countChip.classList.add('count-bump');
  // Session end button
  document.getElementById('btn-end-session').style.display = sessionEntries.length > 0 ? '' : 'none';
  // Der Weg ins Kontaminations-Formular für alle, die am Tisch mit dem
  // Handscanner sammeln: die Kamera-Leiste mit dem ⚠-Knopf sehen die nicht.
  const collectBtn = document.getElementById('btn-contam-collect');
  if (collectBtn) {
    collectBtn.style.display = _crTargets.length ? '' : 'none';
    collectBtn.textContent = t('contam.reportN', { n: _crTargets.length });
  }
  // Also sync camera HUD if it exists
  updateCamHud();
  updateCamContamBtn();
  updateCamModeBtns();
}
// Tap the To chip (scan modal or camera HUD) to set the destination by hand.
// Normally it comes from scanning a location barcode, but a shelf label can be
// missing, damaged or out of reach — this opens the same zone picker the other
// move flows use, so the scanner is no longer barcode-only. Mirrors what
// scanning a location does: sets the target for ADD/MOVE/MOVE_BATCH, and with
// no action chosen yet it starts a MOVE to that destination — the same Umzug
// the Umziehen button starts, so it counts and lights up the same way.
function scanPickDestination() {
  const act = scan.action;
  if (act && act !== 'ADD' && act !== 'MOVE' && act !== 'MOVE_BATCH') return;
  _openZonePicker(t('scan.pickDest'), function (dest) {
    if (!scan.action || scan.action === 'MOVE') {
      armMoveRun(dest);
      return;
    }
    scan.to = dest;
    updateSD();
    setFb('ok', t('scanFb.to', { loc: zoneDisplayName(dest) }));
  });
}
function resetScan() {
  scan = { action: null, from: null, to: null, count: scan.count, harvestBag: null };
  // Zurücksetzen heißt auch: die gesammelten Beutel sind weg. Sie hier stehen
  // zu lassen hieße, sie zu einem späteren Bericht mitzunehmen, den niemand
  // über sie schreiben wollte.
  _crTargets = [];
  _crResumeForm = false;
  // Und ein laufender Umzug ist vorbei — der Scannen-Knopf soll ihn danach
  // nicht wieder aufnehmen.
  _modeRun = null;
  // It clears scan.action, and it is bound to a button inside the open camera
  // HUD — so without this the CONTAM toggle beside it stayed lit and pressed
  // over a disarmed scanner, and the next bad bag got the neutral sheet.
  updateCamContamBtn();
  document.getElementById('harvest-panel').style.display = 'none';
  _pendingDupe = null;
  _pendingPlace = null;
  clearTimeout(_pendingDupeTimer);
  clearTimeout(_pendingPlaceTimer);
  updateSD();
  setFb('info', t('scanFb.setAction'));
}
// Was ein Rückgängig gerade bewirkt hat, in Worten statt "Undo: MOVE BO-…-03".
function undoneMsg(entry) {
  const was = entry.bag || entry.batch;
  if (entry.action === 'MOVE' && entry.from) {
    return t('scanFb.undoneMove', { bag: was, loc: zoneDisplayName(entry.from) });
  }
  return t('scanFb.undone', { bag: was });
}
// Nimmt einen Scan-Eintrag zurück: aus dem Log auf dem Telefon, aus der
// laufenden Runde samt ihrer Zeile im Verlauf, und vom Server — auch einen,
// dessen Speichern noch läuft oder der offline in der Warteschlange steht. Der
// ↩-Knopf und das Rückgängig nach "Verbraucht" nehmen denselben Weg.
function scanEintragZuruecknehmen(entry) {
  const tempId = entry._tempId;
  const si = scanLog.findIndex((e) => e._tempId === tempId);
  if (si !== -1) scanLog.splice(si, 1);
  const mi = movements.findIndex((e) => e._tempId === tempId);
  if (mi !== -1) movements.splice(mi, 1);
  const ri = sessionEntries.findIndex((e) => e._tempId === tempId);
  if (ri !== -1) {
    sessionEntries.splice(ri, 1);
    scan.count = Math.max(0, scan.count - 1);
    const row = document.querySelector('.scan-log-entry[data-scan-id="' + tempId + '"]');
    if (row) row.remove();
  }
  modeRunUntally(entry);
  // Delete from server
  if (entry._serverId) apiDelete('/api/scan-log/' + entry._serverId);
  // _queued: the SW holds it offline, so there is no server row to DELETE and
  // none is coming until replay — pull it out of the queue instead.
  else if (entry._queued && dropQueuedScanEntry(entry)) entry._queued = false;
  else entry._undoPending = true; // POST not resolved yet — delete once its id arrives
}
// Undo a single scan entry by clicking the ↩ button
function undoScanEntry(btn) {
  const row = btn.closest('.scan-log-entry');
  const tempId = row ? row.getAttribute('data-scan-id') : null;
  if (!tempId) return;
  const entry = sessionEntries.find((e) => e._tempId === tempId);
  if (entry) scanRueckgaengig(entry);
}
// Nimmt einen Eintrag der laufenden Runde zurück und sagt es. ↩ in der Kamera
// kommt direkt hierher und sucht nicht erst die Zeile im Verlauf: die gibt es
// nicht für jeden Eintrag (mehrere Beutel auf einmal verbraucht schreiben eine
// Meldung, keine je Beutel), und der Verlauf behält nur die letzten 80.
function scanRueckgaengig(entry) {
  scanEintragZuruecknehmen(entry);
  _scanBeep(400, 100);
  setFb('info', undoneMsg(entry));
  updateSD();
  renderStatus();
  if (typeof renderScanSuccesses === 'function') renderScanSuccesses();
}
// Ctrl+Z undo support
let _ctrlZPending = false;
let _ctrlZTimer = null;
document.addEventListener('keydown', function (e) {
  if (!document.getElementById('scan-overlay').classList.contains('open')) return;
  if (e.ctrlKey && e.key === 'z') {
    e.preventDefault();
    if (sessionEntries.length === 0) {
      setFb('info', 'Nichts zum Rückgängig machen');
      return;
    }
    if (!_ctrlZPending) {
      _ctrlZPending = true;
      setFb('info', 'Ctrl+Z nochmal drücken zum Bestätigen');
      _ctrlZTimer = setTimeout(() => {
        _ctrlZPending = false;
      }, 2000);
      return;
    }
    _ctrlZPending = false;
    clearTimeout(_ctrlZTimer);
    // Walk backwards to find the most recent undoable entry (skip HARVEST)
    let lastUndoable = null;
    for (let i = sessionEntries.length - 1; i >= 0; i--) {
      if (sessionEntries[i].action !== 'HARVEST') {
        lastUndoable = sessionEntries[i];
        break;
      }
    }
    if (!lastUndoable) {
      setFb('info', 'Keine Scans zum Rückgängig machen');
      return;
    }
    const btn = document.querySelector('[data-scan-id="' + lastUndoable._tempId + '"] .sle-undo');
    if (btn) undoScanEntry(btn);
  }
});
// End session → show summary
function endScanSession() {
  if (sessionEntries.length === 0) return;
  // Summary lives in the "current" tab panel — make sure it's visible
  if (typeof switchScanTab === 'function') switchScanTab('current');
  const sumEl = document.getElementById('scan-session-summary');
  // Hide log, show summary
  document.getElementById('scan-modal-log').style.display = 'none';
  document.getElementById('scan-toast').style.display = 'none';
  sumEl.style.display = 'block';
  const dur = sessionStartTime ? Math.round((Date.now() - sessionStartTime) / 60000) : 0;
  const startStr = sessionStartTime
    ? new Date(sessionStartTime).toLocaleTimeString('de', { hour: '2-digit', minute: '2-digit' })
    : '';
  const endStr = new Date().toLocaleTimeString('de', { hour: '2-digit', minute: '2-digit' });
  // Count by action
  const counts = { ADD: 0, MOVE: 0, REMOVE: 0, HARVEST: 0 };
  const touchedBatches = new Map();
  sessionEntries.forEach((e) => {
    if (counts[e.action] !== undefined) counts[e.action]++;
    if (e.batch && !touchedBatches.has(e.batch)) touchedBatches.set(e.batch, e.species || '');
  });
  // Location summary
  const locSummary = [];
  if (counts.ADD > 0) {
    const locs = {};
    sessionEntries
      .filter((e) => e.action === 'ADD')
      .forEach((e) => {
        locs[e.to] = (locs[e.to] || 0) + 1;
      });
    Object.entries(locs).forEach(([l, n]) => locSummary.push(n + ' Bags → ' + esc(l)));
  }
  if (counts.MOVE > 0) {
    const moves = {};
    sessionEntries
      .filter((e) => e.action === 'MOVE')
      .forEach((e) => {
        const k = esc(e.from) + ' → ' + esc(e.to);
        moves[k] = (moves[k] || 0) + 1;
      });
    Object.entries(moves).forEach(([k, n]) => locSummary.push(n + ' Bags ' + k));
  }
  let batchHtml = '';
  touchedBatches.forEach((sp, bid) => {
    batchHtml += '<span>' + esc(bid) + (sp ? ' (' + esc(sp) + ')' : '') + '</span>';
  });
  sumEl.innerHTML =
    '<h3>' +
    t('scan.sessionSummary') +
    '</h3>' +
    '<div class="scan-summary-grid">' +
    '<div class="scan-summary-stat"><div class="ss-num">' +
    scan.count +
    '</div><div class="ss-lbl">' +
    t('scan.totalCount') +
    '</div></div>' +
    (counts.ADD
      ? '<div class="scan-summary-stat" style="border-top:3px solid #86efac"><div class="ss-num">' +
        counts.ADD +
        '</div><div class="ss-lbl">ADD</div></div>'
      : '') +
    (counts.MOVE
      ? '<div class="scan-summary-stat" style="border-top:3px solid #93c5fd"><div class="ss-num">' +
        counts.MOVE +
        '</div><div class="ss-lbl">MOVE</div></div>'
      : '') +
    (counts.REMOVE
      ? '<div class="scan-summary-stat" style="border-top:3px solid #fca5a5"><div class="ss-num">' +
        counts.REMOVE +
        '</div><div class="ss-lbl">REMOVE</div></div>'
      : '') +
    (counts.HARVEST
      ? '<div class="scan-summary-stat" style="border-top:3px solid #fcd34d"><div class="ss-num">' +
        counts.HARVEST +
        '</div><div class="ss-lbl">HARVEST</div></div>'
      : '') +
    (sessionErrors
      ? '<div class="scan-summary-stat" style="border-top:3px solid #fca5a5"><div class="ss-num">' +
        sessionErrors +
        '</div><div class="ss-lbl">' +
        t('scan.sessionErrors') +
        '</div></div>'
      : '') +
    '</div>' +
    '<div class="fs-meta" style="color:var(--c-text-muted);margin-bottom:8px">' +
    t('scan.duration') +
    ': ' +
    dur +
    ' Min' +
    (startStr ? ' (' + startStr + ' – ' + endStr + ')' : '') +
    '</div>' +
    (batchHtml ? '<div class="scan-summary-batches">' + t('scan.batches') + ': ' + batchHtml + '</div>' : '') +
    (locSummary.length ? '<div class="fs-meta" style="margin-bottom:12px">' + locSummary.join(' · ') + '</div>' : '') +
    '<div class="scan-summary-actions">' +
    '<button class="btn-xs" onclick="closeScanSession()">' +
    t('scan.close') +
    '</button>' +
    '<button class="btn-xs green" onclick="newScanSession()">' +
    t('scan.newSession') +
    '</button>' +
    '</div>';
}
function closeScanSession() {
  document.getElementById('scan-session-summary').style.display = 'none';
  document.getElementById('scan-modal-log').style.display = '';
  document.getElementById('scan-toast').style.display = '';
  closeScanModal();
}
function newScanSession() {
  document.getElementById('scan-session-summary').style.display = 'none';
  document.getElementById('scan-modal-log').style.display = '';
  document.getElementById('scan-toast').style.display = '';
  document.getElementById('scan-modal-log').innerHTML = '';
  sessionEntries = [];
  sessionStartTime = null;
  sessionErrors = 0;
  _lastScanVal = null;
  scan.count = 0;
  if (typeof renderScanSuccesses === 'function') renderScanSuccesses();
  resetScan();
}
let _scanTempIdCounter = 0;

// I-12: handle a 409 zone_mismatch response from POST /api/scan-log. The server
// rejected the MOVE because another user moved the bag while this client's
// view was stale (typical flow: offline scan that replayed after the bag was
// moved by someone else online). We discard the local in-memory entry and
// surface a toast so the user knows their MOVE didn't apply.
function handleZoneMismatch(r, entries) {
  if (!r || r.error !== 'zone_mismatch') return false;
  const list = Array.isArray(entries) ? entries : [entries];
  // The server rejects the ENTIRE POST on a single conflict, so none of these
  // entries persisted. Drop them all from local state — not just the offending
  // bag — or the other N-1 entries of a bulk move linger as phantom moves on
  // the dashboard until the next resync silently reverts them.
  for (const e of list) {
    if (!e) continue;
    const i = scanLog.lastIndexOf(e);
    if (i >= 0) scanLog.splice(i, 1);
    const j = movements.lastIndexOf(e);
    if (j >= 0) movements.splice(j, 1);
    modeRunUntally(e);
  }
  if (typeof setFb === 'function') setFb('err', movedMeanwhileMsg(r.bag, r.current_zone));
  if (typeof renderStatus === 'function') renderStatus();
  if (typeof updateSD === 'function') updateSD();
  // Der eigene Stand war alt, sonst gäbe es den Konflikt nicht. Gleich den neuen
  // holen: dann geht der nächste Scan desselben Beutels durch, statt wieder
  // gegen denselben alten Platz zu laufen.
  if (typeof syncNow === 'function') syncNow();
  return true;
}
// Ein Umzug, den der Server abgelehnt hat, weil der Beutel inzwischen woanders
// ist. Auf Deutsch, mit dem Namen des Platzes, und mit dem, was jetzt zu tun ist
// — vorher stand hier "MOVE rejected: bag … was moved by another user".
function movedMeanwhileMsg(bag, zone) {
  return zone
    ? t('scanFb.movedMeanwhile', { bag: bag || '', loc: zoneDisplayName(zone) })
    : t('scanFb.movedMeanwhileGone', { bag: bag || '' });
}

// I-11: idempotency key for scan-log POSTs. The offline queue (sw.js) replays
// queued POSTs verbatim; without a stable per-entry key, a network partition
// that times out on the client but succeeds on the server would leave the
// entry queued and replay it next time, creating a duplicate. The server
// upserts on client_uuid (UNIQUE INDEX), so retries are safe.
// crypto.randomUUID is available in all modern browsers and Node 16+; the
// fallback covers very old browsers (no offline support there anyway).
function newScanUuid() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  // Fallback: 16 random bytes formatted as UUID v4. Not cryptographically
  // strong, but the only consumer is the unique index; sufficient for dedup.
  const r = Math.random;
  const hex = (n) =>
    Math.floor(r() * 16 ** n)
      .toString(16)
      .padStart(n, '0');
  return `${hex(8)}-${hex(4)}-4${hex(3)}-${(8 + Math.floor(r() * 4)).toString(16)}${hex(3)}-${hex(12)}`;
}

// Etwas Gescanntes ist auf diesem Telefon unbekannt. Bevor die Meldung "nicht
// im System" lautet, einmal den Stand vom Server holen und denselben Scan noch
// einmal durchlaufen lassen: die Listen hier sind nur so neu wie die letzte
// Abfrage, und eine App, die im Hintergrund lag oder kurz kein Netz hatte, kann
// weit zurück sein. "Unbekannter Barcode: 1234567" stand dann über einem
// Etikett, das der Server sehr wohl kannte — und der einzige Ausweg, den man
// fand, war die App neu zu starten.
function scanAfterSync(raw) {
  setFb('info', t('scanFb.checking'));
  syncNow().then(function (ok) {
    if (!ok) {
      // Weder hier bekannt noch nachzufragen: dann sagen, woran es liegt, und
      // was hilft — nicht so tun, als gäbe es das Etikett nicht.
      setFb('err', t('scanFb.unknownOffline'));
      return;
    }
    processScan(raw, { synced: true });
  });
}

// Ein Strichcode aus der Zeit vor den siebenstelligen Nummern, oder einer, der
// gedruckt wurde, als dieses Telefon die Nummer des Beutels noch nicht kannte:
//   KUERZEL_MMDD_N  → nach _ → - drei Teile
//   SP_ST_MMDD_N    → vier Teile (altes spAbbrev + Stammpräfix)
// Gibt null zurück, wenn val keins von beiden ist; sonst { bag, batch }, oder
// { ambiguous: [...] }, oder {} für "keine passende Charge".
//
// Der Beutel wird über seine NUMMER gesucht, nicht über einen zusammengesetzten
// Text. Vorher hieß "_7" immer "-07" — aber Blöcke aus einem Substratansatz
// tragen in einer Charge unter zehn Beuteln "-7", und der Scan suchte einen
// Beutel, den es nicht gibt: "nicht im System" über einem Block, der dort stand.
// Und es galt die erste Charge mit Kürzel und Tag; zwei Chargen vom selben Tag
// (-01, -02) haben beide einen Beutel 7, und der Scan nahm stumm den falschen.
function legacyBagMatch(val) {
  const parts = val.split('-');
  let num, passt;
  if (parts.length === 3 && /^\d{4}$/.test(parts[1]) && /^\d{1,2}$/.test(parts[2])) {
    const [kz, mmdd] = parts;
    num = parseInt(parts[2], 10);
    passt = (b) => (b.strainKuerzel || b.strain || '').toUpperCase() === kz && _batchMmdd(b) === mmdd;
  } else if (parts.length === 4 && /^\d{4}$/.test(parts[2]) && /^\d{1,2}$/.test(parts[3])) {
    const [sp, st, mmdd] = parts;
    num = parseInt(parts[3], 10);
    passt = (b) =>
      spAbbrev(b.species) === sp && (b.strain || '000').slice(0, 3).toUpperCase() === st && _batchMmdd(b) === mmdd;
  } else {
    return null;
  }
  const kandidaten = batches.filter(passt);
  const treffer = [];
  for (const b of kandidaten) {
    for (const bag of b.bags || []) {
      if (parseInt(String(bag).split('-').pop(), 10) === num) treffer.push({ bag, batch: b.batchId });
    }
  }
  if (treffer.length === 1) return treffer[0];
  if (treffer.length > 1) return { ambiguous: treffer.map((x) => x.bag) };
  // Die Charge gibt es, den Beutel in ihr nicht: so wie früher weiterreichen,
  // damit die Meldung danach den Beutel nennt, statt die Charge zu verneinen.
  if (kandidaten.length) {
    return { bag: kandidaten[0].batchId + '-' + String(num).padStart(2, '0'), batch: kandidaten[0].batchId };
  }
  return {};
}
function _batchMmdd(b) {
  const d = b.batchId.split('-')[1];
  return d ? d.slice(2, 4) + d.slice(0, 2) : '';
}

function processScan(raw, opts) {
  // Underscore/hyphen convention:
  // - Location barcodes use UNDERSCORES (e.g. INC_MUSTER_01, SPAWN_R1) — kept as-is
  // - Action commands use UNDERSCORES — kept as-is
  // - Bag/batch IDs use HYPHENS internally (e.g. BLUES-260101-01-06)
  // German HID barcode scanners send underscores for hyphens, so we convert
  // only for non-location, non-action values. Adding new location formats that
  // use hyphens would break this logic — always use underscores for locations.
  let val = raw.trim().toUpperCase();
  if (!val) return;
  // Zweiter Durchlauf nach frischem Stand (scanAfterSync): was jetzt noch
  // unbekannt ist, ist es wirklich, und die Meldung darf das sagen.
  const synced = !!(opts && opts.synced);

  // ── Numeric barcode lookup (new system: 7+ digit numbers) ──
  const numVal = parseInt(val, 10);
  if (/^\d{7,}$/.test(val) && numVal >= 1000000) {
    const entry = barcodeRegistry.get(numVal);
    if (!entry) {
      if (!synced) {
        scanAfterSync(raw);
        return;
      }
      // Die Nummern, die diese App druckt, haben sieben Stellen. Längere sind
      // Produkt-Barcodes (EAN hat dreizehn) — die kennt hier niemand, und es
      // hilft, das zu sagen, statt "gelöscht?" zu fragen.
      setFb('err', val.length <= 8 ? t('scanFb.labelNotInSystem') : t('scanFb.notOurLabel'));
      return;
    }
    if (entry.type === 'bag') {
      val = entry.id; // e.g. "SHI-260101-01-06"
      setFb('info', t('scanFb.matched', { val: val, batch: val.split('-').slice(0, -1).join('-') }));
    } else if (entry.type === 'culture') {
      val = entry.id; // e.g. "MC-SHI-260101-01"
    } else if (entry.type === 'zone' || entry.type === 'rack') {
      val = entry.id; // e.g. "INC" or "INC_R1"
    }
  } else {
    // ── Legacy barcode fallback ──
    if (ACTIONS.includes(val) || LOCS.includes(val)) {
      /* keep underscores */
    } else {
      val = val.replace(/_/g, '-');
    } // German HID keyboard fix for bag IDs
    const legacy = legacyBagMatch(val);
    if (legacy) {
      if (legacy.bag) {
        val = legacy.bag;
        setFb('info', t('scanFb.matched', { val: val, batch: legacy.batch }));
      } else if (!synced) {
        scanAfterSync(raw);
        return;
      } else if (legacy.ambiguous) {
        setFb('err', t('scanFb.legacyAmbiguous', { list: legacy.ambiguous.join(', ') }));
        return;
      } else {
        setFb('err', t('scanFb.noBatchFound', { val: val }));
        return;
      }
    }
  }
  if (ACTIONS.includes(val)) {
    // Ein gedrucktes USED-Etikett aus der Zeit vor dem einen Raus-Knopf stellt
    // Raus scharf: Körnerbrut geht darüber ohnehin als verbraucht raus.
    armScanAction(val === 'USED' ? 'REMOVE' : val);
    return;
  }
  if (LOCS.includes(val)) {
    // Warn if scanning a zone that has racks — suggest using a rack instead
    const zoneObj = zones.find((z) => z.id === val);
    const isZoneWithRacks = zoneObj && zoneObj.racks.length > 0;
    if (scan.action === 'ADD') {
      scan.to = val;
      updateSD();
      setFb(
        isZoneWithRacks ? 'warn' : 'ok',
        isZoneWithRacks
          ? t('scanFb.preferRack', { loc: val, example: zoneObj.racks[0].id })
          : t('scanFb.location', { loc: val })
      );
      return;
    }
    // Kein Vorgang oder Umziehen: ein Platz-Etikett heißt "ab jetzt hierhin" —
    // derselbe Umzug, den der Umziehen-Knopf startet. Mit schon gesetztem Ziel
    // war das vorher ein Fehler, der mitten im laufenden Umzug verlangte, man
    // solle erst einen Vorgang scannen.
    if (!scan.action || scan.action === 'MOVE') {
      armMoveRun(val);
      if (isZoneWithRacks) setFb('warn', t('scanFb.preferRack', { loc: val, example: zoneObj.racks[0].id }));
      return;
    }
    if (scan.action === 'MOVE_BATCH') {
      scan.to = val;
      updateSD();
      setFb(
        isZoneWithRacks ? 'warn' : 'ok',
        isZoneWithRacks
          ? t('scanFb.preferRack', { loc: val, example: zoneObj.racks[0].id })
          : t('scanFb.to', { loc: zoneDisplayName(val) })
      );
      return;
    }
    // Ernten, Entfernen, Kontamination: da gibt es keinen Platz zu wählen.
    setFb('err', t('scanFb.locNotNeeded', { loc: zoneDisplayName(val), action: scanActionName(scan.action) }));
    return;
  }
  // Culture ID scan → auto-fill parent (lab work) or source (new batch), else open lineage
  // Die Kennung einer Kultur: Art, Kürzel der Sorte, der Stamm, wenn einer gewählt
  // war (logLabWork hängt ihn an), Tag und Nummer — PD-KO-KOKQ07-090926-05. Ohne
  // den Stamm-Teil hier lief so ein Etikett in die Beutel-Logik und kam als "nicht
  // im System" zurück, obwohl die Kultur in der Liste stand. SY: Spritzen genauso.
  // Dasselbe Muster steht in isKnownBarcode.
  if (/^(MC|PD|LC|SY|G2G|GS)-[A-Z0-9]+(?:-[A-Z0-9]+)?-\d{6}-\d{2}$/.test(val)) {
    // Lab stocktake: a scan means "this culture is on the shelf in front of me",
    // so it ticks the check list rather than running the normal culture flow.
    // Checked before the used/contam guard below — finding a written-off culture
    // is exactly the correction the check exists to make.
    if (_zcScanMode && _zcMode === 'culture') {
      labCheckScanned(val);
      return;
    }
    // Quick dialog asked for a source culture: take it there instead of opening
    // the lineage view. Refused if it is not a type this dialog state accepts.
    if (_inocScanPrefix) {
      const hit = cultures.find((x) => x.id.toUpperCase() === val);
      if (!hit) {
        if (!synced) {
          scanAfterSync(raw);
          return;
        }
        _scanBeep(300, 150);
        setFb('err', t('scanFb.cultureNotInSystem', { id: val }));
        return;
      }
      if (cultureGone(hit)) {
        _scanBeep(300, 150);
        setFb('err', cultureRefusal(hit));
        return;
      }
      const addErr =
        _inocScanPrefix === 'wkb'
          ? wkbInocAdd(hit.id)
          : _inocScanPrefix === 'ms-q'
            ? msqInocAdd(hit.id)
            : inocAdd(hit.id);
      if (addErr) {
        _scanBeep(300, 150);
        setFb('err', addErr);
        return;
      }
      if (_inocScanPrefix === 'ms-q') msQuickRender();
      else inocRender(_inocScanPrefix);
      _scanBeep(800, 60);
      setFb('ok', t('scanFb.cultureAutofilled', { id: hit.id }));
      closeCamScan();
      return;
    }
    const c = cultures.find((x) => x.id.toUpperCase() === val);
    if (c && scan.action === 'REMOVE') {
      kulturRausScan(c);
      return;
    }
    if (c) {
      if (cultureGone(c)) {
        setFb('err', cultureRefusal(c));
        return;
      }
      closeCamScan();
      // If new-batch form is visible, auto-fill source + strain
      const nbPanel = document.getElementById('sp-batch-new');
      if (nbPanel && nbPanel.classList.contains('active')) {
        const cultureSel = document.getElementById('nb-culture');
        if (cultureSel) cultureSel.value = c.id;
        if (c.strainId) document.getElementById('nb-strain-sel').value = String(c.strainId);
        const nbStInput = document.getElementById('nb-strain-text');
        if (nbStInput && c.strainText) nbStInput.value = c.strainText;
        renderNbGrainBanner();
        setFb('ok', t('scanFb.cultureAutofilled', { id: c.id }));
        return;
      }
      // If lab work form is visible, auto-fill parent instead of opening lineage
      const lwPanel = document.getElementById('sp-lab-work');
      const parentSel = document.getElementById('lw-parent');
      const parentRow = document.getElementById('lw-parent-row');
      if (lwPanel && lwPanel.classList.contains('active') && parentRow && parentRow.style.display !== 'none') {
        parentSel.value = c.id;
        if (c.strainId) document.getElementById('lw-st').value = String(c.strainId);
        const stInput = document.getElementById('lw-strain-text');
        if (stInput && c.strainText) stInput.value = c.strainText;
        lwPreview();
        setFb('ok', 'Parent gesetzt: ' + c.id);
        return;
      }
      // Ein Fenster mit Knöpfen, wie beim Beutel. Vorher ging die Kamera zu und
      // der Stammbaum auf, ohne einen Knopf — gescannt, und dann nichts.
      openCultureSheet(c);
      setFb('ok', t('scanFb.cultureScanned', { val: val }), { noModal: true });
      return;
    }
    // Eine Kultur-Nummer, die hier keiner kennt. Ohne diese Stelle lief sie
    // weiter in die Beutel-Logik (sie endet auf -NN wie ein Beutel) und kam als
    // "Charge MC-… gibt es nicht" heraus.
    if (!synced) {
      scanAfterSync(raw);
      return;
    }
    kulturAufnehmenAnbieten(val);
    return;
  }
  // Ein Beutel ist, was eine Charge als Beutel führt — nicht nur, was auf zwei
  // Ziffern endet. Blöcke aus einem Substratansatz werden nur so breit gezählt,
  // wie die Charge groß ist: der siebte von acht heißt "-7". Die Zwei-Ziffern-
  // Regel allein ließ jeden davon als "kein Etikett aus diesem System" durchfallen,
  // obwohl er dastand. Für Beutel, die dieses Telefon noch nicht kennt, gilt sie
  // weiter: die fragen erst beim Server nach.
  const bagOwner = batches.find((b) => (b.bags || []).some((x) => String(x).toUpperCase() === val));
  const isBag = !!bagOwner || /-\d{2}$/.test(val);
  const batchId = bagOwner ? bagOwner.batchId : isBag ? val.split('-').slice(0, -1).join('-') : val;
  const batch = batches.find((b) => b.batchId.toUpperCase() === batchId.toUpperCase());
  // Ein Beutel, dessen Charge hier niemand kennt. Vorher ging er trotzdem in die
  // Vorgänge und kam als "hat keinen bekannten Standort — erst mit ADD
  // platzieren" heraus: eine Anweisung, die nicht helfen kann, weil es die
  // Charge gar nicht gibt — oder weil das Telefon sie noch nicht kennt. Die
  // Inventur ist ausgenommen; ihr Abgleich will auch fremde Beutel sehen.
  if (isBag && !batch && !_zcScanMode) {
    if (!synced) {
      scanAfterSync(raw);
      return;
    }
    setFb('err', t('scanFb.batchNotInSystem', { bag: val, batch: batchId }));
    return;
  }
  // When the bag-select modal is open and we scan a bag, toggle it in the selection
  // instead of opening a new bag-info modal.
  if (
    isBag &&
    bsBatchId &&
    document.getElementById('m-bagselect').classList.contains('open') &&
    batchId.toUpperCase() === bsBatchId.toUpperCase()
  ) {
    const res = bsToggleBag(val);
    if (res.toggled) {
      _scanBeep(800, 60);
      setFb(
        'ok',
        t('bagSelect.toggled', { bag: val, action: res.added ? t('bagSelect.added') : t('bagSelect.removed') })
      );
    } else {
      _scanBeep(300, 150);
      setFb('err', t('scanFb.bagNotPlaced', { bag: val }));
    }
    return;
  }
  // Scan belongs to a different batch while the select modal is open: warn.
  if (
    isBag &&
    bsBatchId &&
    document.getElementById('m-bagselect').classList.contains('open') &&
    batchId.toUpperCase() !== bsBatchId.toUpperCase()
  ) {
    _scanBeep(300, 150);
    setFb('err', t('bagSelect.notInBatch', { bag: val, id: bsBatchId }));
    return;
  }
  if (batch || isBag) {
    // Stocktake: a scan means "this bag is physically in front of me", so it
    // ticks off the check list instead of running the normal action flow.
    if (_zcScanMode && isBag) {
      zoneCheckScanned(val, batchId);
      return;
    }
    // A "Beimpft mit" field has the camera: the worker is naming the grain bag
    // they inoculated from, not asking about the bag. Only with no action armed,
    // so an explicit MOVE/REMOVE still wins. Closing the camera is what brings
    // the quick dialog back into view (it steps aside for the camera).
    if (isBag && !scan.action && _inocScanPrefix) {
      const err =
        _inocScanPrefix === 'wkb' ? wkbInocAdd(val) : _inocScanPrefix === 'ms-q' ? msqInocAdd(val) : inocAdd(val);
      if (err) {
        _scanBeep(300, 150);
        setFb('err', err);
        return;
      }
      if (_inocScanPrefix === 'ms-q') msQuickRender();
      else inocRender(_inocScanPrefix);
      _scanBeep(800, 60);
      setFb('ok', t('inoc.added', { id: val }));
      closeCamScan();
      return;
    }
    if (!scan.action) {
      openBagInfo(val, batchId, batch);
      return;
    }
    if (scan.action === 'HARVEST') {
      showHarvestPanel(isBag ? val : batchId, batchId);
      return;
    }
    if (scan.action === 'CONTAM') {
      // Eine ganze Charge hat keine Beutelnummer — dafür gibt es nichts zu
      // sammeln, das Formular geht wie bisher sofort auf.
      if (!isBag) {
        // Es sei denn, es liegen schon Beutel in der Liste: die Meldung über
        // die ganze Charge würde sie ersetzen, ohne dass jemand es sieht.
        if (_crTargets.length) {
          setFb('err', t('contam.batchWhileCollecting', { n: _crTargets.length }));
          return;
        }
        // Die Kamera muss zu, sonst läge sie über dem Formular (beide z-index
        // 200, die Kamera steht im Quelltext dahinter).
        closeCamScan();
        openContamReport(null, batchId, null);
        return;
      }
      // Sonst wird gesammelt: der Scanner bleibt in CONTAM, die Kamera bleibt
      // offen, und der Beutel legt sich zu den anderen. Das Formular kommt
      // einmal am Ende — vorher stand es nach jedem einzelnen Scan im Weg.
      const r = crToggleTarget(val, batchId);
      _scanBeep(r.added ? 800 : 500, 60);
      setFb(
        'ok',
        r.added ? t('contam.collected', { bag: val, n: r.count }) : t('contam.uncollected', { bag: val, n: r.count })
      );
      // Ein offenes Formular zeigt die Liste mit — am Tisch scannt man mit dem
      // Handscanner weiter, während es aufsteht.
      if (document.getElementById('m-contam-report').classList.contains('open')) _crRenderTargets();
      updateSD();
      return;
    }
    // Raus mit einem Körnerbeutel heißt: er ging in Blöcke. Gebucht wie
    // "Verbraucht", damit er nicht als weggeworfen zählt.
    if (scan.action === 'REMOVE' && isBag && batch && batch.batchType === 'grain') {
      verbrauchtScan(val, batch);
      return;
    }
    if (scan.action === 'ADD' && !scan.to) {
      setFb('err', t('scanFb.scanLocFirst'));
      return;
    }
    if ((scan.action === 'MOVE' || scan.action === 'MOVE_BATCH') && !scan.to) {
      setFb('err', t('scanFb.scanToFirst'));
      return;
    }
    // MOVE_BATCH: scan any bag or batch ID → move entire batch
    if (scan.action === 'MOVE_BATCH' && batch) {
      moveBatchTo(batch, scan.to, function (moved, skipped) {
        if (!moved) {
          _scanBeep(500, 120);
          // Alle schon am Ziel ist kein Fehler, sondern nichts zu tun.
          setFb(
            skipped ? 'warn' : 'err',
            batch.batchId +
              ': ' +
              (skipped
                ? t('batch.allAlreadyAt', { n: skipped, loc: zoneDisplayName(scan.to) })
                : t('batch.noBagsToMove'))
          );
          updateSD();
          return;
        }
        setFb(
          'ok',
          'MOVE BATCH ' +
            batch.batchId +
            ': ' +
            moved +
            ' Bags → ' +
            scan.to +
            (skipped ? ' (' + skipped + ' übersprungen)' : '')
        );
        scan.count += moved;
        updateSD();
      });
      return;
    }
    // Was dieser Scan bucht. Meist der Vorgang selbst — beim Umziehen wird ein
    // Beutel ohne Platz im System am Ziel eingelagert statt umgezogen (unten).
    let act = scan.action;
    // MOVE: auto-derive FROM from bag's last known location
    if (scan.action === 'MOVE') {
      // Umgezogen wird Beutel für Beutel; eine Chargen-Nummer allein hat keinen
      // Platz, den man ändern könnte.
      if (!isBag) {
        _scanBeep(300, 150);
        setFb('err', t('scanFb.moveNeedsBag', { batch: batchId }));
        return;
      }
      const bagLast = [...scanLog]
        .reverse()
        .find(
          (e) =>
            (e.bag || '').toUpperCase() === val.toUpperCase() &&
            (e.action === 'ADD' || e.action === 'MOVE' || e.action === 'REMOVE')
        );
      if (!bagLast || bagLast.action === 'REMOVE') {
        // Laut System liegt der Beutel nirgends: nie eingelagert, oder als
        // entfernt gebucht. Wer ihn in der Hand hat, weiß es besser. Hier stand
        // "erst mit ADD platzieren" — ein Weg, den es am Telefon nicht gibt, und
        // die Reihe blieb an diesem Beutel hängen. Jetzt reicht derselbe Beutel
        // ein zweites Mal, dann wird er am Ziel eingelagert; ein einzelner
        // versehentlicher Scan bucht nichts.
        const key = val + '>' + scan.to;
        if (_pendingPlace !== key) {
          _pendingPlace = key;
          clearTimeout(_pendingPlaceTimer);
          _pendingPlaceTimer = setTimeout(() => {
            _pendingPlace = null;
          }, CONFIRM_SCAN_MS);
          _scanBeep(300, 150);
          setFb(
            'warn',
            t(bagLast ? 'scanFb.bagRemovedPlace' : 'scanFb.bagNotPlacedPlace', {
              bag: val,
              loc: zoneDisplayName(scan.to)
            })
          );
          return;
        }
        clearTimeout(_pendingPlaceTimer);
        _pendingPlace = null;
        act = 'ADD';
        scan.from = null;
      } else {
        const curLoc = bagLast.to || null;
        if (curLoc && curLoc.toUpperCase() === scan.to.toUpperCase()) {
          // Schon da: kein Fehler, nur nichts zu tun.
          _scanBeep(500, 120);
          setFb('warn', t('scanFb.bagAlreadyAt', { bag: val, loc: zoneDisplayName(scan.to) }));
          return;
        }
        scan.from = curLoc;
      }
    }
    // REMOVE: auto-derive FROM from bag's last known location.
    //
    // Entsorgen ist ein Scan pro Beutel. Hier stand eine Doppel-Bestätigung:
    // jeden Beutel zweimal scannen, mit drei Sekunden dazwischen, weil die
    // Kamera dasselbe Etikett so lange nicht wieder annimmt. Für eine Reihe
    // verschimmelter Beutel hieß das: niemand benutzt es. Die Bestätigung ist
    // jetzt der Knopf, der dafür an sein muss; jeder Beutel steht mit seinem
    // Rückgängig im Protokoll, und ↩ in der Kamera nimmt den letzten zurück.
    if (scan.action === 'REMOVE') {
      const bagLastR = [...scanLog]
        .reverse()
        .find(
          (e) =>
            (e.bag || '').toUpperCase() === val.toUpperCase() &&
            (e.action === 'ADD' || e.action === 'MOVE' || e.action === 'REMOVE')
        );
      // Schon entsorgt: nichts zu tun. Vorher bekam er einen zweiten Eintrag.
      if (isBag && bagLastR && bagLastR.action === 'REMOVE') {
        _scanBeep(500, 120);
        setFb('warn', t('scanFb.alreadyRemoved', { bag: val }));
        return;
      }
      scan.from = bagLastR ? bagLastR.to : null;
    }
    // Duplicate detection: warn if same bag+action+to already in session
    const dupeKey = val + '|' + act + '|' + scan.to;
    if (act !== 'REMOVE') {
      const hasDupe = sessionEntries.some((e) => (e.bag || e.batch) + '|' + e.action + '|' + e.to === dupeKey);
      if (hasDupe) {
        if (_pendingDupe === dupeKey) {
          clearTimeout(_pendingDupeTimer);
          _pendingDupe = null;
          // Confirmed duplicate — fall through
        } else {
          _pendingDupe = dupeKey;
          clearTimeout(_pendingDupeTimer);
          _pendingDupeTimer = setTimeout(() => {
            _pendingDupe = null;
          }, CONFIRM_SCAN_MS);
          _scanBeep(500, 120);
          setFb('warn', t('scanFb.dupeConfirm', { bag: val }));
          return;
        }
      }
    }
    const tempId = 's' + ++_scanTempIdCounter;
    const isMove = act === 'MOVE' || act === 'MOVE_BATCH';
    const entry = {
      time: new Date().toISOString(),
      action: act,
      batch: batchId,
      bag: isBag ? val : null,
      from: act === 'ADD' ? null : scan.from,
      to: scan.to,
      species: batch?.species,
      strain: batch?.strain,
      user: currentUser?.username || null,
      client_uuid: newScanUuid(),
      // I-12: optimistic concurrency snapshot for offline-queue replays.
      // Only meaningful for MOVE/MOVE_BATCH (ADD has no expected zone).
      expected_current_zone: isMove && scan.from ? toZone(scan.from) : null,
      _tempId: tempId
    };
    scanLog.push(entry);
    movements.push(entry);
    if (!sessionStartTime) sessionStartTime = Date.now();
    sessionEntries.push(entry);
    if (scanChannel)
      scanChannel.postMessage({
        type: 'scan-entry',
        entry: { bag: entry.bag, batch: entry.batch, action: entry.action, to: entry.to }
      });
    scan.count++;
    // I-12 applies: on a zone_mismatch the server rejected the MOVE because the
    // bag has since been moved by someone else — postScanEntries drops the local
    // entry and toasts, without retrying into the same 409.
    postScanEntries([entry]);
    _lastScanVal = isBag ? val : batchId;
    // Umziehen: mit den Namen der Plätze statt ihrer Kürzel, und mitgezählt —
    // die Zahl steht auch auf dem Knopf, solange die Kamera das Bild füllt.
    if (scan.action === 'MOVE') {
      const n = modeRunTally('MOVE', entry.to, entry);
      const zu = zoneDisplayName(entry.to);
      setFb(
        'ok',
        act === 'ADD'
          ? t('scanFb.placedLogged', { bag: val, to: zu, n: n })
          : t('scanFb.moveLogged', { bag: val, from: entry.from ? zoneDisplayName(entry.from) : '?', to: zu, n: n }),
        entry
      );
      updateSD();
      return;
    }
    // Entsorgen: der Beutel beim Namen, und mitgezählt wie beim Umziehen.
    if (act === 'REMOVE') {
      const n = modeRunTally('REMOVE', null, entry);
      setFb('ok', t('scanFb.trashLogged', { bag: val, n: n }), entry);
      updateSD();
      return;
    }
    const fbTo = scan.to ? ' \u2192 ' + zoneDisplayName(scan.to) : '';
    setFb('ok', t('scanFb.logged', { action: scan.action, val: val, to: fbTo, n: scan.count }), entry);
    updateSD();
    return;
  }
  // URL QR codes: inform user instead of showing "unknown"
  if (/^https?:\/\//i.test(raw.trim())) {
    setFb('info', 'QR-Code enthält URL: ' + raw.trim().slice(0, 80) + (raw.trim().length > 80 ? '…' : ''));
    return;
  }
  // Nichts davon. Ein neuer Platz oder eine neue Charge kann aber jünger sein als
  // der Stand auf diesem Telefon — erst nachfragen, dann urteilen.
  if (!synced) {
    scanAfterSync(raw);
    return;
  }
  setFb('err', t('scanFb.unknown', { val: val }));
}

// Der Vorgang in Worten, für Meldungen. Die Kürzel (MOVE, HARVEST …) stehen auf
// den gedruckten Etiketten und im Log; wer eine Meldung liest, braucht das Wort.
function scanActionName(a) {
  const s = t('scanAct.' + a);
  return s === 'scanAct.' + a ? a : s;
}
// Raus aus dem Bestand: verbraucht, verkauft oder kontaminiert.
function cultureGone(c) {
  return c.status === 'used' || c.status === 'sold' || c.status === 'contam';
}
// Warum eine Kultur nicht genommen werden kann, in Worten statt "ist contam".
function cultureRefusal(c) {
  if (c.status === 'contam') return t('scanFb.cultureContam', { id: c.id });
  if (c.status === 'sold') return t('scanFb.cultureSold', { id: c.id });
  return t('scanFb.cultureUsed', { id: c.id });
}
// ── Verbraucht: Körnerbrut aus dem Bestand ──────────────────
// Ein Körnerbeutel, mit dem Blöcke beimpft wurden, stand weiter im Bestand, bis
// ihn jemand entsorgte — und dann zählte er als weggeworfen. "Verbraucht" bucht
// ihn aus wie Entsorgen: ein Knopf, dann Beutel für Beutel scannen, ↩ nimmt den
// letzten zurück. Gebucht wird, was das Anlegen einer Charge bucht, wenn dort
// Körnerbrut als verbraucht angegeben wird (inocVerbrauchtBuchen): ein REMOVE mit
// dem Grund "spawn". Ohne die Charge dahinter — in welche der Beutel ging, weiß
// der Scanner nicht; das weiß "Charge anlegen", und dort wird sie mitgeschrieben.
function verbrauchtScan(val, batch) {
  const bag = (batch.bags || []).find((x) => x.toUpperCase() === val.toUpperCase()) || val;
  const last = buildLastPlacementByBag().get(bag.toUpperCase());
  if (last && last.action === 'REMOVE') {
    _scanBeep(500, 120);
    setFb('warn', t(istVerbraucht(last) ? 'scanFb.alreadyUsed' : 'scanFb.alreadyRemoved', { bag: bag }));
    return;
  }
  const [entry] = spawnBuchen([bag], 'spawn', { sitzung: true });
  _lastScanVal = bag;
  const n = modeRunTally('REMOVE', null, entry);
  setFb('ok', t('scanFb.usedLogged', { bag: bag, n: n }), entry);
  updateSD();
}
// ── Raus: eine Kultur aus dem System ─────────────────────────
// Im Raus-Modus der Kamera ist eine gescannte Kultur verbraucht — derselbe
// Status, den "Verbraucht" in der Kulturliste setzt. ↩ nimmt die letzte zurück
// (camUndoLastScan), darum merkt sich _kulturRaus, was vorher war.
const _kulturRaus = [];
function kulturRausScan(c) {
  if (cultureGone(c)) {
    _scanBeep(500, 120);
    setFb('warn', cultureRefusal(c));
    return;
  }
  _kulturRaus.push({ id: c.id, prev: c.status, at: Date.now() });
  if (_kulturRaus.length > 50) _kulturRaus.shift();
  setCultureStatus(c.id, 'used');
  _lastScanVal = c.id;
  const n = modeRunTally('REMOVE', null, null);
  _scanBeep(800, 60);
  setFb('ok', t('scanFb.cultureOut', { id: c.id, n: n }));
  updateSD();
}
// ── Das Kultur-Fenster ───────────────────────────────────────
// Eine gescannte Kultur zeigt, was sie ist, und was man mit ihr tun kann — im
// selben Fenster wie ein Beutel (m-baginfo), mit eigenen Knöpfen (data-bi="ci-…").
let ciCultureId = null;
function openCultureSheet(c) {
  biBagId = null;
  biBatchId = null;
  ciCultureId = c.id;
  document.getElementById('bi-title').textContent = c.id;
  const STATUS = { active: 'lab.active', stored: 'lab.stored', used: 'lab.usedUp', sold: 'lab.sold', contam: 'lab.contaminated' };
  const status = STATUS[c.status];
  const kinder = cultures.filter((x) => x.parentId === c.id).length;
  const met = (k, v) =>
    `<div class="met"><div class="met-l">${esc(k)}</div><div class="fs-base" style="font-weight:600">${v}</div></div>`;
  const name = c.strainName || c.species || '';
  document.getElementById('bi-body').innerHTML =
    ciVerfuegbarHtml(c) +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">' +
    met(t('ci.type'), esc(t('ci.type.' + c.type))) +
    met(t('batch.species'), spDot(name) + esc(name)) +
    met(t('batch.strain'), (c.strainText || '').trim() ? esc(c.strainText.trim()) : '\u2014') +
    met(t('ci.status'), esc(status ? t(status) : c.status || '')) +
    met(t('ci.created'), esc(c.created ? fmtDt(c.created) : '\u2014')) +
    '</div>' +
    ciGroesseHtml(c) +
    ciHerkunftHtml(c) +
    (kinder
      ? `<div class="fs-meta muted" style="margin-bottom:10px">${esc(t('ci.children', { n: kinder }))}</div>`
      : '');
  renderCiActions(c);
  closeCamScan();
  closeScanModal();
  document.getElementById('m-baginfo').classList.add('open');
}
// Wieviele aus demselben Ansatz noch da sind: dieselbe Kennung bis auf die
// letzte Nummer (SY-…-011026-01 bis -04). Das ist die erste Frage, wenn man ein
// Glas oder eine Spritze in der Hand hat, also steht es zuoberst — die Zahl groß,
// darunter die Nummern, die gemeinsam angesetzten, die schon raus sind,
// durchgestrichen und die gescannte hervorgehoben.
// Spritzen nur gleicher Größe: eine 10er und eine 50er vom selben Tag tragen
// dieselbe Kennung bis auf die Nummer, sind aber nicht dasselbe Angebot.
function ciGeschwister(c) {
  const stamm = c.id.slice(0, c.id.lastIndexOf('-') + 1);
  return cultures
    .filter(
      (x) =>
        x.id.startsWith(stamm) &&
        /^\d+$/.test(x.id.slice(stamm.length)) &&
        (x.type !== 'SY' || (x.ml || 10) === (c.ml || 10))
    )
    .sort((a, b) => a.id.localeCompare(b.id));
}
function ciVerfuegbarHtml(c) {
  const alle = ciGeschwister(c);
  const da = (x) => x.status === 'active' || x.status === 'stored';
  const n = alle.filter(da).length;
  const chips = alle
    .map((x) => {
      const nr = x.id.slice(x.id.lastIndexOf('-') + 1);
      const ich = x.id === c.id;
      const stil = ich
        ? 'background:var(--c-text);color:#fff;border-color:var(--c-text)'
        : da(x)
          ? 'background:var(--c-bg);color:var(--c-text-sec)'
          : 'background:transparent;color:var(--c-text-muted);text-decoration:line-through';
      return `<span class="fs-xs" style="font-family:monospace;padding:3px 8px;border-radius:5px;border:1px solid var(--c-border);${stil}">${esc(nr)}</span>`;
    })
    .join('');
  return (
    `<div class="met" style="margin-bottom:12px"><div class="met-l">${esc(t('ci.availableLbl'))}</div>` +
    `<div style="font-size:1.75rem;font-weight:700;line-height:1.1;color:${n ? 'var(--c-primary)' : 'var(--c-red-dark)'}">` +
    `${esc(t('ci.available', { n: n, total: alle.length }))}</div>` +
    (alle.length > 1 ? `<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:6px">${chips}</div>` : '') +
    '</div>'
  );
}
// Die Größe einer Spritze, mit den drei Knöpfen: falsch gewählt beim Abfüllen
// ist ein Tipp zum Richtigstellen, mit Rückgängig unten. Solange sie da ist —
// eine verkaufte oder verbrauchte zeigt ihre Größe nur noch an.
function ciGroesseHtml(c) {
  if (c.type !== 'SY') return '';
  const da = c.status === 'active' || c.status === 'stored';
  const inhalt = da
    ? `<div style="margin-top:4px">${syMlKnoepfe('ci-ml', syMl(c))}</div>`
    : `<div class="fs-base" style="font-weight:600">${syMl(c)} ml</div>`;
  return `<div class="met" style="margin-bottom:12px"><div class="met-l">${esc(t('sy.size'))}</div>${inhalt}</div>`;
}
function setCultureMl(id, ml) {
  const c = cultures.find((x) => x.id === id);
  if (!c || c.type !== 'SY') return;
  const prev = syMl(c);
  c.ml = ml;
  renderCultures();
  if (ciCultureId === id) openCultureSheet(c);
  apiPatch('/api/cultures/' + encodeURIComponent(id), { ml }).then((r) => {
    if (r && r.error) {
      c.ml = prev;
      renderCultures();
      if (ciCultureId === id) openCultureSheet(c);
      setFb('err', t('common.error') + ': ' + r.error);
    }
  });
}
(function wireCiMl() {
  document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-ci-ml]');
    if (!b || !ciCultureId) return;
    const c = cultures.find((x) => x.id === ciCultureId);
    const ml = parseInt(b.dataset.ciMl, 10);
    if (!c || !SY_ML.includes(ml) || ml === syMl(c)) return;
    const prev = syMl(c);
    setCultureMl(c.id, ml);
    showUndoBar(t('ci.sizeDone', { id: c.id, ml: ml }), () => setCultureMl(c.id, prev));
  });
})();
// Der Stammbaum nach oben, gleich im Fenster: Slant → Petrischale → … → diese.
// Wer eine Spritze in der Hand hat, will wissen, woher sie kommt, und dafür
// musste man sonst auf die Laborseite. Ohne Herkunft steht da, dass es keine gibt.
function ciHerkunftHtml(c) {
  const kette = [];
  const seen = new Set([c.id]);
  let p = c.parentId ? cultures.find((x) => x.id === c.parentId) : null;
  while (p && !seen.has(p.id) && kette.length < 10) {
    seen.add(p.id);
    kette.unshift(p);
    p = p.parentId ? cultures.find((x) => x.id === p.parentId) : null;
  }
  const zeile = (x, ich) =>
    `<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">${ctBadge(x.type)}<span class="fs-meta" style="font-family:monospace;${ich ? 'font-weight:700' : ''}">${esc(x.id)}</span></div>`;
  // Eine Herkunft, die nicht (mehr) in der Liste steht, wird trotzdem genannt.
  const oben = kette.length ? kette[0] : c;
  if (oben.parentId && !cultures.some((x) => x.id === oben.parentId))
    kette.unshift({ id: oben.parentId, type: oben.parentId.split('-')[0] });
  const inhalt = kette.length
    ? kette.map((x) => zeile(x, false)).join('<div class="fs-xs muted" style="margin-left:10px">↓</div>') +
      '<div class="fs-xs muted" style="margin-left:10px">↓</div>' +
      zeile(c, true)
    : `<div class="fs-meta muted">${esc(t('ci.noParent'))}</div>`;
  return (
    `<div class="met" style="margin-bottom:12px"><div class="met-l">${esc(t('ci.herkunft'))}</div>` +
    `<div style="display:flex;flex-direction:column;gap:2px;margin-top:4px">${inhalt}</div></div>`
  );
}
// Was als Kultur auch im Shop steht.
const CI_VERKAUFBAR = ['SY', 'PD'];
function renderCiActions(c) {
  const el = document.getElementById('bi-actions');
  if (!el) return;
  const aktiv = c.status === 'active' || c.status === 'stored';
  // Dieselben Formen wie renderBiActions.
  const big =
    'width:100%;display:flex;align-items:center;justify-content:center;gap:8px;padding:15px;border-radius:12px;border:0;font-weight:600;margin-bottom:8px;cursor:pointer';
  const sec =
    'flex:1;display:flex;align-items:center;justify-content:center;gap:6px;padding:13px;border-radius:10px;cursor:pointer;background:var(--c-surface);border:1px solid var(--c-border)';
  // Ob aus dieser Kultur überhaupt etwas angesetzt werden kann.
  const alsHerkunft = bmpArten(c.type).length > 0;
  let html = '';
  // Spritzen und Petrischalen gehen auch in den Versand. Verkauft steht dann
  // zuoberst: es ist der haeufigste Weg hinaus, und es haelt die Zahl ehrlich,
  // die Billbee den Shops meldet (syringe-stock.js).
  if (aktiv && CI_VERKAUFBAR.includes(c.type))
    html += `<button type="button" data-bi="ci-sold" class="fs-floor" style="--fs-own:1.0625rem;${big};background:var(--c-primary);color:#fff">✓ ${esc(t('ci.sold'))}</button>`;
  if (aktiv)
    html += `<button type="button" data-bi="ci-out" class="fs-floor" style="--fs-own:1.0625rem;${big};background:var(--c-purple-dark);color:#fff">✓ ${esc(t('ci.out'))}</button>`;
  html += '<div style="display:flex;gap:8px;margin-bottom:8px">';
  if (aktiv && alsHerkunft)
    html += `<button type="button" data-bi="ci-beimpfen" class="fs-base" style="${sec};color:var(--c-text);font-weight:600">${esc(t('ci.beimpfen'))}</button>`;
  html += `<button type="button" data-bi="ci-lineage" class="fs-base" style="${sec};color:var(--c-text-sec)">${esc(t('ci.lineage'))}</button>`;
  html += '</div>';
  if (aktiv)
    html += `<button type="button" data-bi="ci-contam" class="fs-base" style="${big};padding:13px;background:var(--c-red-light);color:var(--c-red-dark);border:1px solid var(--c-red-border)">${esc(t('ci.contam'))}</button>`;
  // Was die Tabelle der Kulturbibliothek je Zeile hatte: drucken, löschen, und
  // eine erledigte wieder in den Bestand holen, wenn sie doch noch da ist.
  if (!aktiv)
    html += `<button type="button" data-bi="ci-active" class="fs-base" style="${big};padding:13px;background:var(--c-primary-light);color:var(--c-primary);border:1px solid var(--c-border)">${esc(t('ci.backActive'))}</button>`;
  html += '<div style="display:flex;gap:8px">';
  html += `<button type="button" data-bi="ci-print" class="fs-base" style="${sec};color:var(--c-text)">${esc(t('ci.print'))}</button>`;
  if (_lbDarfWeg(c))
    html += `<button type="button" data-bi="ci-delete" class="fs-base" style="${sec};color:var(--c-red-dark)">${esc(t('ci.delete'))}</button>`;
  html += '</div>';
  el.innerHTML = html;
}
// Ein Tipp, mit Rückgängig unten — wie überall, wo etwas aus dem System geht.
function ciSetStatus(status, msgKey) {
  const c = cultures.find((x) => x.id === ciCultureId);
  if (!c) return;
  const prev = c.status;
  document.getElementById('m-baginfo').classList.remove('open');
  setCultureStatus(c.id, status);
  showUndoBar(t(msgKey, { id: c.id }), () => setCultureStatus(c.id, prev));
}
function ciAction(a) {
  const c = cultures.find((x) => x.id === ciCultureId);
  if (!c) return;
  if (a === 'ci-out') return ciSetStatus('used', 'ci.outDone');
  if (a === 'ci-sold') return ciSetStatus('sold', 'ci.soldDone');
  if (a === 'ci-contam') return ciSetStatus('contam', 'ci.contamDone');
  if (a === 'ci-active') return ciSetStatus('active', 'ci.activeDone');
  document.getElementById('m-baginfo').classList.remove('open');
  if (a === 'ci-print') return quickPrintCulture(c.id);
  if (a === 'ci-delete') return kulturenLoeschen([c]);
  if (a === 'ci-lineage') {
    go('lab', 'n-lab');
    openStab('lab', 'lineage');
    setTimeout(() => {
      const sel = document.getElementById('lineage-sel');
      if (sel) sel.value = 'C:' + c.id;
      renderLineage();
      // Am Telefon steht über dem Stammbaum der Laborbestand; ohne das hier sah
      // man nur den oberen Teil der Laborseite, und der Baum lag darunter.
      const sp = document.getElementById('sp-lab-lineage');
      if (sp) sp.scrollIntoView({ block: 'start' });
    }, 100);
    return;
  }
  if (a === 'ci-beimpfen') bmpOpen(c);
}
// ── Beimpfen: aus einer Kultur vieles auf einmal ─────────────
// Eine Spritze, 40 ml aus dem Glas: daraus gehen 4 Körnerbeutel, 3 neue
// Flüssigkulturen und 10 Petrischalen, in einem Durchgang am Tisch. Einzeln
// hieß das: für jede Art den Dialog öffnen und dieselbe Spritze neu scannen.
// Hier steht je Art eine Zahl, und ein Tipp legt alles an — jede neue Kultur
// mit dieser als Herkunft, so dass der Stammbaum zeigt, wohin sie ging.
let _bmp = null;
// Was aus einer Kultur dieser Art angesetzt werden darf, in der Reihenfolge der
// Zeilen. KB ist Körnerbrut (eine Charge mit Beuteln), der Rest sind Kulturen.
function bmpArten(type) {
  return ['KB', 'LC', 'PD', 'MC', 'SY'].filter((k) => (LAB_PARENT_TYPES[k] || []).includes(type));
}
function bmpOpen(c) {
  // Jede Anzahl fängt bei 0 an: was letztes Mal angesetzt wurde, ist nicht, was
  // heute ansteht, und eine stehengebliebene Zahl legt unbemerkt zu viel an.
  // Körnerbeutel und Spritzen zählen je Größe.
  _bmp = {
    id: c.id,
    n: Object.fromEntries(bmpArten(c.type).map((k) => [k, 0])),
    sy: Object.fromEntries(SY_ML.map((ml) => [ml, 0])),
    kb: Object.fromEntries(KB_KG.map((kg) => [kg, 0]))
  };
  anlageReset('bmp');
  document.getElementById('bmp-title').textContent = t('bmp.title', { id: c.id });
  const name = c.strainName || c.species || '';
  document.getElementById('bmp-sub').textContent =
    name + ((c.strainText || '').trim() ? ' · ' + c.strainText.trim() : '');
  bmpRender();
  document.getElementById('m-beimpfen').style.display = 'flex';
}
function bmpClose() {
  _bmp = null;
  document.getElementById('m-beimpfen').style.display = 'none';
}
function bmpRender() {
  if (!_bmp) return;
  const c = cultures.find((x) => x.id === _bmp.id);
  if (!c) return;
  const knopf =
    'width:var(--tap);height:var(--tap);min-width:44px;min-height:44px;flex:none;border-radius:10px;border:1px solid var(--c-border);background:var(--c-surface);font-size:1.25rem;font-weight:600;cursor:pointer';
  document.getElementById('bmp-rows').innerHTML = bmpArten(c.type)
    .map((k) => {
      // Spritzen und Körnerbeutel zählen je Größe: drei Zähler unter einer
      // Überschrift.
      if (k === 'SY' || k === 'KB')
        return (
          `<div style="padding:8px 0;border-bottom:1px solid var(--c-border-light)">` +
          `<div class="fs-base" style="font-weight:600;margin-bottom:6px">${esc(t('bmp.' + k))}</div>` +
          (k === 'SY' ? syMengenHtml('bmp', _bmp.sy) : kbMengenHtml('bmp', _bmp.kb)) +
          '</div>'
        );
      const zeile =
        `<div style="display:flex;align-items:center;gap:8px">` +
        `<button type="button" data-bmp="minus" data-k="${k}" aria-label="${esc(t('bmp.less'))}" style="${knopf}">−</button>` +
        `<input type="number" inputmode="numeric" min="0" max="500" id="bmp-n-${k}" data-bmp-n="${k}" value="${_bmp.n[k]}" style="width:64px;text-align:center;font-weight:600" />` +
        `<button type="button" data-bmp="plus" data-k="${k}" aria-label="${esc(t('bmp.more'))}" style="${knopf}">+</button>` +
        `<span class="fs-base" style="font-weight:600">${esc(t('bmp.' + k))}</span></div>`;
      return `<div style="padding:8px 0;border-bottom:1px solid var(--c-border-light)">${zeile}</div>`;
    })
    .join('');
  anlageRender('bmp');
  bmpPreview();
}
function _bmpLesen() {
  if (!_bmp) return;
  for (const k of Object.keys(_bmp.n)) {
    const el = document.getElementById('bmp-n-' + k);
    if (el) _bmp.n[k] = Math.max(0, Math.min(500, parseInt(el.value, 10) || 0));
  }
  if ('SY' in _bmp.n) {
    _bmp.sy = syMengenLesen('bmp');
    _bmp.n.SY = sySumme(_bmp.sy);
  }
  if ('KB' in _bmp.n) {
    _bmp.kb = kbMengenLesen('bmp');
    _bmp.n.KB = KB_KG.reduce((a, kg) => a + _bmp.kb[kg], 0);
  }
}
function bmpPreview() {
  if (!_bmp) return;
  _bmpLesen();
  const teile = Object.entries(_bmp.n)
    .filter(([, n]) => n > 0)
    .flatMap(([k, n]) =>
      k === 'KB'
        ? KB_KG.filter((kg) => _bmp.kb[kg] > 0).map((kg) => t('bmp.previewGrain', { n: _bmp.kb[kg], kg }))
        : k === 'SY'
          ? syTeile(_bmp.sy)
          : [n + ' ' + t('bmp.' + k)]
    );
  const summe = Object.values(_bmp.n).reduce((a, n) => a + n, 0);
  const prev = document.getElementById('bmp-preview');
  if (prev) prev.textContent = teile.length ? t('bmp.preview', { list: teile.join(' · ') }) : t('bmp.nothing');
  const go = document.getElementById('bmp-go');
  if (go) {
    go.disabled = !summe;
    go.textContent = summe ? t('bmp.goN', { n: summe }) : t('bmp.go');
  }
}
function bmpGo() {
  if (!_bmp) return;
  _bmpLesen();
  const c = cultures.find((x) => x.id === _bmp.id);
  if (!c) return;
  const ms = c.strainId ? mushroomStrains.find((x) => x.id === c.strainId) : null;
  if (!ms) {
    toast(t('bmp.noSorte', { id: c.id }), 'err');
    return;
  }
  const n = _bmp.n;
  if (!Object.values(n).some((x) => x > 0)) return;
  const angesetzt = anlageLesen('bmp');
  if (angesetzt === null) return;
  const wann = anlageZeitpunkt(angesetzt);
  // Alles aus dem Fenster jetzt: bmpClose() setzt _bmp auf null, und ein
  // Lesen aus _bmp danach brach das Anlegen mit einem Fehler ab.
  const sy = _bmp.sy || {};
  const kb = _bmp.kb || {};
  bmpClose();
  // Erst die Kulturen: jede Art ihre eigenen Kennungen, alle mit dieser als
  // Herkunft. Spritzen je Größe, jede Größe ihre eigenen Nummern.
  const ids = [];
  const saves = [];
  for (const k of ['LC', 'PD', 'MC', 'SY']) {
    if (!(n[k] > 0)) continue;
    const posten = k === 'SY' ? SY_ML.filter((ml) => sy[ml] > 0).map((ml) => [sy[ml], ml]) : [[n[k], null]];
    for (const [qty, ml] of posten) {
      const r = kulturenAnlegen({
        type: k,
        ms,
        wann,
        qty,
        parentId: c.id,
        strainText: (c.strainText || '').trim(),
        ml
      });
      ids.push(...r.newC.map((x) => x.id));
      saves.push(r.saved);
    }
  }
  // Dann die Körnerbrut, über denselben Weg wie aus dem Schnelldialog — mit der
  // Kultur als Herkunft und ohne eigenes Fenster: ihre Etiketten kommen mit
  // denen der Kulturen in eines (etikettenFuerAlles).
  let korn = null;
  if (n.KB > 0) {
    const setv = (id, val) => {
      const el = document.getElementById(id);
      if (el) el.value = val;
    };
    setv('lw-st', ms.id);
    setv('lw-strain-text', (c.strainText || '').trim());
    setv('lw-created', angesetzt);
    gsSetLines(KB_KG.filter((kg) => kb[kg] > 0).map((kg) => ({ kg, qty: kb[kg] })));
    setv('gs-days', 14);
    setv('gs-rh', ms.recGrainRhPct != null ? ms.recGrainRhPct : 52);
    setv('lw-notes', '');
    _inoc = [{ kind: 'culture', id: c.id }];
    korn = createGrainBatch({ ohneFenster: true }) || null;
  }
  renderLabLog();
  etikettenFuerAlles(ids, Promise.all(saves), korn);
}
(function wireBeimpfen() {
  document.addEventListener('click', (e) => {
    const b = e.target.closest('[data-bmp]');
    if (!b || !_bmp) return;
    const a = b.dataset.bmp;
    if (a === 'go') return bmpGo();
    if (a === 'cancel') return bmpClose();
    _bmpLesen();
    const k = b.dataset.k;
    if (!(k in _bmp.n)) return;
    _bmp.n[k] = Math.max(0, Math.min(500, _bmp.n[k] + (a === 'plus' ? 1 : -1)));
    const el = document.getElementById('bmp-n-' + k);
    if (el) el.value = _bmp.n[k];
    bmpPreview();
  });
  document.addEventListener('input', (e) => {
    if (_bmp && e.target.closest('#m-beimpfen')) bmpPreview();
  });
})();
// ─── GLOBAL BARCODE BUFFER (timing-based scanner detection) ──
const _scanBuf = { chars: [], timer: null };
const SCAN_MAX_GAP = 50;
const SCAN_MIN_LEN = 3;

function isKnownBarcode(val) {
  val = val.toUpperCase();
  // Numeric barcode (new system)
  if (/^\d{7,}$/.test(val) && parseInt(val, 10) >= 1000000) return true;
  // Check actions/locations with underscores intact (barcode locations use underscores)
  if (ACTIONS.includes(val)) return true;
  if (LOCS.includes(val)) return true;
  // For bag/batch patterns, convert underscores to hyphens
  const h = val.replace(/_/g, '-');
  if (/^[A-Z]{2,6}-[A-Z]{2,6}-\d{4}-\d{1,2}$/.test(h)) return true;
  if (/^(MC|PD|LC|SY|G2G|GS)-[A-Z0-9]+(?:-[A-Z0-9]+)?-\d{6}-\d{2}$/.test(h)) return true; // wie in processScan
  // Beutel: die Nummer hat eine bis drei Stellen ("-7" bei einer Charge unter zehn).
  if (/^[A-Z]+-\d{6}-\d{2}-\d{1,3}$/.test(h)) return true;
  if (/^[A-Z]+-\d{6}-\d{2}$/.test(h)) return true;
  return false;
}

function _flushScanBuf() {
  const raw = _scanBuf.chars.map((c) => c.ch).join('');
  _scanBuf.chars = [];
  if (raw.length < SCAN_MIN_LEN) return;
  const cleaned = raw.trim().toUpperCase();
  if (!isKnownBarcode(cleaned)) {
    setFb(
      'err',
      t('scanFb.unknownFormat', { val: cleaned }) || 'Unbekanntes Format: ' + cleaned + ' — Barcode prüfen.'
    );
    return;
  }
  processScan(raw);
}

document.addEventListener('keydown', (e) => {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  // Ignore keystrokes while user is typing in form fields — prevents the scan buffer
  // from swallowing Enter on form submits or mis-firing on fast typing in search boxes.
  // The scan modal and camera modal are exceptions: keep the buffer active there.
  const ae = document.activeElement;
  if (ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.tagName === 'SELECT' || ae.isContentEditable)) {
    const scanOpen = document.getElementById('scan-overlay')?.classList.contains('open');
    const camOpen = document.getElementById('m-camscan')?.classList.contains('open');
    // The search palette is the search box this comment already warns about,
    // and it is the one that resolves a scanned code itself. Two readers of the
    // same keystrokes would open a result and log a movement off one scan.
    const gsOpenNow = document.getElementById('m-search')?.classList.contains('open');
    if (gsOpenNow || (!scanOpen && !camOpen)) {
      _scanBuf.chars = [];
      clearTimeout(_scanBuf.timer);
      return;
    }
  }
  const now = performance.now();
  if (e.key === 'Enter') {
    if (_scanBuf.chars.length >= SCAN_MIN_LEN) {
      clearTimeout(_scanBuf.timer);
      const allFast = _scanBuf.chars.every((c, i) => i === 0 || c.t - _scanBuf.chars[i - 1].t < SCAN_MAX_GAP);
      if (allFast) {
        e.preventDefault();
        e.stopPropagation();
        _flushScanBuf();
        return;
      }
    }
    _scanBuf.chars = [];
    clearTimeout(_scanBuf.timer);
    return;
  }
  if (e.key.length !== 1) return;
  if (_scanBuf.chars.length > 0 && now - _scanBuf.chars[_scanBuf.chars.length - 1].t > SCAN_MAX_GAP) {
    _scanBuf.chars = [];
  }
  _scanBuf.chars.push({ ch: e.key, t: now });
  clearTimeout(_scanBuf.timer);
  _scanBuf.timer = setTimeout(() => {
    _scanBuf.chars = [];
  }, SCAN_MAX_GAP * 2);
});

// ─── USER MANAGEMENT ─────────────────────────────────────────
async function doLogout() {
  try {
    await authFetch('/api/auth/logout', { method: 'POST' });
  } catch {}
  window.location.href = '/login.html';
}

async function loadUsersTab() {
  const c = document.getElementById('sp-settings-users');
  if (!c) return;
  const acct = document.getElementById('users-account');
  if (acct && currentUser)
    acct.innerHTML =
      t('users.loggedInAs', { user: esc(currentUser.username), role: esc(currentUser.role) }) +
      ` <button class="btn fs-xs" style="padding:2px 8px;margin-left:8px" onclick="showChangePasswordModal()">${t('chpw.title')}</button>`;
  if (!currentUser || currentUser.role !== 'admin') {
    const tbl = document.getElementById('users-table');
    if (tbl) tbl.innerHTML = '<p style="color:var(--c-text-muted)">' + t('users.adminRequiredManage') + '</p>';
    return;
  }
  try {
    const r = await authFetch('/api/users');
    const users = await r.json();
    const tbl = document.getElementById('users-table');
    if (!tbl) return;
    tbl.innerHTML =
      '<table class="t-cards us-tab" role="table"><thead role="rowgroup"><tr role="row">' +
      '<th role="columnheader">Username</th>' +
      '<th role="columnheader">Role</th>' +
      '<th role="columnheader" title="Darf Labels kaufen + Versanddaten sehen">Versand</th>' +
      '<th role="columnheader" title="Darf Ernte für den Verkauf freigeben — die Menge, die der Shop anbietet">Freigabe</th>' +
      '<th role="columnheader">Created</th>' +
      '<th role="columnheader"></th></tr></thead><tbody role="rowgroup">' +
      users
        .map(
          (u) =>
            `<tr><td data-mlabel="Username">${esc(u.username)}</td><td data-mlabel="Role">${esc(u.role)}</td><td data-mlabel="Versand">${u.role === 'admin' ? '<input type="checkbox" checked disabled title="Admins dürfen immer versenden">' : `<input type="checkbox" data-action="toggle-ship" data-user-id="${esc(u.id)}" ${u.can_ship ? 'checked' : ''}>`}</td><td data-mlabel="Freigabe">${u.role === 'admin' ? '<input type="checkbox" checked disabled title="Admins dürfen immer freigeben">' : `<input type="checkbox" data-action="toggle-release" data-user-id="${esc(u.id)}" ${u.can_release ? 'checked' : ''}>`}</td><td data-mlabel="Created">${u.created ? fmtDt(u.created) : ''}</td><td class="us-actions">${u.username !== currentUser.username ? `<button class="btn btn-r fs-xs" style="padding:2px 8px" data-action="delete-user" data-user-id="${esc(u.id)}">Delete</button>` : ''}</td></tr>`
        )
        .join('') +
      '</tbody></table>';
    // Diese Tabelle entsteht erst hier, also kann der Beobachter aus
    // watchCardTables() sie beim Aufbau der Seite nicht gekannt haben.
    watchCardTables(tbl);
    tbl.onclick = onUsersTableClick;
  } catch (e) {
    console.error('Failed to load users:', e);
  }
}

function onUsersTableClick(e) {
  const ship = e.target.closest('input[data-action="toggle-ship"]');
  if (ship) {
    const sid = parseInt(ship.dataset.userId, 10);
    if (Number.isFinite(sid)) toggleUserShip(sid, ship.checked);
    return;
  }
  const rel = e.target.closest('input[data-action="toggle-release"]');
  if (rel) {
    const rid = parseInt(rel.dataset.userId, 10);
    if (Number.isFinite(rid)) toggleUserRelease(rid, rel.checked);
    return;
  }
  const btn = e.target.closest('button[data-action="delete-user"]');
  if (!btn) return;
  const id = parseInt(btn.dataset.userId, 10);
  if (Number.isFinite(id)) deleteUser(id);
}
// Grant/revoke the shipping capability for a non-admin user. Reloads to reflect
// the server's truth (and revert the checkbox if the PATCH failed).
async function toggleUserShip(id, canShip) {
  try {
    const r = await authFetch('/api/users/' + id, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ canShip })
    });
    if (!r.ok) {
      const d = await r.json();
      toast(d.error || 'Failed', 'err');
    }
  } catch (e) {
    toast(e.message, 'err');
  }
  loadUsersTab();
}

// Grant/revoke the release capability. Same shape as toggleUserShip, and the
// reload matters for the same reason: the checkbox must end up showing what the
// server stored, not what was clicked.
async function toggleUserRelease(id, canRelease) {
  try {
    const r = await authFetch('/api/users/' + id, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ canRelease })
    });
    if (!r.ok) {
      const d = await r.json();
      toast(d.error || 'Failed', 'err');
    }
  } catch (e) {
    toast(e.message, 'err');
  }
  loadUsersTab();
}

async function addUser() {
  const u = document.getElementById('new-username').value.trim();
  const p = document.getElementById('new-password').value;
  const role = document.getElementById('new-role').value;
  if (!u || !p) {
    fieldError(u ? 'new-password' : 'new-username', t('users.required'));
    return;
  }
  if (p.length < 8) {
    fieldError('new-password', t('users.minPw'));
    return;
  }
  try {
    const r = await authFetch('/api/users', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: u, password: p, role })
    });
    if (!r.ok) {
      const d = await r.json();
      toast(d.error || 'Failed', 'err');
      return;
    }
    document.getElementById('new-username').value = '';
    document.getElementById('new-password').value = '';
    loadUsersTab();
  } catch (e) {
    toast(e.message, 'err');
  }
}

async function deleteUser(id) {
  if (!(await askConfirm(t('common.delete'), t('users.deleteConfirm'), t('common.delete')))) return;
  try {
    const r = await authFetch('/api/users/' + id, { method: 'DELETE' });
    if (!r.ok) {
      const d = await r.json();
      toast(d.error || 'Failed', 'err');
      return;
    }
    loadUsersTab();
  } catch (e) {
    toast(e.message, 'err');
  }
}

function showChangePasswordModal() {
  const m = document.getElementById('change-pw-modal');
  if (m) {
    m.style.display = 'flex';
    document.getElementById('chpw-current').value = '';
    document.getElementById('chpw-new').value = '';
    document.getElementById('chpw-status').textContent = '';
    // Populate the hidden username companion so iOS Keychain knows which
    // credential entry this dialog is updating.
    const helper = document.getElementById('chpw-username-helper');
    if (helper && currentUser && currentUser.username) helper.value = currentUser.username;
  }
}
function hideChangePasswordModal() {
  const m = document.getElementById('change-pw-modal');
  if (m) m.style.display = 'none';
}
async function submitChangePassword() {
  const cur = document.getElementById('chpw-current').value;
  const nw = document.getElementById('chpw-new').value;
  const st = document.getElementById('chpw-status');
  if (!cur || !nw) {
    st.textContent = t('chpw.required');
    st.style.color = 'red';
    return;
  }
  if (nw.length < 8) {
    st.textContent = t('chpw.minLength');
    st.style.color = 'red';
    return;
  }
  try {
    const r = await authFetch('/api/auth/password', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ currentPassword: cur, newPassword: nw })
    });
    if (!r.ok) {
      const d = await r.json().catch(() => ({}));
      st.textContent = d.error || 'Failed';
      st.style.color = 'red';
      return;
    }
    st.textContent = t('chpw.success');
    st.style.color = 'green';
    setTimeout(() => hideChangePasswordModal(), 1500);
  } catch (e) {
    st.textContent = t('common.error') + ': ' + e.message;
    st.style.color = 'red';
  }
}

// ─── INIT ────────────────────────────────────────────────────
// Set initial language
// P-03: locale files are loaded on demand. The user's saved choice (or
// default 'de') is fetched up front; until it lands, translatePage() will
// no-op gracefully (`t()` falls back to the key when no locale is loaded).
// We translate again as soon as the locale resolves.
const _allowedLangs = ['en', 'de', 'pt'];
const savedLang = localStorage.getItem('mp-lang');
if (savedLang && _allowedLangs.indexOf(savedLang) !== -1) currentLang = savedLang;
document.getElementById('lang-sel').value = currentLang;
loadLang(currentLang)
  .then(() => translatePage())
  .catch((err) => console.error('Initial locale load failed:', err));

// ─── CALENDAR ───────────────────────────────────────────────
if (typeof calendarEvents === 'undefined') var calendarEvents = [];
if (typeof MS_PER_DAY === 'undefined') var MS_PER_DAY = 86400000;
let calYear = new Date().getFullYear(),
  calMonth = new Date().getMonth(),
  calView = 'month';
let calSelectedDate = new Date(),
  caldavImports = [];
function calDays() {
  return (t('cal.days') || 'Mo,Di,Mi,Do,Fr,Sa,So').split(',');
}
function calMonths() {
  return (
    t('cal.months') || 'Januar,Februar,März,April,Mai,Juni,Juli,August,September,Oktober,November,Dezember'
  ).split(',');
}
const CAL_HOURS_START = 6,
  CAL_HOURS_END = 22;

function fmtDate(y, m, d) {
  return y + '-' + String(m + 1).padStart(2, '0') + '-' + String(d).padStart(2, '0');
}
function localDateStr(d) {
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}
function parseDateStr(s) {
  const p = s.split('-');
  return new Date(+p[0], +p[1] - 1, +p[2]);
}

function getBatchLoc(b, lastByBag) {
  const locs = {};
  // Caller (e.g. collectCalendarEvents) can pass in a pre-built map to avoid
  // O(N×M) when this is called per-batch in a loop.
  const map = lastByBag || buildLastScanByBag();
  b.bags.forEach((bag) => {
    const last = map.get(bag.toUpperCase());
    if (last && last.action !== 'REMOVE' && last.to) locs[last.to] = (locs[last.to] || 0) + 1;
  });
  const entries = Object.entries(locs);
  if (!entries.length) return '';
  entries.sort((a, b) => b[1] - a[1]);
  return entries[0][0];
}
function getCalendarRange() {
  // Window for expanding recurring events — covers any visible view with margin
  const y = calYear,
    m = calMonth;
  const start = new Date(y, m - 2, 1);
  const end = new Date(y, m + 3, 0);
  return { start, end };
}
function addDays(d, n) {
  const x = new Date(d);
  x.setDate(x.getDate() + n);
  return x;
}
// Add n months to `base`, clamping the day to the target month's last day
// (Jan 31 + 1 → Feb 28/29). MUST be computed from the original base each time,
// NOT cumulatively from the previous occurrence — setMonth overflows (Feb 31 →
// Mar 3), which both skips February and permanently shifts every later
// occurrence onto the 3rd.
function addMonthsClamped(base, n) {
  const m = base.getMonth() + n;
  const y = base.getFullYear() + Math.floor(m / 12);
  const tm = ((m % 12) + 12) % 12;
  const day = Math.min(base.getDate(), new Date(y, tm + 1, 0).getDate());
  const r = new Date(base);
  r.setFullYear(y, tm, day);
  return r;
}
function expandRecurringEvent(ev) {
  const out = [];
  if (!ev.recurrence) {
    out.push(ev.startDate);
    return out;
  }
  const exceptions = new Set(Array.isArray(ev.exceptionDates) ? ev.exceptionDates : []);
  const { start: winStart, end: winEnd } = getCalendarRange();
  const base = parseDateStr(ev.startDate);
  const hardEnd = ev.recurrenceUntil ? parseDateStr(ev.recurrenceUntil) : null;
  let cur = new Date(base);
  let guard = 0;
  let monthIdx = 0;
  while (guard++ < 500) {
    if (hardEnd && cur > hardEnd) break;
    if (cur > winEnd) break;
    if (cur >= winStart || cur.getTime() === base.getTime()) {
      const ds = localDateStr(cur);
      if (!exceptions.has(ds)) out.push(ds);
    }
    if (ev.recurrence === 'daily') cur = addDays(cur, 1);
    else if (ev.recurrence === 'weekly') cur = addDays(cur, 7);
    else if (ev.recurrence === 'monthly') cur = addMonthsClamped(base, ++monthIdx);
    else break;
  }
  return out;
}
function expandRecurringTaskDates(task) {
  const out = [];
  const startStr = task.dueDate ? task.dueDate.split('T')[0] : null;
  if (!startStr) return out;
  if (!task.recurrence) {
    out.push(startStr);
    return out;
  }
  const { start: winStart, end: winEnd } = getCalendarRange();
  const base = parseDateStr(startStr);
  const hardEnd = task.recurrenceUntil ? parseDateStr(task.recurrenceUntil) : null;
  let cur = new Date(base);
  let guard = 0;
  let monthIdx = 0;
  while (guard++ < 500) {
    if (hardEnd && cur > hardEnd) break;
    if (cur > winEnd) break;
    if (cur >= winStart || cur.getTime() === base.getTime()) {
      out.push(localDateStr(cur));
    }
    if (task.recurrence === 'daily') cur = addDays(cur, 1);
    else if (task.recurrence === 'weekly') cur = addDays(cur, 7);
    else if (task.recurrence === 'monthly') cur = addMonthsClamped(base, ++monthIdx);
    else break;
  }
  return out;
}
function collectCalendarEvents() {
  const events = [];
  const lastByBag = buildLastScanByBag();
  batches.forEach((b) => {
    if (!b.due) return;
    const d = new Date(b.due);
    const loc = getBatchLoc(b, lastByBag);
    events.push({
      date: localDateStr(d),
      label: b.batchId + (loc ? ' — ' + loc : ''),
      type: 'batch-due',
      id: b.batchId,
      draggable: true,
      allDay: true,
      color: '#ef4444',
      species: b.species
    });
  });
  manualTasks.forEach((t) => {
    if (!t.dueDate) return;
    const dates = expandRecurringTaskDates(t);
    const hasTime = !!t.dueTime;
    dates.forEach((ds, idx) => {
      // Only the base occurrence is draggable; recurring instances are locked
      const isBase = idx === 0 && ds === t.dueDate.split('T')[0];
      events.push({
        date: ds,
        label: t.text,
        type: 'task-due',
        id: t.created,
        draggable: !t.done && !t.recurrence && isBase,
        allDay: !hasTime,
        startTime: hasTime ? t.dueTime : undefined,
        endTime: hasTime ? t.dueEndTime || undefined : undefined,
        color: '#3b82f6',
        recurrence: t.recurrence || null
      });
    });
  });
  harvests.forEach((h) => {
    if (!h.time) return;
    const d = new Date(h.time);
    events.push({
      date: localDateStr(d),
      label: (h.batch || '?') + ' ' + h.grams + 'g',
      type: 'harvest',
      id: null,
      draggable: false,
      allDay: true,
      color: '#f59e0b',
      species: h.species
    });
  });
  const filterName = document.getElementById('cal-filter-user')?.value || '';
  calendarEvents.forEach((ev) => {
    const teamList = Array.isArray(ev.teamAssignees) ? ev.teamAssignees : [];
    if (filterName && teamList.length && !teamList.includes(filterName)) return;
    const dates = expandRecurringEvent(ev);
    const displayAssignees = teamList.map((n) => ({ userId: 0, username: n }));
    dates.forEach((ds) => {
      events.push({
        date: ds,
        label: ev.title,
        type: 'custom',
        id: ev.id,
        draggable: !ev.recurrence,
        allDay: ev.allDay,
        startTime: ev.startTime,
        endTime: ev.endTime,
        color: CATEGORY_COLORS[ev.category] || ev.color || '#16a34a',
        description: ev.description,
        assignees: displayAssignees,
        recurrence: ev.recurrence || null
      });
    });
  });
  caldavImports.forEach((ev) => {
    events.push({
      date: ev.date,
      label: ev.summary,
      type: 'caldav-import',
      id: ev.uid,
      draggable: false,
      allDay: ev.allDay !== false,
      startTime: ev.startTime,
      endTime: ev.endTime,
      color: '#6366f1'
    });
  });
  return events;
}

// One place decides whether this is a phone, and both the router and the
// navigation read it. The breakpoint is duplicated in styles.css — where it
// hides the view toggle — and that pair is exactly the split-brain
// test/mobile-nav.test.js exists to catch, so it is asserted there too.
// A group heading whose entries are all in the bottom bar would be left over
// the gap where they used to be — "Arbeiten" loses all three. Derived from what
// is actually marked rather than named, so it follows the list above.
function markEmptyDrawerGroups() {
  document.querySelectorAll('.sb-group-label').forEach((label) => {
    const entries = [];
    for (let el = label.nextElementSibling; el && !el.classList.contains('sb-group-label'); el = el.nextElementSibling) {
      if (el.classList.contains('sb-btn')) entries.push(el);
    }
    const allInBar = entries.length > 0 && entries.every((e) => e.classList.contains('sb-in-bottom-nav'));
    label.classList.toggle('sb-in-bottom-nav', allInBar);
  });
}

// The same question the sidebar asks, so the same query answers it. It used to
// build a fresh MediaQueryList on every renderCalendar() call and carry its own
// copy of the 768, which meant two predicates that could disagree about which
// arrangement the window is in. Disagreeing predicates are what this branch is
// about.
function calAgendaOnly() {
  return sbIsPhone();
}

function renderCalendar() {
  const title = document.getElementById('cal-title');
  if (!title) return;
  document.querySelectorAll('.cal-vbtn').forEach((b) => b.classList.remove('active'));
  const btn = document.getElementById('cv-' + calView);
  if (btn) btn.classList.add('active');
  if (calAgendaOnly()) renderCalAgenda();
  else if (calView === 'month') renderCalMonth();
  else if (calView === 'week') renderCalWeek();
  else if (calView === 'day') renderCalDay();
}

function setCalView(v) {
  calView = v;
  renderCalendar();
}
function calToday() {
  calYear = new Date().getFullYear();
  calMonth = new Date().getMonth();
  calSelectedDate = new Date();
  renderCalendar();
}

function calNav(delta) {
  // The agenda spans the displayed month, so on a phone prev/next moves a
  // month regardless of which grid calView still names — otherwise a stale
  // 'week' from a desktop session steps the title by seven days while the list
  // below it changes by thirty.
  if (calView === 'month' || calAgendaOnly()) {
    calMonth += delta;
    if (calMonth < 0) {
      calMonth = 11;
      calYear--;
    }
    if (calMonth > 11) {
      calMonth = 0;
      calYear++;
    }
  } else if (calView === 'week') {
    calSelectedDate.setDate(calSelectedDate.getDate() + delta * 7);
    calYear = calSelectedDate.getFullYear();
    calMonth = calSelectedDate.getMonth();
  } else if (calView === 'day') {
    calSelectedDate.setDate(calSelectedDate.getDate() + delta);
    calYear = calSelectedDate.getFullYear();
    calMonth = calSelectedDate.getMonth();
  }
  renderCalendar();
}

function printCalendar() {
  const modal = document.getElementById('m-cal-print');
  if (!modal) return;
  modal.classList.add('open');
}
function closeCalPrintModal() {
  const m = document.getElementById('m-cal-print');
  if (m) m.classList.remove('open');
}

// The type of an event, in words. Shared by the printed task list and the
// on-screen agenda, because a dot in one and a word in the other would be two
// vocabularies for one set of five things.
function calTypeLabels() {
  return {
    'batch-due': t('cal.legend.batches'),
    'task-due': t('calDetail.taskDue'),
    harvest: t('cal.legend.harvests'),
    custom: t('calEntry.cat.custom'),
    'caldav-import': t('calDetail.external')
  };
}

// Every day between two dates, each carrying its events in reading order:
// all-day first, then by start time. Empty days are kept — on a task list the
// blank Sunday is information.
//
// This was the middle of printCalendarTaskList() and nothing else could reach
// it, which is the only reason the calendar had no agenda view: the grouping
// and the sort, the two parts that are actually fiddly against recurrence
// expansion, were already written and already correct, three lines below a
// window.print().
function calAgendaDays(startDate, endDate) {
  const DAYS = calDays();
  const startStr = fmtDate(startDate.getFullYear(), startDate.getMonth(), startDate.getDate());
  const endStr = fmtDate(endDate.getFullYear(), endDate.getMonth(), endDate.getDate());
  const byDate = {};
  collectCalendarEvents()
    .filter((e) => e.date >= startStr && e.date <= endStr)
    .forEach((e) => {
      (byDate[e.date] = byDate[e.date] || []).push(e);
    });
  const days = [];
  for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
    const ds = fmtDate(d.getFullYear(), d.getMonth(), d.getDate());
    const dayEvents = (byDate[ds] || []).slice().sort((a, b) => {
      if (a.allDay && !b.allDay) return -1;
      if (!a.allDay && b.allDay) return 1;
      return (a.startTime || '').localeCompare(b.startTime || '');
    });
    days.push({ ds, dayName: DAYS[(d.getDay() + 6) % 7], date: new Date(d), events: dayEvents });
  }
  return days;
}

function printCalendarTaskList(range) {
  const sheet = document.getElementById('print-sheet');
  if (!sheet) return;

  const MONTHS = calMonths();

  // Determine date range — rolling window anchored on today
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  let startDate, endDate, rangeLabel;
  if (range === 'week') {
    startDate = new Date(today);
    endDate = new Date(today);
    endDate.setDate(today.getDate() + 6);
  } else {
    startDate = new Date(today);
    endDate = new Date(today);
    endDate.setDate(today.getDate() + 29);
  }
  const sameYear = startDate.getFullYear() === endDate.getFullYear();
  const rangePrefix = range === 'week' ? t('cal.weekShort') : t('cal.monthShort');
  rangeLabel =
    rangePrefix +
    ': ' +
    startDate.getDate() +
    '. ' +
    MONTHS[startDate.getMonth()] +
    (sameYear ? '' : ' ' + startDate.getFullYear()) +
    ' – ' +
    endDate.getDate() +
    '. ' +
    MONTHS[endDate.getMonth()] +
    ' ' +
    endDate.getFullYear();

  const days = calAgendaDays(startDate, endDate);
  const typeLabels = calTypeLabels();
  const totalEvents = days.reduce((n, d) => n + d.events.length, 0);

  // Render HTML
  const todayStr = localDateStr(new Date());
  let bodyHtml = '';
  days.forEach((day) => {
    const isToday = day.ds === todayStr;
    bodyHtml += '<div class="cal-print-day' + (isToday ? ' today' : '') + '">';
    bodyHtml +=
      '<div class="cal-print-day-hdr">' +
      day.dayName +
      ', ' +
      day.date.getDate() +
      '. ' +
      MONTHS[day.date.getMonth()] +
      ' ' +
      day.date.getFullYear() +
      '</div>';
    if (day.events.length === 0) {
      bodyHtml += '<div class="cal-print-empty">— ' + t('cal.noTasks') + ' —</div>';
    } else {
      bodyHtml += '<ul class="cal-print-list">';
      day.events.forEach((e) => {
        const time = e.allDay ? t('cal.allDay') : (e.startTime || '') + (e.endTime ? ' – ' + e.endTime : '');
        const typeLbl = typeLabels[e.type] || '';
        const dotColor = safeColor(e.color || '#64748b');
        const assigneeStr =
          e.assignees && e.assignees.length
            ? ' <span class="cal-print-assignees">(' + e.assignees.map((a) => esc(a.username)).join(', ') + ')</span>'
            : '';
        const desc = e.description ? '<div class="cal-print-desc">' + esc(e.description) + '</div>' : '';
        bodyHtml +=
          '<li class="cal-print-item">' +
          '<span class="cal-print-dot" style="background:' +
          dotColor +
          '"></span>' +
          '<span class="cal-print-time">' +
          esc(time) +
          '</span>' +
          '<span class="cal-print-type">' +
          typeLbl +
          '</span>' +
          '<span class="cal-print-label">' +
          esc(e.label) +
          assigneeStr +
          desc +
          '</span>' +
          '</li>';
      });
      bodyHtml += '</ul>';
    }
    bodyHtml += '</div>';
  });

  // px-auf-papier: the calendar task list, laid out for a printed page by
  // .cal-print-* in styles.css, whose sizes are px for the same reason.
  sheet.innerHTML =
    '<div class="cal-print-page cal-print-tasklist">' +
    '<div class="cal-print-header">' +
    '<div style="font-size:20px;font-weight:800;color:#111">' +
    esc(t('cal.taskListTitle')) +
    '</div>' +
    '<div style="font-size:13px;color:#444;margin-top:2px">' +
    esc(rangeLabel) +
    '</div>' +
    '<div class="fs-xs" style="color:#666;margin-top:2px">' +
    totalEvents +
    ' ' +
    t('cal.entries') +
    ' — ' +
    t('cal.printed') +
    ' ' +
    new Date().toLocaleDateString(loc()) +
    '</div>' +
    '</div>' +
    '<div class="cal-print-body">' +
    bodyHtml +
    '</div>' +
    '</div>';

  closeCalPrintModal();
  setTimeout(() => window.print(), 150);
}

// ── Agenda View — what the calendar is on a phone ──
//
// Not a preference and not a fourth tab: below 769px the three grids cannot
// work, and the numbers say so rather than taste. Seven columns at the 44px
// WCAG floor need 316px of grid, which fits in 343px of content — and leaves
// each cell 36px wide, so the day-number circle fills it edge to edge with
// nothing left for an event. Today a month cell is 47.9px wide and an event
// label gets 29.9px at 10px type: four glyphs and an ellipsis. Week view is
// worse at 40.7px per column. The constraint is horizontal, and a taller cell
// cannot reach it, which is what settles §9 decision 3.
//
// Empty days are dropped here and kept in print. That is deliberate on both
// sides: on paper the blank Sunday is a line you tick, on a phone it is thirty
// rows of "no tasks" between you and the four that matter.
function renderCalAgenda() {
  const container = document.getElementById('cal-container');
  const title = document.getElementById('cal-title');
  if (!container || !title) return;
  const MONTHS = calMonths();
  title.textContent = MONTHS[calMonth] + ' ' + calYear;

  const days = calAgendaDays(new Date(calYear, calMonth, 1), new Date(calYear, calMonth + 1, 0)).filter(
    (d) => d.events.length
  );
  const typeLabels = calTypeLabels();
  const todayStr = localDateStr(new Date());

  if (!days.length) {
    container.innerHTML = '<div class="cal-agenda-empty">' + esc(t('cal.agendaEmpty')) + '</div>';
    container.onclick = null;
    return;
  }

  container.innerHTML =
    '<div class="cal-agenda">' +
    days
      .map((day) => {
        const rows = day.events
          .map((e) => {
            const when = e.allDay
              ? t('cal.allDay')
              : (e.startTime || '') + (e.endTime ? '–' + e.endTime : '');
            const desc = e.description
              ? '<span class="cal-agenda-desc">' + esc(e.description) + '</span>'
              : '';
            const who =
              e.assignees && e.assignees.length
                ? '<span class="cal-agenda-who">' + e.assignees.map((a) => esc(a.username)).join(', ') + '</span>'
                : '';
            return (
              '<button type="button" class="cal-agenda-row" data-type="' +
              esc(e.type) +
              '" data-id="' +
              esc(e.id || '') +
              '">' +
              '<span class="cal-agenda-dot" style="background:' +
              safeColor(e.color || '#64748b') +
              '"></span>' +
              '<span class="cal-agenda-when">' +
              esc(when) +
              '</span>' +
              '<span class="cal-agenda-what">' +
              '<span class="cal-agenda-label">' +
              esc(e.label) +
              '</span>' +
              '<span class="cal-agenda-meta">' +
              esc(typeLabels[e.type] || '') +
              who +
              '</span>' +
              desc +
              '</span>' +
              '</button>'
            );
          })
          .join('');
        return (
          '<div class="cal-agenda-day' +
          (day.ds === todayStr ? ' today' : '') +
          '" data-date="' +
          day.ds +
          '">' +
          '<div class="cal-agenda-date">' +
          '<span class="cal-agenda-num">' +
          day.date.getDate() +
          '</span>' +
          '<span class="cal-agenda-dow">' +
          esc(day.dayName) +
          '</span>' +
          '</div>' +
          '<div class="cal-agenda-rows">' +
          rows +
          '</div>' +
          '</div>'
        );
      })
      .join('') +
    '</div>';

  // The same opener the month grid uses. No drag-and-drop: rescheduling by
  // dragging is a mouse gesture, and this view exists for the hand.
  container.onclick = function (ev) {
    const row = ev.target.closest('.cal-agenda-row');
    if (!row) return;
    onCalMonthEventClick(row.dataset.type, row.dataset.id);
  };

  const today = container.querySelector('.cal-agenda-day.today');
  if (today) today.scrollIntoView({ block: 'nearest' });
}

// ── Month View ──
function renderCalMonth() {
  const container = document.getElementById('cal-container');
  const title = document.getElementById('cal-title');
  const months = calMonths(),
    days2 = calDays();
  title.textContent = months[calMonth] + ' ' + calYear;
  const firstDay = new Date(calYear, calMonth, 1);
  const daysInMonth = new Date(calYear, calMonth + 1, 0).getDate();
  const startDow = (firstDay.getDay() + 6) % 7;
  const prevLast = new Date(calYear, calMonth, 0).getDate();
  const events = collectCalendarEvents();
  const todayStr = localDateStr(new Date());
  const totalCells = startDow + daysInMonth;
  const rows = Math.max(6, Math.ceil(totalCells / 7));
  const trailing = rows * 7 - totalCells;

  let html = '<div class="cal-grid" id="cal-grid">';
  html += days2.map((d) => '<div class="cal-hdr">' + d + '</div>').join('');

  function eventsForDate(ds) {
    const de = events.filter((e) => e.date === ds);
    const mx = 3;
    let o = de
      .slice(0, mx)
      .map((e) => {
        const drag = e.draggable ? 'draggable="true"' : '';
        const cls = e.draggable ? 'cal-event' : 'cal-event no-drag';
        const bg = e.color ? 'style="background:' + safeColor(e.color) + '"' : '';
        const assigneeStr =
          e.assignees && e.assignees.length
            ? ' <span class="cal-ev-assignees">' + e.assignees.map((a) => esc(a.username)).join(', ') + '</span>'
            : '';
        const dot = e.species ? spDot(e.species) : '';
        return (
          '<div class="' +
          cls +
          '" ' +
          drag +
          ' data-type="' +
          esc(e.type) +
          '" data-id="' +
          esc(e.id || '') +
          '" title="' +
          esc(e.label) +
          '" ' +
          bg +
          '>' +
          dot +
          esc(e.label) +
          assigneeStr +
          '</div>'
        );
      })
      .join('');
    if (de.length > mx)
      o +=
        '<div class="cal-more" onclick="event.stopPropagation();calGotoDay(\'' +
        ds +
        '\')">+' +
        (de.length - mx) +
        ' ' +
        t('cal.more') +
        '</div>';
    return o;
  }

  for (let i = startDow - 1; i >= 0; i--) {
    const day = prevLast - i,
      m = calMonth === 0 ? 11 : calMonth - 1,
      y = calMonth === 0 ? calYear - 1 : calYear,
      ds = fmtDate(y, m, day);
    html +=
      '<div class="cal-cell other" data-date="' +
      ds +
      '" onclick="calCellClick(event,\'' +
      ds +
      '\')"><div class="cal-day" onclick="event.stopPropagation();calGotoDay(\'' +
      ds +
      '\')">' +
      day +
      '</div>' +
      eventsForDate(ds) +
      '</div>';
  }
  for (let d = 1; d <= daysInMonth; d++) {
    const ds = fmtDate(calYear, calMonth, d),
      cls = ds === todayStr ? 'cal-cell today' : 'cal-cell';
    html +=
      '<div class="' +
      cls +
      '" data-date="' +
      ds +
      '" onclick="calCellClick(event,\'' +
      ds +
      '\')"><div class="cal-day" onclick="event.stopPropagation();calGotoDay(\'' +
      ds +
      '\')">' +
      d +
      '</div>' +
      eventsForDate(ds) +
      '</div>';
  }
  for (let d = 1; d <= trailing; d++) {
    const m = calMonth === 11 ? 0 : calMonth + 1,
      y = calMonth === 11 ? calYear + 1 : calYear,
      ds = fmtDate(y, m, d);
    html +=
      '<div class="cal-cell other" data-date="' +
      ds +
      '" onclick="calCellClick(event,\'' +
      ds +
      '\')"><div class="cal-day" onclick="event.stopPropagation();calGotoDay(\'' +
      ds +
      '\')">' +
      d +
      '</div>' +
      eventsForDate(ds) +
      '</div>';
  }
  html += '</div>';
  container.innerHTML = html;
  initCalDragDrop(container);
}
function calCellClick(e, ds) {
  if (e.target.closest('.cal-event') || e.target.closest('.cal-more')) return;
  openEventModal(ds);
}
function calGotoDay(ds) {
  calSelectedDate = parseDateStr(ds);
  calYear = calSelectedDate.getFullYear();
  calMonth = calSelectedDate.getMonth();
  setCalView('day');
}

// ── Week View ──
function getWeekStart(d) {
  const dt = new Date(d);
  const dow = (dt.getDay() + 6) % 7;
  dt.setDate(dt.getDate() - dow);
  dt.setHours(0, 0, 0, 0);
  return dt;
}

function renderCalWeek() {
  const container = document.getElementById('cal-container');
  const title = document.getElementById('cal-title');
  const ws = getWeekStart(calSelectedDate);
  const days = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(ws);
    d.setDate(ws.getDate() + i);
    days.push(d);
  }
  const todayStr = localDateStr(new Date());
  const MONTHS = calMonths(),
    DAYS = calDays();
  title.textContent =
    days[0].getDate() +
    '. ' +
    (days[0].getMonth() !== days[6].getMonth()
      ? MONTHS[days[0].getMonth()] + ' — ' + days[6].getDate() + '. ' + MONTHS[days[6].getMonth()]
      : ' — ' + days[6].getDate() + '. ' + MONTHS[days[0].getMonth()]) +
    ' ' +
    days[6].getFullYear();
  const events = collectCalendarEvents();
  const dayStrs = days.map((d) => localDateStr(d));

  let html = '<div class="cal-week">';
  html += '<div class="cal-week-hdr"><div class="cal-week-hdr-cell"></div>';
  days.forEach((d, i) => {
    const ds = dayStrs[i];
    html +=
      '<div class="cal-week-hdr-cell' +
      (ds === todayStr ? ' today-col' : '') +
      '" onclick="calGotoDay(\'' +
      ds +
      '\')">' +
      DAYS[i] +
      '<span class="wk-day-num">' +
      d.getDate() +
      '</span></div>';
  });
  html += '</div>';
  html += '<div class="cal-week-allday"><div class="cal-week-allday-label">' + t('cal.allDayShort') + '</div>';
  days.forEach((d, i) => {
    const ds = dayStrs[i];
    const de = events.filter((e) => e.date === ds && e.allDay);
    html += '<div class="cal-week-allday-cell" data-date="' + ds + '">';
    de.forEach((e) => {
      const cls = e.draggable ? 'cal-event' : 'cal-event no-drag';
      const bg = e.color ? 'style="background:' + safeColor(e.color) + '"' : '';
      const dot = e.species ? spDot(e.species) : '';
      html +=
        '<div class="' +
        cls +
        '" ' +
        (e.draggable ? 'draggable="true"' : '') +
        ' data-type="' +
        esc(e.type) +
        '" data-id="' +
        esc(e.id || '') +
        '" title="' +
        esc(e.label) +
        '" ' +
        bg +
        '>' +
        dot +
        esc(e.label) +
        '</div>';
    });
    html += '</div>';
  });
  html += '</div>';
  html += '<div class="cal-week-body">';
  for (let h = CAL_HOURS_START; h <= CAL_HOURS_END; h++) {
    html += '<div class="cal-week-time">' + String(h).padStart(2, '0') + ':00</div>';
    days.forEach((d, i) => {
      const ds = dayStrs[i];
      html +=
        '<div class="cal-week-slot' +
        (ds === todayStr ? ' today-col' : '') +
        '" data-date="' +
        ds +
        '" data-hour="' +
        h +
        '" onclick="openEventModal(\'' +
        ds +
        "','" +
        String(h).padStart(2, '0') +
        ':00\')"></div>';
    });
  }
  html += '</div></div>';
  container.innerHTML = html;

  const body = container.querySelector('.cal-week-body');
  if (body) {
    days.forEach((d, i) => {
      const ds = dayStrs[i];
      const timed = events.filter((e) => e.date === ds && !e.allDay && e.startTime);
      timed.forEach((e) => {
        const [sh, sm] = (e.startTime || '09:00').split(':').map(Number);
        const [eh, em] = (e.endTime || String(sh + 1).padStart(2, '0') + ':00').split(':').map(Number);
        const top = (sh - CAL_HOURS_START) * 48 + (sm / 60) * 48;
        const height = Math.max(24, (eh - sh) * 48 + ((em - sm) / 60) * 48);
        const col = i + 2;
        const el = document.createElement('div');
        el.className = 'cal-week-ev';
        el.style.cssText =
          'top:' + top + 'px;height:' + height + 'px;background:' + safeColor(e.color) + ';grid-column:' + col;
        const wkDot = e.species ? spDot(e.species) : '';
        let wkContent = wkDot + esc(e.label);
        if (e.assignees && e.assignees.length)
          wkContent +=
            ' <span class="cal-ev-assignees">' + e.assignees.map((a) => esc(a.username)).join(', ') + '</span>';
        if (height >= 48 && e.startTime)
          wkContent +=
            '<div class="fs-micro" style="opacity:.8">' + e.startTime + (e.endTime ? ' — ' + e.endTime : '') + '</div>';
        if (height >= 72 && e.description)
          wkContent += '<div class="fs-micro" style="opacity:.7;margin-top:1px">' + esc(e.description) + '</div>';
        el.innerHTML = wkContent;
        el.title = e.label;
        el.dataset.type = e.type;
        el.dataset.id = e.id || '';
        el.dataset.date = ds;
        el.onclick = function () {
          if (!el._dragged) onCalEventClick(e);
        };
        if (e.type === 'custom') {
          const rh = document.createElement('div');
          rh.className = 'ev-resize';
          el.appendChild(rh);
          initEventDrag(el, body, 'week', dayStrs);
          initEventResize(el, rh, body, 'week');
        }
        body.appendChild(el);
      });
    });
    const now = new Date();
    const nowDs = localDateStr(now);
    const todayIdx = dayStrs.indexOf(nowDs);
    if (todayIdx >= 0) {
      const nowH = now.getHours(),
        nowM = now.getMinutes();
      if (nowH >= CAL_HOURS_START && nowH <= CAL_HOURS_END) {
        const top = (nowH - CAL_HOURS_START) * 48 + (nowM / 60) * 48;
        const line = document.createElement('div');
        line.className = 'cal-week-now-line';
        line.style.top = top + 'px';
        body.appendChild(line);
        body.scrollTop = Math.max(0, top - 150);
      }
    }
  }
  initCalDragDrop(container);
}

// ── Day View ──
function renderCalDay() {
  const container = document.getElementById('cal-container');
  const title = document.getElementById('cal-title');
  const d = calSelectedDate;
  const ds = localDateStr(d);
  const DAYS = calDays(),
    MONTHS = calMonths();
  const dayName = DAYS[(d.getDay() + 6) % 7];
  title.textContent = dayName + ', ' + d.getDate() + '. ' + MONTHS[d.getMonth()] + ' ' + d.getFullYear();
  const events = collectCalendarEvents();
  const dayEvents = events.filter((e) => e.date === ds);
  const allDay = dayEvents.filter((e) => e.allDay);
  const timed = dayEvents.filter((e) => !e.allDay && e.startTime);

  let html = '<div class="cal-day-view">';
  html += '<div class="cal-day-allday"><div class="sec">' + t('cal.allDay') + '</div>';
  if (allDay.length) {
    allDay.forEach((e) => {
      const cls = e.draggable ? 'cal-event' : 'cal-event no-drag';
      const bg = e.color ? 'style="background:' + safeColor(e.color) + '"' : '';
      const dot = e.species ? spDot(e.species) : '';
      html +=
        '<div class="' +
        cls +
        '" ' +
        (e.draggable ? 'draggable="true"' : '') +
        ' data-type="' +
        esc(e.type) +
        '" data-id="' +
        esc(e.id || '') +
        '" title="' +
        esc(e.label) +
        '" ' +
        bg +
        '>' +
        dot +
        esc(e.label) +
        '</div>';
    });
  } else {
    html += '<div class="cal-day-allday-empty">' + t('cal.noAllDay') + '</div>';
  }
  html += '</div>';
  html += '<div class="cal-day-body">';
  for (let h = CAL_HOURS_START; h <= CAL_HOURS_END; h++) {
    html += '<div class="cal-day-time">' + String(h).padStart(2, '0') + ':00</div>';
    html +=
      '<div class="cal-day-slot" data-date="' +
      ds +
      '" data-hour="' +
      h +
      '" onclick="openEventModal(\'' +
      ds +
      "','" +
      String(h).padStart(2, '0') +
      ':00\')"></div>';
  }
  html += '</div></div>';
  container.innerHTML = html;

  const body = container.querySelector('.cal-day-body');
  if (body) {
    timed.forEach((e) => {
      const [sh, sm] = (e.startTime || '09:00').split(':').map(Number);
      const [eh, em] = (e.endTime || String(sh + 1).padStart(2, '0') + ':00').split(':').map(Number);
      const top = (sh - CAL_HOURS_START) * 48 + (sm / 60) * 48;
      const height = Math.max(24, (eh - sh) * 48 + ((em - sm) / 60) * 48);
      const el = document.createElement('div');
      el.className = 'cal-day-ev';
      el.style.cssText =
        'top:' + top + 'px;height:' + height + 'px;background:' + safeColor(e.color) + ';grid-column:2';
      const dayDot = e.species ? spDot(e.species) : '';
      let dayContent = dayDot + '<strong>' + esc(e.label) + '</strong>';
      if (e.assignees && e.assignees.length)
        dayContent +=
          ' <span class="cal-ev-assignees">' + e.assignees.map((a) => esc(a.username)).join(', ') + '</span>';
      if (e.startTime)
        dayContent +=
          '<div class="fs-xs" style="opacity:.8;margin-top:2px">' +
          e.startTime +
          (e.endTime ? ' — ' + e.endTime : '') +
          '</div>';
      if (height >= 72 && e.description)
        dayContent += '<div class="fs-micro" style="opacity:.7;margin-top:2px">' + esc(e.description) + '</div>';
      el.innerHTML = dayContent;
      el.title = e.label;
      el.dataset.type = e.type;
      el.dataset.id = e.id || '';
      el.dataset.date = ds;
      el.onclick = function () {
        if (!el._dragged) onCalEventClick(e);
      };
      if (e.type === 'custom') {
        const rh = document.createElement('div');
        rh.className = 'ev-resize';
        el.appendChild(rh);
        initEventDrag(el, body, 'day', null);
        initEventResize(el, rh, body, 'day');
      }
      body.appendChild(el);
    });
    const now = new Date();
    const nowDs = localDateStr(now);
    if (ds === nowDs) {
      const nowH = now.getHours(),
        nowM = now.getMinutes();
      if (nowH >= CAL_HOURS_START && nowH <= CAL_HOURS_END) {
        const top = (nowH - CAL_HOURS_START) * 48 + (nowM / 60) * 48;
        const line = document.createElement('div');
        line.className = 'cal-day-now-line';
        line.style.top = top + 'px';
        body.appendChild(line);
        body.scrollTop = Math.max(0, top - 150);
      }
    }
  }
  initCalDragDrop(container);
}

// ── Calendar Drag-and-Drop ──
function initCalDragDrop(root) {
  if (!root) return;
  root.onclick = function (e) {
    const ev = e.target.closest('.cal-event');
    if (!ev) return;
    e.stopPropagation();
    onCalMonthEventClick(ev.dataset.type, ev.dataset.id);
  };
  root.ondragstart = function (e) {
    const ev = e.target.closest('.cal-event');
    if (!ev || ev.classList.contains('no-drag')) {
      e.preventDefault();
      return;
    }
    e.dataTransfer.setData('text/plain', ev.dataset.type + '|' + ev.dataset.id);
    e.dataTransfer.effectAllowed = 'move';
    ev.style.opacity = '0.4';
  };
  root.ondragend = function (e) {
    const ev = e.target.closest('.cal-event');
    if (ev) ev.style.opacity = '1';
    root.querySelectorAll('.drag-over').forEach((c) => c.classList.remove('drag-over'));
  };
  root.ondragover = function (e) {
    const cell = e.target.closest('[data-date]');
    if (!cell) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    root.querySelectorAll('.drag-over').forEach((c) => c.classList.remove('drag-over'));
    cell.classList.add('drag-over');
  };
  root.ondragleave = function (e) {
    const cell = e.target.closest('[data-date]');
    if (cell) cell.classList.remove('drag-over');
  };
  root.ondrop = function (e) {
    e.preventDefault();
    root.querySelectorAll('.drag-over').forEach((c) => c.classList.remove('drag-over'));
    const cell = e.target.closest('[data-date]');
    if (!cell || !cell.dataset.date) return;
    const data = e.dataTransfer.getData('text/plain');
    if (!data) return;
    const [type, id] = data.split('|');
    handleCalendarDrop(type, id, cell.dataset.date);
  };
}

function handleCalendarDrop(type, id, newDateStr) {
  if (type === 'batch-due') {
    const b = batches.find((x) => x.batchId === id);
    if (!b) return;
    const newDue = new Date(newDateStr + 'T12:00:00');
    b.due = newDue.toISOString();
    const created = new Date(b.created);
    b.days = Math.max(1, Math.round((newDue - created) / MS_PER_DAY));
    apiPatch('/api/batches/' + encodeURIComponent(id), { due: b.due, days: b.days });
    renderCalendar();
    pushBatchCaldav(b);
  } else if (type === 'task-due') {
    const t = manualTasks.find((x) => x.created === id);
    if (!t) return;
    t.dueDate = newDateStr;
    t.caldavSynced = null;
    apiPatch('/api/tasks/' + t.id, { dueDate: newDateStr, caldavSynced: null });
    renderCalendar();
    if (caldav.enabled && t.caldavUid && typeof pushTaskCaldav === 'function') pushTaskCaldav(t);
  } else if (type === 'custom') {
    const ev = calendarEvents.find((x) => x.id === id);
    if (!ev) return;
    // A dragged window is a moved handover. Only recurrence-free events are
    // draggable, so the whole event and the one occurrence are the same thing.
    confirmBookedWindow(ev.id, null, () => {
      ev.startDate = newDateStr;
      ev.caldavSynced = null;
      apiPatch('/api/calendar-events/' + encodeURIComponent(ev.id), { startDate: newDateStr, caldavSynced: null });
      renderCalendar();
      if (typeof pushEventCaldav === 'function') pushEventCaldav(ev);
    });
  }
}

// ── Time-based Drag & Resize for Week/Day views ──
function pxToTime(px) {
  const totalMin = (px / 48) * 60;
  let h = CAL_HOURS_START + Math.floor(totalMin / 60);
  let m = Math.round((totalMin % 60) / 15) * 15;
  if (m >= 60) {
    h++;
    m = 0;
  }
  h = Math.max(CAL_HOURS_START, Math.min(CAL_HOURS_END, h));
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

function snapPx(px) {
  return Math.round(px / 12) * 12;
}

function updateEventTime(id, newStart, newEnd, newDate) {
  const ev = calendarEvents.find((x) => x.id === id);
  if (!ev) return;
  if (newStart) ev.startTime = newStart;
  if (newEnd) ev.endTime = newEnd;
  if (newDate) ev.startDate = newDate;
  ev.caldavSynced = null;
  const patch = { caldavSynced: null };
  if (newStart) patch.startTime = newStart;
  if (newEnd) patch.endTime = newEnd;
  if (newDate) patch.startDate = newDate;
  apiPatch('/api/calendar-events/' + encodeURIComponent(id), patch);
  renderCalendar();
  if (typeof pushEventCaldav === 'function') pushEventCaldav(ev);
}

function initEventDrag(el, body, viewType, dayStrs) {
  function startDrag(clientX, clientY) {
    if (el._resizing) return;
    const startY = clientY,
      startX = clientX;
    const origTop = parseFloat(el.style.top);
    let dragging = false;
    el._dragged = false;
    const onMove = function (cx, cy) {
      const dy = cy - startY;
      const dx = cx - startX;
      if (!dragging && Math.abs(dy) < 4 && Math.abs(dx) < 4) return;
      dragging = true;
      el._dragged = true;
      el.style.top = snapPx(origTop + dy) + 'px';
      el.style.opacity = '0.7';
      el.style.zIndex = '10';
      if (viewType === 'week' && dayStrs) {
        const bodyRect = body.getBoundingClientRect();
        const timeColW = 56;
        const colW = (bodyRect.width - timeColW) / 7;
        const relX = cx - bodyRect.left - timeColW;
        const newColIdx = Math.max(0, Math.min(6, Math.floor(relX / colW)));
        el.style.gridColumn = String(newColIdx + 2);
      }
    };
    const onUp = function () {
      document.removeEventListener('mousemove', mmh);
      document.removeEventListener('mouseup', muh);
      document.removeEventListener('touchmove', tmh);
      document.removeEventListener('touchend', teh);
      el.style.opacity = '';
      el.style.zIndex = '';
      if (!dragging) return;
      const newTop = Math.max(0, snapPx(parseFloat(el.style.top)));
      const evId = el.dataset.id;
      const newStart = pxToTime(newTop);
      const ce = calendarEvents.find((x) => x.id === evId);
      if (!ce) return;
      const [osh, osm] = (ce.startTime || '09:00').split(':').map(Number);
      const [oeh, oem] = (ce.endTime || '10:00').split(':').map(Number);
      const durMin = oeh * 60 + oem - (osh * 60 + osm);
      const [nsh, nsm] = newStart.split(':').map(Number);
      const endMin = nsh * 60 + nsm + durMin;
      const neh = Math.min(CAL_HOURS_END, Math.floor(endMin / 60));
      const nem = endMin % 60;
      const newEnd = String(neh).padStart(2, '0') + ':' + String(nem).padStart(2, '0');
      let newDate = el.dataset.date;
      if (viewType === 'week' && dayStrs) {
        const newColIdx = parseInt(el.style.gridColumn) - 2;
        if (newColIdx >= 0 && newColIdx < dayStrs.length) newDate = dayStrs[newColIdx];
      }
      updateEventTime(evId, newStart, newEnd, newDate);
    };
    const mmh = function (e) {
      onMove(e.clientX, e.clientY);
    };
    const muh = function () {
      onUp();
    };
    const tmh = function (e) {
      e.preventDefault();
      const t = e.touches[0];
      onMove(t.clientX, t.clientY);
    };
    const teh = function () {
      onUp();
    };
    document.addEventListener('mousemove', mmh);
    document.addEventListener('mouseup', muh);
    document.addEventListener('touchmove', tmh, { passive: false });
    document.addEventListener('touchend', teh);
  }
  el.addEventListener('mousedown', function (e) {
    if (e.target.classList.contains('ev-resize')) return;
    e.preventDefault();
    startDrag(e.clientX, e.clientY);
  });
  el.addEventListener(
    'touchstart',
    function (e) {
      if (e.target.classList.contains('ev-resize')) return;
      const t = e.touches[0];
      startDrag(t.clientX, t.clientY);
    },
    { passive: true }
  );
}

function initEventResize(el, handle, body, viewType) {
  function startResize(clientY) {
    el._resizing = true;
    const startY = clientY;
    const origHeight = parseFloat(el.style.height);
    let resizing = false;
    const onMove = function (cy) {
      const dy = cy - startY;
      if (!resizing && Math.abs(dy) < 4) return;
      resizing = true;
      el._dragged = true;
      const newH = Math.max(12, snapPx(origHeight + dy));
      el.style.height = newH + 'px';
    };
    const onUp = function () {
      document.removeEventListener('mousemove', mmh);
      document.removeEventListener('mouseup', muh);
      document.removeEventListener('touchmove', tmh);
      document.removeEventListener('touchend', teh);
      el._resizing = false;
      if (!resizing) return;
      const evId = el.dataset.id;
      const newHeight = Math.max(12, parseFloat(el.style.height));
      const topPx = parseFloat(el.style.top);
      const endPx = topPx + newHeight;
      const newEnd = pxToTime(endPx);
      const newStart = pxToTime(topPx);
      updateEventTime(evId, newStart, newEnd, null);
    };
    const mmh = function (e) {
      onMove(e.clientY);
    };
    const muh = function () {
      onUp();
    };
    const tmh = function (e) {
      e.preventDefault();
      onMove(e.touches[0].clientY);
    };
    const teh = function () {
      onUp();
    };
    document.addEventListener('mousemove', mmh);
    document.addEventListener('mouseup', muh);
    document.addEventListener('touchmove', tmh, { passive: false });
    document.addEventListener('touchend', teh);
  }
  handle.addEventListener('mousedown', function (e) {
    e.preventDefault();
    e.stopPropagation();
    startResize(e.clientY);
  });
  handle.addEventListener(
    'touchstart',
    function (e) {
      e.stopPropagation();
      startResize(e.touches[0].clientY);
    },
    { passive: true }
  );
}

// ── Calendar Event Click ──
function onCalEventClick(ev) {
  if (ev.type === 'harvest') return;
  openEventDetail(ev);
}

function openEventDetail(ev) {
  const titleEl = document.getElementById('cal-detail-title');
  const metaEl = document.getElementById('cal-detail-meta');
  const badgesEl = document.getElementById('cal-detail-badges');
  const assignEl = document.getElementById('cal-detail-assignee');
  const descEl = document.getElementById('cal-detail-desc');
  const btnsEl = document.getElementById('cal-detail-btns');

  if (ev.type === 'custom') {
    const ce = calendarEvents.find((x) => x.id === ev.id);
    if (!ce) return;
    titleEl.textContent = ce.title;
    const occDate = ev.date || ce.startDate;
    let meta = new Date(occDate).toLocaleDateString(loc(), {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });
    if (!ce.allDay && ce.startTime) meta += ', ' + ce.startTime + (ce.endTime ? ' — ' + ce.endTime : '');
    if (ce.endDate && ce.endDate !== ce.startDate)
      meta +=
        ' ' +
        t('calEntry.until') +
        ' ' +
        new Date(ce.endDate).toLocaleDateString(loc(), { day: 'numeric', month: 'long', year: 'numeric' });
    const place = ce.locationId ? pickupLocations.find((l) => l.id === ce.locationId) : null;
    if (place) meta += ' · ' + place.name;
    metaEl.textContent = meta;
    const catLabels = {
      custom: t('calEntry.cat.custom'),
      meeting: t('calEntry.cat.meeting'),
      delivery: t('calEntry.cat.delivery'),
      maintenance: t('calEntry.cat.maintenance'),
      pickup: t('calEntry.cat.pickup')
    };
    const recLabels = {
      daily: t('calEntry.rec.daily'),
      weekly: t('calEntry.rec.weekly'),
      monthly: t('calEntry.rec.monthly')
    };
    let badges =
      '<span class="fs-xs" style="display:inline-block;padding:2px 10px;border-radius:4px;font-weight:500;background:' +
      (CATEGORY_COLORS[ce.category] || safeColor(ce.color)) +
      ';color:#fff">' +
      esc(catLabels[ce.category] || ce.category) +
      '</span>';
    if (ce.recurrence)
      badges +=
        '<span class="fs-xs" style="display:inline-block;padding:2px 10px;border-radius:4px;font-weight:500;background:var(--c-text-muted);color:#fff">🔁 ' +
        esc(recLabels[ce.recurrence] || ce.recurrence) +
        '</span>';
    // Seats, but only where they mean something. A window with no number takes
    // as many as turn up, and saying "unbegrenzt" on every ordinary appointment
    // would be noise.
    if (ce.category === 'pickup' && ce.pickupCapacity !== null && ce.pickupCapacity !== undefined)
      badges +=
        '<span class="fs-xs" style="display:inline-block;padding:2px 10px;border-radius:4px;font-weight:500;background:var(--c-text-muted);color:#fff">' +
        esc(t('calDetail.seats', { n: ce.pickupCapacity })) +
        '</span>';
    badgesEl.innerHTML = badges;
    const teamList = Array.isArray(ce.teamAssignees) ? ce.teamAssignees : [];
    assignEl.innerHTML =
      t('calDetail.assignedTo') +
      ': <strong>' +
      (teamList.length ? teamList.map((n) => esc(n)).join(', ') : esc(t('calDetail.everyone'))) +
      '</strong>';
    descEl.textContent = ce.description || '';
    descEl.style.display = ce.description ? '' : 'none';
    btnsEl.innerHTML =
      '<button class="btn btn-r" data-cal-action="delete-event" data-cal-id="' +
      esc(ce.id) +
      '" data-cal-date="' +
      esc(occDate || '') +
      '">' +
      esc(t('calEntry.delete')) +
      '</button><span style="flex:1"></span><button class="btn" data-cal-action="close">' +
      esc(t('calDetail.close')) +
      '</button><button class="btn btn-p" data-cal-action="edit-event" data-cal-id="' +
      esc(ce.id) +
      '">' +
      esc(t('calDetail.edit')) +
      '</button>';
  } else if (ev.type === 'task-due') {
    const tk = manualTasks.find((x) => x.created === ev.id);
    if (!tk) return;
    titleEl.textContent = tk.text;
    let meta = t('calDetail.taskDue');
    if (tk.dueDate)
      meta +=
        ' — ' +
        t('calDetail.dueLabel') +
        ': ' +
        new Date(tk.dueDate).toLocaleDateString(loc(), { day: 'numeric', month: 'long', year: 'numeric' });
    if (tk.dueTime) meta += ', ' + tk.dueTime + (tk.dueEndTime ? ' — ' + tk.dueEndTime : '');
    metaEl.textContent = meta;
    const prioLabels = {
      high: t('calEntry.prio.high'),
      med: t('calEntry.prio.med'),
      medium: t('calEntry.prio.med'),
      low: t('calEntry.prio.low')
    };
    const prioColors = { high: '#ef4444', med: '#f59e0b', medium: '#f59e0b', low: '#22c55e' };
    const recLabels2 = {
      daily: t('calEntry.rec.daily'),
      weekly: t('calEntry.rec.weekly'),
      monthly: t('calEntry.rec.monthly')
    };
    let tBadges =
      '<span class="fs-xs" style="display:inline-block;padding:2px 10px;border-radius:4px;font-weight:500;background:var(--c-blue);color:#fff">' +
      esc(t('calDetail.taskDue')) +
      '</span>';
    if (tk.priority)
      tBadges +=
        '<span class="fs-xs" style="display:inline-block;padding:2px 10px;border-radius:4px;font-weight:500;background:' +
        (prioColors[tk.priority] || '#888') +
        ';color:#fff">' +
        esc(prioLabels[tk.priority] || tk.priority) +
        '</span>';
    if (tk.recurrence)
      tBadges +=
        '<span class="fs-xs" style="display:inline-block;padding:2px 10px;border-radius:4px;font-weight:500;background:var(--c-text-muted);color:#fff">🔁 ' +
        esc(recLabels2[tk.recurrence] || tk.recurrence) +
        '</span>';
    badgesEl.innerHTML = tBadges;
    const assigneeList = parseTaskAssignees(tk.assignee);
    assignEl.innerHTML =
      t('calDetail.assignedTo') +
      ': <strong>' +
      (assigneeList.length ? assigneeList.map((n) => esc(n)).join(', ') : esc(t('calDetail.everyone'))) +
      '</strong>';
    descEl.textContent = tk.description || '';
    descEl.style.display = tk.description ? '' : 'none';
    const doneLabel = tk.done ? t('calDetail.markUndone') : t('calDetail.markDone');
    btnsEl.innerHTML =
      '<button class="btn btn-r" data-cal-action="delete-task" data-cal-id="' +
      esc(ev.id) +
      '">' +
      esc(t('calEntry.delete')) +
      '</button><button class="btn' +
      (tk.done ? '' : ' btn-p') +
      '" data-cal-action="toggle-task" data-cal-id="' +
      esc(ev.id) +
      '">' +
      esc(doneLabel) +
      '</button><span style="flex:1"></span><button class="btn" data-cal-action="close">' +
      esc(t('calDetail.close')) +
      '</button><button class="btn btn-p" data-cal-action="edit-task" data-cal-id="' +
      esc(ev.id) +
      '">' +
      esc(t('calDetail.edit')) +
      '</button>';
  } else if (ev.type === 'batch-due') {
    titleEl.textContent = ev.label;
    const b = batches.find((x) => x.batchId === ev.id);
    let meta = t('calDetail.batchDue');
    if (b && b.due)
      meta += ' — ' + new Date(b.due).toLocaleDateString(loc(), { day: 'numeric', month: 'long', year: 'numeric' });
    metaEl.textContent = meta;
    badgesEl.innerHTML =
      '<span class="fs-xs" style="display:inline-block;padding:2px 10px;border-radius:4px;font-weight:500;background:var(--c-red);color:#fff">' +
      esc(t('calDetail.batchDue')) +
      '</span>';
    const curDate = b && b.due ? b.due.slice(0, 10) : '';
    assignEl.innerHTML =
      '<label class="fs-meta" style="color:var(--c-text-sec)">' +
      esc(t('calDetail.changeDate')) +
      '</label> <input type="date" id="cal-detail-batch-date" value="' +
      curDate +
      '" class="fs-sm" style="margin-left:8px;padding:4px 8px;border:1px solid var(--c-border);border-radius:4px;background:var(--c-bg);color:var(--c-text)">';
    assignEl._currentBatchId = ev.id;
    descEl.textContent = b ? b.species + (b.strain ? ' (' + b.strain + ')' : '') : '';
    descEl.style.display = '';
    btnsEl.innerHTML =
      '<span style="flex:1"></span><button class="btn" data-cal-action="close">' +
      esc(t('calDetail.close')) +
      '</button><button class="btn btn-p" data-cal-action="save-batch-due" data-cal-id="' +
      esc(ev.id) +
      '">' +
      esc(t('calEntry.save')) +
      '</button>';
  } else if (ev.type === 'caldav-import') {
    titleEl.textContent = ev.label;
    let meta = t('calDetail.external');
    if (ev.date)
      meta += ' — ' + new Date(ev.date).toLocaleDateString(loc(), { day: 'numeric', month: 'long', year: 'numeric' });
    if (ev.startTime) meta += ', ' + ev.startTime + (ev.endTime ? ' — ' + ev.endTime : '');
    metaEl.textContent = meta;
    badgesEl.innerHTML =
      '<span class="fs-xs" style="display:inline-block;padding:2px 10px;border-radius:4px;font-weight:500;background:var(--c-indigo);color:#fff">' +
      esc(t('calDetail.external')) +
      '</span>';
    assignEl.innerHTML = '';
    descEl.textContent = ev.description || '';
    descEl.style.display = ev.description ? '' : 'none';
    btnsEl.innerHTML = '<button class="btn" data-cal-action="close">' + esc(t('calDetail.close')) + '</button>';
  }
  document.getElementById('m-cal-detail').classList.add('open');
}

function closeEventDetail() {
  document.getElementById('m-cal-detail').classList.remove('open');
}

// Delegated click handler for calendar detail buttons (avoids inline onclick XSS).
document.getElementById('cal-detail-btns').addEventListener('click', function (e) {
  const btn = e.target.closest('[data-cal-action]');
  if (!btn) return;
  const action = btn.dataset.calAction;
  const id = btn.dataset.calId;
  const date = btn.dataset.calDate || '';
  if (action === 'close') return closeEventDetail();
  if (action === 'delete-event') return deleteCalEventFromDetail(id, date);
  if (action === 'edit-event') return editEventFromDetail(id);
  if (action === 'delete-task') return deleteTaskFromCalendar(id);
  if (action === 'toggle-task') return toggleTaskFromCalendar(id);
  if (action === 'edit-task') return editTaskFromCalendar(id);
  if (action === 'save-batch-due') return saveBatchDueFromDetail(id);
});

// Change handler for batch due-date picker in detail modal.
document.getElementById('cal-detail-assignee').addEventListener('change', function (e) {
  if (e.target.id !== 'cal-detail-batch-date') return;
  const newDate = e.target.value;
  if (!newDate) return;
  const batchId = this._currentBatchId;
  if (!batchId) return;
  handleCalendarDrop('batch-due', batchId, newDate);
  closeEventDetail();
});

function editEventFromDetail(id) {
  closeEventDetail();
  const ce = calendarEvents.find((x) => x.id === id);
  if (ce) openEventModal(ce.startDate, ce.startTime, ce);
}

function saveBatchDueFromDetail(id) {
  const picker = document.getElementById('cal-detail-batch-date');
  if (!picker || !picker.value) return;
  const b = batches.find((x) => x.batchId === id);
  if (!b) return;
  const newDue = new Date(picker.value + 'T12:00:00');
  b.due = newDue.toISOString();
  const created = new Date(b.created);
  b.days = Math.max(1, Math.round((newDue - created) / MS_PER_DAY));
  apiPatch('/api/batches/' + encodeURIComponent(id), { due: b.due, days: b.days });
  renderCalendar();
  pushBatchCaldav(b);
  closeEventDetail();
}

// ── Windows somebody has already booked into ────────────────
// `[{event, date, count}]`, refreshed when the calendar opens. The join between
// a calendar entry and its bookings is made on the server: a booking names the
// window by the id the harvest feed published, and reimplementing that id here
// would give two versions of one key. The one that drifts reads as "nobody has
// booked this", which is the answer that gets somebody sent away at a stall.
let pickupBookings = [];

async function loadPickupBookings() {
  const r = await apiGet('/api/pickup-bookings');
  pickupBookings = r && Array.isArray(r.booked) ? r.booked : [];
}

/** Bookings for one occurrence, or for the whole series when `date` is null. */
function bookedForWindow(eventId, date) {
  return pickupBookings
    .filter((b) => b.event === eventId && (!date || b.date === date))
    .reduce((n, b) => n + (Number(b.count) || 0), 0);
}

/**
 * Run `proceed`, asking first if anyone has booked into this window.
 *
 * Not a block — the lab may well have to cancel a market. It is the difference
 * between deciding to and finding out afterwards.
 */
function confirmBookedWindow(eventId, date, proceed) {
  const n = bookedForWindow(eventId, date);
  if (!n) {
    proceed();
    return;
  }
  confirm2(t('calEntry.bookedTitle'), t('calEntry.bookedMsg', { n }), t('calEntry.bookedGoOn'), proceed);
}

function findSameTitleEvents(ce) {
  if (!ce || !ce.title) return [];
  return calendarEvents.filter((x) => x.id !== ce.id && !x.recurrence && x.title === ce.title);
}

function deleteAllSameTitle(ids) {
  const idSet = new Set(ids);
  calendarEvents = calendarEvents.filter((x) => !idSet.has(x.id));
  renderCalendar();
  ids.forEach((eid) => apiDelete('/api/calendar-events/' + encodeURIComponent(eid)));
}

function deleteCalEventFromDetail(id, date) {
  closeEventDetail();
  const ce = calendarEvents.find((x) => x.id === id);
  const isRecurring = !!(ce && ce.recurrence);
  if (isRecurring && date) {
    confirm3(
      t('calEntry.deleteRecurTitle'),
      t('calEntry.deleteRecurMsg'),
      t('calEntry.deleteOccurrence'),
      t('calEntry.deleteSeries'),
      // One date, so only that date's bookings are at stake…
      () =>
        confirmBookedWindow(id, date, () => {
          if (!Array.isArray(ce.exceptionDates)) ce.exceptionDates = [];
          if (!ce.exceptionDates.includes(date)) ce.exceptionDates.push(date);
          renderCalendar();
          apiDelete('/api/calendar-events/' + encodeURIComponent(id) + '?occurrence=' + encodeURIComponent(date));
        }),
      // …and here every one of them, across the whole series.
      () =>
        confirmBookedWindow(id, null, () => {
          calendarEvents = calendarEvents.filter((x) => x.id !== id);
          renderCalendar();
          apiDelete('/api/calendar-events/' + encodeURIComponent(id));
        })
    );
    return;
  }
  if (!isRecurring) {
    const dups = findSameTitleEvents(ce);
    if (dups.length) {
      confirm3(
        t('calEntry.deleteDupTitle'),
        t('calEntry.deleteDupMsg', { n: dups.length }),
        t('calEntry.deleteOnlyThis'),
        t('calEntry.deleteAllSameTitle', { n: dups.length + 1 }),
        () => {
          calendarEvents = calendarEvents.filter((x) => x.id !== id);
          renderCalendar();
          apiDelete('/api/calendar-events/' + encodeURIComponent(id));
        },
        () => deleteAllSameTitle([id, ...dups.map((d) => d.id)])
      );
      return;
    }
  }
  confirm2(t('calEntry.deleteEvent'), t('calEntry.deleteEventMsg'), t('calEntry.delete'), () =>
    confirmBookedWindow(id, null, () => {
      calendarEvents = calendarEvents.filter((x) => x.id !== id);
      renderCalendar();
      apiDelete('/api/calendar-events/' + encodeURIComponent(id));
    })
  );
}

function toggleTaskFromCalendar(taskId) {
  const t = manualTasks.find((t) => t.created === taskId);
  if (!t) return;
  toggleTask(t.id);
  renderCalendar();
  closeEventDetail();
}

function deleteTaskFromCalendar(taskId) {
  closeEventDetail();
  confirm2(t('calEntry.deleteTask'), t('calEntry.deleteTaskMsg'), t('calEntry.delete'), () => {
    const tk = manualTasks.find((x) => x.created === taskId);
    if (!tk) return;
    manualTasks = manualTasks.filter((x) => x.id !== tk.id);
    apiDelete('/api/tasks/' + tk.id);
    renderCalendar();
    updateTodoBadge();
  });
}

// ─── UNIFIED CALENDAR ENTRY MODAL ─────────────────────────────
const CATEGORY_COLORS = {
  custom: '#16a34a',
  meeting: '#8b5cf6',
  delivery: '#14b8a6',
  maintenance: '#64748b',
  pickup: '#f59e0b'
};
let calEntryType = 'task';

// Fill the location dropdown. Retired locations are offered only when the event
// being edited already points at one — otherwise a window would silently lose
// its place the first time somebody opened it to change the time.
function fillEntryLocationSelect(selectedId) {
  const sel = document.getElementById('cal-entry-location');
  if (!sel) return;
  const chosen = selectedId ? Number(selectedId) : null;
  const options = pickupLocations.filter((l) => l.active !== false || l.id === chosen);
  sel.innerHTML =
    `<option value="">${esc(t('calEntry.placeNone'))}</option>` +
    options
      .map(
        (l) =>
          `<option value="${l.id}"${l.id === chosen ? ' selected' : ''}>${esc(l.name)}${
            l.active === false ? ' (' + t('pickupLoc.retired') + ')' : ''
          }</option>`
      )
      .join('');
  sel.value = chosen ? String(chosen) : '';
}

function setEntryType(type) {
  const isTask = type === 'task';
  calEntryType = isTask ? 'task' : 'event';
  document.getElementById('cal-entry-type-select').value = type;
  document.getElementById('cal-entry-enddate-wrap').style.display = isTask ? 'none' : '';
  // A pickup window without a clock is not a window: "Saturday" is not something
  // anyone can book into, and the feed skips such a row — silently, from the
  // author's point of view. So the option is not offered rather than explained.
  const isPickup = type === 'pickup';
  if (isPickup) document.getElementById('cal-entry-allday').checked = false;
  document.getElementById('cal-entry-allday-wrap').style.display = isPickup ? 'none' : '';
  document.getElementById('cal-entry-prio-wrap').style.display = isTask ? '' : 'none';
  document.getElementById('cal-entry-task-assign-wrap').style.display = isTask ? '' : 'none';
  document.getElementById('cal-entry-ev-assign-wrap').style.display = isTask ? 'none' : '';
  document.getElementById('cal-entry-private-wrap').style.display = isTask ? 'flex' : 'none';
  const recWrap = document.getElementById('cal-entry-recurrence-wrap');
  if (recWrap) recWrap.style.display = 'grid';
  // A place belongs to any appointment; the seat count only to a pickup window,
  // which is the only kind somebody outside the lab books into.
  const placeWrap = document.getElementById('cal-entry-place-wrap');
  if (placeWrap) placeWrap.style.display = isTask ? 'none' : 'grid';
  const capWrap = document.getElementById('cal-entry-capacity-wrap');
  if (capWrap) capWrap.style.display = type === 'pickup' ? '' : 'none';
  document.getElementById('cal-entry-name').placeholder = isTask ? t('calEntry.namePhTask') : t('calEntry.namePhEvent');
  toggleEntryTimeInputs();
  toggleRecurrenceUntil();
}
function toggleRecurrenceUntil() {
  const sel = document.getElementById('cal-entry-recurrence');
  const wrap = document.getElementById('cal-entry-recurrence-until-wrap');
  if (sel && wrap) wrap.style.display = sel.value ? '' : 'none';
}

function openEntryModal(type, date, time, existing) {
  const modal = document.getElementById('m-cal-entry');
  const isEdit = !!existing;
  document.getElementById('cal-entry-name').disabled = false;
  document.getElementById('cal-entry-desc').closest('div').style.display = '';
  document.getElementById('cal-entry-type-select').closest('.g2').style.display = '';
  document.getElementById('cal-entry-type-select').disabled = isEdit;
  setEntryType(type || 'task');
  if (type === 'task' && existing) {
    document.getElementById('cal-entry-title').textContent = t('calEntry.titleEdit');
    document.getElementById('cal-entry-mode').value = 'edit';
    document.getElementById('cal-entry-id').value = existing.id;
    document.getElementById('cal-entry-name').value = existing.text;
    document.getElementById('cal-entry-date').value = existing.dueDate ? existing.dueDate.split('T')[0] : '';
    document.getElementById('cal-entry-allday').checked = !existing.dueTime;
    document.getElementById('cal-entry-start-time').value = existing.dueTime || '09:00';
    document.getElementById('cal-entry-end-time').value = existing.dueEndTime || '10:00';
    document.getElementById('cal-entry-prio').value = existing.priority || 'med';
    calTaskSelectedAssignees = parseTaskAssignees(existing.assignee);
    renderTaskAssigneePicker();
    document.getElementById('cal-entry-desc').value = existing.description || '';
    document.getElementById('cal-entry-private').checked = !!existing.private;
    document.getElementById('cal-entry-recurrence').value = existing.recurrence || '';
    document.getElementById('cal-entry-recurrence-until').value = existing.recurrenceUntil || '';
    toggleRecurrenceUntil();
    document.getElementById('cal-entry-del-btn').style.display = '';
  } else if (type === 'event' && existing) {
    document.getElementById('cal-entry-title').textContent = t('calEntry.titleEdit');
    document.getElementById('cal-entry-mode').value = 'edit';
    document.getElementById('cal-entry-id').value = existing.id;
    document.getElementById('cal-entry-name').value = existing.title;
    document.getElementById('cal-entry-date').value = existing.startDate;
    document.getElementById('cal-entry-end-date').value = existing.endDate || '';
    document.getElementById('cal-entry-allday').checked = existing.allDay;
    document.getElementById('cal-entry-start-time').value = existing.startTime || '09:00';
    document.getElementById('cal-entry-end-time').value = existing.endTime || '10:00';
    setEntryType(existing.category || 'custom');
    fillEntryLocationSelect(existing.locationId);
    document.getElementById('cal-entry-capacity').value =
      existing.pickupCapacity === null || existing.pickupCapacity === undefined ? '' : existing.pickupCapacity;
    document.getElementById('cal-entry-desc').value = existing.description || '';
    calEvSelectedAssignees = Array.isArray(existing.teamAssignees) ? existing.teamAssignees.slice() : [];
    renderAssigneePicker();
    document.getElementById('cal-entry-recurrence').value = existing.recurrence || '';
    document.getElementById('cal-entry-recurrence-until').value = existing.recurrenceUntil || '';
    toggleRecurrenceUntil();
    document.getElementById('cal-entry-del-btn').style.display = '';
  } else {
    document.getElementById('cal-entry-title').textContent = t('calEntry.titleNew');
    document.getElementById('cal-entry-mode').value = 'create';
    document.getElementById('cal-entry-id').value = '';
    document.getElementById('cal-entry-name').value = '';
    document.getElementById('cal-entry-date').value = date || localDateStr(new Date());
    document.getElementById('cal-entry-end-date').value = '';
    document.getElementById('cal-entry-allday').checked = !time;
    document.getElementById('cal-entry-start-time').value = time || '09:00';
    const endH = time ? String(Math.min(23, parseInt(time) + 1)).padStart(2, '0') + ':00' : '10:00';
    document.getElementById('cal-entry-end-time').value = endH;
    document.getElementById('cal-entry-prio').value = 'med';
    calTaskSelectedAssignees = [];
    renderTaskAssigneePicker();
    document.getElementById('cal-entry-desc').value = '';
    document.getElementById('cal-entry-private').checked = false;
    calEvSelectedAssignees = [];
    renderAssigneePicker();
    document.getElementById('cal-entry-recurrence').value = '';
    document.getElementById('cal-entry-recurrence-until').value = '';
    toggleRecurrenceUntil();
    fillEntryLocationSelect(null);
    document.getElementById('cal-entry-capacity').value = '';
    document.getElementById('cal-entry-del-btn').style.display = 'none';
  }
  document.getElementById('cal-ev-assignee-dropdown').style.display = 'none';
  const tdd = document.getElementById('cal-task-assignee-dropdown');
  if (tdd) tdd.style.display = 'none';
  toggleEntryTimeInputs();
  modal.classList.add('open');
  if (!existing) setTimeout(() => document.getElementById('cal-entry-name').focus(), 50);
}

function parseTaskAssignees(val) {
  if (!val) return [];
  if (Array.isArray(val)) return val.slice();
  // Split comma-separated for backward compat with old single-assignee strings
  return String(val)
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
}

function openEventModal(date, time, existing) {
  openEntryModal(existing ? 'event' : 'custom', date, time, existing);
}

function closeEntryModal() {
  document.getElementById('m-cal-entry').classList.remove('open');
  const idEl = document.getElementById('cal-entry-id');
  idEl.dataset.moveType = '';
  idEl.dataset.moveId = '';
}

function toggleEntryTimeInputs() {
  const timesEl = document.getElementById('cal-entry-times');
  timesEl.style.display = document.getElementById('cal-entry-allday').checked ? 'none' : 'grid';
}

// Normalize a user-entered time string to 24h HH:MM, or '' if invalid.
// Accepts "9", "9:5", "930", "0930", "9:30", "09:30", etc.
function normalizeTimeInput(raw) {
  if (raw == null) return '';
  const s = String(raw).trim();
  if (!s) return '';
  const digits = s.replace(/\D/g, '');
  let h, m;
  if (digits.length <= 2) {
    h = parseInt(digits, 10);
    m = 0;
  } else if (digits.length === 3) {
    h = parseInt(digits.slice(0, 1), 10);
    m = parseInt(digits.slice(1), 10);
  } else {
    h = parseInt(digits.slice(0, 2), 10);
    m = parseInt(digits.slice(2, 4), 10);
  }
  if (!Number.isFinite(h) || !Number.isFinite(m)) return '';
  if (h < 0 || h > 23 || m < 0 || m > 59) return '';
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

function wireTimeInput(el) {
  if (!el || el.dataset.timeWired) return;
  el.dataset.timeWired = '1';
  el.addEventListener('blur', () => {
    const n = normalizeTimeInput(el.value);
    if (n) el.value = n;
  });
}

function saveEntry() {
  const mode = document.getElementById('cal-entry-mode').value;
  if (mode === 'move') {
    const idEl = document.getElementById('cal-entry-id');
    const moveType = idEl.dataset.moveType;
    const moveId = idEl.dataset.moveId;
    const newDate = document.getElementById('cal-entry-date').value;
    if (newDate && moveType) handleCalendarDrop(moveType, moveId, newDate);
    closeEntryModal();
    return;
  }
  if (calEntryType === 'task') saveEntryTask();
  else saveEntryEvent();
}

function saveEntryTask() {
  const mode = document.getElementById('cal-entry-mode').value;
  const text = document.getElementById('cal-entry-name').value.trim();
  if (!text) return;
  const prio = document.getElementById('cal-entry-prio').value;
  const due = document.getElementById('cal-entry-date').value || null;
  const allDay = document.getElementById('cal-entry-allday').checked;
  const dueTime =
    !allDay && due ? normalizeTimeInput(document.getElementById('cal-entry-start-time').value) || null : null;
  let dueEndTime =
    !allDay && due ? normalizeTimeInput(document.getElementById('cal-entry-end-time').value) || null : null;
  if (dueTime && dueEndTime && dueEndTime <= dueTime) dueEndTime = null;
  const assignee = calTaskSelectedAssignees.length ? calTaskSelectedAssignees.join(',') : null;
  const desc = document.getElementById('cal-entry-desc').value.trim() || null;
  const priv = document.getElementById('cal-entry-private').checked;
  const recurrence = document.getElementById('cal-entry-recurrence').value || null;
  const recurrenceUntil = recurrence ? document.getElementById('cal-entry-recurrence-until').value || null : null;
  if (mode === 'edit') {
    const id = parseInt(document.getElementById('cal-entry-id').value);
    const tk = manualTasks.find((x) => x.id === id);
    if (!tk) {
      closeEntryModal();
      return;
    }
    tk.text = text;
    tk.priority = prio;
    tk.dueDate = due;
    tk.dueTime = dueTime;
    tk.dueEndTime = dueEndTime;
    tk.assignee = assignee;
    tk.description = desc;
    tk.private = priv;
    tk.recurrence = recurrence;
    tk.recurrenceUntil = recurrenceUntil;
    tk.caldavSynced = null;
    apiPatch('/api/tasks/' + id, {
      text: tk.text,
      priority: tk.priority,
      dueDate: tk.dueDate,
      dueTime: tk.dueTime,
      dueEndTime: tk.dueEndTime,
      assignee: tk.assignee,
      description: tk.description,
      private: priv ? 1 : 0,
      recurrence,
      recurrenceUntil,
      caldavSynced: null
    });
    if (caldav.enabled && tk.caldavUid) pushTaskCaldav(tk);
  } else {
    const task = {
      text,
      priority: prio,
      done: false,
      created: new Date().toISOString(),
      assignee,
      dueDate: due,
      dueTime,
      dueEndTime,
      description: desc,
      caldavUid: null,
      caldavSynced: null,
      private: priv,
      recurrence,
      recurrenceUntil
    };
    manualTasks.push(task);
    apiPost('/api/tasks', task).then((r) => {
      if (r && r.id) {
        task.id = r.id;
        if (caldav.enabled && due) pushTaskCaldav(task);
      }
      renderCalendar();
      updateTodoBadge();
    });
  }
  closeEntryModal();
  if (document.getElementById('cal-entry-id').value) {
    renderCalendar();
    updateTodoBadge();
  }
}

function saveEntryEvent() {
  const mode = document.getElementById('cal-entry-mode').value;
  const name = document.getElementById('cal-entry-name').value.trim();
  if (!name) return;
  const allDay = document.getElementById('cal-entry-allday').checked;
  const category = document.getElementById('cal-entry-type-select').value;
  const recurrence = document.getElementById('cal-entry-recurrence').value || null;
  const recurrenceUntil = recurrence ? document.getElementById('cal-entry-recurrence-until').value || null : null;
  const teamAssignees = calEvSelectedAssignees.slice();
  const locationId = Number(document.getElementById('cal-entry-location').value) || null;
  // Only a pickup window has a seat count; anything else must not carry one
  // out of a field the user could not see. The empty string stays null
  // (uncapped) while a typed 0 survives as 0 (open, but taking nobody).
  const capRaw = document.getElementById('cal-entry-capacity').value;
  const pickupCapacity = category === 'pickup' && capRaw !== '' && capRaw != null ? Number(capRaw) : null;
  const ev = {
    id:
      mode === 'edit'
        ? document.getElementById('cal-entry-id').value
        : 'cev-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
    title: name,
    description: document.getElementById('cal-entry-desc').value.trim() || null,
    startDate: document.getElementById('cal-entry-date').value,
    endDate: document.getElementById('cal-entry-end-date').value || null,
    allDay: allDay,
    startTime: allDay ? null : normalizeTimeInput(document.getElementById('cal-entry-start-time').value) || null,
    endTime: allDay ? null : normalizeTimeInput(document.getElementById('cal-entry-end-time').value) || null,
    category: category,
    color: CATEGORY_COLORS[category] || '#16a34a',
    caldavUid: null,
    caldavSynced: null,
    created: new Date().toISOString(),
    recurrence: recurrence,
    recurrenceUntil: recurrenceUntil,
    teamAssignees: teamAssignees,
    assignees: [],
    locationId: locationId,
    pickupCapacity: pickupCapacity
  };
  // Somebody may already have arranged to turn up for this. Ask before the
  // arrangement changes underneath them — but only when the change is one they
  // would notice: a corrected title is not worth a dialog, a new time is.
  const previous = mode === 'edit' ? calendarEvents.find((x) => x.id === ev.id) : null;
  const movesAWindow =
    previous &&
    (previous.category === 'pickup' || category === 'pickup') &&
    (previous.startDate !== ev.startDate ||
      previous.startTime !== ev.startTime ||
      previous.endTime !== ev.endTime ||
      (previous.locationId || null) !== (ev.locationId || null) ||
      (previous.recurrence || null) !== (ev.recurrence || null) ||
      (previous.recurrenceUntil || null) !== (ev.recurrenceUntil || null) ||
      (previous.category === 'pickup' && category !== 'pickup'));
  if (movesAWindow) {
    confirmBookedWindow(ev.id, null, () => applyEntryEvent(ev, mode));
    return;
  }
  applyEntryEvent(ev, mode);
}

function applyEntryEvent(ev, mode) {
  if (mode === 'edit') {
    const idx = calendarEvents.findIndex((x) => x.id === ev.id);
    if (idx >= 0) {
      ev.caldavUid = calendarEvents[idx].caldavUid;
      ev.created = calendarEvents[idx].created;
      calendarEvents[idx] = ev;
    }
    apiPatch('/api/calendar-events/' + encodeURIComponent(ev.id), {
      title: ev.title,
      description: ev.description,
      startDate: ev.startDate,
      endDate: ev.endDate,
      allDay: ev.allDay,
      startTime: ev.startTime,
      endTime: ev.endTime,
      category: ev.category,
      color: ev.color,
      recurrence: ev.recurrence,
      recurrenceUntil: ev.recurrenceUntil,
      teamAssignees: ev.teamAssignees,
      // '' rather than null: updateCalendarEvent skips a field only when the key
      // is absent, and both spellings normalise to NULL — but sending '' keeps
      // "clear the place again" expressible through the same path that set it.
      locationId: ev.locationId === null ? '' : ev.locationId,
      pickupCapacity: ev.pickupCapacity === null ? '' : ev.pickupCapacity
    });
  } else {
    calendarEvents.push(ev);
    apiPost('/api/calendar-events', ev).then((r) => {
      if (r && r.id) ev.id = r.id;
    });
  }
  renderCalendar();
  closeEntryModal();
  if (caldav.enabled && typeof pushEventCaldav === 'function') pushEventCaldav(ev);
}

function deleteEntry() {
  if (calEntryType === 'task') {
    const id = parseInt(document.getElementById('cal-entry-id').value);
    if (!id) {
      closeEntryModal();
      return;
    }
    closeEntryModal();
    confirm2(t('calEntry.deleteTask'), t('calEntry.deleteTaskMsg'), t('calEntry.delete'), () => {
      manualTasks = manualTasks.filter((x) => x.id !== id);
      apiDelete('/api/tasks/' + id);
      renderCalendar();
      updateTodoBadge();
    });
  } else {
    const id = document.getElementById('cal-entry-id').value;
    if (!id) return;
    const ce = calendarEvents.find((x) => x.id === id);
    const isRecurring = !!(ce && ce.recurrence);
    closeEntryModal();
    if (!isRecurring) {
      const dups = findSameTitleEvents(ce);
      if (dups.length) {
        confirm3(
          t('calEntry.deleteDupTitle'),
          t('calEntry.deleteDupMsg', { n: dups.length }),
          t('calEntry.deleteOnlyThis'),
          t('calEntry.deleteAllSameTitle', { n: dups.length + 1 }),
          () => {
            calendarEvents = calendarEvents.filter((x) => x.id !== id);
            apiDelete('/api/calendar-events/' + encodeURIComponent(id));
            renderCalendar();
          },
          () => deleteAllSameTitle([id, ...dups.map((d) => d.id)])
        );
        return;
      }
    }
    const title = isRecurring ? t('calEntry.deleteRecurTitle') : t('calEntry.deleteEvent');
    const body = isRecurring ? t('calEntry.deleteSeriesMsg') : t('calEntry.deleteEventMsg');
    confirm2(title, body, t('calEntry.delete'), () =>
      confirmBookedWindow(id, null, () => {
        calendarEvents = calendarEvents.filter((x) => x.id !== id);
        apiDelete('/api/calendar-events/' + encodeURIComponent(id));
        renderCalendar();
      })
    );
  }
}

function editTaskFromCalendar(taskId) {
  closeEventDetail();
  const tk = manualTasks.find((x) => x.created === taskId);
  if (tk) openEntryModal('task', tk.dueDate, null, tk);
}

function onCalMonthEventClick(type, id) {
  if (!type || !id) return;
  const events = collectCalendarEvents();
  const ev = events.find((e) => e.type === type && String(e.id) === String(id));
  if (ev) onCalEventClick(ev);
}

async function pushEventCaldav(ev) {
  if (!caldav.enabled) return;
  try {
    const r = await authFetch('/api/caldav/push-event', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ event: ev })
    }).then((r) => r.json());
    if (r.ok && r.uid) {
      ev.caldavUid = r.uid;
      ev.caldavSynced = new Date().toISOString();
      apiPatch('/api/calendar-events/' + encodeURIComponent(ev.id), {
        caldavUid: ev.caldavUid,
        caldavSynced: ev.caldavSynced
      });
    }
  } catch (e) {
    console.error('CalDAV event push error:', e);
  }
}

// ── User list + Assignee picker ──
