  // Delegated clicks for Batch tasks + Ready-to-harvest cards
  function dashTaskCardClick(e) {
    const el = e.target.closest('[data-action]');
    if (!el) return;
    const action = el.dataset.action;
    if (action === 'dash-dest') {
      setFruitingTarget(el.dataset.zone);
      return;
    }
    if (action === 'edit-rhythm') {
      openRhythmEditor();
      return;
    }
    if (action === 'chore-done') {
      setChoreDone(el.dataset.task, el.dataset.date, el.dataset.done !== '1');
      return;
    }
    if (action === 'rhythm-target') {
      editRhythmTarget(el.dataset.date, Number(el.dataset.target));
      return;
    }
    if (action === 'dash-print') {
      // 'move' is the walk this card is mostly about; the modal has its own
      // group switcher for the rest.
      openWorkList('move');
      return;
    }
    if (action === 'dash-room-more') {
      toggleDashRoom(el.dataset.room);
      return;
    }
    if (action === 'dash-day') {
      setDashDay(el.dataset.off);
      return;
    }
    if (action === 'dash-view') {
      setDashView(el.dataset.day === '1');
      return;
    }
    if (action === 'bulk-fruiting') {
      bulkSectionToFruiting(el.dataset.bucket);
      return;
    }
    // Zogen mit den Hinweisen aus der eigenen Karte hierher; ihr alter
    // Zuhörer hängte an #dash-alerts, das es nicht mehr gibt.
    if (action === 'go-attention') {
      goToBatchesAttention(el.dataset.key);
      return;
    }
    if (action === 'go-page') {
      go(el.dataset.page, el.dataset.btn);
      return;
    }
    if (action === 'labgroup-toggle') {
      dashLabGroupOpen = !dashLabGroupOpen;
      renderDashBatchTasks();
      return;
    }
    // Laborarbeit für eine Art: alles, was ihr fehlt, in einem Dialog
    // (lbAnsetzen), wie der Knopf unter Nachproduzieren.
    if (action === 'labmin-make') {
      const id = parseInt(el.dataset.strain, 10);
      if (!_lbSpecies().some((x) => x.strainId === id)) {
        setFb('err', t('todo.supplyNoSorte'));
        return;
      }
      lbAnsetzen(id);
      return;
    }
    // A supply row carries a Sorte, not a batch — the batch is what it is
    // asking for. Both buttons open the quick-create the Pilzsorten page
    // already uses, with the Sorte filled in.
    if (action === 'supply-make-grain' || action === 'supply-make-batch') {
      const ms = _strainByKey(el.dataset.sorte);
      if (!ms) {
        setFb('err', t('todo.supplyNoSorte'));
        return;
      }
      // msQuickCharge() already says so itself when the Sorte carries no
      // recipe, so there is nothing to check here.
      if (action === 'supply-make-grain') {
        msQuickLabor(ms.id);
        _msqPickType('KB');
      } else msQuickCharge(ms.id);
      return;
    }
    const batch = el.dataset.batch;
    if (!batch) return;
    switch (action) {
      // Der Knopf heißt „Ernte erfassen", also erfasst er eine Ernte. Vorher
      // sprang er nur zur Charge, und nach dem Umbau lag sein Fall im
      // Verteiler der Chargenliste — er tat gar nichts mehr.
      case 'harvest-batch':
        wkfOpen('harvest');
        wkfPickBatch(batch);
        break;
      case 'go-to-batch':
        goToBatch(batch);
        break;
      case 'open-move-modal':
        openMoveBatchModal(batch);
        break;
      case 'move-to-fruiting':
        moveBatchToFruiting(batch);
        break;
      case 'inoculate-from':
        inoculateFromBatch(batch);
        break;
    }
  }
  $('dash-batch-tasks').addEventListener('click', dashTaskCardClick);
