// Camera FAB is in the HTML *after* the <script> tag, so it doesn't exist
// when initEventListeners() runs. Bind it once the full DOM is ready.
document.addEventListener('DOMContentLoaded', function () {
  const fab = document.getElementById('cam-fab');
  if (fab)
    fab.addEventListener('click', function () {
      // Front-door scan: always start neutral so scanning a bag opens its
      // action sheet, never a leftover armed mode from an earlier session.
      //
      // Bis auf einen Umzug oder eine Ernte, die eben noch liefen: ein Anruf,
      // die Sperre oder ein Tipp neben das Bild schließen die Kamera mitten in
      // der Reihe, und wer gleich weitermacht, soll nicht wieder von vorn
      // anfangen. Was "eben" heißt und warum Entsorgen nie dazugehört, steht an
      // MODE_RUN_KEEP_MS. Die Meldung sagt, dass er noch läuft — ein Vorgang,
      // von dem man nichts weiß, bucht den nächsten Beutel.
      const weiter = modeRunResumable();
      if (!weiter) {
        scan.action = null;
        scan.to = null;
        scan.from = null;
        scan.harvestBag = null;
        _modeRun = null;
      }
      updateSD();
      openCamScan();
      if (weiter) {
        _showCamHudToast(
          'info',
          scan.action === 'MOVE' ? t('cam.moveResumed', { loc: zoneDisplayName(scan.to) }) : t('cam.harvestResumed')
        );
      }
    });

  // Back rows for the sub-tab strips. Here rather than in initEventListeners()
  // for the same reason as the FAB above: this inserts elements, and doing that
  // once the document is settled keeps it off the critical path.
  stabDrillInit();
  gsInit();

  // PWA shortcuts (manifest.json -> shortcuts[]) launch with ?action=...
  // Wait until the rest of the app has had a chance to fetch data + render
  // before dispatching, so go() / openCamScan find the elements they need.
  try {
    const actionParam = new URLSearchParams(window.location.search).get('action');
    if (actionParam) {
      window.setTimeout(function () {
        if (actionParam === 'scan') {
          if (typeof openCamScan === 'function') openCamScan();
        } else if (actionParam === 'newbatch') {
          // Old New-batch form is hidden; open the Sorte-driven create dialog directly.
          if (typeof msQuickChargeNew === 'function') msQuickChargeNew();
        } else if (actionParam === 'dash') {
          if (typeof go === 'function') go('dash', 'n-dash');
        }
        // Clean up the URL so a refresh doesn't re-trigger the action.
        try {
          window.history.replaceState({}, '', window.location.pathname);
        } catch (e) {
          /* ignore */
        }
      }, 400);
    }
  } catch (e) {
    /* ignore — bad URL or no URLSearchParams */
  }
});

// ═══ ARBEITSGÄNGE ════════════════════════════════════════════════════════════
// The launcher page and the click-driven flows behind it.
//
// Every job in here already existed — it just could only be started by scanning
// a barcode. openBagInfo() had exactly one caller, inside the scan engine, and
// the harvest panel's bag field is readonly, so on a laptop (which never scans
// here) most of the app was unreachable. These flows reach the same functions
// from a list instead. The scanner still works and is still faster on the
// tablet; it is no longer the only door.
//
// One modal shell (#m-work-flow) carries all of them, so picking a batch looks
// the same whether you are harvesting, moving or reporting a contamination.

const WKF = {
  kind: null, // 'harvest' | 'move' | 'contam'
  step: null, // 'pick' | 'detail' | 'done'
  batchId: null,
  grams: {}, // bagId -> raw input string (harvest)
  // Leer: jeder Beutel bekommt seinen eigenen nächsten Flush. Eine Zahl gilt
  // für alle Beutel dieses Durchgangs — für Wellen, die über mehrere Tage
  // gepflückt werden und trotzdem eine Welle sind.
  flushOverride: null,
  releaseAll: false,
  dest: null, // destination zone id (move)
  receipt: null
};

function wkf(id) {
  return document.getElementById(id);
}

// Where a bag sits right now. The last placement scan wins; a REMOVE or no
// entry at all means it is not on a shelf, so it is not offered for work.
function wkBagZone(lastByBag, bagId) {
  const last = lastByBag.get(String(bagId).toUpperCase());
  if (!last || last.action === 'REMOVE' || !last.to) return null;
  return toZone(last.to);
}

// What a bag has already yielded. Shown in the harvest list so a second flush
// starts from what the first one brought instead of looking like a fresh bag.
function wkBagHarvested(bagId) {
  const k = String(bagId).toUpperCase();
  let grams = 0;
  let lastFlush = 0;
  for (const h of harvests) {
    if (String(h.bag || '').toUpperCase() !== k) continue;
    grams += Number(h.grams) || 0;
    lastFlush = Math.max(lastFlush, Number(h.flush) || 1);
  }
  return { grams, lastFlush };
}

// Der nächste Flush dieses Beutels. Ein Beutel, der noch nie geerntet wurde,
// liefert Flush 1 — unabhängig davon, wie oft seine Nachbarn schon dran waren.
function wkBagFlush(bag) {
  return (wkBagHarvested(bag).lastFlush || 0) + 1;
}

// Der Flush, der für diesen Beutel gebucht wird. `lastFlush` reicht wkLiveBags()
// schon herum — ohne das Argument liest diese Funktion alle Ernten noch einmal,
// und das je Zeile der Liste.
function wkfBagFlush(bag, lastFlush) {
  if (WKF.flushOverride) return WKF.flushOverride;
  return lastFlush != null ? lastFlush + 1 : wkBagFlush(bag);
}

// Batches that still have bags standing somewhere, newest first. `roles` limits
// it to zone roles that make sense for the job (harvest only offers fruiting).
function wkLiveBatches(roles) {
  const lastByBag = buildLastScanByBag();
  const out = [];
  for (const b of batches) {
    const bags = b.bags || [];
    if (!bags.length) continue;
    const perZone = {};
    let live = 0;
    for (const bag of bags) {
      const z = wkBagZone(lastByBag, bag);
      if (!z) continue;
      const role = (ZONE_BY_ID[z] || {}).role;
      if (roles && roles.indexOf(role) === -1) continue;
      perZone[z] = (perZone[z] || 0) + 1;
      live++;
    }
    if (!live) continue;
    const zoneId = Object.keys(perZone).sort((a, c) => perZone[c] - perZone[a])[0];
    out.push({ batch: b, live, zoneId, zoneName: (ZONE_BY_ID[zoneId] || {}).name || zoneId });
  }
  out.sort((a, c) => String(c.batch.created || '').localeCompare(String(a.batch.created || '')));
  return out;
}

// Bags of one batch that are still standing, with their zone and history.
function wkLiveBags(batchId, roles) {
  const b = batches.find((x) => x.batchId === batchId);
  if (!b) return [];
  const lastByBag = buildLastScanByBag();
  const out = [];
  for (const bag of b.bags || []) {
    const z = wkBagZone(lastByBag, bag);
    if (!z) continue;
    const role = (ZONE_BY_ID[z] || {}).role;
    if (roles && roles.indexOf(role) === -1) continue;
    out.push({ bag, zoneId: z, zoneName: (ZONE_BY_ID[z] || {}).name || z, ...wkBagHarvested(bag) });
  }
  return out;
}

// ─── Modal shell ─────────────────────────────────────────────────────────────

function wkfOpen(kind) {
  WKF.kind = kind;
  WKF.step = 'pick';
  WKF.batchId = null;
  WKF.grams = {};
  WKF.flushOverride = null;
  WKF.releaseAll = false;
  WKF.dest = null;
  WKF.receipt = null;
  wkf('m-work-flow').classList.add('open');
  wkfRender();
}

function wkfClose() {
  wkf('m-work-flow').classList.remove('open');
  // Die Beimpf-Liste gehört zu genau einer Charge. Wer den Ablauf verlässt,
  // nimmt sie nicht in die nächste mit; beim Anlegen ist sie vorher kopiert.
  if (WKF.kind === 'batch') _inoc = [];
  WKF.kind = null;
  WKF.step = null;
  WKF.receipt = null;
}

// Der Kopf-Knopf gehört allen vier Abläufen, aber jeder hat seinen eigenen
// Schrittzähler. Ohne diese Weiche lief er immer durch die Ernte-/Umzugs-
// Maschine — im Chargen-Assistenten landete man damit im Umzugsbildschirm
// und konnte von dort einen echten Umzug buchen.
function wkfBackDispatch() {
  if (WKF.kind === 'batch') return wkbBack();
  if (WKF.kind === 'mix') return wkfClose();
  wkfBack();
}
function wkfBack() {
  if (WKF.step === 'detail') {
    WKF.step = 'pick';
    WKF.batchId = null;
    // Ein Ziel aus der vorigen Charge darf nicht überleben: der Fußknopf ist
    // allein an WKF.dest gebunden, also wäre „Buchen" beim nächsten Schritt
    // sofort aktiv und würde in eine Zone buchen, die niemand gewählt hat.
    WKF.dest = null;
    wkfRender();
    return;
  }
  wkfClose();
}

function wkfTitle() {
  if (WKF.step === 'done') return t('work.receiptTitle');
  if (WKF.kind === 'harvest') return t('work.harvest');
  if (WKF.kind === 'move') return t('work.move');
  if (WKF.kind === 'contam') return t('work.contam');
  return '';
}

// Step chips. They exist so a worker can see how far along the job is and that
// it will end — a two-step form with no end in sight is where people bail out.
function wkfStepChips() {
  const labels =
    WKF.kind === 'harvest'
      ? [t('work.stepBatch'), t('work.stepGrams'), t('work.stepBooked')]
      : WKF.kind === 'move'
        ? [t('work.stepBatch'), t('work.stepTarget'), t('work.stepBooked')]
        : [t('work.stepBatch'), t('work.stepReport')];
  const at = WKF.step === 'pick' ? 0 : WKF.step === 'detail' ? 1 : 2;
  return (
    '<div class="wkf-chips">' +
    labels
      .map((l, i) => {
        const cls = i < at ? 'wkf-chip done' : i === at ? 'wkf-chip now' : 'wkf-chip';
        return `<span class="${cls}">${i < at ? '&#10003; ' : ''}${esc(l)}</span>`;
      })
      .join('') +
    '</div>'
  );
}

function wkfRender() {
  // Nur die drei Abläufe, die diese Hülle selbst zeichnet. Der Assistent und
  // das Mischen bringen ihre eigenen Renderer mit — ein später Rückruf darf
  // deren Bildschirm nicht durch einen Umzugsbildschirm ersetzen.
  if (WKF.kind !== 'harvest' && WKF.kind !== 'move' && WKF.kind !== 'contam') return;
  wkf('wkf-title').textContent = wkfTitle();
  wkf('wkf-back').hidden = WKF.step !== 'detail';
  wkf('wkf-steps').innerHTML = WKF.step === 'done' ? '' : wkfStepChips();
  if (WKF.step === 'pick') return wkfRenderPick();
  if (WKF.step === 'detail') return WKF.kind === 'harvest' ? wkfRenderHarvest() : wkfRenderMove();
  if (WKF.step === 'done') return wkfRenderReceipt();
}

// ─── Step 1: which batch ─────────────────────────────────────────────────────

function wkfRenderPick() {
  const roles = WKF.kind === 'harvest' ? ['fruiting'] : null;
  const rows = wkLiveBatches(roles);
  const hint =
    WKF.kind === 'harvest'
      ? t('work.pickHarvestHint')
      : WKF.kind === 'move'
        ? t('work.pickMoveHint')
        : t('work.pickContamHint');
  if (!rows.length) {
    wkf('wkf-body').innerHTML =
      '<div class="wkf-empty">' +
      esc(WKF.kind === 'harvest' ? t('work.noFruiting') : t('work.noBatches')) +
      '</div>';
    wkf('wkf-foot').innerHTML = `<button class="btn" onclick="wkfClose()">${esc(t('work.close'))}</button>`;
    return;
  }
  wkf('wkf-body').innerHTML =
    `<div class="wkf-hint">${esc(hint)}</div>` +
    '<div class="wkf-list">' +
    rows
      .map(
        (r) => `<button type="button" class="wkf-row" onclick="wkfPickBatch('${esc(r.batch.batchId)}')">
        <span class="wkf-row-id">${esc(r.batch.batchId)}</span>
        <span class="wkf-row-meta">${esc(r.batch.species || '')} &middot; ${r.live} ${esc(t('work.bags'))}</span>
        <span class="wkf-row-zone">${esc(r.zoneName)}</span>
      </button>`
      )
      .join('') +
    '</div>';
  wkf('wkf-foot').innerHTML = `<button class="btn" onclick="wkfClose()">${esc(t('work.cancel'))}</button>`;
}

function wkfPickBatch(batchId) {
  WKF.batchId = batchId;
  // Siehe wkfBack(): eine Zielzone gilt immer nur für die Charge, für die sie
  // gewählt wurde.
  WKF.dest = null;
  // The contamination report is already a finished dialog — it only ever lacked
  // a way in that wasn't a scan. So this flow hands over and gets out of the way.
  if (WKF.kind === 'contam') {
    wkfClose();
    openContamReport(null, batchId, null);
    return;
  }
  if (WKF.kind === 'harvest') {
    // Kein gemeinsamer Flush mehr: jeder Beutel bringt seinen eigenen mit,
    // siehe wkBagFlush(). Ein Durchgang kann Erst- und Zweiternte mischen,
    // und genau das kam vorher falsch heraus.
    WKF.grams = {};
    // Übersteuerung und Freigabe gelten für die Charge, für die sie gewählt
    // wurden. „Alle freigeben" hat vorher jede weitere Charge mit abgeräumt.
    WKF.flushOverride = null;
    WKF.releaseAll = false;
  }
  WKF.step = 'detail';
  wkfRender();
}

// ─── Step 2a: harvest — one row per bag ──────────────────────────────────────

function wkfRenderHarvest() {
  const bags = wkLiveBags(WKF.batchId, ['fruiting']);
  const b = batches.find((x) => x.batchId === WKF.batchId);
  if (!bags.length) {
    wkf('wkf-body').innerHTML = `<div class="wkf-empty">${esc(t('work.noBagsInZone'))}</div>`;
    wkf('wkf-foot').innerHTML = `<button class="btn" data-wk="back">${esc(t('work.back'))}</button>`;
    return;
  }
  const relRow = harvestRelease.on
    ? `<label class="wkf-check"><input type="checkbox" id="wkf-release-all" ${WKF.releaseAll ? 'checked' : ''}
         onchange="WKF.releaseAll = this.checked" /> <span>${esc(t('work.releaseAll'))}</span></label>`
    : '';
  wkf('wkf-body').innerHTML =
    `<div class="wkf-hint">${esc(t('work.gramsHint'))}</div>
     <div class="wkf-bar">
       <label for="wkf-flush">${esc(t('harvest.flush'))}</label>
       <input type="number" id="wkf-flush" min="1" inputmode="numeric"
              value="${WKF.flushOverride || ''}" placeholder="${esc(t('work.flushAuto'))}"
              onchange="WKF.flushOverride = Math.max(0, parseInt(this.value, 10) || 0) || null; wkfRender()" />
       <span class="wkf-bar-sp">${esc(b ? b.species || '' : '')}</span>
     </div>
     ${relRow}
     <div class="wkf-bags">` +
    bags
      .map((x) => {
        // Was der Beutel bisher brachte, und welcher Flush jetzt gebucht wird —
        // beides an der Zeile, weil beides je Beutel verschieden sein kann.
        const fl = esc(t('work.flushN', { n: wkfBagFlush(x.bag, x.lastFlush) }));
        const prev = x.grams
          ? `<span class="wkf-prev">${esc(t('work.already', { g: Math.round(x.grams) }))} · ${fl}</span>`
          : `<span class="wkf-prev">${fl}</span>`;
        const val = WKF.grams[x.bag] != null ? esc(String(WKF.grams[x.bag])) : '';
        return `<div class="wkf-bag">
          <span class="wkf-bag-id">${esc(x.bag)}</span>
          ${prev}
          <input type="text" inputmode="decimal" class="wkf-g" data-bag="${esc(x.bag)}" value="${val}"
                 placeholder="0" aria-label="${esc(t('harvest.grams'))} ${esc(x.bag)}" />
          <span class="wkf-unit">g</span>
        </div>`;
      })
      .join('') +
    '</div>' +
    `<div class="wkf-sum"><b id="wkf-total">0</b> <span id="wkf-total-sub">${esc(t('work.sumEmpty'))}</span></div>`;
  wkf('wkf-foot').innerHTML =
    `<button class="btn" data-wk="back">${esc(t('work.back'))}</button>` +
    `<button class="btn btn-p" id="wkf-book" data-wk="book-harvest">${esc(t('work.book'))}</button>`;
  wkfUpdateTotal();
}

function wkfGramsInput(el) {
  WKF.grams[el.dataset.bag] = el.value;
  wkfUpdateTotal();
}

// Live total. Bags left empty are not booked at all — that is what makes the
// list safe to walk down: you fill in the ones you actually picked.
function wkfUpdateTotal() {
  let total = 0;
  let n = 0;
  for (const k of Object.keys(WKF.grams)) {
    const g = parseDecimal(WKF.grams[k]);
    if (g && g > 0) {
      total += g;
      n++;
    }
  }
  const el = wkf('wkf-total');
  if (!el) return;
  el.textContent = total ? (total >= 1000 ? (total / 1000).toFixed(2) + ' kg' : Math.round(total) + ' g') : '0';
  wkf('wkf-total-sub').textContent = n ? t('work.sumFrom', { n }) : t('work.sumEmpty');
  const book = wkf('wkf-book');
  if (book) book.disabled = n === 0;
}

function wkfBookHarvest() {
  const b = batches.find((x) => x.batchId === WKF.batchId);
  if (!b) return;
  const picked = [];
  for (const bag of Object.keys(WKF.grams)) {
    const g = parseDecimal(WKF.grams[bag]);
    if (g && g > 0) picked.push({ bag, grams: g });
  }
  if (!picked.length) return;
  // Einmal lesen, zweimal benutzen: für den Flush je Beutel und für die Frage,
  // was nach diesem Durchgang noch steht. Sonst läuft wkBagHarvested() je Beutel
  // noch einmal durch alle Ernten.
  const standing = wkLiveBags(WKF.batchId, ['fruiting']);
  const lastFlushByBag = {};
  for (const x of standing) lastFlushByBag[x.bag] = x.lastFlush;
  const time = new Date().toISOString();
  let total = 0;
  const entries = picked.map((p) => {
    total += p.grams;
    return {
      time,
      batch: b.batchId,
      bag: p.bag,
      species: b.species,
      strain: b.strain,
      grams: p.grams,
      flush: wkfBagFlush(p.bag, lastFlushByBag[p.bag])
    };
  });
  const left = standing.filter((x) => !WKF.grams[x.bag] || !parseDecimal(WKF.grams[x.bag]));
  // Zuerst der Zettel, dann die Buchungen: so hat jede Antwort einen festen
  // Adressaten für ihren Fehler, auch wenn der Arbeiter inzwischen weiter ist.
  const receipt = {
    batchId: b.batchId,
    species: b.species || '',
    by: (currentUser && currentUser.username) || '—',
    grams: total,
    bags: picked.length,
    bagsTotal: (b.bags || []).length,
    released: WKF.releaseAll,
    releaseFailed: 0,
    next: left.length ? { label: t('work.nextHarvest', { n: left.length }), action: 'harvest-again' } : null
  };
  wkfHarvestReceiptText(receipt);
  WKF.receipt = receipt;
  WKF.step = 'done';
  wkfRender();
  // Mirror the single-bag panel: push locally so the totals update at once, and
  // roll the entry back if the server refuses it.
  entries.forEach((e) => {
    harvests.push(e);
    const body = WKF.releaseAll ? { ...e, release: e.grams } : e;
    apiPost('/api/harvests', body).then((r) => {
      if (r && r.error) {
        const i = harvests.lastIndexOf(e);
        if (i >= 0) harvests.splice(i, 1);
        // Die Kopfzeile darf die abgelehnten Gramm nicht weiter mitzählen.
        receipt.grams -= e.grams;
        receipt.bags--;
        wkfHarvestReceiptText(receipt);
        wkfReceiptProblem(t('work.bookFailed', { bag: e.bag, err: r.error }), receipt);
        if (typeof renderHarvests === 'function') renderHarvests();
        return;
      }
      if (r && r.releaseError) {
        // Freigegeben stimmt dann nur noch für einen Teil.
        receipt.releaseFailed++;
        wkfHarvestReceiptText(receipt);
        wkfReceiptProblem(t('harvest.releaseFailed', { bag: e.bag }) + ': ' + r.releaseError, receipt);
      }
    });
    const sEntry = {
      time,
      action: 'HARVEST',
      batch: b.batchId,
      bag: e.bag,
      from: null,
      to: null,
      species: b.species,
      strain: b.strain,
      grams: e.grams,
      // Der Flush steht am Eintrag selbst, seit er je Beutel bestimmt wird.
      flush: e.flush,
      _tempId: 's' + ++_scanTempIdCounter
    };
    if (!sessionStartTime) sessionStartTime = Date.now();
    sessionEntries.push(sEntry);
  });
  if (typeof renderHarvests === 'function') renderHarvests();
  if (typeof updateSD === 'function') updateSD();
  if (typeof renderStatus === 'function') renderStatus();
}

// ─── Step 2b: move — where to ────────────────────────────────────────────────

function wkfRenderMove() {
  const bags = wkLiveBags(WKF.batchId, null);
  // Vor dem Aufbau, nicht danach: vorher wurde die Fußzeile mit einem aktiven
  // „Buchen" geschrieben und erst anschließend der Körper durch den Leerfall
  // ersetzt — der Knopf blieb stehen und buchte auf eine Charge ohne Beutel.
  // Die Charge selbst wird nicht mehr mitgeprüft: ist sie zwischen Auswahl und
  // Anzeige verschwunden, liefert wkLiveBags() ohnehin nichts, und der Leerfall
  // muss dann erst recht greifen — sonst steht ein Buchen-Knopf da, den
  // wkfBookMove() anschließend wortlos verweigert.
  if (!bags.length) {
    wkf('wkf-body').innerHTML = `<div class="wkf-empty">${esc(t('work.noBagsStanding'))}</div>`;
    wkf('wkf-foot').innerHTML = `<button class="btn" data-wk="back">${esc(t('work.back'))}</button>`;
    return;
  }
  const here = bags[0].zoneId;
  const targets = zones.filter((z) => z.id !== here);
  wkf('wkf-body').innerHTML =
    `<div class="wkf-hint">${esc(t('work.moveHint', { n: bags.length, batch: WKF.batchId }))}</div>` +
    '<div class="wkf-zones">' +
    targets
      .map(
        (z) => `<button type="button" class="wkf-zone${WKF.dest === z.id ? ' sel' : ''}"
          onclick="WKF.dest='${esc(z.id)}'; wkfRender()">
          <span class="wkf-zone-dot" style="background:${esc(z.color || '#94a3b8')}"></span>
          <span class="wkf-zone-n">${esc(z.name || z.id)}</span>
        </button>`
      )
      .join('') +
    '</div>';
  wkf('wkf-foot').innerHTML =
    `<button class="btn" data-wk="back">${esc(t('work.back'))}</button>` +
    `<button class="btn btn-p" data-wk="book-move" ${WKF.dest ? '' : 'disabled'}>${esc(t('work.book'))}</button>`;
}

function wkfBookMove() {
  const b = batches.find((x) => x.batchId === WKF.batchId);
  if (!b || !WKF.dest) return;
  const destZone = ZONE_BY_ID[WKF.dest] || {};
  moveBatchTo(b, WKF.dest, function (moved, skipped) {
    WKF.receipt = {
      headline: t('work.receiptMove', { n: moved, zone: destZone.name || WKF.dest }),
      lines: [
        [t('work.rBatch'), b.batchId],
        [t('work.rMoved'), String(moved)],
        [t('work.rSkipped'), String(skipped || 0)],
        [t('work.rBy'), (currentUser && currentUser.username) || '—']
      ],
      next: null
    };
    WKF.step = 'done';
    wkfRender();
    if (typeof renderBatches === 'function') renderBatches();
    if (typeof renderStatus === 'function') renderStatus();
    if (typeof updateSD === 'function') updateSD();
  });
}

// ─── Step 3: the receipt ─────────────────────────────────────────────────────
// Shown after every flow. A worker who is new needs to see that something was
// booked, what it changed, and what the obvious next move is — otherwise the
// only feedback is a form that closed.

// Kopfzeile und Beutelzeile der Ernte-Quittung, gerechnet aus den Zahlen, die
// wirklich gebucht sind. Lehnt der Server hinterher eine Zeile ab, wird das hier
// noch einmal aufgerufen — vorher blieb die Kopfzeile auf dem Wunschwert stehen.
function wkfHarvestReceiptText(r) {
  r.headline = t('work.receiptHarvest', {
    kg: r.grams >= 1000 ? (r.grams / 1000).toFixed(2) + ' kg' : Math.round(r.grams) + ' g',
    species: r.species
  });
  r.lines = [
    [t('work.rBatch'), r.batchId],
    [t('work.rBags'), t('work.rBagsVal2', { n: r.bags, total: r.bagsTotal })],
    [
      t('work.rReleased'),
      !r.released
        ? t('work.rReleasedNo')
        : r.releaseFailed
          ? t('work.rReleasedPartial', { n: r.releaseFailed })
          : t('work.rReleasedYes')
    ],
    [t('work.rBy'), r.by]
  ];
}

// Ein Fehler, der eintrifft, nachdem die Quittung schon steht. Er geht immer
// durch setFb — das zählt ihn mit, schreibt ihn ins Scan-Protokoll und piept —
// und zusätzlich auf seinen Zettel. Vorher ging er restlos verloren, sobald der
// Arbeiter die Quittung geschlossen oder die nächste Ernte begonnen hatte.
// `owner` ist der Zettel, zu dem die Buchung gehört: ohne ihn hängt eine späte
// Meldung an der Quittung eines ganz anderen Durchgangs.
function wkfReceiptProblem(msg, owner) {
  setFb('err', msg, { noModal: true });
  const r = owner || WKF.receipt;
  if (!r) return;
  r.problems = (r.problems || []).concat(msg);
  if (WKF.receipt === r && WKF.step === 'done') wkfRenderReceipt();
}

function wkfRenderReceipt() {
  const r = WKF.receipt;
  if (!r) return wkfClose();
  wkf('wkf-body').innerHTML =
    `<div class="wkf-receipt">
       <div class="wkf-r-head"><span class="wkf-r-tick">&#10003;</span><b>${esc(r.headline)}</b></div>
       <div class="wkf-r-lines">` +
    r.lines.map((l) => `<div><span class="wkf-r-k">${esc(l[0])}</span><span>${esc(l[1])}</span></div>`).join('') +
    '</div>' +
    (r.problems && r.problems.length
      ? '<div class="wkf-note bad" style="margin:10px 0 0">' + r.problems.map((x) => esc(x)).join('<br>') + '</div>'
      : '') +
    '</div>';
  wkf('wkf-foot').innerHTML =
    (r.next ? `<button class="btn btn-p" data-wk="receipt-next">${esc(r.next.label)}</button>` : '') +
    `<button class="btn" onclick="wkfClose()">${esc(t('work.done'))}</button>`;
}

function wkfReceiptNext() {
  const r = WKF.receipt;
  if (r && r.next && r.next.action === 'harvest-again') {
    const batchId = WKF.batchId;
    wkfOpen('harvest');
    wkfPickBatch(batchId);
    return;
  }
  wkfClose();
}

// ─── Launcher wiring ─────────────────────────────────────────────────────────

// Körnerbrut is a Laborarbeit type in the data model, so it opens the same
// guided dialog with its type preselected rather than getting a second one.
function wkOpenGrain() {
  msQuickLaborNew();
  const sel = document.getElementById('ms-q-labtype');
  if (sel) {
    sel.value = 'KB';
    if (typeof msQuickLabTypeChanged === 'function') msQuickLabTypeChanged();
  }
}

// ─── Aufs Handy legen ────────────────────────────────────────────────────────
// Chrome meldet beforeinstallprompt, sobald die App installierbar ist, und legt
// das Ereignis für später beiseite; Safari meldet gar nichts und will den Weg
// über Teilen. Beides landet im selben Streifen.
let _installEvent = null;

// Läuft die App schon als Symbol? Dann hat der Streifen nichts mehr zu sagen.
function wkAlsAppOffen() {
  return window.matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
}
// iPadOS meldet sich seit 13 als Macintosh — ohne den Touch-Zähler hielte man
// jedes iPad für einen Rechner und zeigte den Hinweis nie an.
function wkIstApple(ua, touchPoints) {
  if (/iphone|ipad|ipod/i.test(ua)) return true;
  return /macintosh/i.test(ua) && touchPoints > 1;
}
function wkInstallRender() {
  const bar = document.getElementById('wk-install');
  if (!bar) return;
  const why = document.getElementById('wk-install-why');
  const apple = document.getElementById('wk-install-apple');
  const btn = document.getElementById('wk-install-btn');
  const apfel = !_installEvent && !wkAlsAppOffen() && wkIstApple(navigator.userAgent, navigator.maxTouchPoints);
  why.hidden = !_installEvent || wkAlsAppOffen();
  btn.hidden = why.hidden;
  apple.hidden = !apfel;
  bar.hidden = why.hidden && apple.hidden;
}
async function wkInstall() {
  if (!_installEvent) return;
  _installEvent.prompt();
  const wahl = await _installEvent.userChoice;
  // Das Ereignis ist verbraucht, wie die Antwort auch ausfiel — ein zweites
  // prompt() auf demselben wirft.
  _installEvent = null;
  wkInstallRender();
  if (wahl && wahl.outcome === 'accepted') setFb('ok', t('work.installDone'), { noModal: true });
}
window.addEventListener('beforeinstallprompt', (e) => {
  // Ohne preventDefault zeigt Chrome seinen eigenen Streifen — und der ist für
  // immer weg, sobald man ihn einmal wegwischt.
  e.preventDefault();
  _installEvent = e;
  wkInstallRender();
});
window.addEventListener('appinstalled', () => {
  _installEvent = null;
  wkInstallRender();
});

// Die Reihenfolge der Kacheln stellt jeder selbst ein. Wer jeden Tag erntet,
// will Ernte oben, wer im Labor steht, Labor. Gespeichert am Benutzer auf dem
// Server (/api/auth/me bringt sie mit, /api/me/tile-order schreibt sie), damit
// sie auf jedem Telefon gilt, auf dem man sich anmeldet; dazu eine Kopie auf
// dem Gerät für den Start ohne Netz. Umsortiert wird mit ↑/↓ in einer Liste statt mit
// Ziehen — Ziehen auf dem Telefon kämpft mit dem Scrollen, und ein Knopf in
// einer Kachel ginge nicht, die Kachel ist selbst einer.
const WK_TILES = {
  move: 'work.move',
  harvest: 'work.harvest',
  batch: 'work.tileBatch',
  lab: 'work.lab',
  grain: 'work.grain',
  sub: 'work.tileSubstrate',
  contam: 'work.contam'
};
const WK_TILE_DEFAULT = Object.keys(WK_TILES);
function _wkOrderKey() {
  return 'mp-tile-order:' + ((currentUser && currentUser.username) || '');
}
function _wkLocalOrder() {
  try {
    const v = JSON.parse(localStorage.getItem(_wkOrderKey()) || 'null');
    return Array.isArray(v) ? v : null;
  } catch (_) {
    return null;
  }
}
function wkTileOrder() {
  // Der Server zuerst; die Kopie auf dem Gerät nur, solange er nichts gesagt hat.
  const fromServer = currentUser && Array.isArray(currentUser.tileOrder) ? currentUser.tileOrder : null;
  const saved = fromServer || _wkLocalOrder() || [];
  // Eine gespeicherte Liste von gestern kennt eine neue Kachel nicht, und eine
  // gestrichene gibt es nicht mehr: die eine hinten anhängen, die andere weglassen.
  const order = saved.filter((id, i) => WK_TILES[id] && saved.indexOf(id) === i);
  for (const id of WK_TILE_DEFAULT) if (!order.includes(id)) order.push(id);
  return order;
}
let _wkOrderSendTimer = null;
function saveWkTileOrder(order) {
  try {
    localStorage.setItem(_wkOrderKey(), JSON.stringify(order));
  } catch (_) {
    /* dann gilt der Server */
  }
  if (!currentUser) return;
  currentUser.tileOrder = order.slice();
  // Mehrere ↑-Tipps hintereinander sind ein Umsortieren, nicht fünf: erst
  // senden, wenn eine Weile Ruhe ist, und dann nur den letzten Stand.
  clearTimeout(_wkOrderSendTimer);
  _wkOrderSendTimer = setTimeout(() => {
    apiPost('/api/me/tile-order', { order: currentUser.tileOrder });
  }, 600);
}
// Wer schon vor dem Server-Speicher sortiert hat, hat die Reihenfolge nur auf
// dem Telefon. Kennt der Server noch keine, geht die vom Gerät einmal hinauf.
function syncWkTileOrderUp() {
  if (!currentUser || currentUser.tileOrder !== null) return;
  const local = _wkLocalOrder();
  if (local && local.length) saveWkTileOrder(wkTileOrder());
}
function applyWkTileOrder() {
  const grid = document.getElementById('wk-tiles');
  if (!grid) return;
  const order = wkTileOrder();
  const now = [...grid.children].map((el) => el.id.replace('wk-t-', ''));
  if (now.join() === order.join()) return;
  for (const id of order) {
    const el = document.getElementById('wk-t-' + id);
    if (el) grid.appendChild(el);
  }
}
function renderWkOrderList() {
  const list = document.getElementById('wk-order-list');
  if (!list) return;
  const order = wkTileOrder();
  list.innerHTML = order
    .map(
      (id, i) =>
        '<li class="wk-order-row"><span class="wk-order-name">' +
        esc(t(WK_TILES[id])) +
        '</span><button type="button" class="btn btn-sm" data-wk-order="' +
        id +
        '" data-dir="-1" aria-label="' +
        esc(t('work.orderUp', { name: t(WK_TILES[id]) })) +
        '"' +
        (i === 0 ? ' disabled' : '') +
        '>↑</button><button type="button" class="btn btn-sm" data-wk-order="' +
        id +
        '" data-dir="1" aria-label="' +
        esc(t('work.orderDown', { name: t(WK_TILES[id]) })) +
        '"' +
        (i === order.length - 1 ? ' disabled' : '') +
        '>↓</button></li>'
    )
    .join('');
}
function setWkOrderOpen(open) {
  const panel = document.getElementById('wk-order');
  const btn = document.getElementById('wk-order-btn');
  if (!panel || !btn) return;
  panel.hidden = !open;
  btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  if (open) renderWkOrderList();
}
function wireWkTileOrder() {
  const btn = document.getElementById('wk-order-btn');
  const list = document.getElementById('wk-order-list');
  if (!btn || !list) return;
  btn.addEventListener('click', () => setWkOrderOpen(document.getElementById('wk-order').hidden));
  list.addEventListener('click', (ev) => {
    const b = ev.target.closest('[data-wk-order]');
    if (!b || b.disabled) return;
    const order = wkTileOrder();
    const i = order.indexOf(b.dataset.wkOrder);
    const j = i + Number(b.dataset.dir);
    if (i < 0 || j < 0 || j >= order.length) return;
    [order[i], order[j]] = [order[j], order[i]];
    saveWkTileOrder(order);
    applyWkTileOrder();
    renderWkOrderList();
    // Den Fokus beim selben Pfeil der verschobenen Kachel lassen, damit man
    // mehrmals hintereinander tippen kann.
    const again = list.querySelector('[data-wk-order="' + order[j] + '"][data-dir="' + b.dataset.dir + '"]');
    if (again && !again.disabled) again.focus();
  });
  document.getElementById('wk-order-reset').addEventListener('click', () => {
    saveWkTileOrder(WK_TILE_DEFAULT.slice());
    applyWkTileOrder();
    renderWkOrderList();
  });
  document.getElementById('wk-order-done').addEventListener('click', () => setWkOrderOpen(false));
  applyWkTileOrder();
}

(function wireWorkSteps() {
  wireWkTileOrder();
  const tiles = [
    ['wk-t-lab', msQuickLaborNew],
    ['wk-t-grain', wkOpenGrain],
    ['wk-t-batch', wkbOpen],
    ['wk-t-sub', wkmOpen],
    ['wk-t-move', () => wkfOpen('move')],
    ['wk-t-harvest', () => wkfOpen('harvest')],
    ['wk-t-contam', () => wkfOpen('contam')]
  ];
  tiles.forEach(([id, fn]) => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('click', fn);
  });
  const inst = document.getElementById('wk-install-btn');
  if (inst) inst.addEventListener('click', wkInstall);
  // Für den Apple-Weg und für den Fall, dass beforeinstallprompt schon durch
  // war, bevor diese Datei lief.
  wkInstallRender();
  const nav = document.getElementById('n-work');
  if (nav) nav.addEventListener('click', () => go('work', 'n-work'));
  const close = document.getElementById('wkf-close');
  if (close) close.addEventListener('click', wkfClose);
  const back = document.getElementById('wkf-back');
  if (back) back.addEventListener('click', wkfBackDispatch);
  const bg = document.getElementById('m-work-flow');
  if (bg) {
    bg.addEventListener('click', (e) => {
      if (e.target === bg) return wkfClose();
      // Delegated so the rendered bodies stay plain markup: an inline onclick on
      // generated HTML hides the call from every tool that reads this file.
      const act = e.target.closest('[data-wk]');
      if (!act) return;
      if (act.dataset.wk === 'back') wkfBackDispatch();
      else if (act.dataset.wk === 'book-harvest') wkfBookHarvest();
      else if (act.dataset.wk === 'book-move') wkfBookMove();
      else if (act.dataset.wk === 'receipt-next') wkfReceiptNext();
    });
    bg.addEventListener('input', (e) => {
      const g = e.target.closest('.wkf-g');
      if (g) wkfGramsInput(g);
    });
  }
})();
// ═══ CHARGE ANLEGEN ALS ARBEITSGANG ══════════════════════════════════════════
// Der geführte Weg aus dem Entwurf: drei Schritte, das Rezept sichtbar und
// änderbar, Notizen als eigenes Feld. Er ersetzt das lange Formular nicht — der
// bleibt unter Chargen → Neue Charge für alles, was hier nicht hineinpasst
// (ohne Ansatz, Körnerbrut, Produkte). Gebucht wird über dieselbe Funktion, die
// das Formular benutzt, samt ihrer Warnung bei Überzug.

const WKB = {
  step: 1,
  strainId: null,
  qty: 20,
  bagKg: NB_BAG_KG_DEFAULT,
  subId: '',
  // Hat jemand den Ansatz selbst gewählt? Dann schlägt wkbQuelleVorgabe nichts
  // mehr vor.
  subVonHand: false,
  notes: '',
  custom: false,
  hw: null,
  wb: null,
  rh: null,
  days: null
};

function wkbStrain() {
  return mushroomStrains.find((x) => x.id === WKB.strainId) || null;
}
// Die Werte, mit denen gerechnet wird: das Rezept der Sorte, sofern nicht von
// Hand überschrieben. Beides an einer Stelle, damit Anzeige und Buchung nicht
// auseinanderlaufen.
function wkbRecipe() {
  const ms = wkbStrain();
  return {
    hw: WKB.hw != null ? WKB.hw : (ms && ms.recHardwoodPct) || 0,
    wb: WKB.wb != null ? WKB.wb : (ms && ms.recWheatbranPct) || 0,
    rh: WKB.rh != null ? WKB.rh : (ms && ms.recRhPct) || 0,
    days: WKB.days != null ? WKB.days : (ms && ms.recIncDays) || 14
  };
}
function wkbMix() {
  return wkOpenMixes().find((x) => x.subId === WKB.subId) || null;
}
function wkbDraw() {
  return WKB.qty * WKB.bagKg;
}

// Woraus die Beutel wirklich bestehen. Ist ein Ansatz gewählt, ist das dessen
// Mischung — so, wie sie angesetzt wurde. Der Server bucht es genauso
// (createBagBatchFromSubstrate liest die Prozente aus substrate_batches), das
// Rezept der Sorte spielt dann keine Rolle mehr, auch wenn es sich seitdem
// geändert hat. Ohne Ansatz gilt das Rezept.
function wkbMischung() {
  const mix = wkbMix();
  if (mix && mix.composition) {
    return {
      hw: mix.composition.hardwoodPct || 0,
      wb: mix.composition.wheatbranPct || 0,
      rh: mix.composition.rhPct || 0,
      ausAnsatz: mix.subId
    };
  }
  const r = wkbRecipe();
  return { hw: r.hw, wb: r.wb, rh: r.rh, ausAnsatz: null };
}

// Woraus die Charge ist, schlägt der Ablauf vor: den ersten offenen Ansatz —
// außer bei einer Charge aus der Inventur. Die stand schon, bevor es den Ansatz
// von heute gab, und bucht ohnehin nichts ab; ein vorausgewählter Ansatz wäre
// dort eine erfundene Herkunft. Wer selbst gewählt hat, behält seine Wahl.
function wkbQuelleVorgabe() {
  if (WKB.subVonHand) return;
  const mixes = wkOpenMixes();
  WKB.subId = !anlageFrueher('wkb') && mixes.length ? mixes[0].subId : '';
}

function wkbOpen() {
  WKB.step = 1;
  WKB.notes = '';
  WKB.custom = false;
  WKB.hw = WKB.wb = WKB.rh = WKB.days = null;
  // Jede Charge fängt bei "ohne Stamm" und heute an — auch "Noch eine Charge".
  // Und ohne Beimpfmaterial: das der letzten ist verbraucht.
  stammReset('wkb');
  anlageReset('wkb');
  _inoc = [];
  const first = mushroomStrains.filter((x) => x.recBatchType)[0] || mushroomStrains[0];
  WKB.strainId = first ? first.id : null;
  WKB.subVonHand = false;
  wkbQuelleVorgabe();
  WKF.kind = 'batch';
  WKF.step = 'detail';
  WKF.receipt = null;
  wkf('m-work-flow').classList.add('open');
  wkbRender();
}

function wkbBack() {
  // Erst lesen, dann zurück: der Fußknopf tut das seit jeher, der Kopfknopf
  // warf die Notiz und das geänderte Rezept weg.
  wkbReadStep();
  if (WKB.step > 1) {
    WKB.step--;
    wkbRender();
    return;
  }
  wkfClose();
}

function wkbRender() {
  // Der Renderer wird auch aus einem späten onDone gerufen. Landet der, während
  // schon ein anderer Ablauf offen ist, würde er dessen Bildschirm überschreiben.
  if (WKF.kind !== 'batch') return;
  const ms = wkbStrain();
  const r = wkbRecipe();
  const mix = wkbMix();
  const m = wkbMischung();
  wkf('wkf-title').textContent = t('work.batch');
  wkf('wkf-back').hidden = WKB.step === 1 || WKF.step === 'done';
  const labels = [t('work.bStep1'), t('work.bStep2'), t('work.bStep3')];
  wkf('wkf-steps').innerHTML =
    WKF.step === 'done'
      ? ''
      : '<div class="wkf-chips">' +
        labels
          .map((l, i) => {
            const n = i + 1;
            const cls = n < WKB.step ? 'wkf-chip done' : n === WKB.step ? 'wkf-chip now' : 'wkf-chip';
            return `<span class="${cls}">${n < WKB.step ? '&#10003; ' : ''}${esc(l)}</span>`;
          })
          .join('') +
        '</div>';

  if (WKF.step === 'done') {
    const d = WKF.receipt || {};
    wkf('wkf-body').innerHTML =
      `<div class="wkf-receipt">
         <div class="wkf-r-head"><span class="wkf-r-tick">&#10003;</span><b>${esc(d.headline || '')}</b></div>
         <div class="wkf-r-lines">` +
      (d.lines || []).map((l) => `<div><span class="wkf-r-k">${esc(l[0])}</span><span>${esc(l[1])}</span></div>`).join('') +
      '</div></div>';
    wkf('wkf-foot').innerHTML =
      `<button class="btn btn-p" data-wkb="again">${esc(t('work.bAnother'))}</button>` +
      `<button class="btn" onclick="wkfClose()">${esc(t('work.done'))}</button>`;
    return;
  }

  let body = '';
  if (WKB.step === 1) {
    const list = mushroomStrains
      .slice()
      .sort((a, b) => (a.name || '').localeCompare(b.name || ''))
      .map((x) => `<option value="${x.id}"${x.id === WKB.strainId ? ' selected' : ''}>${esc(x.name)}${x.kuerzel ? ' (' + esc(x.kuerzel) + ')' : ''}</option>`)
      .join('');
    // "Beimpft mit" steht zuoberst: die Körnerbrut hat man in der Hand, und
    // gescannt bringt sie Sorte und Stamm gleich mit (wkbInocAdd). Wählen geht
    // auch; die Liste zeigt nur, was zur Sorte passt.
    body =
      `<div class="wkf-q">${esc(t('work.bQ1'))}</div>
       <div class="wkf-field"><label for="wkb-inoc-pick">${esc(t('work.bInoc'))}</label>
         <div class="stamm-row"><button type="button" class="btn" data-wkb="inoc-scan">📷 ${esc(t('work.bInocScan'))}</button>
           <select id="wkb-inoc-pick"></select></div>
         <div id="wkb-inoc-chips" class="inoc-chips"></div></div>
       <div class="wkf-field"><label>${esc(t('strains.pilzsorte'))}</label>
         <select id="wkb-strain">${list}</select></div>
       <div id="wkb-stamm-wrap" class="wkf-field stamm-wrap"></div>
       <div class="wkf-two">
         <div class="wkf-field"><label>${esc(t('batch.qty'))}</label>
           <input type="text" inputmode="numeric" id="wkb-qty" value="${WKB.qty}" /></div>
         <div class="wkf-field"><label>${esc(t('batch.bagWeight'))}</label>
           <div class="wkf-chipsrow">` +
      [3.5, 3.8, 4.3, 5]
        .map((k) => `<button type="button" class="wkf-w${WKB.bagKg === k ? ' on' : ''}" data-wkb="kg" data-val="${k}">${String(k).replace('.', ',')} kg</button>`)
        .join('') +
      `</div></div>
       </div>
       <div id="wkb-anlage-wrap" class="anlage-wrap"></div>`;
  } else if (WKB.step === 2) {
    const mixes = wkOpenMixes();
    const rest = mix ? mix.remainingKg - wkbDraw() : null;
    // Eine Charge aus der Inventur bucht nichts ab. Die Zeilen, die sagen, was
    // aus dem Ansatz oder vom Lager ginge, wären hier falsch — an ihrer Stelle
    // steht, dass nichts geht.
    const frueher = anlageFrueher('wkb');
    const vomLager = frueher ? '' : `<div class="wkf-note">${esc(t('work.bFromShelf'))}</div>`;
    body =
      `<div class="wkf-q">${esc(t('work.bQ2'))}</div>` +
      (frueher ? `<div class="wkf-note">${esc(t('anlage.notBookedNote'))}</div>` : '') +
      (mixes.length
        ? `<div class="wkf-field"><label>${esc(t('sub.fromMix'))}</label><select id="wkb-mix">` +
          mixes
            .map((m) => `<option value="${esc(m.subId)}"${m.subId === WKB.subId ? ' selected' : ''}>${esc(m.subId)} &middot; ${t('work.bLeft', { kg: m.remainingKg.toFixed(0) })}</option>`)
            .join('') +
          // "vom Lager" stimmt bei Bestand aus der Inventur nicht — von dort geht nichts.
          `<option value=""${WKB.subId ? '' : ' selected'}>${esc(frueher ? t('anlage.noMix') : t('work.bNoMixOption'))}</option>` +
          '</select></div>' +
          (mix && !frueher
            ? `<div class="wkf-note${rest != null && rest < -1e-9 ? ' bad' : ''}">${esc(
                t('work.bDraw', { qty: WKB.qty, kg: WKB.bagKg, need: wkbDraw().toFixed(0) })
              )} &mdash; ${
                rest != null && rest < -1e-9
                  ? esc(t('work.bShort', { kg: (-rest).toFixed(0) }))
                  : esc(t('work.bRest', { kg: (rest || 0).toFixed(0) }))
              }</div>`
            : mix
              ? ''
              : vomLager)
        : vomLager +
          // Einen Ansatz anzulegen, damit eine Charge von vor drei Wochen daraus
          // ziehen kann, ergibt keinen Sinn — sie zieht ja nichts.
          (frueher ? '' : `<button class="btn" data-wkb="tosub">${esc(t('work.bMixFirst'))}</button>`)) +
      // Mit Ansatz steht dessen Mischung da, und zwar fest: sie lässt sich nicht
      // mehr ändern, also darf hier auch kein Feld so tun. Die Inkubationstage
      // gehen weiterhin vom Assistenten an den Server, die bleiben einstellbar.
      (mix
        ? `<div class="wkf-note">
             <b>${esc(t('work.bMixFrom', { id: mix.subId }))}</b>
             ${esc(t('work.bMixLine', { hw: m.hw, wb: m.wb, rh: m.rh }))}
             <div class="wkf-hint">${esc(t('work.bMixFixed'))}</div>
           </div>
           <div class="wkf-field"><label>${esc(t('batch.incDays'))}</label>
             <input type="text" inputmode="numeric" id="wkb-days" value="${r.days}" /></div>`
        : `<div class="wkf-note">
             <b>${esc(t('work.bRecipe', { name: ms ? ms.name : '' }))}${WKB.custom ? esc(t('work.bChanged')) : ''}</b>
             ${
               r.hw || r.wb || r.rh
                 ? esc(t('work.bRecipeLine', { hw: r.hw, wb: r.wb, rh: r.rh, days: r.days }))
                 : esc(t('work.bNoRecipe'))
             }
             <button type="button" class="wkf-link" data-wkb="custom">${esc(WKB.custom ? t('work.bCollapse') : t('work.bEditRecipe'))}</button>
           </div>` +
          (WKB.custom
            ? `<div class="wkf-two">
                 <div class="wkf-field"><label>${esc(t('batch.hardwood'))}</label><input type="text" inputmode="decimal" id="wkb-hw" value="${r.hw}" /></div>
                 <div class="wkf-field"><label>${esc(t('batch.wheatBran'))}</label><input type="text" inputmode="decimal" id="wkb-wb" value="${r.wb}" /></div>
               </div>
               <div class="wkf-two">
                 <div class="wkf-field"><label>${esc(t('batch.fieldCapacity'))}</label><input type="text" inputmode="decimal" id="wkb-rh" value="${r.rh}" /></div>
                 <div class="wkf-field"><label>${esc(t('batch.incDays'))}</label><input type="text" inputmode="numeric" id="wkb-days" value="${r.days}" /></div>
               </div>
               <div class="wkf-hint">${esc(t('work.bOnlyThis'))}</div>`
            : ''));
  } else {
    const frueher = anlageFrueher('wkb');
    // Was aus dem Ansatz oder vom Lager geht — bei einer Charge aus der Inventur
    // nichts, und das steht dann auch so da.
    const quelle = frueher
      ? (mix ? esc(mix.subId) + ' · ' : '') + esc(t('anlage.notBooked'))
      : mix
        ? esc(mix.subId) + ' · ' + wkbDraw().toFixed(0) + ' kg'
        : esc(t('work.bFromShelfShort'));
    body =
      `<div class="wkf-q">${esc(t('work.bQ3'))}</div>
       <div class="wkf-sum-card">
         <div><span class="wkf-r-k">${esc(t('strains.pilzsorte'))}</span><b>${esc(ms ? ms.name : '')}</b></div>
         <div><span class="wkf-r-k">${esc(t('stamm.label'))}</span>${stammAnzeige('wkb') ? esc(stammAnzeige('wkb')) : '&mdash;'}</div>
         ${wkbInocZeile()}
         <div><span class="wkf-r-k">${esc(t('anlage.label'))}</span>${frueher ? '<b>' + esc(fmtDt(anlageZeitpunkt(anlageState('wkb').datum))) + '</b>' : esc(t('anlage.today'))}</div>
         <div><span class="wkf-r-k">${esc(t('batch.qty'))}</span>${WKB.qty} &times; ${String(WKB.bagKg).replace('.', ',')} kg</div>
         <div><span class="wkf-r-k">${esc(t('work.stepSubstrate'))}</span>${quelle}</div>
         <div><span class="wkf-r-k">${esc(t('work.bMixLabel'))}</span>${m.hw}/${m.wb} @ ${m.rh} %${
           m.ausAnsatz ? '' : WKB.custom ? esc(t('work.bChanged')) : ''
         }
           <button type="button" class="wkf-link" data-wkb="step2">${esc(t('work.bEdit'))}</button></div>
         <div><span class="wkf-r-k">${esc(t('batch.incDays'))}</span>${r.days}</div>
       </div>
       <div class="wkf-field"><label>${esc(t('work.bNote'))}</label>
         <input type="text" id="wkb-notes" value="${esc(WKB.notes)}" placeholder="${esc(t('work.bNotePh'))}" /></div>`;
  }
  wkf('wkf-body').innerHTML = body;
  // Stamm und Datum zeichnen sich selbst in ihre Plätze; ihr Zustand überlebt
  // so jeden Schritt vor und zurück. Das Datum steht im ersten Schritt, weil es
  // den zweiten bestimmt: eine Charge aus der Inventur zieht aus keinem Ansatz.
  if (WKB.step === 1) {
    stammRender('wkb', WKB.strainId);
    anlageRender('wkb');
    inocRender('wkb');
  }

  const back = `<button class="btn" data-wkb="back">${esc(t('work.back'))}</button>`;
  wkf('wkf-foot').innerHTML =
    (WKB.step > 1 ? back : `<button class="btn" onclick="wkfClose()">${esc(t('work.cancel'))}</button>`) +
    (WKB.step < 3
      ? `<button class="btn btn-p" data-wkb="next">${esc(t('work.bNext'))}</button>`
      : `<button class="btn btn-p" data-wkb="create">${esc(t('work.bCreate', { n: WKB.qty }))}</button>`);
}

function wkbReadStep() {
  const g = (id) => document.getElementById(id);
  if (WKB.step === 1) {
    if (g('wkb-strain')) WKB.strainId = parseInt(g('wkb-strain').value, 10) || WKB.strainId;
    if (g('wkb-qty')) WKB.qty = Math.max(1, parseInt(g('wkb-qty').value, 10) || 1);
    if (g('wkb-stamm')) stammState('wkb').wert = g('wkb-stamm').value;
    if (g('wkb-anlage')) anlageState('wkb').datum = g('wkb-anlage').value;
  } else if (WKB.step === 2) {
    if (g('wkb-mix')) WKB.subId = g('wkb-mix').value;
    // Die Inkubationstage stehen auch beim Ansatz-Weg auf dem Bildschirm, wo es
    // kein „Rezept ändern" gibt — sie hängen nicht am Rezept, sondern gehen so
    // oder so an den Server.
    if (g('wkb-days')) WKB.days = parseInt(g('wkb-days').value, 10) || 14;
    if (WKB.custom) {
      if (g('wkb-hw')) WKB.hw = parseDecimal(g('wkb-hw').value) || 0;
      if (g('wkb-wb')) WKB.wb = parseDecimal(g('wkb-wb').value) || 0;
      if (g('wkb-rh')) WKB.rh = parseDecimal(g('wkb-rh').value) || 0;
    }
  } else if (WKB.step === 3) {
    if (g('wkb-notes')) WKB.notes = g('wkb-notes').value;
  }
}

// ── Beimpft mit, im geführten Ablauf ─────────────────────────
// Beim Anlegen die Körnerbrut scannen, damit man weiß, welche Brut in welchen
// Blöcken steckt. Das lange Formular und der Schnelldialog konnten das seit
// #449; seit die Kacheln der Weg zum Anlegen sind, öffnet die aber niemand
// mehr, und der Ablauf kannte es nicht.
//
// Der erste Körnerbeutel bringt Sorte und Stamm mit: gescannt ist schneller als
// gewählt, und die Brut sagt, was aus ihr wird. Danach nimmt die Liste nur Brut
// derselben Sorte, aus zwei Sorten wird keine Charge. Beim Anlegen gelten die
// Körnerbeutel als verbraucht — ein geöffneter Beutel geht ganz in die Blöcke,
// und die Zusammenfassung sagt es vorher. Eine Kultur wird nur verknüpft; sie
// hält meist für mehr als eine Charge.
function wkbInocAdd(id) {
  if (WKB.step === 1) wkbReadStep();
  const gesucht = String(id || '')
    .trim()
    .toUpperCase();
  const beutel = nbAvailableSpawnBags().find((x) => x.bag.toUpperCase() === gesucht);
  const hatBrut = _inoc.some((x) => x.kind === 'bag');
  if (beutel && hatBrut && beutel.strainId !== WKB.strainId) {
    const ms = wkbStrain();
    return t('work.bInocOtherSorte', { bag: beutel.bag, sorte: beutel.species, charge: ms ? ms.name : '' });
  }
  const err = inocAdd(id);
  if (err) return err;
  if (beutel && !hatBrut && beutel.strainId) {
    const sorteNeu = WKB.strainId !== beutel.strainId;
    WKB.strainId = beutel.strainId;
    // Der Stamm der Brut, wenn die Sorte ihn in ihrer Liste führt. Führt sie
    // ihn nicht, bleibt eine Wahl von Hand stehen — außer die Sorte hat eben
    // gewechselt, dann gehört die alte Wahl zu einer anderen Sorte.
    const stamm = staemmeFor(beutel.strainId).find((s) => stammGleich(s.name, beutel.strainText));
    if (stamm || sorteNeu) {
      const st = stammState('wkb');
      st.strainId = beutel.strainId;
      st.neu = false;
      st.getippt = '';
      st.wert = stamm ? stamm.name : '';
    }
  }
  wkbRender();
  return null;
}
// Die Sorte von Hand gewechselt, nachdem Brut gescannt war: Brut einer anderen
// Sorte gehört nicht zu dieser Charge und geht aus der Liste — mit Meldung.
function wkbInocSortePruefen() {
  const alle = nbAvailableSpawnBags();
  const fremd = _inoc.filter((x) => {
    if (x.kind !== 'bag') return false;
    const b = alle.find((y) => y.bag === x.id);
    return !!b && b.strainId !== WKB.strainId;
  });
  if (!fremd.length) return;
  _inoc = _inoc.filter((x) => !fremd.includes(x));
  toast(t('work.bInocDropped', { list: fremd.map((x) => x.id).join(', ') }));
}
// Die Zeile in der Zusammenfassung: womit beimpft wird, und dass die
// Körnerbeutel dabei ausgebucht werden — gesagt, bevor es geschieht.
function wkbInocZeile() {
  if (!_inoc.length) return '';
  const brut = _inoc.some((x) => x.kind === 'bag');
  return (
    `<div><span class="wkf-r-k">${esc(t('work.bInoc'))}</span>${esc(_inoc.map((x) => x.id).join(', '))}` +
    (brut ? `<div class="wkf-hint">${esc(t('work.bInocSpent'))}</div>` : '') +
    '</div>'
  );
}
// Die Liste fürs Anlegen, mit der Antwort auf "verbraucht?" schon darin.
function wkbInocListe() {
  return _inoc.map((x) => ({ kind: x.kind, id: x.id, spent: x.kind === 'bag' }));
}

// Ohne Ansatz läuft die Buchung über createBatch() des langen Formulars: es
// zieht Rohmaterial vom Lager, fragt danach die Zone ab und druckt Etiketten.
// Der Ablauf füllt dessen Felder und übergibt, statt denselben Weg noch einmal
// zu schreiben — eine zweite Fassung wäre die, die irgendwann abweicht.
// `stamm` und `angesetzt` kommen aus wkbCreate, schon geprüft: der Name aus der
// Liste der Sorte ('' für ohne), der Tag als JJJJ-MM-TT ('' für heute). `inoc`
// ist die Beimpf-Liste aus wkbInocListe(); createBatch() bucht die Brut nach dem
// Speichern aus (inocAskConsume) und nimmt die erste Kultur als Herkunft.
function wkbCreateFromShelf(stamm, angesetzt, inoc) {
  const ms = wkbStrain();
  if (!ms) return;
  const r = wkbRecipe();
  wkfClose();
  // Erst bereitmachen, dann füllen: beim ersten Mal in einer Sitzung setzt
  // nbEnsureReady() die gemerkten Vorgaben, und die überschrieben sonst alles,
  // was hier gesetzt wird. Die Seite wechselt dafür nicht mehr — siehe
  // msQuickConfirm, derselbe Grund.
  nbEnsureReady();
  // Das Rezept des Assistenten überschreibt das der Sorte, wo es abweicht.
  nbFillFromStrain(ms, {
    qty: WKB.qty,
    bagKg: WKB.bagKg,
    days: r.days,
    hw: r.hw,
    wb: r.wb,
    rh: r.rh,
    notes: WKB.notes.trim(),
    strainText: stamm || '',
    created: angesetzt || '',
    inoc: inoc || []
  });
  createBatch();
}

async function wkbCreate() {
  wkbReadStep();
  // Die Beimpf-Liste jetzt, solange der Ablauf offen ist: wkfClose() leert sie.
  const inoc = wkbInocListe();
  const ms = wkbStrain();
  const mix = wkbMix();
  if (!ms) return;
  // Ein gewählter Ansatz, der inzwischen leer ist, ist kein "ohne Ansatz":
  // _sbList wird im Hintergrund aufgefrischt, und derselbe Tipp buchte sonst
  // klammheimlich Pellets und Kleie vom Lager statt aus dem Ansatz.
  if (!mix && WKB.subId) {
    toast(t('work.bMixGone', { id: WKB.subId }), 'err');
    WKB.subId = '';
    WKB.step = 2;
    wkbRender();
    return;
  }
  // Ein Tag in der Zukunft wird abgewiesen, solange der Ablauf noch offen ist.
  const angesetzt = anlageLesen('wkb');
  if (angesetzt === null) return;
  // Ein im ersten Schritt getippter, nicht hinzugefügter Stamm wird jetzt
  // angelegt; so lange nimmt der Knopf keinen zweiten Tipp an.
  const knopf = document.querySelector('#m-work-flow [data-wkb="create"]');
  if (knopf) knopf.disabled = true;
  const stamm = await stammFertig('wkb');
  if (knopf) knopf.disabled = false;
  // Fehlgeschlagen (gemeldet ist es), oder der Ablauf wurde währenddessen zu.
  if (stamm === null || WKF.kind !== 'batch') return;
  if (!mix) return wkbCreateFromShelf(stamm, angesetzt, inoc);
  const r = wkbRecipe();
  const wann = anlageZeitpunkt(angesetzt);
  const batchId = genBatchId(ms.name, wann);
  const kultur = inoc.find((x) => x.kind === 'culture');
  // Wie das lange Formular: der Stamm steht in beiden Spalten, und ohne ihn steht
  // in `strain` 'XXX', nicht das Sorten-Kürzel. Sonst bedeutet dieselbe Spalte je
  // nach Eingabeweg etwas anderes.
  createBatchFromSubstrate(batchId, mix.subId, ms.id, WKB.qty, WKB.bagKg, r.days, stamm || 'XXX', stamm, {
    notes: WKB.notes.trim(),
    created: angesetzt ? wann.toISOString() : undefined,
    sourceId: kultur ? kultur.id : undefined,
    onDone: (res) => {
      const neuId = res.batchId || batchId;
      const neu = batches.find((x) => x.batchId === neuId);
      // Die Körnerbrut geht jetzt aus dem Bestand, mit der neuen Charge als
      // Grund. Auch wenn der Ablauf inzwischen zu ist: angelegt ist angelegt.
      const brut = neu ? inocVerbrauchtBuchen(neu, inoc) : 0;
      // Was noch im Ansatz steht, ist die Zahl, gegen die die nächste Charge
      // geplant wird. Sie stand auf der Quittung, die dieser Weg jetzt nicht
      // mehr zeigt — also geht sie in die Meldung mit. Eine Charge aus der
      // Inventur hat nichts gezogen, und die Meldung sagt genau das.
      const gezogen = angesetzt
        ? t('anlage.notBooked')
        : t('work.bDrawn', {
            kg: (res.drawKg || wkbDraw()).toFixed(0),
            id: mix.subId,
            left: (res.remainingKg || 0).toFixed(0)
          });
      const meldung =
        t('work.bDone', { n: WKB.qty, name: ms.name }) +
        ' — ' +
        gezogen +
        (brut ? ' — ' + t('work.bInocDone', { n: brut }) : '');
      // Der Ablauf kann inzwischen verlassen oder ein anderer geöffnet worden
      // sein. Dann gehört WKF nicht mehr uns — die Bestätigung sagt es dem
      // Fenster, statt den fremden Bildschirm zu übernehmen.
      if (WKF.kind !== 'batch') {
        toast(meldung);
        return;
      }
      // Zuerst zu, dann einlagern: m-move-batch und m-batch-print lägen sonst
      // hinter diesem Fenster (siehe nbPlaceAndPrint). Die Quittung entfällt
      // dafür — der Zonenwähler ist ein Pflichtschritt, und ein Bildschirm, der
      // vorher "fertig" sagt, lädt dazu ein, ihn wegzutippen. Genau so können
      // Chargen ohne einen einzigen ADD-Scan entstehen.
      wkfClose();
      toast(meldung);
      if (neu) nbPlaceAndPrint(neu, neu.bags || []);
    }
  });
}

(function wireBatchWizard() {
  const flow = document.getElementById('m-work-flow');
  if (!flow) return;
  flow.addEventListener('click', (e) => {
    if (WKF.kind !== 'batch') return;
    // Das ✕ an einem Beimpf-Eintrag: raus aus der Liste, sonst bleibt alles.
    const weg = e.target.closest('[data-action="inoc-drop"]');
    if (weg) {
      wkbReadStep();
      inocRemove(weg.dataset.id);
      wkbRender();
      return;
    }
    const el = e.target.closest('[data-wkb]');
    if (!el || el.disabled) return;
    const a = el.dataset.wkb;
    if (a === 'inoc-scan') {
      // Die Kamera liegt über dem Ablauf (beide z-index 200, die Kamera steht in
      // index.html dahinter); der Scan landet über _inocScanPrefix in
      // wkbInocAdd(), und das Schließen der Kamera gibt den Ablauf wieder frei.
      wkbReadStep();
      msqOpenScan('wkb');
      return;
    }
    if (a === 'kg') {
      wkbReadStep();
      WKB.bagKg = parseDecimal(el.dataset.val) || NB_BAG_KG_DEFAULT;
    } else if (a === 'next') {
      wkbReadStep();
      // Ein Tag in der Zukunft hält den ersten Schritt fest, die Meldung steht am
      // Feld. Geht es in den zweiten, gilt die Vorgabe für den Ansatz neu: sie
      // hängt am Datum, das eben gewählt wurde.
      if (WKB.step === 1 && anlageLesen('wkb') === null) return;
      WKB.step++;
      if (WKB.step === 2) wkbQuelleVorgabe();
    } else if (a === 'back') {
      wkbReadStep();
      WKB.step--;
    } else if (a === 'step2') {
      wkbReadStep();
      WKB.step = 2;
    } else if (a === 'custom') {
      wkbReadStep();
      WKB.custom = !WKB.custom;
    } else if (a === 'again') {
      wkbOpen();
      return;
    } else if (a === 'tosub') {
      // Direkt in den Misch-Dialog, nicht auf die Chargenseite: das lange
      // Formular ließe den Arbeiter dort erst suchen. Die
      // Kachel auf der Arbeitsgang-Seite öffnet längst den Dialog; dieser Knopf
      // steht an genau der Stelle, an der man ihn am dringendsten braucht — es
      // gibt keinen Ansatz, also legen wir jetzt einen an.
      wkmOpen();
      return;
    } else if (a === 'create') {
      wkbCreate();
      return;
    }
    wkbRender();
  });
  // Menge und Sorte wirken auf die Zeile im zweiten Schritt, also sofort merken.
  flow.addEventListener('change', (e) => {
    if (WKF.kind !== 'batch') return;
    // Beimpfmaterial aus der Liste gewählt statt gescannt: derselbe Weg.
    if (e.target.closest('#wkb-inoc-pick')) {
      const wahl = e.target.value;
      if (!wahl) return;
      const err = wkbInocAdd(wahl);
      if (err) {
        toast(err, 'err');
        inocRender('wkb');
      }
      return;
    }
    if (e.target.closest('#wkb-mix')) WKB.subVonHand = true;
    if (e.target.closest('#wkb-strain,#wkb-qty,#wkb-mix')) {
      wkbReadStep();
      if (e.target.closest('#wkb-strain')) wkbInocSortePruefen();
      wkbRender();
    }
  });
  // Derselbe Weg aus der Karte heraus, wo das lange Formular steht: wer dort
  // landet, soll nicht erst auf die Startseite zurückmüssen, um geführt zu werden.
  const guided = document.getElementById('nb-guided');
  if (guided) {
    guided.addEventListener('click', wkbOpen);
  }
})();

// ═══ SUBSTRAT ANSETZEN ALS ARBEITSGANG ═══════════════════════════════════════
// Die Kachel schickte auf die Chargen-Seite und scrollte dort zu einem Formular.
// Sechs Kacheln öffnen einen Dialog, eine wechselte die Seite — das war der
// Ausreißer. Ein Bildschirm reicht: Rezept, Menge, was dabei herauskommt, und
// ob das Lager es trägt. Gebucht wird über denselben Aufruf wie im Formular.

// `previewKey` sagt, zu welchem Rezept und welcher Menge die Vorschau gehört —
// ohne das lässt sich nicht erkennen, ob sie noch gilt. `bucht` sperrt den
// Knopf für die Dauer der Buchung, nicht für die Dauer der Rechnerei.
const WKM = { recipeId: null, bags: 50, kg: 0, notes: '', preview: null, previewKey: '', laedt: false, bucht: false, fehler: '' };

function wkmKey() {
  return String(WKM.recipeId) + '|' + WKM.kg;
}

function wkmStock() {
  return (inventory && inventory.stock) || {};
}

// Was der Ansatz vom Lager nimmt, gegen das, was da ist. Der Server kappt eine
// Abbuchung auf den Bestand, also muss die Lücke vor dem Buchen dastehen.
function wkmShortfalls() {
  const m = WKM.preview && WKM.preview.mix;
  if (!m) return [];
  const s = wkmStock();
  const zeilen = [
    [t('sub.pellets'), m.pelletsKg, s.hardwood || 0],
    [t('sub.bran'), m.branKg, s.wheatbran || 0],
    [t('sub.gypsum'), m.gypsumKg, s.gypsum || 0]
  ];
  if (m.cornKg > 0.005) zeilen.push([t('sub.corn'), m.cornKg, s.corn || 0]);
  return zeilen.filter((z) => z[1] > z[2] + 1e-9).map((z) => ({ label: z[0], need: z[1], have: z[2] }));
}

// Jede Anfrage bekommt eine Nummer. Nur die jüngste darf schreiben — sonst
// überholt eine früher gestartete Antwort eine spätere und die Tabelle zeigt
// ein anderes Rezept als die Auswahl.
let _wkmSeq = 0;
async function wkmLoadPreview() {
  // Nichts geändert, Vorschau gilt noch: dann auch keine Anfrage. Das Feld
  // meldet ein change auch beim Verlassen ohne Änderung.
  if (WKM.preview && WKM.previewKey === wkmKey()) return;
  const seq = ++_wkmSeq;
  // Die alte Vorschau gilt ab jetzt nicht mehr: sie beschreibt eine andere
  // Menge. Sichtbar leeren, statt eine überholte Tabelle stehen zu lassen.
  WKM.preview = null;
  WKM.previewKey = '';
  WKM.fehler = '';
  if (!WKM.recipeId || !(WKM.kg > 0)) {
    WKM.laedt = false;
    wkmRenderOut();
    wkmUpdateButton();
    return;
  }
  WKM.laedt = true;
  wkmRenderOut();
  wkmUpdateButton();
  const r = await apiPost('/api/substrate-batches/preview', { recipeId: WKM.recipeId, targetKg: WKM.kg });
  if (seq !== _wkmSeq) return;
  WKM.laedt = false;
  if (!r || r.error) {
    WKM.fehler = (r && r.error) || '?';
  } else if (!r.hasRecipe) {
    WKM.fehler = t('sub.noRecipe');
  } else {
    WKM.preview = r;
    WKM.previewKey = wkmKey();
  }
  wkmRenderOut();
  wkmUpdateButton();
}

async function wkmOpen() {
  await loadSubstrateRecipes();
  WKM.recipeId = _sbRecipes.length ? _sbRecipes[0].id : null;
  WKM.bags = 50;
  WKM.kg = sbTargetKg(WKM.bags, sbBagKg());
  WKM.notes = '';
  WKM.preview = null;
  WKM.fehler = '';
  WKF.kind = 'mix';
  WKF.step = 'detail';
  WKF.receipt = null;
  wkf('m-work-flow').classList.add('open');
  wkmRender();
  wkmLoadPreview();
}

function wkmRead() {
  const g = (id) => document.getElementById(id);
  if (g('wkm-recipe')) WKM.recipeId = parseInt(g('wkm-recipe').value, 10) || null;
  if (g('wkm-bags')) WKM.bags = sbParseBags(g('wkm-bags').value);
  WKM.kg = sbTargetKg(WKM.bags, sbBagKg());
  if (g('wkm-notes')) WKM.notes = g('wkm-notes').value;
}

// Nur der Ergebnisbereich: Lagerwarnung, Fehlermeldung, Mischungstabelle.
function wkmRenderOut() {
  const out = document.getElementById('wkm-out');
  if (!out) return;
  const m = WKM.preview && WKM.preview.mix;
  const kurz = WKM.preview ? wkmShortfalls() : [];
  const zeile = (label, wert, einheit) =>
    `<div><span class="wkf-r-k">${esc(label)}</span><span>${fmtKg(wert, 1)} ${einheit}</span></div>`;
  out.innerHTML =
    (kurz.length
      ? '<div class="wkf-note bad"><b>' +
        esc(t('sub.shortTitle')) +
        '</b>' +
        kurz
          .map((x) => esc(t('sub.shortLine', { mat: x.label, need: fmtKg(x.need, 1), have: fmtKg(x.have, 1) })))
          .join('<br>') +
        '<br>' +
        esc(t('sub.shortHint')) +
        '</div>'
      : '') +
    (WKM.fehler ? `<div class="wkf-note bad">${esc(WKM.fehler)}</div>` : '') +
    (m
      ? '<div class="wkf-sum-card">' +
        zeile(t('sub.dryMix'), m.dryKg, 'kg') +
        zeile(t('sub.pellets'), m.pelletsKg, 'kg') +
        zeile(t('sub.bran'), m.branKg, 'kg') +
        (m.cornKg > 0.005 ? zeile(t('sub.corn'), m.cornKg, 'kg') : '') +
        zeile(t('sub.gypsum'), m.gypsumKg, 'kg') +
        zeile(t('sub.waterNow'), sbWater(WKM.preview).nowL, 'L') +
        // Direkt unter die Literzahl: hier steht man am Hahn, und "107 L" sagt
        // nicht, wie lange er laufen soll. Die Vorschau im Formular zeigt es
        // seit jeher, der Arbeitsgang nicht — also ausgerechnet der Schirm
        // nicht, den man dabei in der Hand hat.
        `<div><span class="wkf-r-k">${esc(t('sub.waterTime'))}</span><span>${esc(waterTimeText(sbWater(WKM.preview).nowMinutes))}</span></div>` +
        zeile(t('sub.waterRest'), sbWater(WKM.preview).restL, 'L') +
        zeile(t('sub.moisture'), m.moisturePct, '%') +
        '</div>' +
        `<div class="wkf-hint">${esc(sbWaterHint(sbWater(WKM.preview)))}</div>`
      : WKM.laedt
        ? `<div class="wkf-hint">${esc(t('work.mCalc'))}</div>`
        : '');
}
// Anlegen erst, wenn eine Mischung berechnet ist.
function wkmUpdateButton() {
  const b = document.querySelector('[data-wkm="create"]');
  // Nicht während der Rechnerei sperren: ein Tipp auf den Knopf nimmt dem
  // Mengenfeld den Fokus, dessen change startet die Rechnerei — und die Sperre
  // schluckte dann genau den Tipp, der sie ausgelöst hatte. wkmCreate() wartet
  // die Vorschau selbst ab. Gesperrt wird, solange gebucht wird.
  if (b) b.disabled = WKM.bucht || !(WKM.preview && WKM.preview.mix);
}

function wkmRender() {
  // Siehe wkbRender(): ein spät zurückkommender Ansatz darf nicht in einen
  // inzwischen geöffneten anderen Ablauf schreiben.
  if (WKF.kind !== 'mix') return;
  wkf('wkf-title').textContent = t('work.substrate');
  wkf('wkf-back').hidden = true;
  wkf('wkf-steps').innerHTML = '';

  if (WKF.step === 'done') {
    const d = WKF.receipt || {};
    wkf('wkf-body').innerHTML =
      `<div class="wkf-receipt">
         <div class="wkf-r-head"><span class="wkf-r-tick">&#10003;</span><b>${esc(d.headline || '')}</b></div>
         <div class="wkf-r-lines">` +
      (d.lines || []).map((l) => `<div><span class="wkf-r-k">${esc(l[0])}</span><span>${esc(l[1])}</span></div>`).join('') +
      '</div></div>';
    wkf('wkf-foot').innerHTML =
      // Gemessen wird nach dem Mischen; der Knopf steht hier, weil man in dem
      // Moment ohnehin am Ansatz ist.
      (d.subId
        ? `<button class="btn btn-p" data-wkm="rh" data-sub="${esc(d.subId)}">${esc(t('sub.rhAdd'))}</button>`
        : '') +
      `<button class="btn" data-wkm="again">${esc(t('work.mAnother'))}</button>` +
      `<button class="btn" onclick="wkfClose()">${esc(t('work.done'))}</button>`;
    return;
  }

  const list = sbRecipeOptions(WKM.recipeId);

  wkf('wkf-body').innerHTML =
    `<div class="wkf-q">${esc(t('work.mQ'))}</div>
     <div class="wkf-field"><label>${esc(t('sub.recipe'))}</label><select id="wkm-recipe">${list}</select></div>
     <div class="wkf-two">
       <div class="wkf-field"><label>${esc(t('sub.bags'))}</label>
         <input type="text" inputmode="numeric" id="wkm-bags" value="${WKM.bags || ''}" /></div>
       <div class="wkf-field"><label>${esc(t('batch.bagWeight'))}</label>
         <div class="wkf-chipsrow">${sbBagChips('data-wkm="bagkg" data-val')}</div></div>
     </div>` +
    '<div id="wkm-out"></div>' +
    `<div class="wkf-field"><label>${esc(t('work.bNote'))}</label>
       <input type="text" id="wkm-notes" value="${esc(WKM.notes)}" placeholder="${esc(t('work.mNotePh'))}" /></div>`;

  wkf('wkf-foot').innerHTML =
    `<button class="btn" onclick="wkfClose()">${esc(t('work.cancel'))}</button>` +
    `<button class="btn btn-p" data-wkm="create">${esc(t('sub.create'))}</button>`;
  wkmRenderOut();
  wkmUpdateButton();
}

async function wkmCreate() {
  if (WKM.bucht) return;
  wkmRead();
  // Gehört die Vorschau zu einer anderen Menge als der, die im Feld steht,
  // erst rechnen lassen — und dann weitermachen, statt den Tipp verfallen zu
  // lassen. Sonst muss der Arbeiter nach jeder Mengenänderung zweimal tippen.
  if (!WKM.preview || WKM.previewKey !== wkmKey()) await wkmLoadPreview();
  if (!WKM.preview) return;
  const kurz = wkmShortfalls();
  const subId = sbGenId();
  const menge = { bags: WKM.bags, bagKg: sbBagKg(), kg: WKM.kg };
  const label = WKM.preview.recipeLabel || '';
  sbConfirmMix(subId, menge, label, kurz.length > 0, () => wkmSubmit(subId, menge, label));
}

function wkmSubmit(subId, menge, label) {
  // Der Knopf bleibt sonst die ganze Runde über anfassbar: POST, loadData und
  // refreshSubstrateBatches dauern, auf dem Bildschirm ändert sich nichts, und
  // ein zweiter Tipp legt einen zweiten Ansatz an.
  WKM.bucht = true;
  wkmUpdateButton();
  apiPost('/api/substrate-batches', {
    subId,
    recipeId: WKM.recipeId,
    targetKg: menge.kg,
    notes: WKM.notes.trim()
  })
    .then(async (r) => {
      if (!r || r.error) {
        const err = (r && r.error) || '?';
        // Auch der Fehlschlag braucht ein Zuhause: ist der Ablauf schon zu, malt
        // wkmRender() ins Leere und der Arbeiter hielte den Ansatz für angelegt.
        if (WKF.kind !== 'mix') {
          toast(t('common.error') + ': ' + err, 'err');
          return;
        }
        WKM.fehler = err;
        wkmRender();
        return;
      }
      await loadData();
      await refreshSubstrateBatches();
      // Der Ablauf kann inzwischen verlassen oder ein anderer geöffnet worden
      // sein. Dann gehört WKF nicht mehr uns: die Bestätigung geht ins Fenster,
      // statt den fremden Bildschirm zu überschreiben oder still zu verpuffen.
      if (WKF.kind !== 'mix') {
        toast(t('work.mDone', sbMengeParams(menge, { recipe: label })) + ' — ' + (r.subId || subId));
        return;
      }
      // Die Vorschau kann inzwischen ersetzt worden sein; die Quittung nennt dann
      // nur, was sicher stimmt, statt an einer leeren Referenz abzustürzen.
      const m = (WKM.preview && WKM.preview.mix) || null;
      WKF.receipt = {
        headline: t('work.mDone', sbMengeParams(menge, { recipe: label })),
        subId: r.subId || subId,
        lines: [
          [t('work.mId'), r.subId || subId],
          [t('sub.totalKg'), fmtKg(menge.kg, 1) + ' kg']
        ]
          .concat(
            m
              ? [
                  [t('sub.pellets'), fmtKg(m.pelletsKg, 1) + ' kg'],
                  [t('sub.bran'), fmtKg(m.branKg, 1) + ' kg'],
                  [t('sub.waterNow'), fmtKg(sbWater(r.water ? r : WKM.preview).nowL, 1) + ' L'],
                  [t('sub.waterRest'), fmtKg(sbWater(r.water ? r : WKM.preview).restL, 1) + ' L']
                ]
              : []
          )
          .concat(WKM.notes.trim() ? [[t('work.bNote'), WKM.notes.trim()]] : []),
        next: null
      };
      WKF.step = 'done';
      wkmRender();
    })
    .finally(() => {
      WKM.bucht = false;
      wkmUpdateButton();
    });
}

(function wireMixFlow() {
  const flow = document.getElementById('m-work-flow');
  if (!flow) return;
  flow.addEventListener('click', (e) => {
    if (WKF.kind !== 'mix') return;
    const el = e.target.closest('[data-wkm]');
    if (!el || el.disabled) return;
    if (el.dataset.wkm === 'create') wkmCreate();
    else if (el.dataset.wkm === 'again') wkmOpen();
    else if (el.dataset.wkm === 'bagkg') {
      wkmRead();
      sbSetBagKg(parseFloat(el.dataset.val));
      sbRenderBagChips();
      wkmRead();
      wkmRender();
      wkmLoadPreview();
    } else if (el.dataset.wkm === 'rh') {
      // Erst den Ablauf zu: der Prompt läge sonst dahinter (siehe measureSubstrateRh).
      const s = (_sbList || []).find((x) => x.subId === el.dataset.sub);
      wkfClose();
      if (s) measureSubstrateRh(s, { stay: true });
    }
  });
  // Rezept und Menge neu rechnen lassen; die Notiz nicht, sonst springt der Cursor.
  flow.addEventListener('change', (e) => {
    if (WKF.kind !== 'mix') return;
    if (e.target.closest('#wkm-recipe,#wkm-bags')) {
      wkmRead();
      wkmLoadPreview();
    } else if (e.target.closest('#wkm-notes')) {
      wkmRead();
    }
  });
})();
